export const references = {"ABCD1":{"symbol":"ABCD1","genotype":"X-linked · Hemizygous men, heterozygous women","summary":"ABCD1 variants damage the spinal cord, the adrenal cortex, and in some men the brain. Men face adrenal insufficiency, near-universal myelopathy, and lifelong risk of cerebral disease treatable only if caught early on MRI; most women develop milder myelopathy after age 40 years.","table":{"caption":"Neurologic and adrenal risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"myelopathy","name":"Myelopathy (adrenomyeloneuropathy)","women":{"risk":"63%","relative":"Not established","horizon":"At assessment · carrier cohort","citations":{"risk":["abcd1EngelenWomen"]}},"men":{"risk":"94.7%","relative":"Not established","horizon":"Among carriers older than 50","citations":{"risk":["abcd1Myelopathy"]}}},{"id":"neuropathy","name":"Peripheral neuropathy","women":{"risk":"57%","relative":"Not established","horizon":"At assessment · carrier cohort","citations":{"risk":["abcd1EngelenWomen"]}},"men":{"risk":"Not established","relative":"Not established"}},{"id":"adrenal","name":"Primary adrenal insufficiency","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"80%","relative":"Not established","horizon":"Lifetime estimate · clinical cohort","citations":{"risk":["abcd1Huffnagel"]}}},{"id":"cerebral","name":"Cerebral adrenoleukodystrophy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cerebral-amn","name":"Cerebral disease after myelopathy","women":null,"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Transplantation outcomes","text":"Boys with cerebral ALD: 5-year survival 78% with transplantation versus 55% without. 14 adults transplanted: estimated survival 57%; demyelination arrested in all 8 survivors, but motor function worsened in most. Elivaldogene autotemcel is FDA approved for boys aged 4–17 years with early active cerebral ALD who lack an available HLA-matched donor (label restricted August 2025 after hematologic malignancy in 10 of 67 treated trial participants); allogeneic transplantation remains the standard treatment.","sources":["abcd1ClinGen","abcd1FdaGeneTherapy"]},{"title":"Association evidence","text":"ClinGen: definitive for X-linked adrenoleukodystrophy (December 2020); adult ALD actionable. Plasma C26:0-lysophosphatidylcholine is the most sensitive biomarker; very long-chain fatty acids are normal in about 15% of women.","sources":["abcd1ClinGenValidity","abcd1ClinGen","abcd1Engelen"]}],"otherGenotype":{"title":"If a woman has two affected copies","text":"Rare, including one variant with a single X chromosome as in Turner syndrome; no separate pathway. Risk likely resembles a man's; refer to an ALD center to decide on adrenal screening and MRI surveillance.","sources":["abcd1Engelen","abcd1GeneReviews"]},"plans":{}},"ACTA2":{"symbol":"ACTA2","genotype":"Heterozygous","summary":"ACTA2 variants cause nonsyndromic thoracic aortic aneurysm and dissection, often presenting as a type A or type B dissection rather than a known aneurysm; some variants also cause premature coronary disease and stroke. Risk varies sharply by variant, and penetrance is incomplete.","table":{"caption":"Aortic and vascular risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"aortic-event","name":"Aortic dissection or aneurysm repair","women":{"risk":"76%","relative":"Not established","horizon":"By age 85 · family study","citations":{"risk":["acta2Regalado2015"]}},"men":{"risk":"76%","relative":"Not established","horizon":"By age 85 · family study","citations":{"risk":["acta2Regalado2015"]}}},{"id":"type-a","name":"Type A aortic dissection","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"type-b","name":"Type B aortic dissection","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"small-diameter","name":"Type A dissection below 5.0 cm","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pregnancy","name":"Pregnancy-associated aortic dissection","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"cad","name":"Premature coronary artery disease","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"stroke","name":"Premature ischemic stroke or moyamoya-like disease","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"arg179","name":"Aortic event with p.Arg179 (smooth muscle dysfunction syndrome)","women":{"risk":"100%","relative":"Not established","horizon":"By age 25 · family study","citations":{"risk":["acta2Smds"]}},"men":{"risk":"100%","relative":"Not established","horizon":"By age 25 · family study","citations":{"risk":["acta2Smds"]}}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Association evidence","text":"ClinGen: definitive for HTAD (Renard 2018) and for multisystemic smooth muscle dysfunction syndrome (2025). ACTA2 causes 12–21% of familial nonsyndromic HTAD and about 2.5% of nonfamilial thoracic aortic disease. ClinGen Actionability AC134 covers ACTA2.","sources":["acta2Renard","acta2ClinGen","acta2Regalado2015","acta2Guo2009","acta2Actionability"]},{"title":"Variant type","text":"Nearly all pathogenic ACTA2 variants are missense. Residue-level risk estimates come from small groups; review the exact variant with genetics.","sources":["acta2Renard","acta2Regalado2015","acta2Guo2009"]},{"title":"Treatment if the aorta enlarges","text":"Prophylactic root and ascending replacement, often with part of the arch, by an experienced team. In one series, no deaths followed 16 elective repairs; diameters at repair were 4.2–6.5 cm (10 with records).","sources":["acta2Regalado2015","acta2AccHtad"]}],"otherGenotype":{"title":"If both copies are affected","text":"Almost unreported: one 12-year-old girl homozygous for p.Trp88Arg had a patent ductus arteriosus and a thoracoabdominal aneurysm after a chronic descending dissection. No separate pathway; the plan above does not apply. Refer to clinical genetics and an aortic center, and test both parental lines.","sources":["acta2Regalado2015"]},"plans":{}},"ACTC1":{"symbol":"ACTC1","genotype":"Heterozygous","summary":"ACTC1 variants can cause hypertrophic cardiomyopathy, often apical; some cause dilated cardiomyopathy, left ventricular noncompaction, or atrial septal defect, sometimes within one family. ACTC1 causes about 0.5% of HCM, and gene-specific penetrance is unmeasured.","table":{"caption":"Cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"hcm","name":"Hypertrophic cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dcm","name":"Dilated cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lvnc","name":"Left ventricular noncompaction","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"asd","name":"Atrial septal defect","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"scd","name":"Sudden cardiac death or cardiac arrest","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Most phenotype-negative carriers appear to have a benign course. Thin-filament HCM (cohort including 6 ACTC1 patients) versus thick-filament: maximal wall thickness 18 mm versus 24 mm, LV dysfunction 4.3% versus 1.9% per year, NYHA class III–IV 20% versus 10%. P/LP sarcomere variants: about twice the adverse-outcome risk of no variant.","sources":["actc1Actionability","actc1Coppini","actc1Share"]},{"title":"Association evidence","text":"ClinGen: definitive for HCM (June 2021), moderate for DCM 1R (March 2026), no known relationship for ARVC (2019); no standalone curation for LVNC or atrial septal defect. AHA 2024: strong-evidence HCM gene; 2022 consensus: moderate-evidence DCM gene. ClinGen adult actionability for HCM: strong.","sources":["actc1ClinGen","actc1AhaFamily","actc1Hrs","actc1Actionability"]},{"title":"Treatment if HCM develops","text":"Beta-blockers first line for obstructive symptoms, then nondihydropyridine calcium channel blockers; persistent symptoms may need a cardiac myosin inhibitor, disopyramide, or septal reduction at an experienced center. Anticoagulate clinical atrial fibrillation regardless of CHA2DS2-VASc score. Mavacamten is teratogenic.","sources":["actc1AccPoints","actc1AhaCare"]}],"otherGenotype":{"title":"If both copies are affected","text":"No recessive ACTC1 cardiomyopathy or separate pathway is established. Carriers of more than one P/LP variant, including a second sarcomere variant, may have more severe disease. Refer to clinical genetics and a cardiomyopathy center; apply at least the plan above.","sources":["actc1AhaFamily","actc1ClinGen"]},"plans":{}},"ACTN2":{"symbol":"ACTN2","genotype":"Heterozygous","summary":"ACTN2 variants cause a cardiomyopathy that often fits no single category (hypertrophy, dilation, noncompaction, or restrictive filling), frequently with early atrial fibrillation or conduction disease, and in some families a skeletal myopathy. Penetrance is unknown.","table":{"caption":"Cardiac and muscle risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"hcm","name":"Hypertrophic cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dcm","name":"Dilated cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lvnc","name":"Left ventricular noncompaction","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"rcm","name":"Restrictive cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"acm","name":"Left-dominant arrhythmogenic cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"atrial","name":"Atrial arrhythmia and conduction disease","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ventricular","name":"Ventricular arrhythmia or cardiac arrest","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"skeletal","name":"Skeletal myopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Association evidence","text":"ClinGen lumps ACTN2-related cardiac and skeletal myopathy as one Definitive curation (July 23, 2025): Moderate for HCM and DCM in 2018; Definitive in 2023 with noncompaction, restrictive, and arrhythmogenic cardiomyopathy added; skeletal myopathy added in 2024. ClinGen adult HCM actionability (July 2026) includes ACTN2. ACTN2 is not on the ACMG secondary findings list or among the eight 2024 AHA/ACC strong-evidence HCM genes.","sources":["actn2ClingenValidity","actn2ClingenHcm","actn2Hcm2024"]},{"title":"Phenotype variability","text":"Onset ranges from childhood to old age (case ages 2–82 years). Clear genotype-phenotype correlations exist only for some skeletal myopathies.","sources":["actn2ClingenValidity","actn2MutUpdate","actn2Girolami"]},{"title":"If cardiomyopathy develops","text":"Management follows the phenotype. In HCM: echocardiography, ambulatory ECG, and sudden-death risk reassessment every 1–2 years (AHA/ACC 2024).","sources":["actn2Hcm2024"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, follow the plan above. Recessive ACTN2 disease is reported and needs specialist care beyond this plan; each variant can also cause dominant disease, so keep at least the surveillance above. Homozygous p.Gln860*: progressive heart failure, atrial fibrillation, and restrictive cardiomyopathy, transplant at age 23 years. Homozygous p.Asn480Ser: myopathy from age 30–60 years in 4 patients, one with diastolic dysfunction and atrial fibrillation at 78 years. Homozygous p.Arg506Gly (7 patients, 5 families, a possible founder variant): recessive lower-limb myopathy without cardiomyopathy. Refer to cardiology and a neuromuscular center.","sources":["actn2Lindholm","actn2MutUpdate","actn2ClingenValidity","actn2Donkervoort"]},"plans":{}},"ACVRL1":{"symbol":"ACVRL1","genotype":"Heterozygous","summary":"ACVRL1 variants cause hereditary hemorrhagic telangiectasia type 2, with more liver malformations and GI bleeding and fewer pulmonary and brain malformations than ENG. They also cause heritable pulmonary arterial hypertension (PAH): uncommon, but it can appear young and before any HHT sign.","table":{"caption":"Bleeding, vascular malformation, and pulmonary hypertension frequency","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"epistaxis","name":"Recurrent nosebleeds","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"telangiectasia","name":"Mucocutaneous telangiectasia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"liver","name":"Liver vascular malformation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"gi","name":"GI vascular malformation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pavm","name":"Pulmonary AVM","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"brain","name":"Brain vascular malformation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"spinal","name":"Spinal AVM","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pah","name":"Pulmonary arterial hypertension","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Complicated liver malformations cause high-output heart failure, portal hypertension, biliary ischemia, or encephalopathy. Pulmonary and brain malformations carry the same stroke, abscess, and hemorrhage risks as with ENG.","sources":["acvrl1HhtGuideline","acvrl1GeneReviews","acvrl1Girerd","acvrl1Revuz"]},{"title":"Diagnosis","text":"Curaçao criteria: recurrent nosebleeds, mucocutaneous telangiectasia at characteristic sites, visceral malformations, and a first-degree relative with HHT; three make HHT definite, two possible. A causative variant establishes it alone, and a carrier with few signs is common.","sources":["acvrl1Curacao","acvrl1HhtGuideline","acvrl1Lesca"]},{"title":"Association evidence","text":"ClinGen: Definitive for HHT type 2 (December 2022). The ClinGen pulmonary hypertension expert panel rated ACVRL1 Definitive for PAH in its 2023 publication (Welch 2023); that classification is not yet listed in the ClinGen validity database. The PAH link was shown in HHT families in 2001.","sources":["acvrl1ClinGen","acvrl1Welch","acvrl1Trembath"]},{"title":"ACVRL1 compared with ENG","text":"ACVRL1: more liver malformations, GI bleeding, anemia, and PAH. ENG: several-fold more pulmonary and brain malformations and earlier nosebleeds. The screening schedule is the same, with liver and PAH attention weighted to ACVRL1.","sources":["acvrl1Kitayama","acvrl1Letteboer","acvrl1Lesca","acvrl1Sanchez"]},{"title":"Treatment if disease develops","text":"Symptomatic liver malformations get tailored medical therapy; intravenous bevacizumab improved cardiac output or symptoms in about 80% of small series with high-output heart failure (adverse events 50 per 100 person-years). Liver transplant for refractory complications: 5–10-year survival 82–92%; possible with pulmonary hypertension if pulmonary vascular resistance is below 3 Wood units. Pulmonary AVMs are embolized, usually when a feeding artery is about 2–3 mm or more.","sources":["acvrl1HhtGuideline","acvrl1GeneReviews"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, or until phase is known, manage as heterozygous HHT above. Two loss-of-function copies appear lethal, inferred from pregnancy outcomes rather than genotyped losses: a couple both carrying p.Gln490Ter had 3 miscarriages and 4 early neonatal deaths in 12 pregnancies; all 5 survivors were heterozygous. Two siblings homozygous for hypomorphic p.Phe192Leu had early PAH and diffuse pulmonary AVMs, one with childhood GI bleeding; heterozygous relatives had mild or equivocal HHT. No established pathway. Refer to clinical genetics, an HHT center, and a pulmonary hypertension center; refer carrier couples before pregnancy.","sources":["acvrl1ElHarith","acvrl1Mathavan"]},"plans":{}},"APC":{"symbol":"APC","genotype":"Heterozygous","summary":"FAP-causing APC variants confer high colorectal cancer risk and require lifelong polyposis care, including after colectomy. Specific promoter 1B variants cause gastric polyposis and cancer (GAPPS); I1307K instead confers a modest colorectal cancer predisposition best established in Ashkenazi Jewish ancestry.","table":{"caption":"Cancer and tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"crc-classic","name":"Colorectal cancer, classic FAP, without colectomy","women":{"risk":"Nearly 100%","relative":"Not quantified","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"]}},"men":{"risk":"Nearly 100%","relative":"Not quantified","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"]}}},{"id":"crc-attenuated","name":"Colorectal cancer, attenuated FAP, without colectomy","women":{"risk":"70%","relative":"Not quantified","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"]}},"men":{"risk":"70%","relative":"Not quantified","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"]}}},{"id":"duodenal","name":"Duodenal or periampullary cancer (RR: duodenal only)","women":{"risk":"<1–10%","relative":"Reported RR 330.8","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"],"relative":["apcNciExtracolonic"]}},"men":{"risk":"<1–10%","relative":"Reported RR 330.8","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"],"relative":["apcNciExtracolonic"]}}},{"id":"gastric-fap","name":"Gastric cancer, FAP","women":{"risk":"0.1–7.1%","relative":"Not quantified","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"]}},"men":{"risk":"0.1–7.1%","relative":"Not quantified","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"]}}},{"id":"small-bowel","name":"Small bowel cancer beyond the duodenum","women":{"risk":"<1%","relative":"Not quantified","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"]}},"men":{"risk":"<1%","relative":"Not quantified","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"]}}},{"id":"thyroid","name":"Thyroid cancer, mostly papillary","women":{"risk":"Not established","relative":"Incidence RR 7.6","horizon":"Sex-specific estimate","citations":{"risk":["apcForceRisk"],"relative":["apcGiardiello1993"]}},"men":{"risk":"Not established","relative":"Incidence RR 7.6","horizon":"Sex-specific estimate","citations":{"risk":["apcForceRisk"],"relative":["apcGiardiello1993"]}}},{"id":"desmoid","name":"Intra-abdominal desmoid tumor (RR: all sites)","women":{"risk":"10–24%","relative":"Reported RR 852","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"],"relative":["apcNciExtracolonic"]}},"men":{"risk":"10–24%","relative":"Reported RR 852","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"],"relative":["apcNciExtracolonic"]}}},{"id":"cns","name":"Brain cancer, mostly medulloblastoma","women":{"risk":"1%","relative":"Reported RR 7.0","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"],"relative":["apcNciExtracolonic"]}},"men":{"risk":"1%","relative":"Reported RR 7.0","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"],"relative":["apcNciExtracolonic"]}}},{"id":"pancreatic","name":"Pancreatic cancer","women":{"risk":"<2%","relative":"Incidence RR 4.46","horizon":"Lifetime; sexes pooled","citations":{"risk":["apcEhtg"],"relative":["apcGiardiello1993"]}},"men":{"risk":"<2%","relative":"Incidence RR 4.46","horizon":"Lifetime; sexes pooled","citations":{"risk":["apcEhtg"],"relative":["apcGiardiello1993"]}}},{"id":"hepatoblastoma","name":"Hepatoblastoma, in carrier children","women":{"risk":"0.4–2.5%","relative":"Incidence RR 847","horizon":"Childhood; sexes pooled","citations":{"risk":["apcForceRisk"],"relative":["apcEhtg"]}},"men":{"risk":"0.4–2.5%","relative":"Incidence RR 847","horizon":"Childhood; sexes pooled","citations":{"risk":["apcForceRisk"],"relative":["apcEhtg"]}}},{"id":"gastric-gapps","name":"Gastric cancer, promoter 1B variant (GAPPS)","women":{"risk":"30%","relative":"Not quantified","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"]}},"men":{"risk":"30%","relative":"Not quantified","horizon":"By age 80; sexes pooled","citations":{"risk":["apcForceRisk"]}}},{"id":"crc-i1307k","name":"Colorectal cancer, I1307K, Ashkenazi Jewish ancestry","women":{"risk":"5–10%","relative":"OR 1.68","horizon":"Lifetime; sexes pooled","citations":{"risk":["apcForceRisk"],"relative":["apcInsight"]}},"men":{"risk":"5–10%","relative":"OR 1.68","horizon":"Lifetime; sexes pooled","citations":{"risk":["apcForceRisk"],"relative":["apcInsight"]}}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"With surveillance and timely colectomy, colorectal cancer is largely preventable; duodenal cancer and desmoids become the leading causes of death.","sources":["apcGeneReviews","apcEhtg"]},{"title":"Association evidence","text":"ClinGen: Definitive for classic or attenuated FAP and, separately, for GAPPS (June 20, 2022). InSiGHT: I1307K pathogenic, low penetrance, with risk shown only in Ashkenazi Jewish carriers.","sources":["apcClingen","apcInsight"]},{"title":"Genotype and phenotype","text":"Position predicts phenotype only roughly: codon 1309 marks a severe phenotype, codons 1250–1464 carry the highest rectal cancer risk after rectum-sparing surgery, 5′ and exon 9 variants are often attenuated, and 3′ variants carry more desmoid risk. Management follows the observed polyp burden.","sources":["apcEhtg","apcForceRisk"]},{"title":"Treatment if disease develops","text":"Endoscopic resection handles most duodenal and gastric adenomas; pancreaticoduodenectomy for suspected duodenal cancer. Desmoids are usually watched or treated medically, with surgery for complications.","sources":["apcEhtg","apcGeneReviews"]}],"otherGenotype":{"title":"If both copies are affected","text":"Two I1307K copies: InSiGHT recommends the same colonoscopy approach as for one copy, based on limited evidence. Its 2023 review identified 13 published homozygotes and a 0.14% frequency in the gnomAD v2.1.1 Ashkenazi Jewish sample (7/5,179). Two FAP-causing variants require clinical genetics review; these I1307K observations do not establish their phenotype.","sources":["apcInsight"]},"plans":{}},"APOB":{"symbol":"APOB","genotype":"Heterozygous FH-causing variant","summary":"FH-causing APOB variants impair LDL-receptor binding and can raise LDL cholesterol and coronary risk. Other APOB variants cause low-LDL hypobetalipoproteinemia, which requires a different care pathway; that finding alone is not an indication for a statin.","table":{"caption":"Coronary heart disease risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"ihd-r3527q","name":"Ischemic heart disease, p.Arg3527Gln","women":{"risk":"Not established","relative":"OR 7.0","citations":{"relative":["apobTybjaerg"]}},"men":{"risk":"Not established","relative":"OR 7.0","citations":{"relative":["apobTybjaerg"]}}},{"id":"cad-pooled","name":"Coronary artery disease, any FH variant (pooled genes)","women":{"risk":"Not established","relative":"OR 3.8","citations":{"relative":["apobKhera"]}},"men":{"risk":"Not established","relative":"OR 3.8","citations":{"relative":["apobKhera"]}}},{"id":"cad-pooled-ldl190","name":"Coronary artery disease, FH variant with LDL-C ≥190 mg/dL (pooled genes)","women":{"risk":"Not established","relative":"OR 22.3","citations":{"relative":["apobKhera"]}},"men":{"risk":"Not established","relative":"OR 22.3","citations":{"relative":["apobKhera"]}}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Which APOB variants cause FH","text":"FH-causing APOB variants usually impair LDL-receptor binding, but pathogenic variants are not confined to one historical testing hotspot. Ask the laboratory to interpret the exact variant for the correct disorder; variant location alone and draft classification criteria are not sufficient.","sources":["apobBourbon","fhGr2025"]},{"title":"Severity","text":"In the 1998 Danish study, p.Arg3527Gln carriers had total cholesterol about 100 mg/dL higher when identified in the population sample and 172 mg/dL higher when identified through clinical FH, both compared with noncarriers in the general population. These are total-cholesterol differences from differently ascertained groups, not LDL-C increments or individual risk predictions.","sources":["apobTybjaerg"]},{"title":"Hypobetalipoproteinemia","text":"Heterozygotes are usually symptom-free, with mild liver dysfunction and fatty liver. Biallelic disease presents from infancy to adulthood with fat malabsorption, fat-soluble vitamin deficiency, failure to thrive, liver disease, and, untreated, retinal and neurologic damage.","sources":["apobFhbl"]}],"otherGenotype":{"title":"If both copies are affected","text":"Clinical genetics should establish each variant’s disease association and whether two APOB variants affect the same or opposite copies. An FH-causing APOB variant plus an FH-causing LDLR or PCSK9 variant can also cause severe FH. Lipid levels suggest a phenotype but do not establish allele phase or biallelic disease. Refer confirmed severe FH to an FH centre. Two hypobetalipoproteinemia-causing APOB variants require lipid/metabolic specialist care, including an individualized low-fat diet, fat-soluble vitamin treatment and monitoring. A mixed or unclear result needs specialist interpretation; do not infer risk or treatment from variant count alone.","sources":["apobFhbl","fhGr2025","fhHofh2023"]},"plans":{}},"ATM":{"symbol":"ATM","genotype":"Heterozygous","summary":"ATM variants raise breast, pancreatic, and prostate cancer risk. Breast risk is usually moderate; some variants, notably c.7271T>G, carry higher risk.","table":{"caption":"Cancer risk","inlineReferences":true,"rowHeader":"Cancer","groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"breast","name":"Breast cancer","women":{"risk":"21–24%","horizon":"Lifetime estimate","relative":"OR 1.82","citations":{"risk":["atmForceRisk"],"relative":["atmBreastAssociation"]}},"men":{"risk":"Not established","relative":"OR 1.72","citations":{"relative":["atmAssociations"]}}},{"id":"pancreatic","name":"Pancreatic cancer","women":{"risk":"9.5%","horizon":"By age 80","relative":"6.2×","citations":{"risk":["atmPancreas"],"relative":["atmPancreas"]}},"men":{"risk":"9.5%","horizon":"By age 80","relative":"6.2×","citations":{"risk":["atmPancreas"],"relative":["atmPancreas"]}}},{"id":"prostate","name":"Prostate cancer","women":null,"men":{"risk":"Not established","relative":"OR 2.58","citations":{"relative":["atmAssociations"]}}},{"id":"gastric","name":"Stomach cancer","women":{"risk":"Not established","relative":"OR 5.50","citations":{"relative":["atmUsui"]}},"men":{"risk":"Not established","relative":"OR 5.50","citations":{"relative":["atmUsui"]}}},{"id":"ovarian","name":"Ovarian cancer","women":{"risk":"2–3%","horizon":"Lifetime estimate","relative":"OR 1.57","citations":{"risk":["atmForceRisk"],"relative":["atmAssociations"]}},"men":null},{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"5–10%","horizon":"Lifetime estimate; association uncertain","relative":"OR 1.49","citations":{"risk":["atmForceRisk"],"relative":["atmAssociations"]}},"men":{"risk":"5–10%","horizon":"Lifetime estimate; association uncertain","relative":"OR 1.49","citations":{"risk":["atmForceRisk"],"relative":["atmAssociations"]}}},{"id":"melanoma","name":"Melanoma","women":{"risk":"Not established","relative":"OR 1.46","citations":{"relative":["atmAssociations"]}},"men":{"risk":"Not established","relative":"OR 1.46","citations":{"relative":["atmAssociations"]}}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Tumor characteristics","text":"Breast tumors are more often estrogen receptor-positive.","sources":["atm"]},{"title":"Association evidence","text":"The female breast odds ratio comes from the population-based CARRIERS study. Hall et al. report other associations in a hereditary-cancer testing cohort, adjusted for age, ancestry, and personal and family cancer history. Separately, Usui et al. report gastric cancer OR 5.50 (95% CI 3.82–7.90) in Japan, using 10,366 cases and 37,592 controls after quality control. Ovarian, colorectal, melanoma, and male breast associations remain less settled.","sources":["atmBreastAssociation","atmAssociations","atmUsui","atm"]},{"title":"Treatment if cancer develops","text":"Heterozygosity alone is not a reason to avoid radiotherapy.","sources":["atmAcmg","atmEviq"]}],"otherGenotype":{"title":"If both copies are affected","text":"Clinical genetics must confirm a disease-causing change on each ATM copy: the same variant on both copies (homozygous), or two different variants shown to be in trans. Variants on the same copy do not establish biallelic disease. Biallelic ATM disease can cause ataxia-telangiectasia and needs a separate plan from the one above. Refer to an experienced multidisciplinary team for neurologic, immune, pulmonary, and cancer assessment. Radiation sensitivity requires specialist imaging and treatment planning.","sources":["ataxia"]},"plans":{}},"ATP7B":{"symbol":"ATP7B","genotype":"Biallelic","summary":"Most panel results are a single variant (carrier, about 1 in 90): no monitoring or treatment; see If one copy is affected. Biallelic ATP7B variants block biliary copper excretion, so copper accumulates in the liver, then the brain and eyes. Untreated Wilson disease causes liver disease, movement disorders, or psychiatric illness, usually from childhood to middle age but sometimes in the 70s; lifelong copper-lowering treatment prevents or reverses most of it.","table":{"caption":"Wilson disease presentation","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"hepatic","name":"Liver disease as the first presentation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"neuro","name":"Neurologic disease as the first presentation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"psych","name":"Psychiatric disturbance as the first presentation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"alf","name":"Acute liver failure, among liver presentations","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"kf-neuro","name":"Kayser-Fleischer rings with neurologic disease","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"kf-hepatic","name":"Kayser-Fleischer rings with liver disease only","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hcc","name":"Hepatocellular carcinoma, among liver presentations","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Untreated Wilson disease is uniformly fatal, mostly from liver disease. With treatment, most people live normally; under 1% need transplantation. Survival after transplantation: 87% at 5, 10, and 15 years in one series.","sources":["atp7bClinGen"]},{"title":"Adult and late presentations","text":"Most present at age 5–35 years, but molecularly confirmed patients have presented in their early 70s. In 46 patients symptomatic after age 40 years, 19 of 27 biopsied had cirrhosis; their variants did not differ from earlier onset. Age alone does not exclude the diagnosis.","sources":["atp7bAasld","atp7bClinGen"]},{"title":"Association evidence","text":"ClinGen: definitive for autosomal recessive Wilson disease (March 2019); adult Wilson disease strongly actionable. Biallelic pathogenic variants are found in about 98% of affected people.","sources":["atp7bClinGen","atp7bClinGenValidity"]},{"title":"Treatment response","text":"D-penicillamine was effective in 100% of presymptomatic, 73.7% of hepatic, and 80.6% of neurologic patients; zinc in 100% of presymptomatic patients. Hepatic treatment failure was more common on zinc than chelators in one retrospective analysis. D-penicillamine causes side effects in about a quarter; trientine rarely.","sources":["atp7bClinGen","atp7bAasld"]}],"otherGenotype":{"title":"If one copy is affected","text":"Carriers (about 1 in 90 people) are not expected to develop Wilson disease and need no copper monitoring or treatment. An unexplained liver or neurologic problem still warrants standard evaluation with copper studies, since a second variant can be missed. If the partner is also a carrier, each child has a 25% chance of Wilson disease.","sources":["atp7bAasld","atp7bGeneReviews"]},"plans":{}},"AXIN2":{"symbol":"AXIN2","genotype":"Heterozygous variant associated with AXIN2 oligodontia-cancer predisposition","summary":"AXIN2-associated cancer predisposition can cause missing permanent teeth and colorectal polyposis or cancer. Dental findings may appear in childhood, but they are not present in every carrier. Reliable age-specific cancer risks are not established.","table":{"caption":"Cancer and related risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"colorectal","name":"Colorectal polyposis or colorectal cancer","women":{"risk":"Not established","relative":"OR 11.89","citations":{"relative":["axin2Leclerc"]}},"men":{"risk":"Not established","relative":"OR 11.89","citations":{"relative":["axin2Leclerc"]}}},{"id":"oligodontia","name":"Oligodontia (six or more missing permanent teeth)","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"upper-gi","name":"Small bowel or ampullary cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"breast-ovarian","name":"Breast and ovarian cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified","horizon":"Breast; ovarian not applicable"}},{"id":"other","name":"Skin and other cancers","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"The French series ranged from one adenoma to several hundred; most affected patients had fewer than 100 polyps and onset after age 35 years. This selected cohort does not define the course for every carrier.","sources":["axin2Leclerc"]},{"title":"Which AXIN2 variants count","text":"Reported cancer-associated variants are often truncating and disrupt the C-terminal SMAD3-binding/DIX regions. Recurrent examples include p.Arg656* and p.Asn666Glnfs*41. The exact laboratory classification matters more than the general pattern.","sources":["axin2Leclerc","axin2Review"]},{"title":"Association evidence","text":"ClinGen classified the dominant oligodontia-cancer predisposition association as definitive in December 2023. The first family was reported in Finland in 2004. A 2025 systematic review included 91 people across different AXIN2 variant types and dental/cancer presentations. Population variant frequency alone cannot establish cancer penetrance.","sources":["axin2Clingen","axin2Leclerc","axin2Review"]},{"title":"Oligodontia as a marker","text":"Congenital missing teeth together with colorectal polyposis or cancer should prompt consideration of AXIN2. Younger reported carriers may have only dental findings; absence of bowel disease at that age does not establish absence of future risk.","sources":["axin2Leclerc","axin2Review"]}],"otherGenotype":{"title":"If both copies are affected","text":"If two variants are reported, confirm their classification and phase with clinical genetics. No established biallelic AXIN2 risk estimate or separate management pathway was identified in the sources reviewed. Preserve care indicated by a confirmed cancer-predisposition variant and the individual’s clinical history.","sources":["axin2Clingen","axin2Leclerc"]},"plans":{}},"BAG3":{"symbol":"BAG3","genotype":"Heterozygous","summary":"A BAG3 loss-of-function variant (usually truncating, sometimes missense) causes dilated cardiomyopathy, present in most carriers older than 40 years and tending toward heart failure. p.Pro209Leu instead causes a childhood myofibrillar myopathy with cardiomyopathy.","table":{"caption":"Cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"dcm","name":"Dilated cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"composite","name":"Death, transplant, LVAD, or sustained ventricular arrhythmia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hf-events","name":"Transplant, LVAD, or heart failure death","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"arrhythmia","name":"Serious ventricular arrhythmia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mfm","name":"Myofibrillar myopathy (p.Pro209Leu only)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Association evidence","text":"ClinGen: definitive for DCM 1HH (2026) and myofibrillar myopathy (2016); sufficient evidence for haploinsufficiency; strong adult actionability for DCM. About 2% of DCM. ESC also lists BAG3 for restrictive cardiomyopathy. ACMG secondary-findings gene since SF v3.1 (2022).","sources":["bag3ClinGen","bag3Jordan","bag3Ehra","bag3Esc2023","bag3AcmgSf"]},{"title":"Treatment if disease develops","text":"Progressive heart failure is more typical than early arrhythmic death. Standard heart failure therapy with early advanced heart failure referral. Of 74 carriers with DCM at first evaluation, 6 were lost to follow-up; 2 of the remaining 68 (2.9%) normalized LVEF. Treatment data were not reported.","sources":["bag3Dominguez","bag3ClinGenAc"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance above. No biallelic BAG3 condition is curated; ClinGen lists only dominant disease. The figures and plan are not validated for two copies: refer to clinical genetics and a cardiomyopathy center, use at least this surveillance, and test both parental lines.","sources":["bag3ClinGen"]},"plans":{}},"BAP1":{"symbol":"BAP1","genotype":"Heterozygous","summary":"A BAP1 variant predisposes to uveal melanoma, mesothelioma, cutaneous melanoma, clear cell kidney cancer, and benign BAP1-inactivated skin tumors, usually at younger ages. Lifetime risks are not established; family-based figures probably overstate risk for a panel finding.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"uveal","name":"Uveal (eye) melanoma","women":{"risk":"15.9%","relative":"Not established","horizon":"At assessment · null-variant families","citations":{"risk":["bap1Walpole"]}},"men":{"risk":"15.9%","relative":"Not established","horizon":"At assessment · null-variant families","citations":{"risk":["bap1Walpole"]}}},{"id":"mesothelioma","name":"Mesothelioma, pleural or peritoneal","women":{"risk":"16.9%","relative":"Not established","horizon":"At assessment · null-variant families","citations":{"risk":["bap1Walpole"]}},"men":{"risk":"16.9%","relative":"Not established","horizon":"At assessment · null-variant families","citations":{"risk":["bap1Walpole"]}}},{"id":"melanoma","name":"Cutaneous melanoma","women":{"risk":"12.0%","relative":"Not established","horizon":"At assessment · null-variant families","citations":{"risk":["bap1Walpole"]}},"men":{"risk":"12.0%","relative":"Not established","horizon":"At assessment · null-variant families","citations":{"risk":["bap1Walpole"]}}},{"id":"renal","name":"Kidney cancer, usually clear cell","women":{"risk":"4.9%","relative":"Not established","horizon":"At assessment · null-variant families","citations":{"risk":["bap1Walpole"]}},"men":{"risk":"4.9%","relative":"Not established","horizon":"At assessment · null-variant families","citations":{"risk":["bap1Walpole"]}}},{"id":"nmsc","name":"Nonmelanoma skin cancer, mostly basal cell","women":{"risk":"8.2%","relative":"Not established","horizon":"At assessment · null-variant families","citations":{"risk":["bap1Walpole"]}},"men":{"risk":"8.2%","relative":"Not established","horizon":"At assessment · null-variant families","citations":{"risk":["bap1Walpole"]}}},{"id":"bimt","name":"BAP1-inactivated melanocytic tumors (benign)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"meningioma","name":"Meningioma","women":{"risk":"2.2%","relative":"Not established","horizon":"At assessment · null-variant families","citations":{"risk":["bap1Walpole"]}},"men":{"risk":"2.2%","relative":"Not established","horizon":"At assessment · null-variant families","citations":{"risk":["bap1Walpole"]}}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Mesothelioma median survival is 9–12 months in the general population; BAP1-related cases may do better and respond better to platinum chemotherapy.","sources":["bap1GeneReviews","bap1Guideline","bap1ClinGen"]},{"title":"Evidence for surveillance","text":"All recommendations are expert consensus (Delphi, 34 specialists): renal imaging graded weak, eye and skin moderate.","sources":["bap1Guideline"]},{"title":"Treatment if cancer develops","text":"Kidney cancer, cutaneous melanoma, and basal cell carcinoma: standard treatment. Uveal melanoma: manage as a high-risk (class 2 or monosomy 3) tumor. Mesothelioma is best managed by an oncologist familiar with BAP1 disease. BAP1 meningiomas are usually higher grade (atypical) and are treated accordingly.","sources":["bap1GeneReviews"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic BAP1 condition is established. Rare de novo missense variants cause a separate childhood neurodevelopmental syndrome; the tumor risks and plan do not derive from it.","sources":["bap1Kury","bap1GeneReviews"]},"plans":{}},"BARD1":{"symbol":"BARD1","genotype":"Heterozygous","summary":"A BARD1 variant moderately raises breast cancer risk in women, mainly ER-negative and triple-negative disease. The ovarian link is disputed; no other adult cancer link is established.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"breast","name":"Breast cancer","women":{"risk":"17–30%","relative":"OR 2.09","horizon":"Lifetime estimate","citations":{"risk":["bard1ForceRisk"],"relative":["bard1Bcac"]}},"men":{"risk":"Not estimated","relative":"Not quantified","citations":{"risk":["bard1ForceRisk"]}}},{"id":"ovarian","name":"Ovarian cancer (association disputed)","women":{"risk":"Not estimated","relative":"Association disputed","citations":{"risk":["bard1ForceRisk"],"relative":["bard1ClinGen"]}},"men":null}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Association evidence","text":"ClinGen: BARD1 cancer predisposition Definitive (autosomal dominant, September 3, 2024), with strong breast and emerging neuroblastoma evidence; familial ovarian cancer Disputed. ClinGen adult actionability Moderate (May 14, 2024); pediatric actionability ruled out early for insufficient evidence (September 12, 2022). The CARRIERS estimate falls within the BCAC confidence interval.","sources":["bard1ClinGen","bard1Bcac","bard1Carriers"]},{"title":"Treatment if cancer develops","text":"Breast cancers associated with BARD1 are enriched for ER-negative and triple-negative subtypes; treatment follows the actual tumor findings. For adult metastatic castration-resistant prostate cancer progressing after enzalutamide or abiraterone, olaparib eligibility can include a BARD1 alteration confirmed by an FDA-approved tumor companion diagnostic, with continued GnRH therapy or prior bilateral orchiectomy. The inherited panel finding alone is not sufficient, and inclusion in the label does not demonstrate BARD1-specific benefit. Oncology should check the current drug label and other tumor biomarkers.","sources":["bard1Olaparib","bard1Carriers"]}],"otherGenotype":{"title":"If both copies are affected","text":"The cited ClinGen curation does not establish a biallelic BARD1 syndrome or quantify its risks. Clinical genetics should confirm both variants, their classification and phase, and individualize care. Do not double the single-variant risk estimate or discard otherwise indicated breast surveillance.","sources":["bard1ClinGen"]},"plans":{}},"BMPR1A":{"symbol":"BMPR1A","genotype":"Heterozygous variant associated with juvenile polyposis syndrome","summary":"BMPR1A-associated juvenile polyposis causes gastrointestinal hamartomatous polyps and increased colorectal cancer risk. Gastric polyposis is generally less extensive than with SMAD4; BMPR1A alone does not trigger the SMAD4-specific hereditary hemorrhagic telangiectasia pathway.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"any","name":"Any cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"gastric","name":"Gastric cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"In the mixed-genotype European JPS series, median colonic polyp diagnosis was 18.5 years and median cancer diagnosis was 41 years. These are cohort summaries, not a prediction that an individual’s polyps progress over that interval. BMPR1A index patients with cancer had a median diagnosis age of 34 years. Many patients can be managed endoscopically.","sources":["bmpr1aBlatter"]},{"title":"Other features","text":"Congenital heart defects, mainly septal defects, were reported in 8 of 94 BMPR1A carriers (8.5%) versus 3 of 127 SMAD4 carriers (2.4%) in the European series. This observation does not establish a routine BMPR1A cardiac screening schedule. ClinGen classified the pulmonary arterial hypertension association as disputed in October 2022.","sources":["bmpr1aBlatter","bmpr1aClingen"]},{"title":"Association evidence","text":"ClinGen classified autosomal dominant BMPR1A-associated juvenile polyposis as definitive in December 2022. Cancer estimates come largely from selected retrospective cohorts; expression varies within families. Surveillance guidance relies substantially on expert consensus and limited observational evidence.","sources":["bmpr1aBlatter","bmpr1aJapan","bmpr1aMstf","bmpr1aClingen"]}],"otherGenotype":{"title":"If both copies are affected","text":"A single-family report described homozygous p.Arg406Leu with severe skeletal, airway, cardiac and developmental abnormalities. This does not establish a general biallelic BMPR1A cancer risk or justify doubling the usual risk. Refer two reported variants to clinical genetics to confirm classification, phase and the relevant condition; preserve care indicated by a confirmed JPS-associated variant.","sources":["bmpr1aRussell","bmpr1aClingen"]},"plans":{}},"BMPR2":{"symbol":"BMPR2","genotype":"Heterozygous","summary":"BMPR2 is the commonest genetic cause of pulmonary arterial hypertension (PAH), with lifetime penetrance about 42% in women and 14% in men in PAH families. Carriers are diagnosed younger and sicker, so yearly multimodal screening aims to find PAH early.","table":{"caption":"Pulmonary arterial hypertension risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"pah","name":"Pulmonary arterial hypertension","women":{"risk":"42%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["bmpr2Larkin"]}},"men":{"risk":"14%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["bmpr2Larkin"]}}},{"id":"chd","name":"Congenital heart disease","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Before PAH-specific therapy, median survival from diagnosis was 2.8 years. Most patients are diagnosed more than 2 years after symptom onset, usually at an advanced stage.","sources":["bmpr2Actionability","bmpr2Evans","bmpr2Esc"]},{"title":"Association evidence","text":"ClinGen: Definitive for PAH (2020), one of 12 definitive genes (2024 World Symposium); adult actionability Moderate. Haploinsufficiency with incomplete penetrance; more than 650 variants reported. About 75% of familial PAH.","sources":["bmpr2ClinGen","bmpr2Welch","bmpr2Wsph","bmpr2Actionability"]},{"title":"Treatment if PAH develops","text":"Right heart catheterization at a PH center sets risk-based therapy. Long-term calcium channel blockers seldom apply. PAH drugs improved 6-minute walk distance by 27.9–39.9 m; mortality benefit inconclusive.","sources":["bmpr2Esc","bmpr2Evans","bmpr2Actionability"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic BMPR2 condition is established; these figures come from heterozygous carriers. Refer a second reported variant to a PH center and clinical genetics.","sources":["bmpr2Welch","bmpr2Esc"]},"plans":{}},"BRCA1":{"symbol":"BRCA1","genotype":"Heterozygous","summary":"BRCA1 confers a high risk of breast and ovarian cancer and a smaller increase in pancreatic cancer. Prostate and uterine associations are uncertain.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"breast","name":"Breast cancer","women":{"risk":"72%","relative":"OR 7.62","horizon":"By age 80 · includes DCIS","citations":{"risk":["brcaPenetrance"],"relative":["brca1BreastOdds"]}},"men":{"risk":"0.4%","relative":"3.3×","horizon":"By age 80","citations":{"risk":["maleBrca"],"relative":["maleBrca"]}}},{"id":"ovarian","name":"Ovarian / fallopian tube / peritoneal cancer (OR: ovarian only)","women":{"risk":"44%","relative":"OR 75.6","horizon":"By age 80","citations":{"risk":["brcaPenetrance"],"relative":["brca1CancerOdds"]}},"men":{"risk":"Not estimated","relative":"Not quantified","horizon":"Female cohort estimate only","citations":{"risk":["brcaPenetrance"]}}},{"id":"prostate","name":"Prostate cancer","women":null,"men":{"risk":"21%","relative":"SIR 2.35 (uncertain)","horizon":"By age 75","citations":{"risk":["maleBrca"],"relative":["brca1Nyberg"]}}},{"id":"pancreatic","name":"Pancreatic cancer","women":{"risk":"2–3%","relative":"OR 2.58","horizon":"By age 80","citations":{"risk":["femaleBrca"],"relative":["brca1PancreasOdds"]}},"men":{"risk":"2–3%","relative":"OR 2.58","horizon":"By age 80","citations":{"risk":["maleBrca"],"relative":["brca1PancreasOdds"]}}},{"id":"uterine","name":"Uterine cancer","women":{"risk":"3.4%","relative":"2.0× (uncertain)","horizon":"By age 75","citations":{"risk":["femaleBrca"],"relative":["femaleBrca"]}},"men":null}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"BRCA1 breast cancers are more often triple negative, without hormone or HER2 targets. No effective ovarian screening exists, so ovarian prevention rests on risk-reducing surgery.","sources":["brcaCharacterization"]},{"title":"Association evidence","text":"The ovarian and prostate ORs compare BioBank Japan cases without a family history with controls without personal or family cancer history. The uterine association, mainly serous carcinoma, is not yet certain. BioBank Japan also reported biliary tract (OR 17.4, 95% CI 5.8–51.9) and stomach cancer (OR 5.2, 95% CI 2.6–10.5) associations; single-population findings.","sources":["brcaPenetrance","brca1BreastOdds","brca1CancerOdds","brca1PancreasOdds","maleBrca","brcaCharacterization"]},{"title":"Treatment if cancer develops","text":"A BRCA1 finding can affect cancer treatment, so involve the treating oncology team. Breast-conserving therapy remains an option, and BRCA1 heterozygosity alone is not a contraindication to radiotherapy; discuss the risk of additional breast cancers when choosing surgery. Platinum chemotherapy and PARP inhibitors have roles in selected settings, but eligibility depends on the cancer type, stage, tumor biomarkers, prior treatment and response. Use the current disease-specific guideline and drug label rather than the preventive screening pathway to select treatment.","sources":["brca1TreatmentGuideline","brca1Parp","brcaCharacterization"]}],"otherGenotype":{"title":"If both copies are affected","text":"Biallelic BRCA1 can cause the very rare Fanconi anemia subtype FANCS. Reported features include congenital abnormalities, sensitivity to DNA-crosslinking agents and early cancer; one published patient developed breast cancer at age 23 years. BRCA1-specific cancer probabilities are not established by these sparse reports, and childhood leukemia estimates from other Fanconi subtypes should not be applied. Confirm the variants and their phase with clinical genetics and arrange care with a Fanconi anemia specialist team. The heterozygous risk estimates on this page do not describe this condition.","sources":["fa","brca1Fancs","maleBrca","brcaCharacterization"]},"plans":{}},"BRCA2":{"symbol":"BRCA2","genotype":"Heterozygous","summary":"A disease-causing germline BRCA2 variant confers high breast cancer risk in women and raises ovarian, prostate, pancreatic, and male breast cancer risk. The uterine association is uncertain.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"breast","name":"Breast cancer","women":{"risk":"69%","relative":"OR 5.23","horizon":"By age 80 · includes DCIS","citations":{"risk":["brcaPenetrance"],"relative":["brca2BreastOdds"]}},"men":{"risk":"3.8%","relative":"31.7×","horizon":"By age 80","citations":{"risk":["maleBrca"],"relative":["maleBrca"]}}},{"id":"ovarian","name":"Ovarian / fallopian tube / peritoneal cancer (OR: ovarian only)","women":{"risk":"17%","relative":"OR 11.3","horizon":"By age 80","citations":{"risk":["brcaPenetrance"],"relative":["brca2CancerOdds"]}},"men":{"risk":"Not estimated","relative":"Not quantified","horizon":"Female cohort estimate only","citations":{"risk":["brcaPenetrance"]}}},{"id":"prostate","name":"Prostate cancer","women":null,"men":{"risk":"26.9%","relative":"OR 4.0","horizon":"By age 80","citations":{"risk":["maleBrca"],"relative":["brca2CancerOdds"]}}},{"id":"pancreatic","name":"Pancreatic cancer","women":{"risk":"3–4%","relative":"OR 6.20","horizon":"By age 80","citations":{"risk":["femaleBrca"],"relative":["brca2PancreasOdds"]}},"men":{"risk":"3–4%","relative":"OR 6.20","horizon":"By age 80","citations":{"risk":["maleBrca"],"relative":["brca2PancreasOdds"]}}},{"id":"uterine","name":"Uterine cancer","women":{"risk":"2.0%","relative":"1.2× (uncertain)","horizon":"By age 75","citations":{"risk":["femaleBrca"],"relative":["femaleBrca"]}},"men":null}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"BRCA-associated prostate cancer may be aggressive. Ovarian screening has no established survival benefit, so risk reduction centers on appropriate surgery. Male breast cancer risk is higher with BRCA2 than BRCA1 but remains uncommon in absolute terms.","sources":["brca2ForceTreatment","femaleBrca","maleBrca","brcaCharacterization"]},{"title":"Association evidence","text":"Breast, ovarian, prostate, pancreatic, and male breast associations are established; uterine association remains uncertain. BioBank Japan reported esophageal OR 5.6 (95% CI 2.9–11.0) and stomach OR 4.7 (95% CI 3.1–7.1). Additional exploratory signals were kidney OR 4.5 (95% CI 1.4–14.2), cervical OR 3.2 (95% CI 1.3–7.8), and liver OR 2.4 (95% CI 1.1–5.0). The latter should not be treated as established associations after accounting for multiple testing. These Japanese selected-case odds ratios are not lifetime risk estimates or new screening recommendations.","sources":["brcaPenetrance","brca2BreastOdds","brca2CancerOdds","brca2PancreasOdds","maleBrca","brcaCharacterization"]},{"title":"Treatment if cancer develops","text":"Oncology individualizes treatment. BRCA2 status does not preclude otherwise appropriate breast-conserving therapy; discuss contralateral risk and surgical choices. The ASCO/ASTRO/SSO guideline found no evidence of significantly increased radiation toxicity from BRCA1/2 status. Its 2020 platinum preference applies when offering chemotherapy for metastatic germline-BRCA breast cancer without prior platinum, not all advanced breast cancers. PARP inhibitors have selected BRCA-associated cancer indications; the oncologist must check the current drug label, tumor type, biomarker, stage, prior treatment, and response requirements. Olaparib indications include selected HER2-negative breast cancers, ovarian and pancreatic maintenance settings, and metastatic castration-resistant prostate cancer.","sources":["brca2TreatmentGuideline","brca2Parp","brca2ForceTreatment","brcaCharacterization"]}],"otherGenotype":{"title":"If both copies are affected","text":"Biallelic disease-causing BRCA2 variants can cause Fanconi anemia complementation group D1, with serious childhood cancer risk. A 2007 report of 27 patients included leukemia in 13 and solid tumors in 15; its estimated 97% malignancy probability by age 5.2 years describes that highly selected series, not every biallelic genotype. Confirm the variants and their phase with clinical genetics and arrange a Fanconi anemia specialist team appropriate to the patient’s age. Do not use the heterozygous plan alone: the specialist team should integrate Fanconi-specific care with appropriate hereditary cancer surveillance.","sources":["fa","brca2Fancd1","maleBrca","brcaCharacterization"]},"plans":{}},"BRIP1":{"symbol":"BRIP1","genotype":"Heterozygous","summary":"A BRIP1 variant raises ovarian, fallopian tube, and peritoneal cancer risk, mostly after age 50 years. A clinically relevant increase in breast cancer risk has not been established.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"ovarian","name":"Ovarian / fallopian tube / peritoneal cancer (RR: ovarian model)","women":{"risk":"5.8%","relative":"Incidence RR 3.41","horizon":"Ages 20–80 · truncating variants","citations":{"risk":["brip1Ramus"],"relative":["brip1Ramus"]}},"men":null},{"id":"breast","name":"Breast cancer (association refuted)","women":{"risk":"Not established","relative":"OR 1.11 (uncertain)","citations":{"relative":["brip1Bcac"]}},"men":{"risk":"Not established","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"Ovarian screening has no proven survival benefit. Discuss risk-reducing surgery after an individualized assessment: eviQ recommends considering ages 45–50 years, while ACMG and the UK consensus generally discuss around age 50 years.","sources":["brip1Acmg","brip1Uk","brip1Eviq"]},{"title":"Association evidence","text":"ClinGen: familial ovarian cancer Definitive (autosomal dominant, December 20, 2023); hereditary breast carcinoma Refuted; Fanconi anemia group J Definitive (autosomal recessive, August 18, 2019). Earlier low-penetrance breast reports were not confirmed. Evidence for prostate, colorectal, and other cancers is insufficient.","sources":["brip1ClinGen","brip1Bcac","brip1Acmg"]},{"title":"Treatment if cancer develops","text":"A BRIP1 finding alone does not establish an ovarian-cancer treatment choice. In PAOLA-1, the HRD-negative subgroup showed no progression-free survival benefit from olaparib plus bevacizumab; this was not a BRIP1-specific efficacy result. The FDA olaparib label includes qualifying BRIP1-mutated metastatic castration-resistant prostate cancer that has progressed after enzalutamide or abiraterone. Oncology should confirm tumor testing, treatment history, and current label eligibility.","sources":["brip1Acmg","brip1Olaparib"]}],"otherGenotype":{"title":"If both copies are affected","text":"Fanconi anemia complementation group J is an autosomal recessive marrow failure and cancer syndrome accounting for about 2% of Fanconi anemia. Confirm with clinical genetics and refer to an experienced Fanconi anemia team. Do not use the heterozygous plan alone; the team should integrate Fanconi anemia care and hereditary-cancer surveillance.","sources":["brip1ClinGen","brip1Acmg","fa"]},"plans":{}},"BTD":{"symbol":"BTD","genotype":"Biallelic","summary":"Biallelic BTD variants impair biotin recycling. Profound deficiency (below 10% of mean normal activity) can cause neurologic, hearing, vision, and skin disease, partial (10–30%) usually only under stress; lifelong oral biotin prevents symptoms, but existing hearing, vision, and nerve damage often persists.","table":{"caption":"Untreated biotinidase deficiency","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"hearing","name":"Sensorineural hearing loss","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"seizures","name":"Seizures","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hypotonia","name":"Hypotonia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"skin","name":"Skin rash or alopecia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ataxia","name":"Ataxia or developmental delay","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"vision","name":"Optic atrophy or other visual problems","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"coma","name":"Death in metabolic coma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"adult","name":"Myelopathy, neuropathy, or optic neuropathy in adults","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"symptoms-genotype-first","name":"Any symptoms in an adult found by genetic testing","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Outcome with treatment","text":"Of 44 adolescents and adults treated from infancy after newborn screening, none reported major vision problems and 70% were in college or graduate school.","sources":["btdClinGenAct","btdGeneReviews"]},{"title":"Why adults may be undiagnosed","text":"US newborn screening detects virtually all profound and partial deficiency, but programs began at different dates, so many adults were never screened.","sources":["btdClinGenAct","btdKellom"]},{"title":"Association evidence","text":"ClinGen: definitive for autosomal recessive biotinidase deficiency (2020); moderate for Leigh syndrome (2021), treated as biotinidase deficiency. Adult actionability 6DC (limited); pediatric definitive.","sources":["btdClinGen","btdClinGenAct"]},{"title":"Enzyme activity in early childhood","text":"Activity can rise through early childhood, mainly with D444H; re-measuring at 12 months is suggested. Relevance to adult categories is not established.","sources":["btdEmilia"]}],"otherGenotype":{"title":"If one copy is affected","text":"Carriers (about 1 in 120) have no deficiency and need no treatment or monitoring. If the partner is also a carrier, each child has a 25% chance of biotinidase deficiency, which newborn screening detects and biotin treats. One case report describes a symptomatic child with one identified variant and about 25% activity; a second, undetected variant is a plausible explanation. This does not change carrier management.","sources":["btdGeneReviews","btdClinGenAct","btdNepal"]},"plans":{}},"CACNA1C":{"symbol":"CACNA1C","genotype":"Heterozygous","summary":"Gain-of-function CACNA1C variants cause Timothy syndrome, a multisystem disorder with severe long QT from infancy, or usually milder nonsyndromic long QT type 8 (LQT8). Brugada and short QT associations are disputed, so the exact variant decides the plan.","table":{"caption":"Arrhythmia and multisystem risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"lqt","name":"Long QT syndrome diagnosed","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"sudden-death","name":"Sudden death","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"chd","name":"Congenital heart defect","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hypoglycemia","name":"Hypoglycemia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"anesthesia","name":"Abnormal response to anesthesia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"seizures","name":"Seizure disorder","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Timothy syndrome historically killed many children early from arrhythmia, anesthesia, and hypoglycemia; early ICD implantation has markedly improved survival. Fewer than 70 patients are reported.","sources":["cacna1cNatHist","cacna1cDufendach","cacna1cConsensus","cacna1cEhra"]},{"title":"Association evidence","text":"ClinGen: definitive for Timothy syndrome (2023), moderate for LQTS (2020), disputed for short QT (2020) and Brugada syndrome (2025; EHRA cites an earlier limited rating). Test in Timothy syndrome; may test in high-probability LQTS.","sources":["cacna1cClinGen","cacna1cWilde","cacna1cAdler","cacna1cWalsh","cacna1cEhra"]},{"title":"Variant reporting","text":"No single reference transcript exists, so report the exact protein and genomic change. Do not infer pathogenicity from presumed gain or loss of function; re-evaluate classification periodically.","sources":["cacna1cConsensus"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic CACNA1C condition is established; these risks and plan are unstudied there. Refer to clinical genetics.","sources":["cacna1cGeneReviews"]},"plans":{}},"CACNA1S":{"symbol":"CACNA1S","genotype":"Heterozygous","summary":"Two CACNA1S variants, p.Arg1086His and p.Arg174Trp, cause malignant hyperthermia (MH) susceptibility under volatile anesthetics or succinylcholine. Arginine substitutions in the voltage-sensor segments cause hypokalemic periodic paralysis (HypoPP): episodes of flaccid weakness with low potassium.","table":{"caption":"Malignant hyperthermia and periodic paralysis risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"mh-exposed","name":"MH reaction in carriers of an MH variant given trigger agents","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mh-death","name":"Historical death rate in an untreated MH reaction (all genotypes)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hypopp","name":"Periodic paralysis attacks in carriers of a periodic paralysis variant","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"myopathy","name":"Permanent proximal weakness in periodic paralysis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mh-in-hypopp","name":"MH reaction in carriers of a periodic paralysis variant","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"MH causes hypercapnia, tachycardia, rigidity, acidosis, hyperkalemia with arrhythmia, rhabdomyolysis, and hyperthermia. HypoPP attacks are flaccid, proximal more than distal, and self-limiting, but severe attacks can involve respiratory muscles and hypokalemic arrhythmia, and many patients develop permanent leg weakness.","sources":["mh","cacna1sClingenMh","cacna1sHypopp","cacna1sStatland"]},{"title":"Association evidence","text":"ClinGen: MHS Moderate (autosomal dominant, April 2023); MH precautions Strong actionability. HypoPP is not ClinGen-curated; CACNA1S is the main HypoPP gene. Voltage-sensor arginine substitutions create a gating pore current that depolarizes muscle in low potassium; effect size varies by variant.","sources":["cacna1sClingenValidity","cacna1sClingenMh","cacna1sHypopp","cacna1sStatland","cacna1sGatingPore"]},{"title":"Treatment if an MH reaction occurs","text":"Stop triggers, hyperventilate with 100% oxygen, give intravenous dantrolene from 2.5 mg/kg, cool above 38.5 °C, and avoid calcium channel blockers for arrhythmia. MHAUS hotline (North America): 800-644-9737.","sources":["mh","cacna1sMhausAgents"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance above. Biallelic variants, or in some families one dominant variant, cause a congenital myopathy: perinatal hypotonia, axial and generalized weakness, sometimes ophthalmoplegia, from lethal early onset to milder forms. Refer to neuromuscular medicine; anesthesia under EMHG myopathy guidance. The MH and periodic paralysis plan applies only if a variant is itself one of those. A parent with one recessive myopathy variant is a reproductive finding.","sources":["cacna1sSchartner","cacna1sEmhgMyopathy"]},"plans":{}},"CALM1":{"symbol":"CALM1","genotype":"Heterozygous","summary":"Calmodulinopathy: severe early-onset long QT syndrome, CPVT, or idiopathic ventricular fibrillation, with life-threatening arrhythmias usually in childhood. Most variants are de novo; milder familial cases, including asymptomatic adults, occur.","table":{"caption":"Arrhythmic and associated risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"any-event","name":"Any cardiac event","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mae","name":"Major arrhythmic event","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"scd","name":"Sudden cardiac death","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lqts","name":"Long QT syndrome phenotype","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cpvt","name":"CPVT phenotype","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ivf","name":"Idiopathic ventricular fibrillation phenotype","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"structural","name":"Cardiomyopathy or congenital heart defect","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"neuro","name":"Primary neurodevelopmental or neurological features","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"2019 registry: 86.5% symptomatic; recurrent events despite treatment were common. Broader testing found milder cases, but early sudden deaths still occur.","sources":["calm1Crotti2019","calm1Crotti2023"]},{"title":"Association evidence","text":"ClinGen: definitive for autosomal dominant long QT syndrome (2018), moderate for CPVT (2021); CPVT actionability moderate in adults, strong in children. Test CALM genes in every long QT and CPVT proband; reportable as secondary findings.","sources":["calm1ClinGen","calm1Actionability","calm1Walsh","calm1Adler","calm1Ehra2026"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance above. No biallelic CALM1 condition is described; all reported calmodulinopathy is heterozygous, and this plan is not validated for it. Refer to clinical genetics and an inherited arrhythmia center, and apply at least the evaluation above.","sources":["calm1Crotti2023","calm1ClinGen"]},"plans":{}},"CALM2":{"symbol":"CALM2","genotype":"Heterozygous","summary":"Calmodulinopathy: rare, often severe childhood long QT syndrome, CPVT, or idiopathic ventricular fibrillation, mostly de novo. Milder carriers exist; an adult needs full cardiac evaluation and family planning advice, not reassurance.","table":{"caption":"Arrhythmia risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"any-event","name":"Any arrhythmic cardiac event","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mae","name":"Major arrhythmic event (cardiac arrest, sudden death, or appropriate ICD shock)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"scd","name":"Sudden cardiac death","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lqts","name":"Long QT syndrome phenotype","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cpvt","name":"CPVT phenotype","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ivf","name":"Idiopathic ventricular fibrillation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"structural","name":"Cardiomyopathy or congenital heart defect","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"neuro","name":"Primary neurological or neurodevelopmental features","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"2019 registry: breakthrough events in 56% of treated patients despite beta-blockers and other therapy. Adult outcomes are not described separately.","sources":["calm2Registry2019","calm2Registry2023"]},{"title":"Association evidence","text":"ClinGen: definitive for long QT syndrome (2018), moderate for CPVT (2021). Definitive for LQTS with atypical features (presentation by age 5 years, de novo, marked bradycardia or AV block); role in typical adult LQTS not established. The CPVT panel judged the framework too conservative and concluded all three calmodulin genes cause CPVT, citing de novo p.Asp132Glu in CALM2 and CALM3.","sources":["calm2ClinGen","calm2Adler","calm2Walsh"]},{"title":"Variant location","text":"Most variants alter a calcium-binding residue in EF-hands III and IV and are absent from population databases. EF-hand IV associates with LQTS; EF-hand III and the EF-hand I–II linker with CPVT. p.Asn98Ser has been seen with LQTS, CPVT, idiopathic ventricular fibrillation, and sudden death.","sources":["calm2Registry2019","calm2Registry2023"]},{"title":"Genetic testing guidance","text":"Test CALM1–3 in every high-probability LQTS patient and CPVT proband; incidental findings are actionable secondary findings.","sources":["calm2Wilde","calm2Ehra"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance above. No biallelic CALM2 condition is established, and this plan has not been studied for it. Refer to clinical genetics and inherited arrhythmia electrophysiology.","sources":["calm2Registry2023","calm2Registry2019"]},"plans":{}},"CALM3":{"symbol":"CALM3","genotype":"Heterozygous","summary":"Calmodulinopathy: rare, often severe childhood long QT syndrome, CPVT, or idiopathic ventricular fibrillation, mostly de novo. Milder carriers exist; an adult needs full cardiac evaluation and family planning advice, not reassurance.","table":{"caption":"Arrhythmia risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"any-event","name":"Any arrhythmic cardiac event","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mae","name":"Major arrhythmic event (cardiac arrest, sudden death, or appropriate ICD shock)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"scd","name":"Sudden cardiac death","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lqts","name":"Long QT syndrome phenotype","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cpvt","name":"CPVT phenotype","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ivf","name":"Idiopathic ventricular fibrillation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"structural","name":"Cardiomyopathy or congenital heart defect","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"neuro","name":"Primary neurological or neurodevelopmental features","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"2019 registry: breakthrough events in 56% of treated patients despite beta-blockers and other therapy. Adult outcomes are not described separately.","sources":["calm3Registry2019","calm3Registry2023"]},{"title":"Association evidence","text":"ClinGen: definitive for long QT syndrome (2018), moderate for CPVT (2021); CALM3 scored limited for CPVT on the standard framework and the panel unanimously upgraded it. Definitive for LQTS with atypical features (presentation by age 5 years, de novo, marked bradycardia or AV block); role in typical adult LQTS not established. The CPVT panel judged the framework too conservative and concluded all three calmodulin genes cause CPVT, citing de novo p.Asp132Glu in CALM2 and CALM3.","sources":["calm3ClinGen","calm3Adler","calm3Walsh"]},{"title":"Variant location","text":"Most variants alter a calcium-binding residue in EF-hands III and IV and are absent from population databases. EF-hand IV associates with LQTS; EF-hand III and the EF-hand I–II linker with CPVT. p.Asn98Ser has been seen with LQTS, CPVT, idiopathic ventricular fibrillation, and sudden death.","sources":["calm3Registry2019","calm3Registry2023"]},{"title":"Genetic testing guidance","text":"Test CALM1–3 in every high-probability LQTS patient and CPVT proband; incidental findings are actionable secondary findings.","sources":["calm3Wilde","calm3Ehra"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance above. No biallelic CALM3 condition is established, and this plan has not been studied for it. Refer to clinical genetics and inherited arrhythmia electrophysiology.","sources":["calm3Registry2023","calm3Registry2019"]},"plans":{}},"CASQ2":{"symbol":"CASQ2","genotype":"Biallelic","summary":"Recessive CPVT: polymorphic or bidirectional ventricular tachycardia with exercise or emotion in a structurally normal heart, nearly always expressed and usually starting in childhood. A single variant is usually a carrier state, but a minority of carriers show CPVT, so carriers need a baseline exercise test and Holter, repeated periodically.","table":{"caption":"Arrhythmic risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"ectopy","name":"Exercise- or adrenaline-induced ventricular ectopy (CPVT phenotype)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pvt","name":"Polymorphic or bidirectional ventricular tachycardia on testing","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"syncope","name":"Cardiac syncope","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"aca","name":"Aborted cardiac arrest","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"scd","name":"Sudden cardiac death","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Recessive CPVT presents earlier and with more malignant arrhythmias than dominant CPVT.","sources":["casq2Wilde","casq2Ng"]},{"title":"Association evidence","text":"ClinGen: definitive for autosomal recessive CPVT, moderate for autosomal dominant CPVT (January 2021); strong actionability in adults and children. CASQ2 accounts for about 2–5% of CPVT (ClinGen) or 5–10% (EHRA 2026).","sources":["casq2ClinGen","casq2Walsh","casq2Actionability","casq2Ehra2026"]},{"title":"Treatment response","text":"No CASQ2-specific trial; ESC CPVT recommendations apply to all genotypes. Rare CPVT forms may respond poorly to beta-blockers alone, so EHRA 2026 advises flecainide without waiting for breakthrough, and twice-yearly exercise testing.","sources":["casq2Esc","casq2Ehra2026"]}],"otherGenotype":{"title":"If one copy is affected","text":"Usually a low-penetrance carrier state: presumed pathogenic CASQ2 variants occur in about 0.1% of gnomAD, roughly 400 times the expected frequency of CASQ2 CPVT. Heterozygous missense variants reported with dominant CPVT (for example p.Lys180Arg) carry more weight than truncating variants; ask clinical genetics which applies. Of 51 carrier relatives evaluated, 17 (33.3%) met CPVT criteria. Of 52 carrier relatives in biallelic-proband families, 37 were evaluated and 8 (22%) met CPVT criteria; 2 of all 52 (3.8%) had events, first at 52.5 ± 21.9 years, with no arrest or sudden death. In heterozygous-proband families, 9 of 14 met criteria and 2 of 14 (14%) had events, first at 20 ± 8.5 years, including one aborted arrest. Twelve heterozygous probands had CPVT, 3 with aborted arrest. Arrange a baseline exercise test and Holter reviewed by cardiology, repeated periodically (no fixed interval; carrier events came from adolescence into later adulthood). If normal: Ng 2020, no therapy or exercise restriction; ESC 2022 and GeneReviews do not separate CASQ2 heterozygotes from other genotype-positive relatives and advise considering a beta-blocker even after a negative exercise test (ESC class 2a). Electrophysiology decides. If CPVT is present, manage under electrophysiology. Offer a partner CASQ2 testing before pregnancy.","sources":["casq2Ng","casq2Walsh","casq2Wilde","casq2GeneReviews","casq2ClinGen","casq2Esc"]},"plans":{}},"CAV1":{"symbol":"CAV1","genotype":"Heterozygous","summary":"Heritable pulmonary arterial hypertension (PAH), sometimes in early childhood; only about 10 affected families or individuals are reported, so penetrance is unknown. Screening follows guidance for all PAH-causing variants, which rests on BMPR2 data.","table":{"caption":"Pulmonary arterial hypertension risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"pah","name":"Pulmonary arterial hypertension","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lipodystrophy","name":"Partial lipodystrophy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Within one family, from death at 4 years to diagnosis at 67 years with survival to 71 years. Not compared with BMPR2 carriers or non-carriers.","sources":["cav1Austin"]},{"title":"Association evidence","text":"ClinGen: PAH Definitive (2025), genetic evidence 6 of 12 points, maximum experimental score; likely dominant-negative. Recessive CGL3 Definitive (2025); dominant lipodystrophy Limited (2025); amyotrophic lateral sclerosis Limited (2023).","sources":["cav1ClinGenPah","cav1Welch","cav1ClinGenCgl3","cav1ClinGenFpld","cav1ClinGenAls"]},{"title":"Treatment if PAH develops","text":"Right heart catheterization at a PH centre, then risk-based therapy. No CAV1-specific treatment evidence.","sources":["cav1Esc"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance on this page. Congenital generalized lipodystrophy type 3; this plan does not apply. 5 patients from 2 families: near-total absence of body fat from infancy, short stature, severe insulin resistance, hypertriglyceridemia, fatty liver, diabetes (at 13 years in the first patient), and in some achalasia and low bone density; no PAH reported. Refer to a lipodystrophy endocrinologist. Generalized lipodystrophy: triglycerides and blood pressure at least yearly (class I); liver ultrasound at diagnosis; yearly diabetes screening, liver enzymes, urine protein, ECG, and echocardiogram; metreleptin with diet first-line for metabolic complications (class I, level B). Siblings: 25% chance.","sources":["cav1ClinGenCgl3","cav1Kim","cav1Patni","cav1Brown"]},"plans":{}},"CAV3":{"symbol":"CAV3","genotype":"Heterozygous","summary":"Caveolinopathy: a muscle disease ranging from raised CK alone to exercise intolerance, rippling muscles, and mild limb-girdle or distal weakness, often with little functional impact. Heart involvement is uncommon and weakly supported.","table":{"caption":"Muscle and heart findings","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"ck","name":"Raised CK","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"exercise","name":"Exercise intolerance","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"rippling","name":"Rippling muscle signs","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"aid","name":"Weakness needing a walking aid","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"rhabdo","name":"Rhabdomyolysis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"respiratory","name":"Respiratory impairment","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hcm","name":"Hypertrophic cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lqts","name":"Long QT syndrome (LQT9)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mh","name":"Malignant hyperthermia reaction","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Most caveolinopathy is mild: in the French cohort 2 of 23 needed a walking aid after a mean of 24.2 years, and none had cardiac or respiratory impairment. Phenotypes overlap and differ within families: raised CK alone, exercise intolerance and myalgia, rippling muscle disease, limb-girdle weakness (LGMD1C), and distal myopathy.","sources":["cav3Berling","cav3GeneReviews","cav3ClinGenCaveolinopathy"]},{"title":"Association evidence","text":"ClinGen: caveolinopathy Definitive (autosomal dominant, 2022; 11 probands), lumping rippling muscle disease, raised CK, Tateyama distal myopathy, and HCM. Long QT syndrome Limited (2020), curated separately. An earlier sudden infant death syndrome link was in neither curation.","sources":["cav3ClinGenCaveolinopathy","cav3ClinGenLqts","cav3Hedley"]},{"title":"Diagnosis pitfalls","text":"Caveolin-3 immunostaining was normal in a quarter of the French cohort and 3 of 4 UK patients, while Western blot showed reduced protein; EMG mostly normal. A normal stain does not exclude the diagnosis.","sources":["cav3Berling","cav3Scalco"]},{"title":"Treatment if disease develops","text":"No specific treatment. Supportive: weight control, physical therapy and stretching, mobility aids, social support.","sources":["cav3GeneReviews","cav3Aan"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance on this page. Recessive caveolinopathy is rare; carrier parents may be asymptomatic or have modestly raised CK or calf hypertrophy. Refer for neuromuscular assessment; this plan does not describe that genotype. Siblings: 25% chance.","sources":["cav3GeneReviews","cav3ClinGenCaveolinopathy"]},"plans":{}},"CDC73":{"symbol":"CDC73","genotype":"Heterozygous","summary":"CDC73 variants predispose to hyperparathyroidism-jaw tumor syndrome, including primary hyperparathyroidism and parathyroid carcinoma. Arrange lifelong biochemical and organ surveillance with an endocrine specialist; confirmed hyperparathyroidism requires an experienced parathyroid surgical team.","table":{"caption":"Tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"any","name":"Any CDC73-related manifestation","women":{"risk":"65%","relative":"Not quantified","horizon":"By age 50","citations":{"risk":["cdc73VanDerTuin"]}},"men":{"risk":"65%","relative":"Not quantified","horizon":"By age 50","citations":{"risk":["cdc73VanDerTuin"]}}},{"id":"phpt","name":"Primary hyperparathyroidism","women":{"risk":"53%","horizon":"By age 50","relative":"Not quantified","citations":{"risk":["cdc73VanDerTuin"]}},"men":{"risk":"53%","horizon":"By age 50","relative":"Not quantified","citations":{"risk":["cdc73VanDerTuin"]}}},{"id":"carcinoma","name":"Parathyroid carcinoma","women":{"risk":"Not estimated","relative":"Not quantified","citations":{"risk":["cdc73GeneReviews","cdc73Actionability"]}},"men":{"risk":"Not estimated","relative":"Not quantified","citations":{"risk":["cdc73GeneReviews","cdc73Actionability"]}}},{"id":"jaw","name":"Ossifying fibroma of the jaw","women":{"risk":"Not estimated","relative":"Not quantified","citations":{"risk":["cdc73GeneReviews","cdc73Actionability"]}},"men":{"risk":"Not estimated","relative":"Not quantified","citations":{"risk":["cdc73GeneReviews","cdc73Actionability"]}}},{"id":"kidney","name":"Kidney lesions (cysts, hamartoma, Wilms tumor)","women":{"risk":"Not estimated","relative":"Not quantified","citations":{"risk":["cdc73GeneReviews","cdc73Actionability"]}},"men":{"risk":"Not estimated","relative":"Not quantified","citations":{"risk":["cdc73GeneReviews","cdc73Actionability"]}}},{"id":"uterine","name":"Uterine tumors, benign and malignant","women":{"risk":"Not estimated","relative":"Not quantified","citations":{"risk":["cdc73GeneReviews","cdc73Actionability"]}},"men":null}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"Primary hyperparathyroidism often arises from a treatable adenoma, but persistent or recurrent disease can occur. In one surgical series, recurrent PHPT occurred in 23.5% of 17 patients with benign lesions. Parathyroid carcinoma can metastasize, and jaw fibromas can cause local damage.","sources":["cdc73GeneReviews","cdc73Iacobone2020"]},{"title":"Pathology clue","text":"Loss of nuclear parafibromin staining in a parathyroid tumor should prompt consideration of germline CDC73 evaluation; it does not by itself prove a germline variant. AACR 2017 advocated parafibromin immunostaining of parathyroid neoplasms in young patients.","sources":["cdc73GeneReviews","cdc73Wasserman"]},{"title":"Association evidence","text":"ClinGen classified autosomal dominant CDC73-related HPT-JT as definitive in 2019. AACR 2017 summarized about 80% truncating variants and detection in 50–75% of clinically diagnosed HPT-JT and 14% of familial isolated hyperparathyroidism. These historical diagnostic yields are not an individual carrier’s disease risk.","sources":["cdc73GeneReviews","cdc73Wasserman","cdc73Clingen"]}],"otherGenotype":{"title":"If both copies are affected","text":"If two germline CDC73 variants are reported, ask clinical genetics to confirm their classification and phase. No established separate constitutional biallelic risk estimate or care pathway was identified in the reviewed sources. Acquired loss of the remaining functional copy in a tumor is different from having two germline variants. Management should reflect the confirmed genotype and clinical findings.","sources":["cdc73GeneReviews","cdc73Clingen"]},"plans":{}},"CDH1":{"symbol":"CDH1","genotype":"Heterozygous","summary":"CDH1-related cancer predisposition primarily affects the stomach and, in women, the breast. Gastric risk varies substantially by family history and study population; prevention decisions require an experienced multidisciplinary team.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"gastric","name":"Gastric cancer, including early-stage findings","women":{"risk":"13–33%","relative":"Not quantified","horizon":"By age 80","citations":{"risk":["cdh1Roberts","cdh1Ryan"]}},"men":{"risk":"19–42%","relative":"Not quantified","horizon":"By age 80","citations":{"risk":["cdh1Roberts","cdh1Ryan"]}}},{"id":"gastric-advanced","name":"Advanced gastric cancer (study definition)","women":{"risk":"6.5%","relative":"HR 3.5 at age 70","horizon":"By age 80","citations":{"risk":["cdh1Ryan"],"relative":["cdh1Ryan"]}},"men":{"risk":"10.3%","relative":"HR 3.5 at age 70","horizon":"By age 80","citations":{"risk":["cdh1Ryan"],"relative":["cdh1Ryan"]}}},{"id":"breast","name":"Breast cancer (invasive)","women":{"risk":"37–55%","relative":"HR 3.9 at age 70","horizon":"By age 80","citations":{"risk":["cdh1Ryan","cdh1Roberts"],"relative":["cdh1Ryan"]}},"men":{"risk":"Not estimated","relative":"Not quantified"}},{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"4%","relative":"Not quantified","horizon":"By age 80","citations":{"risk":["cdh1Roberts"]}},"men":{"risk":"7%","relative":"Not quantified","horizon":"By age 80","citations":{"risk":["cdh1Roberts"]}}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"Experts disagree on how well endoscopy detects early diffuse gastric cancer, hence random biopsies and gastrectomy. The stage IA foci in most gastrectomy specimens are of uncertain significance. CDH1 predicts susceptibility, not stage or prognosis.","sources":["cdh1Ryan","cdh1Igclc","cancerPrognosis"]},{"title":"Costs of gastrectomy","text":"Removes most gastric cancer risk but affects eating, weight, vitamin and mineral levels, and bone, with lifelong follow-up. Limit to experienced centers with transparent outcome data and manage complications well.","sources":["cdh1Force","cdh1Igclc"]},{"title":"Association evidence","text":"ClinGen: Definitive. A carrier without a gastric cancer family history likely sits at the lower end of risk; exact variant and family history change management.","sources":["cdh1Clingen","cdh1Roberts","cdh1Xicola","cdh1Ryan"]}],"otherGenotype":{"title":"If both copies are affected","text":"The cited curation describes autosomal dominant CDH1-related cancer predisposition and does not quantify a biallelic cancer-risk scenario. Clinical genetics should verify both variants, their classifications and phase. Do not assume twice the risk or apply this cancer pathway to a variant classified only for a different CDH1-related condition.","sources":["cdh1Clingen"]},"plans":{}},"CDK4":{"symbol":"CDK4","genotype":"Heterozygous activating variant","summary":"Familial melanoma, from an activating variant almost always at codon 24 (p.Arg24Cys or p.Arg24His), clinically identical to CDKN2A melanoma: early onset, atypical nevi, multiple primaries. Only a few dozen families are known, so risk figures are imprecise.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"melanoma","name":"Cutaneous melanoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pancreatic","name":"Pancreatic cancer","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Affected members with multiple primaries more often carried MC1R red-hair-color variants.","sources":["cdk4Puntervoll"]},{"title":"Association evidence","text":"ClinGen: Definitive (2020). Codon 24 variants block p16 binding, making CDK4 constitutively active. No actionability report; surveillance is extrapolated from CDKN2A practice. NCCN names no CDK4 skin schedule; for CDKN2A it recommends dermatologist skin examination with total body photography and dermoscopy, interval not stated in a 2026 payer summary of NCCN.","sources":["cdk4Clingen","cdk4Leachman","cdk4NccnPolicy"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic condition or pathway is described; this plan assumes one copy. Refer to cancer genetics.","sources":["cdk4Clingen"]},"plans":{}},"CDKN1B":{"symbol":"CDKN1B","genotype":"Heterozygous","summary":"Multiple endocrine neoplasia type 4: a rare MEN1-like condition led by primary hyperparathyroidism and pituitary adenomas, with occasional pancreatic and other neuroendocrine tumors. About 50 affected people are reported; penetrance is unknown and surveillance is extrapolated from MEN1.","table":{"caption":"Endocrine tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"phpt","name":"Primary hyperparathyroidism","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pituitary","name":"Pituitary adenoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pnet","name":"Pancreatic neuroendocrine tumor","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"thyroid","name":"Papillary thyroid carcinoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"adrenal","name":"Adrenal tumor","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"thymic","name":"Thymic tumor","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ginet","name":"Gastrointestinal neuroendocrine tumor","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Rarer, usually later, and milder than MEN1, except pancreatic neuroendocrine tumors, nearly half metastatic at presentation. Two or more endocrine organs affected in 44%.","sources":["cdkn1bSingeisen","cdkn1bActionability"]},{"title":"Association evidence","text":"ClinGen: definitive, autosomal dominant; adult actionability moderate. Fewer than 1 in a million affected. Found in about 1.5–3.7% of MEN-type presentations without an MEN1 variant; many earlier cases were probably labeled MEN1.","sources":["cdkn1bClingen","cdkn1bActionability"]},{"title":"Variant types","text":"Mostly missense (44%) and frameshift (35%), spread across the gene, no hotspot.","sources":["cdkn1bSingeisen","cdkn1bBrandi"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan. No biallelic condition is established; a recessive link to hereditary nonpolyposis colon cancer is limited, with no surveillance implication. Have clinical genetics review two variants; apply this MEN4 plan at minimum, with standard colorectal screening.","sources":["cdkn1bClingenCrc","cdkn1bGeneReviews"]},"plans":{}},"CDKN2A":{"symbol":"CDKN2A","genotype":"Heterozygous","summary":"High risk of cutaneous melanoma, often multiple and early, and substantial pancreatic cancer risk. Smoking raises pancreatic risk and adds mouth, throat, and lung cancers.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"melanoma","name":"Cutaneous melanoma","women":{"risk":"28%","relative":"Not established","horizon":"By age 80","citations":{"risk":["cdkn2aBegg"]}},"men":{"risk":"28%","relative":"Not established","horizon":"By age 80","citations":{"risk":["cdkn2aBegg"]}}},{"id":"pancreatic","name":"Pancreatic cancer","women":{"risk":"58%","relative":"Not established","horizon":"By age 80 · family study","citations":{"risk":["cdkn2aMcwilliams"]}},"men":{"risk":"58%","relative":"Not established","horizon":"By age 80 · family study","citations":{"risk":["cdkn2aMcwilliams"]}}},{"id":"oral-pharynx","name":"Lip, mouth, and pharynx cancer","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"respiratory","name":"Lung and other respiratory cancer","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"neural","name":"Nervous system tumors (astrocytoma, nerve sheath tumors)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Melanomas often appear in the 30s and 40s, and multiple primaries are common. Pancreatic cancer is diagnosed earlier than in the general population. In the Dutch surveillance cohort, 83% of detected cancers were resectable; 5-year survival after resection 44.1% (95% CI 27.2–71.3%).","sources":["cdkn2aActionability","cdkn2aKlatte"]},{"title":"Association evidence","text":"ClinGen: Definitive (2019). Lip, mouth, pharynx, and lung associations come from one Dutch founder-variant cohort.","sources":["cdkn2aClingen","cdkn2aPotjer","cdkn2aGenomel"]},{"title":"Phenotype","text":"Some carriers have many nevi, often more than 50, and atypical nevi; a normal skin examination does not exclude the syndrome.","sources":["cdkn2aGeneReviews"]}],"otherGenotype":{"title":"If both copies are affected","text":"No separate management pathway is described in the sources reviewed. Refer to cancer genetics for an individual plan.","sources":["cdkn2aGeneReviews","cdkn2aClingen"]},"plans":{}},"CHEK2":{"symbol":"CHEK2","genotype":"Heterozygous · truncating variant","summary":"A truncating CHEK2 variant, most often c.1100delC, roughly doubles to triples breast cancer odds in women and is associated with prostate cancer in men. Common missense variants such as p.Ile157Thr carry much smaller risk.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"breast","name":"Breast cancer","women":{"risk":"25%","relative":"OR 2.54","horizon":"Lifetime estimate","citations":{"risk":["chek2Acmg"],"relative":["chek2Bcac"]}},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"prostate","name":"Prostate cancer (c.1100delC)","women":null,"men":{"risk":"Not established","relative":"OR 3.29","citations":{"relative":["chek2Prostate"]}}},{"id":"kidney","name":"Kidney cancer","women":{"risk":"Not established","relative":"OR 2.57","citations":{"relative":["chek2Ambry"]}},"men":{"risk":"Not established","relative":"OR 2.57","citations":{"relative":["chek2Ambry"]}}},{"id":"thyroid","name":"Thyroid cancer","women":{"risk":"Not established","relative":"OR 1.63","citations":{"relative":["chek2Ambry"]}},"men":{"risk":"Not established","relative":"OR 1.63","citations":{"relative":["chek2Ambry"]}}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"CHEK2-associated breast cancers are predominantly ER-positive. After a first breast cancer, contralateral risk varies with age, menopause and treatment. FORCE quotes an uncertain 6–8% risk within 10 years without bilateral mastectomy; the CARRIERS study summarized in ACMG estimated about 13% in premenopausal and 4% in postmenopausal carriers. These are conditional risks from different study groups, not risks for an unaffected carrier.","sources":["chek2Carriers","chek2Bcac","chek2ForceRisk","chek2Acmg"]},{"title":"Association evidence","text":"Breast and prostate associations are the most consistent. Colorectal evidence conflicts: revised c.1100delC OR 1.8 (95% CI 1.2–2.7) against OR 0.62 (95% CI 0.51–0.76) in the US testing cohort. Pancreatic: no significant association (OR 1.31, 95% CI 0.91–1.83). Stomach: OR 2.1 for truncating variants, unconfirmed. No ovarian association has been shown.","sources":["chek2Acmg","chek2Ambry","chek2ForceRisk","chek2Pancreas"]},{"title":"Treatment if cancer develops","text":"Use cancer-specific oncology care. CHEK2 alone does not establish benefit from a targeted drug, but it appears in specified FDA HRR gene lists. For eligible HRR-mutated metastatic castration-resistant prostate cancer, labeling includes olaparib after progression on enzalutamide or abiraterone, and talazoparib in combination with enzalutamide. For olaparib, the label requires an FDA-approved companion diagnostic; the listed CHEK2 indication uses tumor testing. Patients require concurrent GnRH therapy or prior bilateral orchiectomy. Confirm all current eligibility criteria with oncology; eligibility is not a guarantee of CHEK2-specific benefit. CHEK2 alone is not a reason to withhold radiotherapy or routinely perform contralateral mastectomy.","sources":["chek2Acmg","fdaOlaparib","fdaTalazoparib"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm that both variants are disease-relevant and in trans with clinical genetics; variants in cis also require interpretation as a combined allele. Biallelic CHEK2 can confer higher breast risk. A selected study of 31 biallelic women reported OR 8.69 (95% CI 3.69–20.47) for ductal invasive breast cancer, compared with 2.02 for monoallelic carriers; this is not an absolute penetrance estimate. A uniform biallelic management guideline is not established, and eviQ excludes these patients from its monoallelic protocol. Arrange an individualized genetics and high-risk breast plan.","sources":["chek2Acmg","chek2Eviq","chek2Rainville"]},"plans":{}},"COL3A1":{"symbol":"COL3A1","genotype":"Heterozygous","summary":"Vascular Ehlers-Danlos syndrome: arteries, colon, and pregnant uterus can rupture without warning, often in young adults and often without prior dilation. Null variants run a milder, later course, but none is risk-free.","table":{"caption":"Arterial, bowel, and pregnancy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"first-complication","name":"First major complication (arterial, bowel, or organ rupture)","women":{"risk":">80%","relative":"Not established","horizon":"By age 40 · clinical cohort","citations":{"risk":["col3a1Pepin2000"]}},"men":{"risk":">80%","relative":"Not established","horizon":"By age 40 · clinical cohort","citations":{"risk":["col3a1Pepin2000"]}}},{"id":"arterial-lesion","name":"Arterial aneurysm, dissection, or rupture, any site","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"aortic-iliac","name":"Aortic, iliac, or visceral artery disease","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cervical","name":"Cervical or other supra-aortic artery lesion","women":{"risk":"42%","relative":"Not established","horizon":"By age 40 · clinical cohort","citations":{"risk":["col3a1Cervical"]}},"men":{"risk":"42%","relative":"Not established","horizon":"By age 40 · clinical cohort","citations":{"risk":["col3a1Cervical"]}}},{"id":"colon","name":"Colonic perforation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lung","name":"Pneumothorax, hemothorax, or hemoptysis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pregnancy-death","name":"Pregnancy-related death, per delivery","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"uterine","name":"Uterine rupture, per delivery","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"death","name":"Death from any cause","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"ClinGen severity 3: sudden death a reasonable possibility.","sources":["col3a1Pepin2000","col3a1Pepin2014","col3a1ClinGenAction"]},{"title":"Diagnosis","text":"Requires molecular confirmation. About 50% have an affected parent. Thin translucent skin, easy bruising, and characteristic facies are often subtle or absent, especially with null variants (minor features absent in 51% of null-variant carriers).","sources":["col3a1GeneReviews","col3a1Malfait","col3a1ClinGenAction"]},{"title":"Association evidence","text":"ClinGen: Definitive (autosomal dominant, 2019), haploinsufficiency sufficient; actionability moderate, with poor effectiveness evidence partly extrapolated from Marfan syndrome.","sources":["col3a1ClinGenGene","col3a1ClinGenAction"]},{"title":"Medical therapy evidence","text":"BBEST was open, stopped early, and only 33 of 53 had a confirmed COL3A1 variant. Observational data are mixed: better survival with celiprolol and at 400 mg per day in France (P = 0.0004 and P = 0.003); 4.7% yearly major events in Sweden; 8.8% yearly symptomatic events on treatment in Italy. A 2025 placebo-controlled trial supports adding irbesartan to celiprolol. ESC 2024 rates celiprolol class IIa, level B.","sources":["col3a1Bbest","col3a1Frank","col3a1Sweden","col3a1Italy","col3a1Irbesartan","col3a1Esc2024"]}],"otherGenotype":{"title":"If both copies are affected","text":"Rare (under 1%). A homozygous null variant caused severe recessive EDS with unaffected heterozygous parents; compound heterozygous siblings had vEDS with aortic dissection death at 15 years and polymicrogyria. Other biallelic families had cobblestone-like cortical malformation, seizures, and developmental delay. Refer to clinical genetics and neurology, apply at least the vEDS precautions, and test both parental lines.","sources":["col3a1Plancke","col3a1Jorgensen","col3a1Horn","col3a1ClinGenGene","col3a1ClinGenAction"]},"plans":{}},"COL5A1":{"symbol":"COL5A1","genotype":"Heterozygous","summary":"Classical Ehlers-Danlos syndrome: fragile, stretchy skin with wide atrophic scars, easy bruising, and loose joints. Aortic root dilation is uncommon and mild; arterial dissection or rupture is rare but reported almost only with COL5A1.","table":{"caption":"Skin, joint, and cardiovascular features","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"scarring","name":"Widened atrophic scarring","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hyperextensibility","name":"Skin hyperextensibility","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"bruising","name":"Easy bruising","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hypermobility","name":"Generalized joint hypermobility","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dislocation","name":"Joint subluxation or dislocation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mvp","name":"Mitral valve prolapse","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"aortic-root","name":"Aortic root dilation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"arterial","name":"Arterial dissection, aneurysm, or rupture","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Mostly skin and joint morbidity; life expectancy unaffected except for rare arterial rupture. ClinGen severity 2 of 3.","sources":["col5a1ClinGenAction"]},{"title":"Diagnosis","text":"Minimal criteria for suspicion: hyperextensibility with atrophic scarring plus either generalized joint hypermobility or 3 minor criteria. Both major criteria were met by 49% in one Italian cohort and 85.6% in a Belgian referral cohort; a confirmed carrier may not look classic.","sources":["col5a1Malfait","col5a1Ritelli","col5a1Colman","col5a1Bowen"]},{"title":"Association evidence","text":"ClinGen: Definitive (autosomal dominant, 2021), haploinsufficiency sufficient; actionability moderate (2025), effectiveness evidence poor.","sources":["col5a1ClinGenGene","col5a1ClinGenAction"]},{"title":"Variant type","text":"Mostly null alleles; collagenous-domain missense variants and exon deletions also occur. No genotype-phenotype correlation beyond the arterial associations. Cardiovascular findings are treated in the standard way.","sources":["col5a1Ritelli","col5a1ClinGenGene","col5a1GeneReviews"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the heterozygous plan above. Rare and not well defined. A boy homozygous for p.Gly530Ser had mild classical EDS; his heterozygous parents were clinically mild or unaffected (soft skin in the mother) with ultrastructural collagen changes. Recessive classical EDS from variants in an alternatively spliced exon is reported. Refer to clinical genetics, use at least the plan above, and test both parental lines.","sources":["col5a1Giunta","col5a1Recessive"]},"plans":{}},"COL5A2":{"symbol":"COL5A2","genotype":"Heterozygous","summary":"Classical Ehlers-Danlos syndrome, often more severe than with COL5A1: fragile, stretchy skin with wide atrophic scars, easy bruising, and loose joints. Aortic root dilation is uncommon and mild; arterial rupture is not reported with COL5A2 in published series.","table":{"caption":"Skin, joint, and cardiovascular features","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"scarring","name":"Widened atrophic scarring","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hyperextensibility","name":"Skin hyperextensibility","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"bruising","name":"Easy bruising","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hypermobility","name":"Generalized joint hypermobility","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dislocation","name":"Joint subluxation or dislocation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mvp","name":"Mitral valve prolapse","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"aortic-root","name":"Aortic root dilation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"arterial","name":"Arterial dissection, aneurysm, or rupture","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Mostly skin and joint morbidity; life expectancy unaffected; rare arterial rupture in classical EDS has been reported only with COL5A1. COL5A2 variants often caused a more severe phenotype in a Belgian referral cohort, and the most severely affected patient in the Italian cohort had a COL5A2 variant that alters the protein. ClinGen severity 2 of 3.","sources":["col5a2ClinGenAction","col5a2Ritelli","col5a2Colman","col5a2Dhondt"]},{"title":"Diagnosis","text":"Minimal criteria for suspicion: hyperextensibility with atrophic scarring plus either generalized joint hypermobility or 3 minor criteria. Both major criteria were met by 49% in one Italian cohort and 85.6% in a Belgian referral cohort; a confirmed carrier may not look classic.","sources":["col5a2Malfait","col5a2Ritelli","col5a2Colman","col5a2Bowen"]},{"title":"Variant type","text":"Missense and in-frame splice variants acting in a dominant-negative way are the usual COL5A2 mechanism, unlike the null alleles that predominate in COL5A1; this is why a null COL5A2 result needs review.","sources":["col5a2Ritelli","col5a2ClinGenGene"]},{"title":"Association evidence","text":"ClinGen: Definitive (autosomal dominant, 2021); actionability moderate (2025), effectiveness evidence poor. No haploinsufficiency evidence (January 2026). Cardiovascular findings are treated in the standard way.","sources":["col5a2ClinGenGene","col5a2ClinGenAction","col5a2GeneReviews"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the heterozygous plan above. No biallelic COL5A2 condition is established. Refer to clinical genetics, use at least the plan above, and test both parental lines.","sources":["col5a2ClinGenGene","col5a2GeneReviews"]},"plans":{}},"CRYAB":{"symbol":"CRYAB","genotype":"Heterozygous","summary":"Myofibrillar myopathy, cardiomyopathy (dilated, restrictive, or hypertrophic), early cataract, or late-onset axonal neuropathy, alone or together, depending on the variant. Evidence is sparse; no gene-specific risk figure exists.","table":{"caption":"Muscle, heart, eye, and nerve risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"mfm","name":"Myofibrillar myopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dcm","name":"Dilated cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"rcm","name":"Restrictive cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hcm","name":"Hypertrophic cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cataract","name":"Cataract, pediatric onset","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"neuropathy","name":"Axonal sensorimotor neuropathy (CMT2)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Association evidence","text":"No ClinGen validity curation for cardiomyopathy or myopathy; not on the ACMG secondary findings list. Cardiac and muscle associations rest on families and case reports; variants at codon 109 range from cataract to isolated myopathy to cardiomyopathy.","sources":["cryabReview","cryabCataract"]},{"title":"Inheritance","text":"Mostly autosomal dominant, including heterozygous C-terminal truncating variants that act in a dominant-negative way. Biallelic variants that abolish the protein cause recessive fatal infantile hypertonic myofibrillar myopathy.","sources":["cryabGeneReviews","cryabReview","cryabSelcen","cryabFihmm"]},{"title":"If disease develops","text":"Manage by phenotype: heart failure and rhythm care, neuromuscular care with pulmonary function testing, cataract surgery when vision requires it. A pacemaker or ICD for arrhythmia or conduction disease and transplant for progressive cardiomyopathy were advised across myofibrillar myopathy genes (retired GeneReviews, 2012); device and transplant decisions follow current cardiomyopathy guidelines.","sources":["cryabGeneReviews","cryabAan","cryabEscComment"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the plan above. Biallelic loss-of-function CRYAB variants, and rarely biallelic missense or start-loss variants, cause fatal infantile hypertonic myofibrillar myopathy: progressive muscle stiffness and respiratory failure in infancy; about 18 cases reported. The plan above does not cover it. Refer to clinical genetics and a neuromuscular center. Each further child of two carriers has a 1 in 4 chance of being affected.","sources":["cryabGeneReviews","cryabFihmm"]},"plans":{}},"CSRP3":{"symbol":"CSRP3","genotype":"Heterozygous","summary":"Semidominant hypertrophic cardiomyopathy: one copy tends to give milder, later-onset disease; two copies more severe disease. The only penetrance estimate is about 38% in relatives found by cascade screening, from fewer than 50 carriers, and the dilated cardiomyopathy link is limited.","table":{"caption":"Cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"hcm","name":"Hypertrophic cardiomyopathy","women":{"risk":"38%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["csrp3Topriceanu"]}},"men":{"risk":"38%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["csrp3Topriceanu"]}}},{"id":"dcm","name":"Dilated cardiomyopathy (ClinGen Limited)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"HCM can cause atrial fibrillation, heart failure, and sudden death. Whether other heterozygous variants behave like p.Cys150Tyr is not established.","sources":["csrp3Aha2024","csrp3Salazar"]},{"title":"Association evidence","text":"ClinGen: Definitive for semidominant HCM (August 2023, upgraded from Moderate); Limited for DCM. The 2024 US guideline lists 8 strong-evidence sarcomere genes; HRS/EHRA 2022 lists CSRP3 as moderate evidence. Both guidelines’ evidence reviews predate the 2023 ClinGen upgrade. Carrier recommendations apply by extension.","sources":["csrp3ClingenHcm","csrp3ClingenDcm","csrp3Aha2024","csrp3Hrs2022"]},{"title":"One copy versus two","text":"Homozygous truncating variants are reported in at least 3 unrelated HCM patients. A 2018 review found only one heterozygous variant meeting likely pathogenic criteria; ClinGen counted 12 heterozygous predicted null variants. How often a single truncating variant causes disease is not established.","sources":["csrp3ClingenHcm","csrp3Janin","csrp3Lipari"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan above. Homozygous or compound heterozygous variants cause more severe or earlier HCM; numbers are too small for estimates. The plan on this page does not apply to two copies; both parents are usually carriers. Refer to an inherited cardiomyopathy center at diagnosis. Each sibling has a 1 in 4 chance of two copies; test both parental lines.","sources":["csrp3ClingenHcm","csrp3Janin","csrp3Lipari","csrp3Salazar"]},"plans":{}},"DES":{"symbol":"DES","genotype":"Heterozygous","summary":"Dilated, restrictive, or arrhythmogenic cardiomyopathy with atrioventricular block, often with slowly progressive skeletal myopathy. Cardiac disease usually starts in the 30s and can precede weakness.","table":{"caption":"Cardiac and muscle risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"any-cardiac","name":"Any cardiac involvement (cardiomyopathy or major cardiac event)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cardiomyopathy","name":"Cardiomyopathy, any type","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"conduction","name":"Conduction disease (mostly AV block needing a device)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"heart-failure","name":"Heart failure event (hospitalization, LVAD or transplant, or death)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"sustained-va","name":"Sustained ventricular arrhythmia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"atrial-fibrillation","name":"Atrial fibrillation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"skeletal","name":"Skeletal muscle involvement","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Death from complete heart block, ventricular arrhythmia, or heart failure. 11.3% of 230 carriers had died (8.3% cardiovascular) at a median age of 40 years; a quarter of 159 at a mean age of 49 years.","sources":["desAsatryan","desVanSpaendonck","desBermudez"]},{"title":"Age at onset","text":"Onset ranges from the first to the seventh decade; 22.5% of probands were first seen before age 18 years.","sources":["desClingenMfm","desAsatryan"]},{"title":"Variant location","text":"2B rod domain variants predominated in isolated muscle disease, head and tail variants in isolated heart disease; ClinGen judges these correlations not yet useful clinically.","sources":["desVanSpaendonck","desClingenMfm"]},{"title":"Association evidence","text":"ClinGen: Definitive for dilated cardiomyopathy (March 2026); Moderate for ARVC (2018). ACMG secondary findings list (v3.3). ESC 2023 lists desminopathy among causes of AV block with cardiomyopathy. HRS 2019 called early arrhythmia uncommon; later pooled data show frequent conduction disease and ventricular arrhythmia.","sources":["desClingenValidity","desClingenArvc","desAcmgSf","desEsc2023","desHrs2019","desAsatryan"]},{"title":"If cardiomyopathy develops","text":"Device decisions weigh conduction disease and ventricular arrhythmia together; refer for transplant in advanced or restrictive disease.","sources":["desClingenDcm","desClingenMfm","desGeneReviews"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan above. Homozygous and compound heterozygous cases start earlier and progress faster, while heterozygous relatives were unaffected; this plan does not apply. Refer to cardiology and a neuromuscular center. Confirm with genetics whether a heterozygous carrier of a recessive-acting variant needs surveillance.","sources":["desClingenMfm"]},"plans":{}},"DICER1":{"symbol":"DICER1","genotype":"Heterozygous","summary":"Thyroid nodules, thyroid cancer, and, in women, ovarian sex cord-stromal tumors. Most carriers stay healthy; the dangerous childhood tumors are past for an adult.","table":{"caption":"Tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"any-neoplasm","name":"Any DICER1-related tumor, benign or malignant","women":{"risk":"26.5%","relative":"Not established","horizon":"By age 50","citations":{"risk":["dicer1Stewart"]}},"men":{"risk":"10.2%","relative":"Not established","horizon":"By age 50","citations":{"risk":["dicer1Stewart"]}}},{"id":"goiter","name":"Multinodular goiter or thyroidectomy","women":{"risk":"75%","relative":"9.4×","horizon":"By age 40","citations":{"risk":["dicer1Khan"],"relative":["dicer1Khan"]}},"men":{"risk":"17%","relative":"Not established","horizon":"By age 40","citations":{"risk":["dicer1Khan"]}}},{"id":"thyroid-cancer","name":"Differentiated thyroid cancer","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ovarian-scst","name":"Ovarian Sertoli-Leydig cell and other sex cord-stromal tumors","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"cervical-erms","name":"Embryonal rhabdomyosarcoma of the cervix","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"lung","name":"Lung cysts and pleuropulmonary blastoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"childhood-other","name":"Other childhood tumors: kidney, eye, pituitary, pineal, nasal","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Most carriers remain unaffected; thyroid cancers have been low stage and indolent. Pleuropulmonary blastoma 5-year survival: 91% for type I, 53–71% for types II and III.","sources":["dicer1GeneReviews","dicer1Registry2024","dicer1Actionability"]},{"title":"Association evidence","text":"Germline variants are found in about two thirds of pleuropulmonary blastomas and more than half of Sertoli-Leydig cell tumors.","sources":["dicer1Actionability","dicer1GeneReviews"]},{"title":"Which variants count","text":"Loss-of-function germline variants. Mosaic hotspot missense variants in the RNase IIIb domain may warrant more intensive surveillance; refer to clinical genetics.","sources":["dicer1GeneReviews","dicer1Schultz2018"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic condition is described in the sources reviewed; tumors carry the inherited variant plus a tumor-specific second hit. Mosaic hotspot variants are a different situation for clinical genetics; this page is written for one inherited copy.","sources":["dicer1GeneReviews","dicer1Schultz2018"]},"plans":{}},"DMD":{"symbol":"DMD","genotype":"X-linked · Hemizygous men, heterozygous women","summary":"Men found on a panel usually have Becker-type muscular dystrophy or a dystrophin cardiomyopathy with little weakness. Carrier women rarely have weakness but carry a lifelong dilated cardiomyopathy risk that rises with age.","table":{"caption":"Cardiac and muscle risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"cardiomyopathy","name":"Cardiac involvement","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lv-dilation","name":"Left ventricular dilation without cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"fibrosis","name":"Myocardial fibrosis on cardiac MRI","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"weakness","name":"Skeletal muscle weakness","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ambulation","name":"Loss of independent walking","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Becker: mean age at death 55.6 years (SD 19.4) among men who died (13 men in 8 studies). Carrier women rarely die of heart disease, but heart failure and sudden deaths (2.6–4% in two series) and transplants in women in their twenties are reported, sometimes after pregnancy.","sources":["dmdMickle","dmdCarrierReview"]},{"title":"Phenotype spectrum","text":"Heart and muscle involvement do not run in parallel; cardiomyopathy can lead in mild Becker disease.","sources":["dmdGeneReviews","dmdMickle","dmdCarrierReview"]},{"title":"Association evidence","text":"ClinGen: Definitive for progressive muscular dystrophy including Duchenne, Becker, and DCM 3B (November 2024), haploinsufficiency sufficient. DMD-related DCM strongly actionable (August 2025).","sources":["dmdClinGen","dmdClinGenDcm"]},{"title":"Why carrier women differ","text":"Expression tracks X inactivation. Variant type does not predict a woman's heart risk.","sources":["dmdCarrierReview","dmdHoogerwaardNmd"]},{"title":"Treatment if cardiomyopathy develops","text":"Standard heart failure therapy. In Duchenne, eplerenone slowed decline in myocardial strain in a randomized trial; ventricular assist devices and, case by case, transplantation. Evidence in carrier women is observational.","sources":["dmdBirnkrant2","dmdCarrierReview"]}],"otherGenotype":{"title":"If a woman has two affected copies","text":"Two DMD variants, or one with an X-autosome translocation or Turner syndrome, can cause male-type disease. Rare. The carrier figures above underestimate her risk. Refer to neuromuscular care and cardiology and use the men's plan under their direction.","sources":["dmdCarrierReview","dmdGeneReviews"]},"plans":{}},"DSC2":{"symbol":"DSC2","genotype":"Heterozygous","summary":"An established but uncommon cause of arrhythmogenic cardiomyopathy; single-copy penetrance is not established. Truncating variants are strongly enriched in ARVC cases; founder variants such as p.Gln554* and p.Asp179Gly cause severe biventricular disease mainly with two copies, and single-copy relatives in the p.Asp179Gly families were asymptomatic.","table":{"caption":"Arrhythmogenic cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"acm-dsc2","name":"Arrhythmogenic cardiomyopathy, DSC2 single copy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"arvc-pooled-rel","name":"Definite ARVC, any ARVC gene (pooled)","women":{"risk":"2%","relative":"Not established","horizon":"At assessment · carriers","citations":{"risk":["dsc2Carruth"]}},"men":{"risk":"2%","relative":"Not established","horizon":"At assessment · carriers","citations":{"risk":["dsc2Carruth"]}}},{"id":"va-pooled-rel","name":"Sustained ventricular arrhythmia, any ARVC gene (pooled)","women":{"risk":"11%","relative":"Not established","horizon":"At assessment · carriers","citations":{"risk":["dsc2Groeneweg"]}},"men":{"risk":"11%","relative":"Not established","horizon":"At assessment · carriers","citations":{"risk":["dsc2Groeneweg"]}}},{"id":"va-pooled","name":"Ventricular arrhythmia diagnosis, any ARVC gene (pooled)","women":{"risk":"1.7%","relative":"Not established","horizon":"At assessment · ARVC genes pooled","citations":{"risk":["dsc2Bourfiss"]}},"men":{"risk":"1.7%","relative":"Not established","horizon":"At assessment · ARVC genes pooled","citations":{"risk":["dsc2Bourfiss"]}}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"No DSC2-specific single-copy outcome. In a mostly DSG2, proband-heavy cohort (17 of 271 DSC2), single-variant carriers met ARVC criteria in 64.8% versus 96.2% with multiple variants; multiple-variant carriers had more end-stage heart failure and malignant arrhythmias.","sources":["dsc2Gerull","dsc2Lorenzon","dsc2Chen"]},{"title":"Association evidence","text":"ClinGen: Definitive for autosomal dominant ARVC (2018), with recessive-pattern pedigrees in specific populations; no recessive curation. ARVC actionability moderate.","sources":["dsc2ClinGen","dsc2James2021","dsc2ClinGenAction"]},{"title":"Treatment if disease develops","text":"Beta-blockers are reasonable in ACM without an ICD (class 2a); antiarrhythmics, ablation, and ICDs are specialist decisions.","sources":["dsc2Hrs"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance above. Early-onset, often severe disease with prominent LV involvement: homozygous p.Gln554* with mainly left-sided aneurysms and sudden death (Hutterite); homozygous p.Asp179Gly with severe biventricular disease (4 Italian probands); a homozygous frameshift with mild keratoderma and woolly hair. One homozygous deletion arose by uniparental isodisomy, so a parent need not carry it. The plan above does not describe biallelic carriers: refer to an inherited cardiac disease center; test siblings and both parental lines.","sources":["dsc2Gerull","dsc2Lorenzon","dsc2Simpson","dsc2Brodehl"]},"plans":{}},"DSG2":{"symbol":"DSG2","genotype":"Heterozygous","summary":"DSG2 variants cause arrhythmogenic cardiomyopathy that is often biventricular, with more left ventricular involvement and heart failure than PKP2 disease. One variant usually causes milder disease than two DSG2 variants or a second desmosomal variant.","table":{"caption":"Arrhythmogenic cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"acm","name":"Arrhythmogenic cardiomyopathy phenotype","women":{"risk":"42%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["dsg2Pinci"]}},"men":{"risk":"42%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["dsg2Pinci"]}}},{"id":"sustained-va","name":"Sustained ventricular arrhythmia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lv","name":"Left ventricular involvement","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"va-pooled","name":"Ventricular arrhythmia diagnosis, any ARVC gene (pooled)","women":{"risk":"1.7%","relative":"Not established","horizon":"At assessment · ARVC genes pooled","citations":{"risk":["dsg2Bourfiss"]}},"men":{"risk":"1.7%","relative":"Not established","horizon":"At assessment · ARVC genes pooled","citations":{"risk":["dsg2Bourfiss"]}}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Association evidence","text":"ClinGen: definitive for autosomal dominant ARVC (2018), limited for dilated cardiomyopathy (2026); some pedigrees show multiple DSG2 variants and recessive inheritance. Adult actionability for ARVC is moderate.","sources":["dsg2ClinGen","dsg2James2021","dsg2ClinGenAction"]},{"title":"Variant type","text":"Most DSG2 variants in affected carriers are missense (66.8% in the 271-carrier cohort), clustering in the calcium-binding extracellular domains, the furin cleavage site, and the PKP2-binding region. About 5% of reported variants have been seen homozygous.","sources":["dsg2Chen","dsg2Pinci"]},{"title":"Treatment if disease develops","text":"HRS finds beta-blockers reasonable in ACM without an ICD (class 2a).","sources":["dsg2Hrs"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance above. Two DSG2 variants cause earlier, more severe disease: onset in adolescence or early adulthood, near-complete penetrance, biventricular involvement, severe arrhythmias, and sometimes heart failure needing transplantation. Padua cohort: 4% homozygous, 9% compound heterozygous. The heterozygous plan is the minimum: refer to an inherited cardiac disease center for closer surveillance and arrhythmic risk assessment, and test both parental lines.","sources":["dsg2Pinci","dsg2Chen","dsg2Fu"]},"plans":{}},"DSP":{"symbol":"DSP","genotype":"Heterozygous","summary":"DSP variants cause an arrhythmogenic cardiomyopathy that more often scars the left ventricle than the right and can flare with chest pain and troponin rise that mimic myocarditis. Arrhythmia and heart failure risk exceeds PKP2, women are not protected, and ARVC criteria miss many cases.","table":{"caption":"Arrhythmogenic cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"any-cm","name":"Any DSP cardiomyopathy (ARVC, dilated, or non-dilated LV)","women":{"risk":"6.8%","relative":"Not established","horizon":"At assessment · population carriers","citations":{"risk":["dspGurumoorthi"]}},"men":{"risk":"6.8%","relative":"Not established","horizon":"At assessment · population carriers","citations":{"risk":["dspGurumoorthi"]}}},{"id":"definite-arvc","name":"Definite ARVC (2010 Task Force Criteria)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"sustained-va","name":"Sustained ventricular arrhythmia or sudden cardiac death","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"injury","name":"Myocarditis-like myocardial injury episode","women":{"risk":"4.5%","relative":"Not established","horizon":"At assessment · population carriers","citations":{"risk":["dspGurumoorthi"]}},"men":{"risk":"4.5%","relative":"Not established","horizon":"At assessment · population carriers","citations":{"risk":["dspGurumoorthi"]}}},{"id":"hf","name":"Heart failure hospitalization","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"va-pooled","name":"Ventricular arrhythmia diagnosis, any ARVC gene (pooled)","women":{"risk":"1.7%","relative":"Not established","horizon":"At assessment · ARVC genes pooled","citations":{"risk":["dspBourfiss"]}},"men":{"risk":"1.7%","relative":"Not established","horizon":"At assessment · ARVC genes pooled","citations":{"risk":["dspBourfiss"]}}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Association evidence","text":"ClinGen: definitive for autosomal dominant arrhythmogenic cardiomyopathy with woolly hair and keratoderma (2025), lumping ARVD8, Carvajal-type dilated cardiomyopathy, and striate palmoplantar keratoderma; the cardiac disease lies between dilated cardiomyopathy and ARVC. Adult actionability for ARVC is moderate.","sources":["dspClinGen","dspClinGenCuration","dspClinGenAction"]},{"title":"Variant type","text":"Most pathogenic variants are truncating (82.4%; 8.1% splice, 9.5% missense). Among loss-of-function variants, predicted nonsense-mediated decay independently marked arrhythmic risk. Population cardiomyopathy rises with stricter classification: 1.4% predicted-deleterious, 5.4% predicted loss-of-function, 6.8% ClinVar pathogenic.","sources":["dspGasperetti","dspGurumoorthi"]},{"title":"Treatment if disease develops","text":"Standard heart failure therapy for LV dysfunction. HRS finds beta-blockers reasonable in ACM without an ICD (class 2a).","sources":["dspHrs"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance above. Biallelic DSP causes Carvajal syndrome: striate keratoderma, woolly hair, and dilated LV cardiomyopathy with heart failure in the teenage years, first described in 3 Ecuadorian families homozygous for one truncating variant. A 2026 family with a homozygous nonsense variant had biventricular disease and two childhood sudden deaths; the parents were heterozygous. Skin fragility–woolly hair syndrome and lethal acantholytic epidermolysis bullosa are other recessive DSP disorders, outside the ClinGen cardiomyopathy curation. For a heterozygous carrier the point is reproductive: if a partner also carries a DSP variant, refer to clinical genetics before conception.","sources":["dspNorgett","dspAlMutairi","dspClinGenCuration"]},"plans":{}},"EGFR":{"symbol":"EGFR","genotype":"Heterozygous activating variant","summary":"A germline activating EGFR variant, principally p.Thr790Met (T790M), causes inherited lung adenocarcinoma, including in never smokers. Loss-of-function variants do not carry this risk.","table":{"caption":"Lung cancer risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"lung","name":"Lung cancer, activating variant carriers","women":{"risk":"52%","relative":"Not established","horizon":"By age 60 · ascertained families","citations":{"risk":["egfrOxnard"]}},"men":{"risk":"52%","relative":"Not established","horizon":"By age 60 · ascertained families","citations":{"risk":["egfrOxnard"]}}},{"id":"lung-never","name":"Lung cancer, never smokers","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lung-ever","name":"Lung cancer, ever smokers","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Association evidence","text":"ClinGen: Definitive for autosomal dominant non-small cell lung cancer (July 2020), gain-of-function mechanism. Strongest for p.Thr790Met; p.Val843Ile and p.Arg776His rest on limited data.","sources":["egfrClingen"]},{"title":"Tumor and imaging features","text":"35 of 37 carrier lung cancers (95%) had an additional somatic EGFR driver. Nodules can appear in the third decade and stay stable for years. Of 46 tumors with T790M at diagnosis, before any EGFR inhibitor, 24 (52%) were germline.","sources":["egfrOxnard"]},{"title":"Frequency and founder effect","text":"About 1 in 15,850 overall and 1 in 2,078 in parts of Southern Appalachia, from a founder about 200–225 years ago; INHERIT estimated a shared haplotype at 223–279 years, enriched in the Southeast US.","sources":["egfrHealio","egfrAscoPost","egfrOxnard"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance on this page. Two loss-of-function variants cause neonatal inflammatory skin and bowel disease 2: skin, bowel, and lung inflammation, recurrent infections, and early death; the first reported child was homozygous and his heterozygous mother unaffected. If both partners carry one, each child has a 1 in 4 chance; offer preconception counseling. No data exist for two activating variants; refer to clinical genetics.","sources":["egfrCampbell"]},"plans":{}},"EMD":{"symbol":"EMD","genotype":"X-linked · Hemizygous men, heterozygous women","summary":"EMD variants cause X-linked Emery-Dreifuss muscular dystrophy in men: early contractures, slow humeroperoneal weakness, and heart disease from atrial arrhythmia and AV block to ventricular arrhythmia, heart failure, and sudden death. Carrier women rarely have muscle findings, but many develop atrial arrhythmia or conduction disease after about age 50 years.","table":{"caption":"Cardiac and muscle risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"any-cardiac","name":"Any cardiac disease","women":{"risk":"43%","relative":"Not established","horizon":"At last follow-up · carrier relatives","citations":{"risk":["emdCannie"]}},"men":{"risk":"Not established","relative":"Not established"}},{"id":"af","name":"Atrial fibrillation or flutter","women":{"risk":"24%","relative":"Not established","horizon":"At last follow-up · carrier relatives","citations":{"risk":["emdCannie"]}},"men":{"risk":"Not established","relative":"Not established"}},{"id":"conduction","name":"Conduction disease needing pacing","women":{"risk":"10%","relative":"Not established","horizon":"At last follow-up · carrier relatives","citations":{"risk":["emdCannie"]}},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lvsd","name":"Left ventricular systolic dysfunction","women":{"risk":"14%","relative":"Not established","horizon":"At last follow-up · carrier relatives","citations":{"risk":["emdCannie"]}},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mva","name":"Malignant ventricular arrhythmia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"eshf","name":"End-stage heart failure","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"stroke","name":"Stroke","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"neuromuscular","name":"Contractures or muscle weakness","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Heart disease dominates the course; sudden death can be the first sign, even with a pacemaker. 3 of 38 men died over a median 65 months.","sources":["emdClinGenAct","emdCannie","emdElkoush"]},{"title":"Association evidence","text":"EMD causes about 61% of X-linked EDMD. No ClinGen gene-disease validity curation; ClinGen adult actionability rates EDMD from EMD as limited (2017, under revision).","sources":["emdClinGenAct","emdClinGen"]},{"title":"Pacemaker or ICD","text":"Older practice offered a pacemaker alone unless ventricular arrhythmia was documented; a 2022 genetic testing consensus still describes preventive pacemaker implantation for conduction defects in DCM with EMD-related muscular dystrophy. The 2022 HRS neuromuscular statement and the Cannie cohort favor an ICD with pacing whenever pacing is needed.","sources":["emdCannie","emdWilde","emdHrs2022"]},{"title":"Course in men","text":"Contractures, then humeroperoneal weakness; cardiac involvement usually after the second decade. Italian cohort: mean onset 12.0 years.","sources":["emdGeneReviews","emdElkoush"]}],"otherGenotype":{"title":"If a woman has two affected copies","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the women's plan. Not described; no separate pathway. Lacking a normal copy, she should be managed on the men's plan under neuromuscular and electrophysiology care.","sources":["emdGeneReviews"]},"plans":{}},"ENG":{"symbol":"ENG","genotype":"Heterozygous","summary":"ENG variants cause hereditary hemorrhagic telangiectasia type 1: nosebleeds, telangiectasia, and arteriovenous malformations in the lungs, brain, and liver. ENG has the highest rates of pulmonary and brain malformations, which cause stroke, abscess, or hemorrhage, so screen even when only nosebleeds are present.","table":{"caption":"Bleeding and vascular malformation frequency","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"epistaxis","name":"Recurrent nosebleeds","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"telangiectasia","name":"Mucocutaneous telangiectasia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pavm","name":"Pulmonary AVM","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"brain","name":"Brain vascular malformation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"liver","name":"Liver vascular malformation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"gi","name":"GI vascular malformation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"spinal","name":"Spinal AVM","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pah","name":"Pulmonary arterial hypertension","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Complications can be sudden: stroke and brain abscess from pulmonary shunting, brain hemorrhage, and high-output heart failure from liver malformations. Nose and GI bleeding cause iron deficiency anemia, typically in adults. Diagnosis is often delayed.","sources":["engGeneReviews","engHhtGuideline","engLesca"]},{"title":"Diagnosis","text":"Curaçao criteria: recurrent nosebleeds, telangiectasia at characteristic sites, visceral malformations, and a first-degree relative with HHT; three make it definite, two possible. A causative ENG variant alone establishes the diagnosis, even without symptoms.","sources":["engCuracao","engHhtGuideline","engGeneReviews"]},{"title":"Association evidence","text":"ClinGen: Definitive for HHT type 1 (December 2022), Limited for juvenile polyposis. ENG, ACVRL1, and SMAD4 account for 97% of definite clinical HHT.","sources":["engClinGen","engWelch","engHhtGuideline"]},{"title":"ENG compared with ACVRL1","text":"ENG: several-fold more pulmonary and brain malformations, earlier nosebleeds, more brain abscess. ACVRL1: more liver malformations, GI bleeding, and PAH. Screening is the same.","sources":["engKitayama","engLetteboer","engLesca"]},{"title":"Treatment if disease develops","text":"Pulmonary AVMs: embolization, usually when a feeding artery is about 2–3 mm or more. High-risk brain malformations: neurovascular centers. Symptomatic liver malformations: tailored medical therapy; intravenous bevacizumab for refractory high-output heart failure (improvement in about 80% in small series); transplant for refractory complications (5–10-year survival 82–92%). Avoid hepatic artery embolization.","sources":["engHhtGuideline","engGeneReviews"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan on this page. No living person with two ENG pathogenic variants is described; a consanguineous family had no live homozygous member, consistent with lethality. If both partners carry ENG variants, refer to clinical genetics before pregnancy.","sources":["engKarabegovic","engGeneReviews"]},"plans":{}},"EPCAM":{"symbol":"EPCAM","genotype":"Heterozygous Lynch-associated 3′ EPCAM deletion","summary":"A Lynch-associated 3′ EPCAM deletion silences the nearby MSH2 gene. A selected family cohort estimated colorectal cancer risk at about 75% by age 70 years; endometrial risk was lower overall, but varied with deletion extent. Deletions directly involving MSH2 require the MSH2 pathway.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"75%","relative":"30.0×","horizon":"By age 70 · sexes pooled · selected families","citations":{"risk":["epcamKempers"],"relative":["epcamKempers"]}},"men":{"risk":"75%","relative":"30.0×","horizon":"By age 70 · sexes pooled · selected families","citations":{"risk":["epcamKempers"],"relative":["epcamKempers"]}}},{"id":"endometrial","name":"Endometrial cancer","women":{"risk":"12%","relative":"7.5×","horizon":"By age 70","citations":{"risk":["epcamKempers"],"relative":["epcamKempers"]}},"men":null},{"id":"ovarian","name":"Ovarian cancer","women":{"risk":"Not estimated","relative":"Not quantified"},"men":null},{"id":"gastric","name":"Gastric cancer","women":{"risk":"Not estimated","relative":"Not quantified"},"men":{"risk":"Not estimated","relative":"Not quantified"}},{"id":"small-bowel","name":"Small bowel cancer, including duodenum","women":{"risk":"Not estimated","relative":"Not quantified"},"men":{"risk":"Not estimated","relative":"Not quantified"}},{"id":"pancreatic","name":"Pancreatic cancer","women":{"risk":"Not estimated","relative":"Not quantified"},"men":{"risk":"Not estimated","relative":"Not quantified"}},{"id":"kidney-ureter","name":"Kidney and ureter cancer","women":{"risk":"Not estimated","relative":"Not quantified"},"men":{"risk":"Not estimated","relative":"Not quantified"}},{"id":"bladder","name":"Bladder cancer","women":{"risk":"Not estimated","relative":"Not quantified"},"men":{"risk":"Not estimated","relative":"Not quantified"}},{"id":"prostate","name":"Prostate cancer","women":null,"men":{"risk":"Not estimated","relative":"Not quantified"}},{"id":"biliary","name":"Biliary tract cancer","women":{"risk":"Not estimated","relative":"Not quantified"},"men":{"risk":"Not estimated","relative":"Not quantified"}},{"id":"brain","name":"Brain tumor","women":{"risk":"Not estimated","relative":"Not quantified"},"men":{"risk":"Not estimated","relative":"Not quantified"}},{"id":"sebaceous","name":"Sebaceous skin tumors","women":{"risk":"Not estimated","relative":"Not quantified"},"men":{"risk":"Not estimated","relative":"Not quantified"}}],"note":"Population benchmarks use the same paper’s Netherlands age-70 estimates; colorectal figures pool sexes. *× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Mechanism","text":"EPCAM is not a mismatch repair gene. A Lynch-associated 3′ deletion removes its transcription termination signal, allowing transcriptional read-through and methylation-mediated silencing of the neighboring MSH2 promoter. Silencing depends on EPCAM expression in the tissue. Lower expression in endometrial precursor cells is a proposed explanation for lower endometrial risk, not a proven mechanism for every deletion.","sources":["epcamGrLab","epcamTutlewska","epcamKempers"]},{"title":"Frequency","text":"EPCAM deletions account for about 1–3% of Lynch syndrome families in the cited series and up to 10% of MSH2-inactivating changes. Founder deletions have been reported in several populations, including the Netherlands, Spain and Italy.","sources":["epcamTutlewska","lynch"]},{"title":"Association evidence","text":"The main EPCAM-specific estimates shown here come from one retrospectively ascertained family cohort. The deletion-extent association with endometrial risk rests on three cancers; population-screened penetrance is not established by this source.","sources":["epcamKempers","lynch"]},{"title":"Treatment if cancer develops","text":"Lynch-associated tumors in EPCAM deletion carriers may show MSH2 loss through promoter methylation. Confirm the tumor phenotype. Immunotherapy eligibility depends on tumor biomarkers, cancer type, stage, prior treatment and the applicable indication; the germline deletion alone is insufficient.","sources":["epcamTutlewska","lynch"]}],"otherGenotype":{"title":"If both copies are affected","text":"Clinical genetics should confirm variant classification and whether two variants are on opposite copies. Biallelic loss-of-function EPCAM variants can cause congenital tufting enteropathy with severe infantile diarrhea; this is distinct from the usual monoallelic 3′-deletion Lynch scenario. The consequences of two Lynch-associated 3′ deletions require specialist assessment. Confirm laboratory coverage; do not assume this adult plan applies.","sources":["lynch","epcamTutlewska","epcamInvitae"]},"plans":{}},"F11":{"symbol":"F11","genotype":"Heterozygous","summary":"One F11 variant usually leaves factor XI at about half of normal. Many carriers never bleed, but some bleed after mucosal surgery or dental work, with heavy periods, or after childbirth; the bleeding history predicts this better than the level.","table":{"caption":"Bleeding risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"bleeding","name":"Bleeding tendency on history","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"surgery","name":"Excessive bleeding after surgery","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hmb","name":"Heavy menstrual bleeding","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"pph","name":"Postpartum hemorrhage","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"cvd","name":"Cardiovascular events (lower risk)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"vte","name":"Venous thromboembolism (lower risk)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Bleeding is usually moderate and provoked: dental extraction, surgery, trauma, circumcision, or childbirth. Intracranial bleeding is very uncommon.","sources":["f11ClinGenAction","f11Wheeler2016"]},{"title":"Level and bleeding","text":"Weak correlation (r = −0.36). In 252 procedures, a level above 40 U/dL predicted lower bleeding risk with 75% specificity and 47% sensitivity. Bleeding varies within a person and family.","sources":["f11Brenner","f11BloodAdv","f11ClinGenAction"]},{"title":"Population","text":"Ashkenazi heterozygote frequency about 5–9% (8–9% in ClinGen); severe deficiency about 1 in 450. Present in all populations. Founders: p.Glu117Ter in Ashkenazi, Iraqi, and other Middle Eastern Jews and Arabs; p.Cys38Arg in French Basques; p.Cys128Ter in the UK. Severe deficiency elsewhere: about 1 per million.","sources":["f11Wheeler2016","f11Wheeler2020","f11ClinGenAction"]},{"title":"Association evidence","text":"ClinGen: definitive, semidominant (2019). Some heterozygous missense variants are dominant-negative and give levels near the severe range.","sources":["f11ClinGenValidity"]},{"title":"Treatment if bleeding occurs","text":"Tranexamic acid for mucosal and minor bleeding; plasma or concentrate for serious bleeding or major surgery. Concentrate has caused thrombosis, mostly in older patients and above 30 U/kg. Low-dose recombinant factor VIIa is an option, especially with an inhibitor.","sources":["f11Wheeler2016","f11Wheeler2020"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan on this page. Severe deficiency, usually below 15–20% of normal: about 1% with two type II variants, 3% with type II and III, 10% with two type III. Bleeding in 58% (OR 13, 95% CI 3.8–45); over 60% bleed after tooth extraction, tonsillectomy, nasal, or urologic surgery without replacement. About 30% with two type II variants develop an inhibitor after plasma or concentrate; screen previously treated patients before surgery or childbirth. UKHCDO: prophylaxis below 15% from induction or before surgery, for 3–4 days after vaginal and 6–7 days after cesarean delivery; excessive delivery bleeding 16–30% below 15 IU/dL. Fewer ischemic strokes (1 observed versus 8.56 expected in 115 patients aged 45 years or older). All hemostatic decisions go through hematology.","sources":["f11Asakai","f11Brenner","f11Wheeler2016","f11Wheeler2020","f11UkhcdoObstetric","f11ClinGenAction","f11Salomon2008"]},"plans":{}},"F2":{"symbol":"F2","genotype":"Heterozygous c.*97G>A","summary":"The prothrombin variant (legacy G20210A) roughly triples the odds of a first venous thromboembolism (VTE), yet most carriers never have one. It does not warrant anticoagulation alone, but it rules out estrogen-containing contraception under US MEC 2024 and shapes surgery and pregnancy decisions.","table":{"caption":"Venous thromboembolism risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"first-vte","name":"First VTE, per year","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"recurrence","name":"Recurrent VTE after a first VTE, per year off anticoagulation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pregnancy-fh","name":"Pregnancy-associated VTE: family-study estimate","women":{"risk":"1.0%","relative":"2.0×","horizon":"Per pregnancy","citations":{"risk":["f2Croles2017"],"relative":["f2Croles2017"]}},"men":null},{"id":"pregnancy-nofh","name":"Pregnancy-associated VTE: non-family-study estimate","women":{"risk":"0.8%","relative":"8.0×","horizon":"Per pregnancy","citations":{"risk":["f2Croles2017"],"relative":["f2Croles2017"]}},"men":null},{"id":"coc","name":"VTE during combined oral contraceptive use, per year","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"hrt","name":"VTE during oral menopausal hormone therapy","women":{"risk":"Not established","relative":"Not established"},"men":null}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Usually a leg DVT or pulmonary embolism in adulthood; some heterozygotes have recurrent events before age 30 years. Risk rises with a second copy, coexisting factor V Leiden, and acquired thrombophilia.","sources":["f2Genereviews"]},{"title":"Frequency","text":"Median prevalence 6.1% among patients with VTE. The compound genotype with factor V Leiden occurs in about 22 per 100,000 people in the US.","sources":["f2Ash2023","f2Clingen105"]},{"title":"Mechanism","text":"A 3′ untranslated region variant that increases prothrombin production (gain of function). ClinGen: Definitive for autosomal dominant thrombophilia.","sources":["f2ClingenValidity"]}],"otherGenotype":{"title":"If both copies are affected","text":"Homozygous: first VTE OR 6.74 (95% CI 2.19–20.72). Pregnancy OR 21.1 (credible interval 0.0–727.4); ASH 2018 estimates about 1.6% antepartum and about 2% postpartum (pooled with homozygous factor V Leiden, wide CI) without family history, suggests against antepartum prophylaxis without family history (recommendation 20) and for postpartum prophylaxis regardless (recommendation 26). GeneReviews: avoid estrogen contraception and hormone therapy with or without prior VTE. Compound heterozygous with factor V Leiden: first VTE OR 3.42 (95% CI 1.64–7.13) pooled and 6.7 (95% CI 2.9–16) in relatives; 2.5% per pregnancy in family studies (OR 21.2); with combined oral contraceptives, OR 17–110 versus oral contraceptive users without either variant and OR 7.85 (95% CI 1.65–37.41) versus non-users without either variant in a meta-analysis of 2 studies; ASH 2018 suggests antepartum (recommendation 21) and postpartum prophylaxis for 6 weeks. Refer to hematology.","sources":["f2Simone2013","f2Croles2017","f2Ash2018","f2Genereviews","f2Clingen105","f2Ash2023"]},"plans":{}},"F5":{"symbol":"F5","genotype":"Heterozygous factor V Leiden","summary":"Factor V Leiden (p.Arg534Gln, legacy R506Q) resists activated protein C and raises the odds of a first venous thromboembolism (VTE) about fourfold, yet most carriers never have one. It does not warrant anticoagulation alone, but it rules out estrogen-containing contraception and shapes hormone, surgery, and pregnancy decisions.","table":{"caption":"Venous thromboembolism risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"first-vte","name":"First VTE, per year","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"recurrence","name":"Recurrent VTE after a first VTE, per year off anticoagulation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pregnancy-fh","name":"Pregnancy-associated VTE: family-study estimate","women":{"risk":"2.4%","relative":"4.8×","horizon":"Per pregnancy","citations":{"risk":["f5Croles2017"],"relative":["f5Croles2017"]}},"men":null},{"id":"pregnancy-nofh","name":"Pregnancy-associated VTE: non-family-study estimate","women":{"risk":"0.4%","relative":"4.0×","horizon":"Per pregnancy","citations":{"risk":["f5Croles2017"],"relative":["f5Croles2017"]}},"men":null},{"id":"coc","name":"VTE during combined oral contraceptive use, per year","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"hrt","name":"VTE during oral menopausal hormone therapy","women":{"risk":"Not established","relative":"Not established"},"men":null}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Leg DVT is the most common event. Pulmonary embolism carries most early mortality; about 30% with DVT develop post-thrombotic syndrome. Heterozygosity does not shorten life expectancy.","sources":["f5Clingen106"]},{"title":"Frequency","text":"In the US, about 5.1% of non-Hispanic white, 2.0% of Hispanic white, and 1.2% of African American people are heterozygous. Present in 15–20% of people with a first VTE (ASH 2023 median 17.5%).","sources":["f5Clingen106","f5Ash2023"]},{"title":"What raises risk in a carrier","text":"Age, obesity, pregnancy, estrogen, surgery, cancer, travel, family history of VTE, a second copy, or a second thrombophilia. The course varies even within a family.","sources":["f5Genereviews","f5Clingen106"]},{"title":"Mechanism","text":"Loss of one of three activated protein C cleavage sites slows factor V inactivation and increases thrombin generation. ClinGen: Definitive for autosomal dominant thrombophilia.","sources":["f5ClingenValidity","f5Clingen106"]}],"otherGenotype":{"title":"If both copies are affected","text":"Homozygous: first VTE OR 11.45 (95% CI 6.79–19.29) pooled, OR 18 (95% CI 7.8–40) in relatives, about 15 per 1000 person-years when found by population screening; pregnancy VTE 6.2% per pregnancy (95% credible interval 0.0–18.0%; 6 studies, 58 carriers), 2.8% antepartum and 2.8% postpartum, separate estimates that do not sum to the per-pregnancy figure; OR 35.8 (95% credible interval 0.4–137.8). Compound heterozygous with prothrombin c.*97G>A: first VTE OR 3.42 (95% CI 1.64–7.13) pooled, 6.7 (95% CI 2.9–16) in relatives; 2.5% per pregnancy in family studies (95% credible interval 0.0–9.5%; 3 studies, 199 carriers; OR 21.2, 1.6–89.0); with oral contraceptives, OR 17–110 versus oral contraceptive users without either variant, and OR 7.85 (95% CI 1.65–37.41, two studies) versus non-users without either variant. ASH 2018 suggests antepartum prophylaxis for both genotypes and postpartum prophylaxis regardless of family history (recommendations 21 and 26); postpartum prophylaxis continues for 6 weeks (ASH 2023, ClinGen); avoid estrogen contraception and hormone therapy with or without prior VTE; ASH 2023 suggests testing sisters with a family history to guide pregnancy prophylaxis. Refer to hematology.","sources":["f5Simone2013","f5Segal2009","f5Clingen105","f5Croles2017","f5Wu2005","f5Ash2018","f5Ash2023","f5Genereviews"]},"plans":{}},"F9":{"symbol":"F9","genotype":"X-linked · Hemizygous men, heterozygous women","summary":"Every man with a loss-of-function F9 variant has hemophilia B, graded by factor IX level. About a quarter to a third of carrier women have factor IX below 40 IU/dL and have hemophilia; others bleed with procedures and childbirth at higher levels.","table":{"caption":"Bleeding risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"low-fix","name":"Hemophilia B (factor IX below 40 IU/dL)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pph-primary","name":"Primary postpartum hemorrhage","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"pph-secondary","name":"Secondary postpartum hemorrhage","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"hmb","name":"Heavy menstrual bleeding","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"joint","name":"Joint bleeding","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"inhibitor","name":"Factor IX inhibitor after treatment","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"thrombosis","name":"Venous thrombosis with factor IX Padua","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Intracranial hemorrhage is the leading bleeding-related cause of death. With factor IX concentrates, life expectancy approaches normal: 77 years for Dutch men with hemophilia, 6 years below the general male population.","sources":["f9GeneReviews"]},{"title":"Carrier nomenclature","text":"ISTH 2021: women with mild (above 0.05 and below 0.40 IU/mL), moderate (0.01–0.05 IU/mL), or severe (below 0.01 IU/mL) hemophilia, and symptomatic or asymptomatic carriers at 0.40 IU/mL or above, by bleeding history.","sources":["f9VanGalen"]},{"title":"Association evidence","text":"ClinGen: definitive for X-linked hemophilia B (2019); limited for X-linked thrombophilia from factor IX Padua (2023).","sources":["f9ClinGenAction","f9ClinGenPadua"]},{"title":"Treatment if bleeding occurs","text":"Intravenous factor IX concentrate as soon as possible, at home once trained. Vitamin K does not prevent or control bleeding. One AAV gene therapy (etranacogene dezaparvovec) is available for adults; it encodes factor IX Padua. A second (fidanacogene elaparvovec) was approved in 2024 but withdrawn from the market in 2025.","sources":["f9GeneReviews","f9Wfh","f9Beqvez"]}],"otherGenotype":{"title":"If a woman has two affected copies","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, follow the carrier plan above. Variants on both X chromosomes, or one with extreme skewed X inactivation or a single X chromosome, can cause hemophilia B as severe as a man’s. Rare. Her factor IX level sets care: grade it and follow the men’s plan through a hemophilia center.","sources":["f9Wfh","f9VanGalen"]},"plans":{}},"FBN1":{"symbol":"FBN1","genotype":"Heterozygous","summary":"FBN1 variants cause Marfan syndrome: aortic root enlargement and dissection, lens dislocation, and mitral valve prolapse. Nearly all clinic-diagnosed patients have aortic dilation by age 60 years; carriers found by population sequencing show it far less often.","table":{"caption":"Aortic, valve, and eye risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"aortic-dilation","name":"Aortic root or ascending aorta dilation","women":{"risk":"96%","relative":"Not established","horizon":"By age 60 · clinical cohort","citations":{"risk":["fbn1Detaint"]}},"men":{"risk":"96%","relative":"Not established","horizon":"By age 60 · clinical cohort","citations":{"risk":["fbn1Detaint"]}}},{"id":"aortic-event","name":"Aortic dissection or preventive aortic surgery","women":{"risk":"74%","relative":"Not established","horizon":"By age 60 · clinical cohort","citations":{"risk":["fbn1Detaint"]}},"men":{"risk":"74%","relative":"Not established","horizon":"By age 60 · clinical cohort","citations":{"risk":["fbn1Detaint"]}}},{"id":"ascending-dissection","name":"Ascending aortic dissection","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ectopia-lentis","name":"Ectopia lentis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mitral-prolapse","name":"Mitral valve prolapse","women":{"risk":"77%","relative":"Not established","horizon":"By age 60 · clinical cohort","citations":{"risk":["fbn1Detaint"]}},"men":{"risk":"77%","relative":"Not established","horizon":"By age 60 · clinical cohort","citations":{"risk":["fbn1Detaint"]}}},{"id":"dural-ectasia","name":"Dural ectasia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"retinal-detachment","name":"Retinal detachment","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Dissection and its surgery drive most early deaths. With current care, life expectancy approaches the general population: 90% of 1,575 patients alive at age 60 years; in 570 Dutch adults (mean follow-up 8.2 years), 10-year survival 93.8% and dissection-free survival 84.2%.","sources":["fbn1GeneReviews","fbn1Arnaud","fbn1Franken"]},{"title":"Diagnosis","text":"Revised Ghent cardinal features are aortic root enlargement and ectopia lentis. Without a family history, both together establish Marfan syndrome; with one, a bona fide FBN1 variant or a systemic score is also required.","sources":["fbn1Ghent","fbn1GeneReviews","fbn1Detaint"]},{"title":"Association evidence","text":"ClinGen: definitive for familial thoracic aortic aneurysm and dissection; haploinsufficiency sufficient. No OR compares unselected pathogenic carriers with non-carriers. A biobank study of 12 historically reported variants (mostly p.Arg1170His) found OR 5.2 (95% CI 2.4–11.6) for any Marfan-related cardiovascular finding; it does not apply to a curated pathogenic result.","sources":["fbn1ClinGen","fbn1Damrauer"]},{"title":"Variant type","text":"Truncating and other haploinsufficient variants carry more aortic risk than dominant-negative missense variants (HR 1.6–2.5, two cohorts), more skeletal involvement, and less ectopia lentis. Cysteine-removing in-frame variants approach truncating aortic risk; cysteine-adding variants carry the highest rate of lens surgery (48%) and the least aortic risk (29% lifelong); cysteine-removing variants have the most ectopia lentis (74%). Exons 24–32 are linked to earlier, more severe disease, including neonatal presentation. These are group averages; interpret the exact variant with genetics.","sources":["fbn1Franken","fbn1Takeda","fbn1Arnaud","fbn1Faivre"]},{"title":"Treatment if the aorta enlarges","text":"Root replacement, often valve-sparing in experienced centers, is definitive; in one series 7% of 239 patients had at least moderate aortic regurgitation at 1 year. Imaging of the remaining aorta continues for life.","sources":["fbn1AccMarfan"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance. Biallelic FBN1 variants are rare: 9 of 1,400 French probands (0.64%), none with two truncating variants. Severity ranged widely and was not uniformly worse, though earlier reports describe severe disease; in one family three compound heterozygous siblings had aortic dilation before age 30 years, one dying of dissection at 31 years. Some missense variants, such as p.Arg485Cys, are recessive in one family and dominant in others. No established pathway: refer to clinical genetics and an aortic center, use at least the Marfan surveillance above.","sources":["fbn1Biallelic","fbn1CompoundHet","fbn1Recessive","fbn1Arg485Cys"]},"plans":{}},"FH":{"symbol":"FH","genotype":"Heterozygous HLRCC-type variant","summary":"HLRCC-type FH variants cause skin and uterine leiomyomas and an uncommon, aggressive kidney cancer that needs surgery as soon as it is found. Many panel FH results, including p.Lys477dup, are recessive fumarase deficiency carrier variants without kidney cancer risk.","table":{"caption":"Tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"rcc","name":"Kidney cancer (FH-deficient renal cell carcinoma)","women":{"risk":"7.3%","relative":"Not established","horizon":"By age 70","citations":{"risk":["fhKaiser"]}},"men":{"risk":"7.3%","relative":"Not established","horizon":"By age 70","citations":{"risk":["fhKaiser"]}}},{"id":"uterine","name":"Uterine leiomyomas (fibroids)","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"cutaneous","name":"Cutaneous leiomyomas","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ppgl","name":"Pheochromocytoma or paraganglioma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Median survival after symptomatic kidney cancer was 21.0 months; screen-detected stage 1 cancers had much longer survival. Fibroids often cause heavy bleeding and pain and lead to early hysterectomy.","sources":["fhForde","fhClinGen"]},{"title":"Evidence for surveillance","text":"81 people had 187 surveillance scans; three stage 1 cancers were found. Evidence is observational; schedules are consensus.","sources":["fhForde","fhMenko"]},{"title":"Treatment if cancer develops","text":"Total or partial nephrectomy with wide margins by an experienced surgeon. Advanced disease: options include erlotinib plus bevacizumab (off-label, phase 2 data) or cabozantinib plus nivolumab; oncology decides.","sources":["fhGeneReviews"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance for each variant. Whatever the phase, if either variant is an HLRCC-type variant, follow the HLRCC plan above. Classic fumarate hydratase deficiency, a severe neonatal or early infantile encephalopathy with seizures and profound developmental delay, is a childhood diagnosis managed by pediatric metabolic and neurology teams, and an adult panel report of two FH variants should not be assumed to be it. For a carrier of a recessive-only variant such as p.Lys477dup, offer partner testing and genetics referral: if both partners carry a pathogenic FH variant, each pregnancy has a 25% chance of fumarate hydratase deficiency.","sources":["fhDeficiency","fhKaiser","fhLu","fhGeneReviews"]},"plans":{}},"FHL1":{"symbol":"FHL1","genotype":"X-linked · Hemizygous men, heterozygous women","summary":"FHL1 variants cause X-linked myopathies, from Emery-Dreifuss-like contractures to scapuloperoneal and postural muscle disease, and a usually hypertrophic cardiomyopathy with arrhythmias and sudden death. Men are typically affected by early adulthood; women are usually unaffected or mildly affected, though arrhythmia, conduction disease, and sudden death occur.","table":{"caption":"Cardiac and muscle findings","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"any-cardiac","name":"Any cardiac abnormality","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lvh","name":"Left ventricular hypertrophy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"af","name":"Atrial fibrillation or flutter","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"va","name":"Ventricular tachycardia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"conduction","name":"Conduction disease","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"scd","name":"Sudden cardiac death","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"transplant","name":"Heart transplantation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"muscle","name":"Skeletal muscle involvement","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Men with truncating or LIM-domain variants had earlier, more severe heart disease. Published families likely represent the severe end.","sources":["fhl1Bobbio"]},{"title":"Association evidence","text":"ClinGen HCM panel (2019): definitive for Emery-Dreifuss muscular dystrophy that can present with left ventricular hypertrophy. ClinGen actionability: limited for EDMD from FHL1. A 2012 study supported FHL1 as a cause of isolated HCM.","sources":["fhl1Ingles","fhl1ClinGen","fhl1ClinGenAct","fhl1Friedrich"]},{"title":"Muscle disease spectrum","text":"Six overlapping myopathies: reducing body myopathy, scapuloperoneal myopathy, X-linked myopathy with postural muscle atrophy, rigid spine syndrome, EDMD type 6, and contractures with hypertrophic cardiomyopathy. Course ranges from fatal early onset to very mild late onset. FHL1 causes about 10% of X-linked EDMD.","sources":["fhl1Caputo","fhl1ClinGenAct"]}],"otherGenotype":{"title":"If a woman has two affected copies","text":"Confirm two variants: homozygous, or two different variants shown on different X chromosomes (in trans) by parental testing or laboratory phasing. If they are on the same copy, follow the women’s plan. Not described, and no separate pathway exists. Lacking a normal copy, as an affected man does, she follows the men's plan under cardiomyopathy and neuromuscular care.","sources":["fhl1GeneReviews"]},"plans":{}},"FLCN":{"symbol":"FLCN","genotype":"Heterozygous","summary":"FLCN variants cause Birt-Hogg-Dubé syndrome: lung cysts with frequent spontaneous pneumothorax, benign facial papules, and often multiple, usually slow-growing kidney tumors. Kidney risk is lower in population-detected carriers, but every carrier gets lifelong kidney imaging.","table":{"caption":"Kidney, lung, and skin risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"renal","name":"Kidney tumors","women":{"risk":"21%","relative":"Not established","horizon":"By age 70","citations":{"risk":["flcnPenetrance"]}},"men":{"risk":"19%","relative":"Not established","horizon":"By age 70","citations":{"risk":["flcnPenetrance"]}}},{"id":"lung","name":"Lung cysts or pneumothorax","women":{"risk":"82%","relative":"Not established","horizon":"By age 70","citations":{"risk":["flcnPenetrance"]}},"men":{"risk":"87%","relative":"Not established","horizon":"By age 70","citations":{"risk":["flcnPenetrance"]}}},{"id":"pneumothorax","name":"Spontaneous pneumothorax","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"skin","name":"Fibrofolliculomas and related skin lesions","women":{"risk":"78%","relative":"Not established","horizon":"By age 70","citations":{"risk":["flcnPenetrance"]}},"men":{"risk":"87%","relative":"Not established","horizon":"By age 70","citations":{"risk":["flcnPenetrance"]}}},{"id":"polyps","name":"Colon polyps","women":{"risk":"32%","relative":"Not established","horizon":"By age 70","citations":{"risk":["flcnPenetrance"]}},"men":{"risk":"21%","relative":"Not established","horizon":"By age 70","citations":{"risk":["flcnPenetrance"]}}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Kidney tumors rarely metastasize below 3 cm, but metastatic disease occurs, mainly with clear cell histology. Pneumothorax is the most frequent acute problem and often recurs. Skin lesions are benign but can affect quality of life.","sources":["flcnErn","flcnClinGen"]},{"title":"Evidence for surveillance","text":"Guidance rests on case series and Delphi consensus; evidence is low. Annual MRI may exceed what an incidentally found carrier needs, but no lighter schedule has been tested.","sources":["flcnErn","flcnPopulation"]},{"title":"Treatment if disease develops","text":"Pneumothorax is treated as in the general population, with surgery considered after recurrence.","sources":["flcnErn","flcnGeneReviews"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic germline FLCN condition is established in humans; the second copy is lost only within tumors. Refer a report of two FLCN variants to clinical genetics. Meanwhile follow the plan above; genetics confirms whether the variants are on the same or different copies.","sources":["flcnErn"]},"plans":{}},"FLNC":{"symbol":"FLNC","genotype":"Heterozygous","summary":"Truncating FLNC variants cause a left-dominant dilated or arrhythmogenic cardiomyopathy with high sudden death risk. Missense and in-frame variants cause hypertrophic or restrictive cardiomyopathy or myofibrillar myopathy.","table":{"caption":"Cardiac and muscle risk by variant type","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"tv-cardiomyopathy","name":"Truncating: dilated or arrhythmogenic left ventricular cardiomyopathy","women":{"risk":">97%","relative":"Not established","horizon":"Among carriers older than 40 · families","citations":{"risk":["flncOrtizGenga"]}},"men":{"risk":">97%","relative":"Not established","horizon":"Among carriers older than 40 · families","citations":{"risk":["flncOrtizGenga"]}}},{"id":"tv-scd-all","name":"Truncating: sudden death or major ventricular arrhythmia, all carriers","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"tv-scd-negative","name":"Truncating: sudden death or major ventricular arrhythmia, phenotype-negative carriers","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ms-hcm","name":"Missense or in-frame: hypertrophic cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ms-rcm","name":"Missense or in-frame: restrictive cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mfm","name":"Myofibrillar myopathy (skeletal muscle)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Sudden death can occur with only mildly reduced LVEF, so LVEF alone underestimates risk. In the registry, 7% had nonarrhythmic death, transplant, or LVAD during follow-up.","sources":["flncRegistry","flncCeleghin","flncOrtizGenga"]},{"title":"Variant type","text":"Truncating variants act through haploinsufficiency and appeared only in DCM among 1,150 French cardiomyopathy patients. Missense and in-frame variants disturb folding and dimerization and form aggregates, the mechanism in HCM and myofibrillar myopathy. Some C-terminal truncating variants such as p.Trp2710Ter cause myopathy.","sources":["flncVerdonschot","flncAder","flncKley"]},{"title":"Association evidence","text":"ClinGen: definitive for DCM (2025) and myofibrillar myopathy (2023); haploinsufficiency score 3; adult actionability for FLNC dilated cardiomyopathy strong (2025; pediatric moderate). The 2022 consensus lists FLNC as first-tier for arrhythmogenic cardiomyopathy and DCM.","sources":["flncClinGen","flncWilde"]},{"title":"Treatment if disease develops","text":"Standard guideline-directed heart failure therapy. The genotype counts as an ICD risk factor alongside LVEF, LGE, NSVT, and syncope.","sources":["flncEsc2023","flncRegistry"]}],"otherGenotype":{"title":"If both copies are affected","text":"Very rare. One compound heterozygous infant (p.Phe106Leu and p.Arg991Ter) had early-onset DCM; the heterozygous parents had no DCM by age 40 years. No established pathway: refer to a cardiomyopathy centre and clinical genetics, and test both parental lines.","sources":["flncVerdonschot"]},"plans":{}},"G6PD":{"symbol":"G6PD","genotype":"X-linked · Hemizygous men, heterozygous women","summary":"Deficient G6PD variants cause hemolysis after oxidant drugs, fava beans, or infection, and make HbA1c read falsely low. Men are deficient; heterozygous women range from deficient to normal and need a quantitative activity test.","table":{"caption":"Hemolysis and laboratory risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"phenotype","name":"G6PD-deficient phenotype","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"primaquine","name":"Clinically significant hemolysis on 14-day primaquine","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"acute","name":"Acute hemolysis after other drugs, fava beans, or infection","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cnsha","name":"Chronic hemolytic anemia (class A variants)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hba1c","name":"Diabetes missed by HbA1c screening","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Most deficient people are well without a trigger. Acute hemolysis can need transfusion, and favism can be fatal, mostly in children.","sources":["g6pdChu","g6pdCpic"]},{"title":"Population","text":"Almost 5% of the world’s population is G6PD deficient, 30% or more in some malaria-endemic groups. About 11% of Black people in the US carry c.202G>A (A−).","sources":["g6pdCpic","g6pdAda"]},{"title":"Variant classification","text":"WHO 2022: class A (median activity below 20%, chronic hemolysis), class B (below 45%, acute hemolysis with triggers and neonatal jaundice; former classes II and III), class C (above 60%, no hemolysis), class U (uncertain). Classes describe variants, not people. CPIC still uses classes I–IV.","sources":["g6pdWho","g6pdCpic"]},{"title":"Association evidence","text":"ClinGen: definitive for X-linked G6PD deficiency without chronic hemolysis (2023).","sources":["g6pdClinGen"]}],"otherGenotype":{"title":"If a woman has two affected copies","text":"Confirm two variants: homozygous, or two different variants shown on opposite X chromosomes (in trans) by parental testing or laboratory phasing; alternatively, measure quantitative G6PD activity. Until confirmed, restrict drugs as deficient. If they are on the same X chromosome, she is heterozygous: use the women’s plan, including the activity test. If homozygous or confirmed in trans, she is deficient like an affected man and follows the men’s plan; every son is deficient and every daughter is at least heterozygous.","sources":["g6pdCpic","g6pdWheeler"]},"plans":{}},"GAA":{"symbol":"GAA","genotype":"Biallelic","summary":"Biallelic GAA variants cause Pompe disease. An adult most likely has or will develop the late-onset form: progressive proximal, trunk, and diaphragm weakness leading to wheelchair use, ventilation, and earlier death, slowed by enzyme replacement started at the first objective sign.","table":{"caption":"Late-onset Pompe disease features","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"weakness","name":"Progressive proximal limb weakness","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"fvc","name":"Reduced forced vital capacity","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ventilation","name":"Respiratory support","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"wheelchair","name":"Wheelchair use","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"arrhythmia","name":"Supraventricular or ventricular tachyarrhythmia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dysphagia","name":"Dysphagia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"bone","name":"Low bone mineral density","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"intracranial","name":"Intracranial arterial abnormalities","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"death","name":"Death without enzyme replacement","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Late-onset disease is progressive; respiratory failure is the main cause of death. The infantile form, with cardiomyopathy and death by age 2 years untreated, does not arise in an adult.","sources":["gaaClinGenAct","gaaGungor"]},{"title":"What treatment changes","text":"In the one randomized trial (90 patients, ages 10–70 years), alglucosidase alfa improved 6-minute walk distance and stabilized upright FVC over 78 weeks, without a measured quality-of-life gain. No study has tested treatment without symptoms or signs.","sources":["gaaClinGenAct","gaaVanDerPloeg"]},{"title":"The common splice variant","text":"c.-32-13T>G (IVS1-13T>G) disturbs exon 2 splicing but leaves some normal enzyme. It is in 86% (253 of 294) of childhood- and adult-onset patients, common in European and Latin American ancestry (allele frequency up to 0.8%), and absent in East Asian ancestry. With a null variant it gives the typical adult course; two copies are uncommon and span isolated raised CK to respiratory insufficiency.","sources":["gaaNino","gaaMusumeci"]},{"title":"Association evidence","text":"ClinGen: definitive for glycogen storage disease II, autosomal recessive (2019); adult actionability moderate (9CA), given variable presentation and uncertain benefit of early treatment.","sources":["gaaClinGen","gaaClinGenAct"]}],"otherGenotype":{"title":"If one copy is affected","text":"Carriers (about 1 in 77–100) do not develop Pompe disease and need no monitoring; intermediate enzyme activity does not indicate disease. If the partner is also a carrier, each child has a 25% chance of Pompe disease, and two severe variants cause the infantile form; offer partner testing before pregnancy. The biallelic risks and plan on this page do not apply.","sources":["gaaGeneReviews","gaaClinGenAct"]},"plans":{}},"GCH1":{"symbol":"GCH1","genotype":"Heterozygous","summary":"GCH1 variants lower dopamine synthesis and cause dopa-responsive dystonia in most women and about half of men, usually from childhood, with foot dystonia that worsens toward evening. Low-dose levodopa gives a dramatic, lasting response; rare variants are associated with adult Parkinson disease.","table":{"caption":"Movement disorder risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"drd","name":"Dopa-responsive dystonia","women":{"risk":"87–100%","relative":"Not established","horizon":"At assessment · family carriers","citations":{"risk":["gch1GeneReviews"]}},"men":{"risk":"35–55%","relative":"Not established","horizon":"At assessment · family carriers","citations":{"risk":["gch1GeneReviews"]}}},{"id":"pd","name":"Parkinson disease","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"psychiatric","name":"Depression, anxiety, or other psychiatric disorder","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Untreated childhood-onset disease progresses to generalized dystonia; after age 20 years parkinsonism predominates, and progression is nearly stable by the fourth decade. Life expectancy is not reduced. ClinGen scores severity as modest morbidity; cognition, sensation, and coordination are generally spared.","sources":["gch1ClingenAc","gch1Opladen","gch1GeneReviews"]},{"title":"What treatment changes","text":"Benefit in 403 of 406 treated people in one review and 87% of 488 in another; residual dystonia (20%) and parkinsonism (11%) in 352. Response is sustained even after decades untreated, but earlier treatment works better across BH4 deficiencies.","sources":["gch1ClingenAc","gch1Opladen"]},{"title":"Association evidence","text":"ClinGen: definitive (2020); actionability of specialist surveillance to guide levodopa strong (2025). Sanger sequencing finds a variant in only 50–60% of typical cases; deletions need MLPA or similar testing.","sources":["gch1ClingenValidity","gch1ClingenAc","gch1Opladen"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the plan above. Either way the dominant plan above applies as a minimum; refer to movement-disorder or metabolic neurology. Biallelic disease is usually recessive GTP cyclohydrolase I deficiency, an infantile neurometabolic disorder with hyperphenylalaninemia usually found by newborn screening (days 2–14; some cases lack hyperphenylalaninemia), with hypotonia and developmental delay, treated by specialists with sapropterin, levodopa with a decarboxylase inhibitor (about 10 mg/kg/day), and 5-hydroxytryptophan. An adult with confirmed trans variants needs specialist assessment for an attenuated form.","sources":["gch1Opladen","gch1ClingenValidity"]},"plans":{}},"GDF2":{"symbol":"GDF2","genotype":"Heterozygous","summary":"GDF2 (BMP9) variants are an established cause of heritable pulmonary arterial hypertension and a probable cause of an HHT-like syndrome with nosebleeds, atypically placed telangiectases, and pulmonary AVMs. Penetrance is unknown; many heterozygous relatives have no signs.","table":{"caption":"Pulmonary hypertension and vascular findings","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"pah","name":"Pulmonary arterial hypertension","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"epistaxis","name":"Recurrent nosebleeds","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"telangiectasia","name":"Telangiectasia or capillary lesions","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pavm","name":"Pulmonary AVM","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"brain-liver","name":"Brain or liver vascular malformation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"PAH is the main threat. In one Asian PAH cohort, GDF2 carriers were younger at diagnosis and had worse hemodynamics than patients without BMPR2 or GDF2 variants. HHT-like features so far are mostly nosebleeds and skin lesions, with pulmonary AVMs in some.","sources":["gdf2Wang","gdf2ClinGenHht5"]},{"title":"Association evidence","text":"ClinGen: Definitive for PAH (2022); Moderate for HHT type 5 (2026, unchanged after reevaluation), with 3.35 of 12 genetic and 4.50 of 6 experimental points from 10 probands in 8 publications, many scored low for population frequency or few features; mouse knockouts developed AVMs on one genetic background only. Curators suggest the name GDF2-related HHT-like syndrome. Treat the HHT link as probable, not settled.","sources":["gdf2ClinGen","gdf2ClinGenHht5","gdf2Welch"]},{"title":"How it differs from classic HHT","text":"Reported patients largely do not meet the Curaçao criteria, so a normal examination does not exclude GDF2-related disease and a positive one does not prove it.","sources":["gdf2Wooderchak","gdf2Hodgson","gdf2Farhan"]},{"title":"Treatment if disease develops","text":"Pulmonary AVMs are embolized; iron deficiency is replaced.","sources":["gdf2EscErsPh","gdf2HhtGuideline"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the plan above. Two children homozygous for nonsense variants had undetectable BMP9 and BMP10, with PAH in one, pulmonary AVMs in the other, and facial telangiectases in both; one child’s heterozygous parents were asymptomatic, and a homozygous frameshift has been reported with pulmonary AVMs. A founder variant in 13 patients caused PAH without HHT features across a wide range of onset ages and severity, consistent with semi-dominant inheritance. With confirmed biallelic variants, use the plan above as a minimum: refer to pulmonary hypertension and HHT centers, screen for pulmonary AVMs, and test both parental lines.","sources":["gdf2Hodgson","gdf2ClinGenHht5","gdf2Aldalaan"]},"plans":{}},"GLA":{"symbol":"GLA","genotype":"X-linked · Hemizygous men, heterozygous women","summary":"Alpha-galactosidase A loss lets glycolipid build up in the kidney, heart, nerves, and vessels. Classic variants in men cause childhood pain, then kidney failure, cardiomyopathy, and stroke from early middle age; later-onset variants such as N215S mainly cause cardiomyopathy from the fifth decade; women are often affected, later and more variably.","table":{"caption":"Fabry disease features","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"pain","name":"Neuropathic pain","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"proteinuria","name":"Proteinuria","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"renal","name":"Kidney disease progression","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"eskd","name":"Kidney failure (dialysis or transplant)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lvh","name":"Left ventricular hypertrophy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cardiac-event","name":"Cardiovascular event","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"n215s","name":"Severe cardiac event, p.Asn215Ser variant","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"stroke","name":"Stroke or TIA","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"gi","name":"Gastrointestinal symptoms","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"microalbuminuria","name":"Microalbuminuria in genotype-first adults","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Classic disease shortens life, mainly through heart failure, arrhythmia, and sudden death, most often after kidney replacement therapy. Later-onset variants can cause cardiomyopathy as severe as classic disease in men, usually later.","sources":["glaClinGenAct","glaN215S"]},{"title":"What treatment changes","text":"Enzyme replacement trials were small and short, mostly with surrogate outcomes, and showed no difference in mortality or cardiac and cerebrovascular events. Pooled cohorts suggest fewer renal, cardiovascular, and cerebrovascular complications with agalsidase beta, and a meta-analysis found fewer recurrent strokes. Experts favor starting at the earliest organ involvement, since much published benefit comes from late treatment after damage.","sources":["glaClinGenAct","glaOrtiz"]},{"title":"Association evidence","text":"ClinGen: definitive (2019); moderately actionable in men (cardiovascular 8CD) and in women (cardiovascular 7CD), with severity in women possibly overstated by secondary ascertainment.","sources":["glaClinGen","glaClinGenAct"]},{"title":"Why women vary","text":"Random X-inactivation leaves some women with little or no disease and others as severe as classic men. Before enzyme replacement, life expectancy in women was about 15 years below the general population.","sources":["glaGeneReviews","glaUkb","glaBiegstraaten"]}],"otherGenotype":{"title":"If a woman has two affected copies","text":"Rare, usually in consanguineous families. Confirm two variants first: homozygous, or two different variants shown on different X chromosomes (in trans) by parental testing or laboratory phasing, and measure leukocyte enzyme activity. Only a confirmed homozygous or trans genotype, or deficient activity, moves her to the men's plan, under Fabry center care. If both variants are on the same X chromosome, use the women's plan.","sources":["glaGeneReviews","glaBiegstraaten"]},"plans":{}},"GREM1":{"symbol":"GREM1","genotype":"Heterozygous upstream duplication","summary":"A duplication upstream of GREM1, most often the 40 kb Ashkenazi Jewish founder duplication, causes hereditary mixed polyposis: adenomatous, serrated, hyperplastic, and atypical juvenile colon polyps with increased colorectal cancer risk of unmeasured size.","table":{"caption":"Cancer risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"polyps","name":"Mixed colorectal polyposis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"extracolonic","name":"Extracolonic tumors","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Highly variable: a few polyps in middle age in some carriers, polyps from adolescence and colorectal cancer in the early 20s in others. Typically fewer than 15 polyps in a 2026 review; other summaries give up to about 80–100.","sources":["grem1Ziai","grem1Lieberman","grem1Review2026"]},{"title":"Association evidence","text":"ClinGen: Definitive (2022). The duplication segregated with polyps in the original families and later Ashkenazi kindreds.","sources":["grem1Clingen","grem1Jaeger","grem1Ziai"]},{"title":"Population","text":"Ashkenazi Jewish founder variant: found in 2 of 438 Ashkenazi Jews with adenomas or colorectal cancer at colonoscopy and 0 of 327 screened regardless of findings. A negative test that did not target the duplication does not exclude it.","sources":["grem1Ashkenazi","grem1Ziai"]}],"otherGenotype":{"title":"If both copies are affected","text":"No condition from two GREM1 duplications is described; ClinGen curates only the dominant syndrome. Manage as above and refer to clinical genetics.","sources":["grem1Clingen"]},"plans":{}},"HAMP":{"symbol":"HAMP","genotype":"Biallelic","summary":"Little or no hepcidin means iron loads fast and early, typically from the first to third decades, with hypogonadism and cardiomyopathy as leading complications and heart disease as the main cause of death. Phlebotomy started before organ damage prevents most complications.","table":{"caption":"Iron overload and organ involvement","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"onset","name":"Onset at or before age 30 years","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hypogonadism","name":"Hypogonadism","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cardiomyopathy","name":"Cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"diabetes","name":"Glucose intolerance or diabetes","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"liver","name":"Liver fibrosis or cirrhosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"liver-cancer","name":"Primary liver cancer","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"What treatment changes","text":"Early phlebotomy to iron depletion sharply reduces morbidity and mortality. Established hypogonadism usually needs lifelong hormone replacement.","sources":["hampGeneReviews","hampEasl"]},{"title":"Association evidence","text":"ClinGen: Definitive, autosomal recessive (October 2025). Classed as non-HFE hemochromatosis with HJV, TFR2, and gain-of-function SLC40A1; rarer than HJV disease.","sources":["hampClingen","hampBioiron","ironReferral"]}],"otherGenotype":{"title":"If one copy is affected","text":"A carrier state; this plan does not apply and no guideline recommends monitoring or treatment. Digenic hemochromatosis, such as HFE C282Y with one HAMP, HJV, or TFR2 variant, is recognized but needs strict proof of pathogenicity. Check iron studies under usual care; refer to an iron-disorders specialist if transferrin saturation and ferritin are raised or the patient also carries C282Y. If a partner also carries a HAMP variant, each child has a 25% chance of juvenile hemochromatosis; offer partner carrier testing when planning a pregnancy.","sources":["hampBioiron","hampEasl","hampGeneReviews"]},"plans":{}},"HCN4":{"symbol":"HCN4","genotype":"Heterozygous","summary":"Loss-of-function HCN4 variants cause familial sinus bradycardia or sick sinus syndrome decades earlier than ordinary sinus node disease, often with atrial fibrillation and left ventricular noncompaction. Pacing is for symptoms, not the genotype.","table":{"caption":"Sinus node and associated cardiac risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"sss","name":"Sick sinus syndrome or sinus bradycardia (diagnosis)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pacemaker","name":"Pacemaker implantation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"af","name":"Atrial fibrillation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lvnc","name":"Left ventricular noncompaction","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"aorta","name":"Ascending aortic dilation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Association evidence","text":"ClinGen: definitive for autosomal dominant sick sinus syndrome 2 (2025), disputed for Brugada syndrome (2017); noncompaction and aortic disease uncurated. An aortopathy expert panel using the ClinGen framework rated it limited for thoracic aortic disease (2018). A core sinus node disease gene (1–10% of cases); genetic testing there is not useful for diagnosis or therapy but has some prognostic value.","sources":["hcn4ClinGen","hcn4Renard","hcn4Wilde"]},{"title":"Mechanism","text":"HCN4 carries the funny current that sets sinus rate and its adrenergic rise. A truncating variant made the current cAMP-insensitive, causing bradycardia with chronotropic incompetence; pore variants (p.Gly480Arg, p.Ala485Val, p.Gly482Arg) shift activation to more negative voltages or reduce channel synthesis.","sources":["hcn4SchulzeBahr","hcn4Nof","hcn4LaishFarkash","hcn4Milano"]},{"title":"Severity","text":"Varies by variant and family: the p.Gly480Arg family had asymptomatic bradycardia with a favorable prognosis; p.Ala485Val presented in three unrelated men with presyncope, weakness, or out-of-hospital cardiac arrest. Noncompaction, bradycardia, and aortic dilation can present in childhood.","sources":["hcn4Nof","hcn4LaishFarkash","hcn4Paszkowska"]}],"otherGenotype":{"title":"If both copies are affected","text":"No condition from two affected HCN4 copies is established, and this plan is unstudied there. Refer to clinical genetics.","sources":["hcn4ClinGen"]},"plans":{}},"HFE":{"symbol":"HFE","genotype":"Homozygous p.Cys282Tyr","summary":"Two C282Y copies let iron accumulate over decades. Most men and about half of women develop raised iron studies; liver disease, liver cancer, and arthropathy follow in a minority, mostly men, and phlebotomy started before cirrhosis or diabetes can prevent them.","table":{"caption":"Iron overload risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"biochemical","name":"Biochemical iron overload","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"iron-disease","name":"Iron overload-related disease","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"diagnosed","name":"Diagnosed hemochromatosis","women":{"risk":"40.5%","relative":"Not established","horizon":"Ages 40–80","citations":{"risk":["hfeLucas"]}},"men":{"risk":"56.4%","relative":"Not established","horizon":"Ages 40–80","citations":{"risk":["hfeLucas"]}}},{"id":"fibrosis","name":"Liver fibrosis or cirrhosis","women":{"risk":"1.9%","relative":"2.4×","horizon":"Ages 40–80","citations":{"risk":["hfeLucas"],"relative":["hfeLucas"]}},"men":{"risk":"7.7%","relative":"5.9×","horizon":"Ages 40–80","citations":{"risk":["hfeLucas"],"relative":["hfeLucas"]}}},{"id":"liver-cancer","name":"Primary liver cancer","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"5.5%","relative":"6.9×","horizon":"Ages 40–80","citations":{"risk":["hfeLucas"],"relative":["hfeLucas"]}}},{"id":"osteoarthritis","name":"Osteoarthritis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"joint-replacement","name":"Joint replacement","women":{"risk":"23.2%","relative":"1.1×","horizon":"Ages 40–80","citations":{"risk":["hfeLucas"],"relative":["hfeLucas"]}},"men":{"risk":"27.9%","relative":"1.6×","horizon":"Ages 40–80","citations":{"risk":["hfeLucas"],"relative":["hfeLucas"]}}},{"id":"osteoporosis","name":"Osteoporosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"diabetes","name":"Diabetes","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"23.5%","relative":"1.2×","horizon":"Ages 40–80","citations":{"risk":["hfeLucas"],"relative":["hfeLucas"]}}},{"id":"death","name":"Death from any cause","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"33.1%","relative":"1.3×","horizon":"Ages 40–80","citations":{"risk":["hfeLucas"],"relative":["hfeLucas"]}}},{"id":"brain","name":"Dementia, delirium, or Parkinson’s disease","women":{"risk":"8.6%","relative":"1.2×","horizon":"Ages 40–80","citations":{"risk":["hfeLucas"],"relative":["hfeLucas"]}},"men":{"risk":"16.4%","relative":"1.6×","horizon":"Ages 40–80","citations":{"risk":["hfeLucas"],"relative":["hfeLucas"]}}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Most homozygotes never develop organ damage. Untreated overload can also cause hypogonadism and, rarely, cardiomyopathy.","sources":["hfeEasl","hfe"]},{"title":"What treatment changes","text":"Phlebotomy can improve fatigue and liver tests, and fibrosis regresses in some. Cirrhosis, arthropathy, diabetes, and hypogonadism usually persist; liver cancer can arise years after iron depletion with cirrhosis.","sources":["hfeAcg","hfeEasl"]},{"title":"Association evidence","text":"Community cohorts report lower risks than studies of patients’ relatives. In UK Biobank, heavy alcohol added to liver risk in men, and a higher polygenic iron score was associated with more incident disease (HR 1.51, 95% CI 1.09–2.09).","sources":["hfePilling","hfeAcg"]},{"title":"Treatment if liver disease develops","text":"Manage cirrhosis as for other causes; consider transplantation for decompensation or hepatocellular carcinoma.","sources":["hfe","hfeAcg"]}],"otherGenotype":{"title":"If one copy is affected","text":"A C282Y heterozygote (about 14% of UK Biobank) is a carrier without clinically significant iron overload; if iron studies are abnormal, look for another cause and refer unexplained severe loading to evaluate other iron genes. For C282Y with H63D, confirm two variants: shown on opposite copies (in trans) by parental testing or laboratory phasing; if they are on the same copy, use the carrier guidance above. A C282Y/H63D compound heterozygote carries low risk: by age 80 years 5.4% of men and 2.7% of women were diagnosed, with no excess death, liver disease, liver cancer, joint replacement, or diabetes. Check transferrin saturation and ferritin, yearly if minimally raised (BSH); phlebotomy only for overload confirmed by MRI or biopsy after excluding alcohol, metabolic liver disease, and inflammation. No extended family testing for either, though the partner’s genotype matters for children.","sources":["hfePilling","hfeLucas","hfeEasl","ironReferral","hfeAcg"]},"plans":{}},"HJV":{"symbol":"HJV","genotype":"Biallelic","summary":"Too little hepcidin lets iron load fast and early, before age 30 years in most reported patients, often with hypogonadism and cardiomyopathy; heart failure is the main cause of death. Phlebotomy started before organ damage prevents most complications.","table":{"caption":"Iron overload and organ involvement","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"onset","name":"Onset at or before age 30 years","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hypogonadism","name":"Hypogonadism","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"fibrosis","name":"Liver fibrosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cardiomyopathy","name":"Cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"diabetes","name":"Glucose intolerance or diabetes","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"arthropathy","name":"Arthropathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cirrhosis","name":"Cirrhosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"liver-cancer","name":"Primary liver cancer","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"death","name":"Death during reported follow-up","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"What treatment changes","text":"Early phlebotomy to iron depletion sharply reduces morbidity and mortality. Established hypogonadism usually needs lifelong hormone replacement.","sources":["hjvGeneReviews","hjvEasl"]},{"title":"Association evidence","text":"ClinGen: Definitive, autosomal recessive (July 2025). Classed as non-HFE hemochromatosis with HAMP, TFR2, and gain-of-function SLC40A1.","sources":["hjvClingen","hjvBioiron"]},{"title":"Variant and ancestry effects","text":"p.Gly320Val is the most common variant (45 unrelated probands, all European ancestry). Later-onset, milder disease treated by phlebotomy alone suggests modifiers or less damaging variants; genotype alone does not set the pace.","sources":["hjvKong","hjvEasl"]}],"otherGenotype":{"title":"If one copy is affected","text":"A carrier state; this plan does not apply and no guideline recommends monitoring or treatment. Iron overload is rare: 15 published single-variant cases (median ferritin 444 µg/L), 10 with a variant in another iron gene, suggesting digenic disease, which needs strict proof of pathogenicity. Check iron studies under usual care; refer to an iron-disorders specialist if transferrin saturation and ferritin are raised or the patient also carries HFE C282Y. If a partner also carries an HJV variant, each child has a 25% chance of juvenile hemochromatosis; offer partner carrier testing when planning a pregnancy.","sources":["hjvKong","hjvBioiron","hjvEasl","hjvGeneReviews"]},"plans":{}},"HMBS":{"symbol":"HMBS","genotype":"Heterozygous","summary":"One HMBS variant halves a liver heme-synthesis enzyme, so drugs, fasting, alcohol, smoking, or progesterone can trigger attacks of severe abdominal pain, neuropathy, and hyponatremia. About 1% of carriers in the general population ever have a potentially life-threatening attack, mostly women aged 15–50 years; active disease brings high liver cancer risk after age 50 years.","table":{"caption":"Porphyria attack and long-term risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"attack-population","name":"Acute attack, carriers in the general population","women":{"risk":"0.5–1%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["hmbsLenglet"]}},"men":{"risk":"0.5–1%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["hmbsLenglet"]}}},{"id":"attack-family","name":"Acute symptoms, carriers in families with AIP","women":{"risk":"50%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["hmbsBaumann"]}},"men":{"risk":"17%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["hmbsBaumann"]}}},{"id":"liver-cancer","name":"Primary liver cancer, diagnosed AIP","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"liver-cancer-latent","name":"Primary liver cancer, urine PBG never raised","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ckd","name":"Chronic kidney disease, diagnosed AIP","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hypertension","name":"Hypertension, diagnosed AIP","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"kidney-cancer","name":"Kidney cancer, diagnosed acute hepatic porphyria","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Abdominal pain lacks peritoneal signs. Attacks can bring ileus, seizures, and motor neuropathy progressing to respiratory paralysis; death is now rare, but sudden arrhythmic death occurs. Recovery from a late-treated attack can take weeks to months, and over half with recurrent attacks report chronic neurologic symptoms.","sources":["hmbsClingenAc","hmbsGeneReviews","hmbsAga"]},{"title":"Triggers","text":"Medications 37%, weight-loss diets 22%, surgery 16%, environmental exposures 7% (US cohort); often none is found. Smoking is associated with frequent attacks (OR 1.62).","sources":["hmbsClingenAc","hmbsGeneReviews"]},{"title":"Association evidence","text":"ClinGen: Definitive, semidominant (May 2022); adult actionability Strong (2023), with penetrance in unselected populations still uncertain.","sources":["hmbsClingenValidity","hmbsClingenAc"]},{"title":"Treatment if attacks recur","text":"Givosiran, an RNAi drug against hepatic ALAS1, cut the 6-month attack rate from a mean 6.5 to 1.9 (rate ratio 0.3, 95% CI 0.2–0.4) and hemin days from 12.8 to 4.7. ALT at least 3 times normal in 15%, renal adverse reactions in 15%, injection-site reactions in 25%.","sources":["hmbsGivosiranLabel"]}],"otherGenotype":{"title":"If both copies are affected","text":"Biallelic (homozygous dominant) AIP is very rare: onset in infancy or early childhood with developmental delay, hypotonia, ataxia, seizures, and progressive leukoencephalopathy, and markedly raised urine ALA and PBG, usually without typical attacks. In 12 cases no therapy modified disease; hemin and liver transplantation gave little benefit, and givosiran helped in one case. Confirm two variants first: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-variant guidance. Refer to metabolic genetics. If both partners carry an HMBS variant, each pregnancy has a 25% chance of a biallelic child.","sources":["hmbsAraque","hmbsClingenValidity"]},"plans":{}},"HNF1A":{"symbol":"HNF1A","genotype":"Heterozygous","summary":"HNF1A-MODY is diabetes from a progressive insulin-secretion defect, usually starting in adolescence or early adulthood in referred families but far less often in carriers without a family history. It is unusually sensitive to low-dose sulfonylurea.","table":{"caption":"Diabetes and liver risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"diabetes-40","name":"Diabetes by age 40 years","women":{"risk":"32–49%","relative":"Not established","horizon":"By age 40 · unselected carriers","citations":{"risk":["hnf1aMirshahi"]}},"men":{"risk":"32–49%","relative":"Not established","horizon":"By age 40 · unselected carriers","citations":{"risk":["hnf1aMirshahi"]}}},{"id":"diabetes-55","name":"Diabetes by age 55 years","women":{"risk":"96%","relative":"Not established","horizon":"By age 55 · family study","citations":{"risk":["hnf1aIspad"]}},"men":{"risk":"96%","relative":"Not established","horizon":"By age 55 · family study","citations":{"risk":["hnf1aIspad"]}}},{"id":"adenoma","name":"Liver adenomatosis found on screening","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cv-death","name":"Cardiovascular death","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Often misclassified as type 1 or type 2 diabetes and treated with insulin. Carriers die of cardiovascular disease more often and younger than unaffected relatives.","sources":["hnf1aIspad","hnf1aClingenAc","hnf1aSteele"]},{"title":"What treatment changes","text":"The beta-cell defect lies upstream of the sulfonylurea receptor. In a dedicated clinic most patients kept good control on sulfonylurea alone for years; retinopathy was less common than in matched type 1 diabetes (13.6% against 50%).","sources":["hnf1aPearson","hnf1aBacon"]},{"title":"Liver adenomas","text":"HNF1A-inactivated adenomas are 30–40% of hepatocellular adenomas, usually from two somatic HNF1A hits; germline variants occur in adenomatosis with MODY. Typically steatotic on MRI. No progression in 14 pregnancies.","sources":["hnf1aEasl","hnf1aHaddouche"]},{"title":"Association evidence","text":"ClinGen: Definitive, autosomal dominant (October 2018); adult actionability Strong. Common low-effect HNF1A variants that modestly raise type 2 diabetes risk are not reported.","sources":["hnf1aClingen","hnf1aClingenAc"]}],"otherGenotype":{"title":"If both copies are affected","text":"No condition from two inherited HNF1A variants is established; HNF1A-MODY is curated as autosomal dominant only. Manage as for one copy with a monogenic diabetes centre.","sources":["hnf1aClingen"]},"plans":{}},"HNF1B":{"symbol":"HNF1B","genotype":"Heterozygous sequence variant or whole-gene deletion","summary":"A sequence variant or whole-gene deletion causes a multisystem disorder led by kidney malformation and slowly progressive kidney disease, with early insulin-requiring diabetes, low magnesium, high urate, abnormal liver tests, pancreatic hypoplasia, and genital tract malformations in some. Expression varies even within families, so every carrier needs baseline kidney and glucose testing.","table":{"caption":"Kidney, metabolic, and other risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"kidney-structure","name":"Kidney structural abnormality (cysts, dysplasia, small or single kidney)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ckd","name":"Chronic kidney disease stage 3–4","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"kidney-failure","name":"Kidney failure","women":{"risk":"10%","relative":"Not established","horizon":"At assessment · deletion carriers","citations":{"risk":["hnf1bCannon"]}},"men":{"risk":"10%","relative":"Not established","horizon":"At assessment · deletion carriers","citations":{"risk":["hnf1bCannon"]}}},{"id":"diabetes","name":"Diabetes","women":{"risk":"60%","relative":"Not established","horizon":"At assessment · deletion carriers","citations":{"risk":["hnf1bCannon"]}},"men":{"risk":"60%","relative":"Not established","horizon":"At assessment · deletion carriers","citations":{"risk":["hnf1bCannon"]}}},{"id":"magnesium","name":"Hypomagnesemia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"exocrine","name":"Exocrine pancreatic dysfunction","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"liver","name":"Abnormal liver tests","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"genital-women","name":"Genital tract malformation in women (uterus, vagina)","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"genital-men","name":"Genital tract malformation in men (epididymis, vas deferens)","women":null,"men":{"risk":"Not established","relative":"Not established"}},{"id":"neuro","name":"Neurodevelopmental disorder (17q12 whole-gene deletion only)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Kidney disease dominates; isolated diabetes without kidney involvement is rare. 46 of 114 French adults with diabetes had retinopathy or neuropathy, and cardiovascular risk factors were common.","sources":["hnf1bDubois","hnf1bClingenAc"]},{"title":"Deletion or sequence variant","text":"Deletions are a third to a half of cases. Deletion carriers had less advanced kidney disease, were leaner, and were more often on insulin.","sources":["hnf1bDubois","hnf1bClissold","hnf1bClissoldReview","hnf1bClingenAc"]},{"title":"Association evidence","text":"ClinGen: Definitive, autosomal dominant (January 2021); adult actionability Strong (2024). Recommendations rest mainly on expert opinion extrapolated from kidney and diabetes care.","sources":["hnf1bClingen","hnf1bClingenAc"]}],"otherGenotype":{"title":"If both copies are affected","text":"No condition from two inherited HNF1B variants is established; this plan applies to one affected copy.","sources":["hnf1bClingen"]},"plans":{}},"HOXB13":{"symbol":"HOXB13","genotype":"Heterozygous","summary":"A HOXB13 variant, most often the Northern European founder p.Gly84Glu (G84E), raises prostate cancer risk about three- to fourfold and shifts diagnosis earlier. No other cancer risk, and no risk for women, is established.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"prostate","name":"Prostate cancer","women":null,"men":{"risk":"33–60%","relative":"Not established","horizon":"By age 80","citations":{"risk":["hoxb13Karlsson","hoxb13MacInnis"]}}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Age at onset and aggressiveness","text":"G84E concentrates in early-onset and familial prostate cancer. There is no clear association with Gleason score, stage, or survival; a 2023 study of 17,546 men found HOXB13 variants in 1.6% of aggressive and 2.1% of nonaggressive cases (OR 0.87, 95% CI 0.69–1.10).","sources":["hoxb13Karlsson","hoxb13Pdq","hoxb13Darst"]},{"title":"Frequency and ancestry","text":"G84E is in 1.3% of Swedish population controls and about 1 in 360 UK men, most common in Nordic populations. X285K occurs in men of West African ancestry; G132E has been reported in Japan.","sources":["hoxb13Karlsson","hoxb13Nyberg","hoxb13Pdq"]}],"otherGenotype":{"title":"If both copies are affected","text":"Two G84E copies are rare, with no separate risk estimate or guidance; the UK model assumed each copy adds risk, which is unmeasured. Use this plan as the minimum and refer to clinical genetics.","sources":["hoxb13Nyberg","hoxb13Ambry"]},"plans":{}},"JUP":{"symbol":"JUP","genotype":"Heterozygous","summary":"One affected JUP copy is usually a carrier state for Naxos disease, a recessive ARVC with woolly hair and palmoplantar keratoderma; Naxos-variant carriers did not develop significant heart disease. Dominant JUP ARVC is reported in very few families, so the plan depends on which condition the variant was classified for.","table":{"caption":"Cardiac findings with one affected copy","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"minor-changes","name":"Minor ECG or echocardiographic changes","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"arvc","name":"Clinically significant ARVC","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Association evidence","text":"Naxos disease was the first ARVC linked to a desmosomal gene. A ClinGen-framework reappraisal (James 2021) rated JUP definitive for ARVC among 26 genes without separating dominant from recessive inheritance; the live ClinGen database holds no JUP validity record. ClinGen adult actionability for ARVD12 is moderate and pediatric strong (2020). JUP is a first-tier ARVC gene.","sources":["jupJames","jupClinGen","jupWilde"]},{"title":"Skin and hair clues","text":"Palmoplantar keratoderma with woolly hair points to Naxos disease (JUP) or Carvajal syndrome (DSP). Palmoplantar keratosis is also listed among ARVC skin features.","sources":["jupEsc2023","jupEsc2022"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan. With two confirmed copies this is Naxos disease and the carrier plan does not apply. In 12 Greek families all 26 homozygous adults met ARVC criteria, the youngest by age 13 years, with woolly hair and palmoplantar keratoderma: ECG abnormalities 92%, ventricular arrhythmias 92%, right ventricular structural change in all, left ventricular involvement 27%. Over about 10 years 62% progressed, 46% had arrhythmic events, and 27% developed heart failure; annual disease-related mortality was 3% and sudden death 2.3%. Manage with full ARVC care at an inherited cardiac disease centre: exercise restriction, beta-blockers once arrhythmias appear, and ICD decisions on risk features. A homozygous nonsense variant with complete plakoglobin loss caused lethal congenital skin fragility (epidermolysis bullosa) without apparent heart disease. Offer siblings counseling and testing.","sources":["jupProtonotarios","jupAntoniades","jupEsc2023","jupPigors"]},"plans":{}},"KCNE1":{"symbol":"KCNE1","genotype":"Heterozygous","summary":"One KCNE1 variant is a low-penetrance QT risk, not established long QT syndrome; ClinGen rates dominant LQT5 as Limited. The clearer risks are drug-induced QT prolongation and, with two affected copies, Jervell and Lange-Nielsen syndrome type 2.","table":{"caption":"QT and arrhythmia risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"qtc","name":"QTc above 460 ms on first ECG","women":{"risk":"20.7%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["kcne1Roberts"]}},"men":{"risk":"20.7%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["kcne1Roberts"]}}},{"id":"event","name":"Definite arrhythmic event","women":{"risk":"1.4%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["kcne1Roberts"]}},"men":{"risk":"1.4%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["kcne1Roberts"]}}},{"id":"dilqts","name":"Drug-induced torsades de pointes (p.Asp85Asn only)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Association evidence","text":"ClinGen downgraded dominant LQT5 from Moderate to Limited in December 2020, and a 2020 international reappraisal listed KCNE1 among nine genes with limited or disputed LQTS evidence. ClinGen has curated KCNE1 only for dominant LQT5 (Limited); the Definitive Jervell and Lange-Nielsen and Strong acquired-LQTS ratings come from the 2022 consensus. KCNE1 explains under 1% of LQTS.","sources":["kcne1ValidityLqt5","kcne1Adler","kcne1Wilde"]},{"title":"Severity","text":"Probands, found through symptoms or a long QTc, had a 16.9% event rate; a carrier with either is higher risk.","sources":["kcne1Roberts"]},{"title":"Testing guidance","text":"KCNE1 testing may be performed in high-probability clinical LQTS and should be offered in Jervell and Lange-Nielsen syndrome. Limited-evidence genes should not be tested at intermediate LQTS probability.","sources":["kcne1Wilde"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan. Two affected copies cause Jervell and Lange-Nielsen syndrome type 2: congenital sensorineural deafness with QT prolongation. Refer to an inherited arrhythmia center at diagnosis and manage as LQTS. KCNE1 causes under 10% of cases and runs milder than the KCNQ1 form: 2 of 19 (10.5%) had a definite arrhythmic event, not significantly different from heterozygotes (HR 1.7, 95% CI 0.3–10.8). Each further child of two carrier parents has a 1 in 4 chance.","sources":["kcne1Roberts","kcne1Jlns","kcne1Wilde"]},"plans":{}},"KCNH2":{"symbol":"KCNH2","genotype":"Heterozygous","summary":"KCNH2 loss of function causes long QT syndrome type 2 (LQT2), with arrhythmias triggered by sudden noise, emotional arousal, and rest. Risk exceeds LQT1, is highest in adult women and after childbirth, and falls with beta-blockers and drug avoidance.","table":{"caption":"Arrhythmia risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"first-event","name":"First cardiac event (syncope, cardiac arrest, or sudden death)","women":{"risk":"46%","relative":"Not established","horizon":"By age 40 · before therapy","citations":{"risk":["kcnh2Priori"]}},"men":{"risk":"46%","relative":"Not established","horizon":"By age 40 · before therapy","citations":{"risk":["kcnh2Priori"]}}},{"id":"arrest","name":"Cardiac arrest or sudden death","women":{"risk":"26%","relative":"Not established","horizon":"By age 40","citations":{"risk":["kcnh2Migdalovich"]}},"men":{"risk":"14%","relative":"Not established","horizon":"By age 40","citations":{"risk":["kcnh2Migdalovich"]}}},{"id":"arrest-normal-qtc","name":"Cardiac arrest or sudden death, QTc 440 ms or less (KCNQ1, KCNH2, and SCN5A pooled) (LQT1–3 pooled)","women":{"risk":"4%","relative":"Not established","horizon":"By age 40","citations":{"risk":["kcnh2Goldenberg"]}},"men":{"risk":"4%","relative":"Not established","horizon":"By age 40","citations":{"risk":["kcnh2Goldenberg"]}}},{"id":"postpartum","name":"Cardiac event after childbirth","women":{"risk":"Not established","relative":"Not established"},"men":null}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"LQTS prevalence is at least 1 in 2,500; untreated symptomatic index cases have about 50% 10-year mortality. Highest-risk groups: LQT2, women with LQT2, QTc above 500 ms, symptoms before age 10 years, and prior cardiac arrest or recurrent syncope. Treated, prognosis is usually excellent.","sources":["kcnh2Wilde","kcnh2Actionability"]},{"title":"Association evidence","text":"ClinGen: Definitive for dominant LQTS (2018) and short QT syndrome (2020); Disputed for Brugada syndrome (2025). Only KCNQ1, KCNH2, and SCN5A are definitive for typical LQTS. KCNH2 causes 30–45% of genotyped LQTS.","sources":["kcnh2Validity","kcnh2Adler","kcnh2Wilde"]},{"title":"Variant location","text":"Pore-region and transmembrane variants independently raise event risk. Ask genetics about location when it may change treatment.","sources":["kcnh2Wilde","kcnh2Migdalovich"]},{"title":"Unselected carriers","text":"In TOPMed (26,976 people), 160 carriers of rare variants judged potentially LQTS-causing in any of 10 LQTS genes had a QTc 10.9 ms longer than noncarriers (95% CI 7.4–14.4 ms); this pooled figure is not specific to KCNH2. In eMERGE-III (21,846 people without an indication for testing), 0.6% carried a pathogenic or likely pathogenic arrhythmia variant, and 19 of the 54 who received results had an inherited arrhythmia diagnosis, mostly LQTS.","sources":["kcnh2Nauffal","kcnh2Glazer"]},{"title":"Treatment effect","text":"Beta-blockers cut LQT2 events by 52% (RR 0.48, 95% CI 0.30–0.77; before-and-after data), less than in LQT1. Only nadolol significantly reduced life-threatening events across all genotypes (HR 0.38; 1,710 patients). Lumacaftor-ivacaftor for trafficking-defect variants is preliminary and not in clinical use for LQTS.","sources":["kcnh2Actionability","kcnh2Wilde","kcnh2Mazzanti"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan. No separate KCNH2 syndrome is described for two affected copies; recessive LQTS generally has a longer QTc and higher arrhythmic risk than one variant, so refer promptly to an inherited arrhythmia center.","sources":["kcnh2Validity","kcnh2Wilde","kcnh2Ehra2026"]},"plans":{}},"KCNJ2":{"symbol":"KCNJ2","genotype":"Heterozygous loss-of-function variant","summary":"Loss-of-function KCNJ2 variants cause Andersen-Tawil syndrome type 1: ventricular ectopy and tachycardia with prominent U waves, episodic weakness, and subtle facial and limb features, any of which may be absent. Rare gain-of-function variants cause short QT syndrome instead.","table":{"caption":"Arrhythmia and muscle risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"lae","name":"Life-threatening arrhythmic event","women":{"risk":"7.9%","relative":"Not established","horizon":"5-year follow-up · carriers","citations":{"risk":["kcnj2Mazzanti"]}},"men":{"risk":"7.9%","relative":"Not established","horizon":"5-year follow-up · carriers","citations":{"risk":["kcnj2Mazzanti"]}}},{"id":"arrest","name":"Cardiac arrest, index patients","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"syncope","name":"Syncope","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"va","name":"Ventricular arrhythmia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"tu","name":"Characteristic T–U wave pattern on ECG","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"paralysis","name":"Periodic paralysis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dysmorphic","name":"Dysmorphic features","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"sqts","name":"Short QT syndrome (gain-of-function variants only)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Most patients stay event-free through young adulthood, with risk accumulating later. Prevalence is about 1 in 1,000,000.","sources":["kcnj2Mazzanti","kcnj2Registry","kcnj2Esc"]},{"title":"Association evidence","text":"Consensus lists KCNJ2 as definitive for ATS; 97% of tested registry patients carried a variant. ClinGen has no ATS curation and rates KCNJ2 moderate for short QT syndrome, limited for isolated long QT syndrome, disputed for CPVT, and no known relationship for congenital heart disease.","sources":["kcnj2Wilde","kcnj2Registry","kcnj2ClinGen","kcnj2Adler","kcnj2Walsh"]},{"title":"Variant location","text":"69 distinct variants in 327 registry patients, 89.9% missense, with hotspots at residues 67, 82, and 218. Phenotype varies even with the same hotspot variant.","sources":["kcnj2RegistryGenetics"]},{"title":"Treatment evidence","text":"Beta-blockers and class Ic drugs reduce ectopy but did not lower the event rate: 1.37 per 100 person-years on beta-blockers alone and 1.46 with class Ic drugs, against 1.24 untreated. Amiodarone is proarrhythmic in ATS; ablation of the ectopy substrate is ineffective.","sources":["kcnj2Mazzanti","kcnj2Ehra"]}],"otherGenotype":{"title":"If both copies are affected","text":"No two-copy KCNJ2 condition is established, and this plan is unstudied in that setting. Refer to clinical genetics.","sources":["kcnj2GeneReviews"]},"plans":{}},"KCNQ1":{"symbol":"KCNQ1","genotype":"Heterozygous · LQT1-associated loss of function","summary":"KCNQ1 loss of function causes long QT syndrome type 1 (LQT1), with arrhythmias triggered mainly by exertion, swimming, and emotional stress. Risk follows the QTc and syncope history, and beta-blockers work especially well.","table":{"caption":"Arrhythmia risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"first-event","name":"Cardiac event during adulthood (LQT1)","women":{"risk":"11%","relative":"5.5×","horizon":"Ages 18–40 · before beta-blockers · sexes pooled","citations":{"risk":["kcnq1Koponen2018"],"relative":["kcnq1Koponen2018"]}},"men":{"risk":"11%","relative":"5.5×","horizon":"Ages 18–40 · before beta-blockers · sexes pooled","citations":{"risk":["kcnq1Koponen2018"],"relative":["kcnq1Koponen2018"]}}},{"id":"arrest","name":"Cardiac arrest or sudden death","women":{"risk":"10%","relative":"Not quantified","horizon":"Observed before age 40 · before therapy, sexes pooled","citations":{"risk":["kcnq1Priori"]}},"men":{"risk":"10%","relative":"Not quantified","horizon":"Observed before age 40 · before therapy, sexes pooled","citations":{"risk":["kcnq1Priori"]}}},{"id":"arrest-normal-qtc","name":"Cardiac arrest or sudden death, QTc 440 ms or less (LQT1–3 pooled)","women":{"risk":"4%","relative":"10×","horizon":"Birth–40 years · mixed treatment · sexes pooled","citations":{"risk":["kcnq1Goldenberg"],"relative":["kcnq1Goldenberg"]}},"men":{"risk":"4%","relative":"10×","horizon":"Birth–40 years · mixed treatment · sexes pooled","citations":{"risk":["kcnq1Goldenberg"],"relative":["kcnq1Goldenberg"]}}},{"id":"qt-drug","name":"Cardiac arrest on a QT-prolonging drug, before beta-blockers","women":{"risk":"Not estimated","relative":"Not quantified"},"men":{"risk":"Not estimated","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"LQT1 can cause syncope, cardiac arrest, or sudden death, including in some carriers with a normal resting QTc. Risk varies with symptoms, QTc, age, variant, treatment, and adherence. Effective beta-blockade and avoidance of QT-prolonging exposures substantially improve prognosis, but do not eliminate risk.","sources":["kcnq1Esc2022","kcnq1Vincent"]},{"title":"Association evidence","text":"ClinGen classifies KCNQ1 as Definitive for autosomal dominant LQTS and autosomal recessive Jervell and Lange-Nielsen syndrome. The 2022 genetic-testing consensus lists KCNQ1 as accounting for 40–55% of genetically explained LQTS; this is a share of diagnosed cases, not carrier penetrance.","sources":["kcnq1Validity","kcnq1Adler","kcnq1Wilde"]},{"title":"Variant location","text":"Transmembrane location, the S6 segment, and a dominant-negative effect independently raise risk; some variants, such as p.Ala341Val, are unusually severe. Ask genetics about location and mechanism when it may change treatment.","sources":["kcnq1Wilde","kcnq1Costa"]},{"title":"Unselected carriers","text":"In TOPMed (26,976 people), 160 carriers of rare variants judged potentially LQTS-causing in any of 10 LQTS genes had a QTc 10.9 ms longer than noncarriers (95% CI 7.4–14.4 ms); this pooled figure is not specific to KCNQ1. In eMERGE-III (21,846 people without an indication for testing), 0.6% carried a pathogenic or likely pathogenic arrhythmia variant, and 19 of the 54 who received results had an inherited arrhythmia diagnosis, mostly LQTS.","sources":["kcnq1Nauffal","kcnq1Glazer"]},{"title":"Treatment effect","text":"A 2017 meta-analysis of before-and-after studies estimated fewer LQT1 cardiac events on beta-blockers (RR 0.29, 95% CI 0.20–0.41). The endpoint included syncope, aborted arrest, and sudden death. These observational treatment comparisons support benefit but are not a carrier-versus-noncarrier risk ratio or a guaranteed 71% reduction for an individual.","sources":["kcnq1Ahn2017"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm that both variants are disease-causing and in trans, with cardiovascular genetics review; two variants in cis do not establish biallelic disease. Biallelic loss-of-function KCNQ1 can cause severe recessive LQTS, often with congenital sensorineural hearing loss (Jervell and Lange-Nielsen syndrome), but normal hearing does not exclude biallelic cardiac disease. Arrange audiology and inherited-arrhythmia review promptly. In a selected 186-patient JLNS series, 86% had cardiac events, half were symptomatic by age 3 years, mean QTc was 557 ±65 ms, and 51% had events despite beta-blockers; 27% had arrest or sudden death despite beta-blocker therapy. These are not universal risks for every biallelic genotype. The specialist individualizes high-dose nonselective beta-blockade, LCSD, and ICD assessment; QTc >550 ms and very early syncope are concerning features. Do not simply apply the routine heterozygous risk figures or initiate a high weight-based dose without specialist titration. If both parents are heterozygous carriers, each pregnancy has a 25% chance of inheriting both variants.","sources":["kcnq1Jlns","kcnq1Ehra2026","kcnq1Hearing2008","kcnq1Wilde"]},"plans":{}},"KIT":{"symbol":"KIT","genotype":"Heterozygous activating variant","summary":"An activating germline KIT variant causes primary familial GIST: usually multiple GISTs from early or mid adulthood, often with skin hyperpigmentation, dysphagia, and sometimes mastocytosis. A KIT variant reported for piebaldism carries no GIST risk.","table":{"caption":"Tumor and feature frequency","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"gist","name":"Gastrointestinal stromal tumor, any","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"multifocal","name":"Multifocal GIST at diagnosis, among patients with GIST","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pigment","name":"Skin hyperpigmentation, lentigines, or nevi","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dysphagia","name":"Dysphagia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mastocytosis","name":"Systemic mastocytosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cutaneous-mast","name":"Urticaria pigmentosa or cutaneous mastocytosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Many familial GISTs behave as low-risk tumors, but metastases occur. A 28-year-old with exon 13 p.Lys642Glu died of progression after stopping imatinib for toxicity; another kindred lost a member to metastatic GIST at age 74 years.","sources":["kitYan","kitBrodey","kitFornasarig"]},{"title":"Association evidence","text":"ClinGen: Definitive for GIST (autosomal dominant, January 2020).","sources":["kitClingen","kitGeneReviews"]},{"title":"Treatment if GIST develops","text":"Exon 11 variants have shown long imatinib responses; exon 13 p.Asn655Lys was poorly inhibited by most agents in laboratory assays; one exon 18 germline case had primary imatinib resistance. Use long-term inhibitors cautiously in younger patients.","sources":["kitBrodey","kitFornasarig","kitYan"]}],"otherGenotype":{"title":"If both copies are affected","text":"No two-copy KIT condition is described. Two variants need clinical genetics review.","sources":["kitGeneReviews"]},"plans":{}},"LAMP2":{"symbol":"LAMP2","genotype":"X-linked · Hemizygous men, heterozygous women","summary":"LAMP2 loss causes Danon disease, a severe, highly penetrant cardiomyopathy. Men develop massive hypertrophy with pre-excitation in childhood or adolescence, often with myopathy and learning difficulty, and many need a transplant or die by their twenties; women develop cardiomyopathy one to two decades later, with a similar eventual rate of death, transplant, or assist device.","table":{"caption":"Cardiac and extracardiac risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"hcm","name":"Hypertrophic cardiomyopathy pattern","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dcm","name":"Dilated cardiomyopathy pattern","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"conduction","name":"Conduction abnormalities","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"preexcitation","name":"Pre-excitation pattern","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hf-admission","name":"First heart failure hospitalization","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"icd","name":"ICD implantation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pacemaker","name":"Pacemaker implantation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"transplant","name":"Heart transplantation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"composite","name":"Death, heart transplant, or assist device","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"death","name":"Death","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"myopathy","name":"Skeletal myopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cognitive","name":"Cognitive problems","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"eye","name":"Eye abnormalities","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Most patients develop symptomatic heart failure. Of 7 young patients followed prospectively, by age 14–24 years 4 died of heart failure, 1 died suddenly despite an ICD, 1 survived cardiac arrest, and 1 received a transplant.","sources":["lamp2ClinGenAct","lamp2Maron","lamp2Lotan"]},{"title":"Association evidence","text":"ClinGen: definitive for Danon disease (2017) and moderately actionable (2023). The 2024 AHA/ACC HCM guideline lists Danon disease among phenocopies where a genetic diagnosis prompts more aggressive management. LAMP2 variants appear in about 1–4% of HCM in reported series.","sources":["lamp2ClinGen","lamp2ClinGenAct","lamp2Aha2024"]},{"title":"Why women differ","text":"Variable expression in women is attributed to X-inactivation. Some have no detectable features; extracardiac signs are usually absent, so diagnosis can come late, after the heart has dilated and become hypokinetic.","sources":["lamp2ClinGenAct"]},{"title":"Treatment if disease advances","text":"No approved disease-specific therapy. An AAV gene therapy (RP-A501) is in a phase 2 trial in males; ask the cardiomyopathy center about trial eligibility and check clinicaltrials.gov for current status. Post-transplant survival appears similar to other cardiomyopathies overall, though early deaths after transplant or assist device were frequent in men in one registry.","sources":["lamp2ClinGenAct","lamp2Lotan","lamp2Rpa501"]}],"otherGenotype":{"title":"If a woman has two affected copies","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the women's plan. Not described. She would lack a normal copy, like an affected man; use the men's plan under cardiomyopathy center care.","sources":["lamp2GeneReviews"]},"plans":{}},"LDLR":{"symbol":"LDLR","genotype":"Heterozygous","summary":"An FH-causing LDLR variant reduces LDL clearance and can raise LDL cholesterol from childhood, increasing premature coronary disease risk. Risk varies with the variant, cumulative LDL-C exposure and other factors; early, sustained treatment lowers it.","table":{"caption":"Coronary artery disease risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"cad-any","name":"Coronary artery disease (predicted loss-of-function variants)","women":{"risk":"Not quantified by age","relative":"OR 5.5","citations":{"relative":["fhAbulHusn2016"]}},"men":{"risk":"Not quantified by age","relative":"OR 5.5","citations":{"relative":["fhAbulHusn2016"]}}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"Untreated FH can cause premature coronary disease. Early and sustained LDL-C lowering reduces cardiovascular risk, but treatment does not guarantee normalization to population risk; prior exposure and existing ASCVD still matter.","sources":["ldlrIas","fhIas2023","fhGr2025"]},{"title":"Variant type and LDL cholesterol","text":"In the cited studies, LDLR loss-of-function variants were associated with higher LDL-C and coronary odds than the studied damaging missense variants. Variant class alone does not establish residual receptor function or an individual prognosis; seek variant-specific interpretation when it changes management.","sources":["ldlrKhera","ldlrDo"]},{"title":"Association evidence","text":"In Khera’s study, LDLR accounted for 141 of 164 FH-variant carriers. The 27% with LDL-C below 130 mg/dL refers to the pooled FH-gene sample, not a separate LDLR penetrance estimate. Variant definitions, treatment correction and ascertainment all affect these observed distributions.","sources":["ldlrKhera","fhAbulHusn2016"]},{"title":"Other vascular disease","text":"Coronary disease dominates; stroke is less common. Calcific aortic valve disease mainly accompanies the severe, usually biallelic, phenotype.","sources":["fhGr2025"]},{"title":"If coronary disease develops","text":"For FH with clinical ASCVD, aim for LDL-C below 55 mg/dL. IAS suggests considering initial high-potency statin, ezetimibe and PCSK9-targeted combination therapy in extremely high-risk patients, such as after myocardial infarction or with multivessel or polyvascular disease.","sources":["ldlrIas","fh2026","fhIas2023"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm that both variants cause FH and establish phase: two variants on one LDLR copy differ from variants affecting both copies. A second FH-causing variant in another gene can also produce severe disease. Refer to an FH specialist centre; phenotype and residual receptor activity guide treatment. Untreated LDL-C above about 400 mg/dL, childhood xanthomas or early coronary/aortic disease raise suspicion but are not required. Start therapy from diagnosis; specialist options include statin plus ezetimibe, response-guided PCSK9 inhibition, apheresis and receptor-independent treatments. EAS advises apheresis ideally from age 3 years and no later than 8 years when needed. US evinacumab eligibility expanded to age 1 year in September 2025; verify current treatment labeling. With biallelic LDLR variants, each child inherits an affected LDLR copy; transmission differs in digenic cases, so provide genetic counseling.","sources":["fhGr2025","fhHofh2023","fhFdaEvkeeza2025"]},"plans":{}},"LDLRAP1":{"symbol":"LDLRAP1","genotype":"Biallelic","summary":"Two affected LDLRAP1 copies cause autosomal recessive hypercholesterolemia, a form of homozygous FH: untreated LDL cholesterol usually above 400 mg/dL, with early coronary and aortic valve disease. Statins often work better than in LDLR-related homozygous FH.","table":{"caption":"Cardiovascular outcomes on treatment","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"ascvd","name":"Atherosclerotic cardiovascular disease","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"avs","name":"Aortic valve stenosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"stroke","name":"Stroke","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Mechanism","text":"LDLRAP1 lets liver cells internalize the bound LDL receptor; without it, hepatic LDL clearance fails. Fibroblasts use another adaptor, so skin-cell receptor assays can look normal. Most patients carry two null variants.","sources":["ldlrap1Bourbon"]},{"title":"Severity","text":"ARH counts as homozygous FH, with a phenotype close to the LDLR form. In one pediatric cohort, children with ARH had lower untreated LDL-C than those with biallelic LDLR variants, fewer xanthomas (42.9% against 62.5%), and no cardiovascular complications, against some in the LDLR group.","sources":["ldlrap1Bourbon","ldlrap1Derasmo","ldlrap1Pediatric"]},{"title":"Treatment response","text":"Statins with ezetimibe often work, reflecting residual receptor activity, but most patients stay above goal. LDL receptor-independent treatments matter most: 6 patients on lomitapide in the 52-patient series reached an 88.3% reduction.","sources":["ldlrap1Derasmo","ldlrap1Lomitapide","ldlrap1Evinacumab","ldlrap1Evolocumab","ldlrap1Bourbon"]},{"title":"Frequency","text":"Ultra-rare outside Sardinia, where a founder effect gives a carrier frequency of about 1 in 143. Biallelic LDLRAP1 accounted for 12 of 404 (3%) in an international homozygous FH registry and 4 of 71 (5.6%) in the Spanish registry.","sources":["ldlrap1Sardinia","ldlrap1Bourbon"]},{"title":"Association evidence","text":"ClinGen: Definitive for familial hypercholesterolemia 4, autosomal recessive (2022). No actionability curation; not on the ACMG secondary findings list.","sources":["ldlrap1Clingen","ldlrap1Hofh"]}],"otherGenotype":{"title":"If one copy is affected","text":"One variant is a carrier state, and the risks and plan on this page do not apply. Carriers have normal LDL-C: in Sardinia, 141 against 137 mg/dL in noncarriers (p = 0.19), with no link to myocardial infarction after adjustment. No lipid-lowering treatment or imaging for the carrier result; use standard lipid screening. Very high LDL-C in a carrier needs a search for a second LDLRAP1 variant or an LDLR, APOB, or PCSK9 variant. Offer partner testing before pregnancy: two carrier parents have a 1 in 4 chance of an affected child in each pregnancy.","sources":["ldlrap1Sardinia","ldlrap1Hofh","ldlrap1Ias","fh"]},"plans":{}},"LMNA":{"symbol":"LMNA","genotype":"Heterozygous","summary":"LMNA variants cause a cardiomyopathy in which conduction disease, atrial arrhythmia, and life-threatening ventricular arrhythmia often precede or accompany heart failure. Penetrance is high and onset often in the 30s; some variants instead cause partial lipodystrophy or muscular dystrophy.","table":{"caption":"Cardiac, metabolic, and muscle risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"av-block","name":"AV block or conduction disease","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"atrial","name":"Atrial fibrillation or other atrial arrhythmia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"sustained-va","name":"Sustained ventricular arrhythmia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lv-dysfunction","name":"LV systolic dysfunction (LVEF 50% or less)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"end-stage-hf","name":"End-stage heart failure","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lipodystrophy","name":"Familial partial lipodystrophy type 2","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"muscular-dystrophy","name":"Emery-Dreifuss or limb-girdle muscular dystrophy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Among the most malignant genetic DCMs: sudden death can occur with only mildly reduced LVEF, and about one in five referral patients reaches end-stage heart failure or transplantation.","sources":["lmnaKumar","lmnaHasselberg","lmnaVanRijsingen"]},{"title":"Association evidence","text":"ClinGen: definitive for dilated cardiomyopathy 1A (2026) and semidominant lipodystrophy (2024), limited for ARVC; sufficient evidence for haploinsufficiency; strong adult actionability for DCM. LMNA explains about 4–7% of DCM. ACMG SF v3.2 returns LMNA variants only with case-level evidence of cardiac disease.","sources":["lmnaClinGen","lmnaJordan","lmnaEhra","lmnaAcmgSf"]},{"title":"Risk calculator","text":"LMNA-risk-VTA (lmna-risk-vta.fr): C-index 0.776 in derivation and 0.800 in external validation; built in adults under specialist care.","sources":["lmnaWahbi"]},{"title":"Treatment if disease develops","text":"Primary-prevention ICD candidacy rests on the calculator and phenotype, not on LVEF 35% or less alone.","sources":["lmnaEscIcd","lmnaEsc2022","lmnaEhra"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan on this page. Rare. Biallelic LMNA is an uncommon cause of recessive Emery-Dreifuss muscular dystrophy; other recessive laminopathies are childhood disorders. This plan does not apply: refer to clinical genetics and a neuromuscular and cardiomyopathy center, and offer testing along both parental lines.","sources":["lmnaEdmd"]},"plans":{}},"LZTR1":{"symbol":"LZTR1","genotype":"Heterozygous","summary":"Most LZTR1 results are loss-of-function variants that predispose to schwannomatosis, benign nerve sheath tumors that can cause chronic pain, but a carrier with no personal or family history has well under a 1% chance of disease. A minority of variants cause dominant Noonan syndrome, and loss-of-function carriers also carry recessive Noonan syndrome.","table":{"caption":"Tumor and syndrome risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"swn-incidental","name":"Schwannomatosis, no personal or family history","women":{"risk":"<1%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["lztr1Ern"]}},"men":{"risk":"<1%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["lztr1Ern"]}}},{"id":"swn-family","name":"Schwannomatosis, family with schwannomatosis","women":{"risk":"40–50%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["lztr1Ern"]}},"men":{"risk":"40–50%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["lztr1Ern"]}}},{"id":"vs","name":"Unilateral vestibular schwannoma, in LZTR1-related schwannomatosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"noonan","name":"Noonan syndrome, dominant-acting variant","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Schwannomas are benign; the main burden is chronic neuropathic pain, sometimes disabling and linked to anxiety and depression.","sources":["lztr1GeneReviewsSwn","lztr1Perrino"]},{"title":"Diagnosis","text":"Under the 2022 international criteria, diagnosis requires a germline variant plus at least one pathologically confirmed schwannoma or hybrid nerve sheath tumor, or a shared LZTR1 variant in two tumors.","sources":["lztr1Criteria","lztr1Perrino"]},{"title":"Treatment if disease develops","text":"Multimodal pain management with a pain specialist or neurologist, mental health support as needed, and surgery for uncontrolled localized pain or a neurologic deficit.","sources":["lztr1GeneReviewsSwn","lztr1Ern"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-variant plan on this page. Two affected copies cause recessive Noonan syndrome, ranging from mild to lethal, with hypertrophic cardiomyopathy more often than in the dominant form. Carrier parents are usually unaffected or mildly affected. The schwannomatosis figures and plan on this page do not describe recessive Noonan syndrome. Refer to clinical genetics and cardiology.","sources":["lztr1Johnston","lztr1Noonan","lztr1Jaouadi"]},"plans":{}},"MAX":{"symbol":"MAX","genotype":"Heterozygous","summary":"MAX variants predispose to pheochromocytoma, often bilateral, and less often to paraganglioma. Tumors usually appear in the 30s, secrete norepinephrine, and arise mainly after paternal transmission.","table":{"caption":"Tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"ppgl","name":"Pheochromocytoma or paraganglioma (any)","women":{"risk":"73%","relative":"Not established","horizon":"By age 40 · family study","citations":{"risk":["maxBausch"]}},"men":{"risk":"73%","relative":"Not established","horizon":"By age 40 · family study","citations":{"risk":["maxBausch"]}}},{"id":"bilateral","name":"Bilateral pheochromocytoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"extra-adrenal","name":"Chest or abdominal paraganglioma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"An unrecognized secreting tumor is dangerous in surgery and pregnancy. Non-metastatic tumors are curable by surgery; with metastases, about 50% survive 5 years.","sources":["maxClingen"]},{"title":"Association evidence","text":"The ClinGen Hereditary Cancer expert panel classified MAX and hereditary pheochromocytoma-paraganglioma as definitive, autosomal dominant (June 2021). MAX accounts for about 4% of hereditary cases and 1.12% of patients without a variant in other known genes.","sources":["maxValidity","maxClingen","maxBurnichon"]},{"title":"Treatment if a tumor develops","text":"Surgery at an experienced center first. After removal, watch for blood pressure instability and hypoglycemia; severe hypoglycemia in 13%, usually 2–4.5 hours after resection. Cortical-sparing surgery leaves tissue that needs surveillance.","sources":["maxClingen","maxBausch"]}],"otherGenotype":{"title":"If both copies are affected","text":"No condition or management pathway for biallelic MAX variants is described in the sources reviewed. Refer to clinical genetics.","sources":["maxClingen"]},"plans":{}},"MEFV":{"symbol":"MEFV","genotype":"Biallelic","summary":"Biallelic MEFV variants cause familial Mediterranean fever: recurrent attacks of fever and serositis and, if uncontrolled, renal AA amyloidosis. Lifelong colchicine prevents both. Penetrance depends on genotype and is not established for people found by screening; colchicine starts after a rheumatology diagnosis, not on genotype alone.","table":{"caption":"Inflammatory and amyloid risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"abdominal","name":"Abdominal attacks (peritonitis)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"joint","name":"Joint attacks (arthritis)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pleural","name":"Chest attacks (pleuritis)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"skin","name":"Erysipelas-like erythema","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"amyloid","name":"Renal AA amyloidosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"proteinuria-on","name":"Amyloid proteinuria within 11 years, colchicine taken regularly","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"proteinuria-off","name":"Amyloid proteinuria within 9 years, colchicine not taken regularly","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Amyloidosis leads to nephrotic syndrome and kidney failure. Untreated FMF raises infertility risk; diagnostic delay is linked to more amyloidosis.","sources":["mefvClingenAc","mefvShohat","mefvGeneReviews"]},{"title":"What treatment changes","text":"Colchicine stabilized or reversed proteinuria in most patients without nephrotic syndrome. Up to 5% do not respond and 2–5% cannot tolerate it; IL-1 inhibitors gave complete responses in 67.5–76.5%.","sources":["mefvZemer","mefvOzen2017","mefvClingenAc"]},{"title":"Genotype and ancestry","text":"Biallelic variants in about 85% of Mediterranean-origin patients meeting clinical criteria; in a different patient group, only one variant in about 20% of clinically diagnosed patients, so the figures do not sum. p.Met694Val dominates in North African Jews.","sources":["mefvClingenAc","mefvTouitou"]},{"title":"Association evidence","text":"ClinGen: Definitive, semidominant (February 2022). Colchicine scored for serositis (10CA) and amyloidosis (9CB); actionability assertion pending.","sources":["mefvClingen","mefvClingenAc"]}],"otherGenotype":{"title":"If one copy is affected","text":"Usually a carrier state: no colchicine or routine monitoring if asymptomatic. A minority, particularly with p.Met694Val, have milder symptoms or raised inflammatory markers; some variants cause a dominant pyrin-associated disease. Refer a symptomatic heterozygote to rheumatology for a colchicine trial (response in 84% of 25). If the partner also carries a variant, each pregnancy has a 25% chance of a biallelic child.","sources":["mefvClingenAd","mefvGeneReviews","mefvShare","mefvOzen2017","mefvClingen"]},"plans":{}},"MEN1":{"symbol":"MEN1","genotype":"Heterozygous","summary":"MEN1 variants cause multiple endocrine neoplasia type 1: nearly all carriers develop primary hyperparathyroidism, and many develop pancreatic or duodenal neuroendocrine tumors, pituitary adenomas, and adrenal or thoracic tumors. Metastatic neuroendocrine tumors are the main cause of early death.","table":{"caption":"Endocrine tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"phpt","name":"Primary hyperparathyroidism","women":{"risk":"95–100%","relative":"Not established","horizon":"By age 50","citations":{"risk":["men1Actionability"]}},"men":{"risk":"95–100%","relative":"Not established","horizon":"By age 50","citations":{"risk":["men1Actionability"]}}},{"id":"nfpnet","name":"Nonfunctioning pancreatic neuroendocrine tumor","women":{"risk":"80%","relative":"Not established","horizon":"By age 80","citations":{"risk":["men1Brandi"]}},"men":{"risk":"80%","relative":"Not established","horizon":"By age 80","citations":{"risk":["men1Brandi"]}}},{"id":"gastrinoma","name":"Gastrinoma (Zollinger-Ellison syndrome)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"insulinoma","name":"Insulinoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pituitary","name":"Pituitary adenoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"adrenal","name":"Adrenocortical tumor","women":{"risk":"40%","relative":"Not established","horizon":"By age 80","citations":{"risk":["men1Brandi"]}},"men":{"risk":"40%","relative":"Not established","horizon":"By age 80","citations":{"risk":["men1Brandi"]}}},{"id":"thymic","name":"Thymic neuroendocrine tumor (mostly men)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"bronchial","name":"Bronchopulmonary neuroendocrine tumor","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"gastric","name":"Gastric neuroendocrine tumor","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"breast","name":"Breast cancer","women":{"risk":"Not established","relative":"Not established"},"men":null}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Older series estimated a 50% probability of death by age 50 years without treatment. Pancreatic tumors, metastatic gastrinomas, and thymic tumors carry most mortality; hyperparathyroidism most morbidity.","sources":["men1Brandi","men1Actionability"]},{"title":"Treatment if disease develops","text":"Subtotal parathyroidectomy lowers persistent and recurrent disease compared with smaller operations, with more permanent hypoparathyroidism (6–30% beyond 12 months). Small stable nonfunctioning pancreatic tumors showed similar metastasis and death rates with surgery or surveillance (low-certainty data).","sources":["men1Brandi"]},{"title":"Association evidence","text":"ClinGen: definitive, autosomal dominant. Test for MEN1 in hyperparathyroidism before age 30 years or multigland disease, gastrinoma, multiple pancreatic tumors, a thymic neuroendocrine tumor, or two MEN1-type tumors.","sources":["men1Clingen","men1Brandi"]}],"otherGenotype":{"title":"If both copies are affected","text":"No separate syndrome from two inherited MEN1 variants is described in the guidance reviewed; loss of the normal copy inside a gland is expected and does not change the plan. Review two germline variants or low-level mosaicism with clinical genetics; surveillance still applies to any confirmed carrier.","sources":["men1Brandi","men1GeneReviews"]},"plans":{}},"MET":{"symbol":"MET","genotype":"Heterozygous activating variant","summary":"Activating MET missense variants cause hereditary papillary renal carcinoma: many small, slow-growing type 1 papillary kidney cancers in both kidneys, with high penetrance by old age in the families studied. Truncating MET variants are not expected to cause it.","table":{"caption":"Kidney cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"prcc","name":"Papillary renal cell carcinoma, type 1","women":{"risk":"90%","relative":"Not established","horizon":"By age 80 · family study","citations":{"risk":["metClinGen"]}},"men":{"risk":"90%","relative":"Not established","horizon":"By age 80 · family study","citations":{"risk":["metClinGen"]}}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Metastasis and death from kidney cancer occur. Repeated surgery threatens kidney function; bilateral nephrectomy and dialysis are a last resort.","sources":["metClinGen","metEarlyOnset"]},{"title":"Evidence for surveillance","text":"Family series only; no study compares outcomes with and without surveillance.","sources":["metClinGen","metErn"]},{"title":"Treatment if cancer develops","text":"Partial nephrectomy by the 3 cm rule; percutaneous ablation and MET-targeted drugs in selected cases.","sources":["metClinGen","metErn"]}],"otherGenotype":{"title":"If both copies are affected","text":"Biallelic loss-of-function MET variants are reported in a few families with nonsyndromic recessive hearing loss (DFNB97); ClinGen rates the link limited. Unrelated to kidney cancer: this plan does not apply, and a single loss-of-function variant carries no established risk beyond reproductive counseling.","sources":["metDeafness"]},"plans":{}},"MITF":{"symbol":"MITF","genotype":"Heterozygous p.Glu318Lys (E318K)","summary":"MITF E318K is a moderate-risk melanoma allele, roughly doubling to tripling melanoma odds, linked to multiple primary melanomas and high nevus counts. A reported kidney cancer risk has not been replicated. Loss-of-function MITF variants cause Waardenburg syndrome type 2, not cancer risk.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"melanoma","name":"Cutaneous melanoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"renal","name":"Renal cell carcinoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ppgl","name":"Pheochromocytoma and paraganglioma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"E318K is a moderate-penetrance allele. Its signal is strongest in people with multiple primary melanomas and high nevus counts; no consistent association with age at onset or pigmentation.","sources":["mitfMonti"]},{"title":"Association evidence","text":"ClinGen has curated MITF only for Waardenburg syndrome type 2 (Definitive, 2017). The melanoma association rests on replicated case-control studies without ClinGen curation.","sources":["mitfClingen","mitfMonti"]}],"otherGenotype":{"title":"If both copies are affected","text":"No management is established for two E318K copies; refer to cancer genetics. Biallelic loss-of-function variants cause COMMAD (coloboma, osteopetrosis, microphthalmia, macrocephaly, albinism, deafness), a severe congenital syndrome reported in very few infants. This plan applies to neither.","sources":["mitfCommad","mitfMonti"]},"plans":{}},"MLH1":{"symbol":"MLH1","genotype":"Heterozygous","summary":"MLH1 variants cause Lynch syndrome: colorectal cancer risk is 48–56% by age 75 years despite colonoscopy, and endometrial risk is 37%. Gastric, small bowel, ovarian, and urinary tract cancers are less common.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"48.3%","relative":"OR 111.67","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"],"relative":["mlh1Bbj"]}},"men":{"risk":"56.0%","relative":"OR 111.67","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"],"relative":["mlh1Bbj"]}}},{"id":"endometrial","name":"Endometrial cancer","women":{"risk":"37.2%","relative":"OR 116.98","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"],"relative":["mlh1Bbj"]}},"men":null},{"id":"ovarian","name":"Ovarian cancer","women":{"risk":"8.0%","relative":"OR 17.31 (nominal)","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"],"relative":["mlh1Bbj"]}},"men":null},{"id":"gastric","name":"Gastric cancer","women":{"risk":"4.3%","relative":"OR 40.86","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"],"relative":["mlh1Bbj"]}},"men":{"risk":"8.9%","relative":"OR 40.86","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"],"relative":["mlh1Bbj"]}}},{"id":"small-bowel","name":"Small bowel cancer","women":{"risk":"4.5%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"]}},"men":{"risk":"8.3%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"]}}},{"id":"pancreatic","name":"Pancreatic cancer","women":{"risk":"3.7%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"]}},"men":{"risk":"3.1%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"]}}},{"id":"biliary","name":"Biliary tract cancer","women":{"risk":"1.5%","relative":"OR 47.56 (nominal)","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"],"relative":["mlh1Bbj"]}},"men":{"risk":"4.0%","relative":"OR 47.56 (nominal)","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"],"relative":["mlh1Bbj"]}}},{"id":"kidney-ureter","name":"Kidney and ureter cancer","women":{"risk":"2.9%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"]}},"men":{"risk":"4.5%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"]}}},{"id":"bladder","name":"Bladder cancer","women":{"risk":"4.8%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"]}},"men":{"risk":"5.6%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"]}}},{"id":"prostate","name":"Prostate cancer","women":null,"men":{"risk":"15.6%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"]}}},{"id":"brain","name":"Brain tumor","women":{"risk":"1.4%","relative":"OR 216.60","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"],"relative":["mlh1Bbj"]}},"men":{"risk":"0.6%","relative":"OR 216.60","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"],"relative":["mlh1Bbj"]}}},{"id":"sebaceous","name":"Sebaceous skin tumors","women":{"risk":"Not estimated","relative":"Not quantified"},"men":{"risk":"Not estimated","relative":"Not quantified"}},{"id":"breast","name":"Breast cancer","women":{"risk":"12.4%","relative":"OR 1.10 (uncertain)","horizon":"By age 75","citations":{"risk":["mlh1Plsd2023"],"relative":["mlh1Bbj"]}},"men":{"risk":"Not estimated","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"10-year survival after colon cancer before age 65 years: 86%; after endometrial cancer: 93%. Across Lynch genes, poor after pancreatic (17%), brain (34%), and biliary tract (42%) cancers.","sources":["mlh1Plsd2023","cancerPrognosis"]},{"title":"Limits of colonoscopy","text":"Colonoscopy reduces preventable disease but does not eliminate risk. An observational comparison of 2,747 Lynch carriers across three countries found no significant difference in cancer incidence or stage between annual, biennial and 2–3-year schedules. This does not prove schedule equivalence; follow the selected guideline and colonoscopy quality standards.","sources":["mlh1Plsd2020","mlh1Mallorca"]},{"title":"Association evidence","text":"UK Biobank included 62 MLH1 carriers and reported colorectal and endometrial risks broadly consistent with PLSD, with wide confidence intervals. This supports continuing guideline care for incidentally identified carriers, but does not prove identical penetrance in every population. BioBank Japan odds ratios support associations with colorectal, endometrial and gastric cancer; they are not cumulative risk estimates.","sources":["mlh1Plsd2023","mlh1Ukb","mlh1Bbj"]},{"title":"Treatment if cancer develops","text":"Metachronous colorectal cancer risk approaches 53% by age 75 years after a first cancer and is substantially lower after extended than segmental resection; consider extended colectomy for a first colon cancer. Rectal cancer needs mismatch repair testing and multidisciplinary review. Metastatic or unresectable mismatch repair-deficient tumors are candidates for immune checkpoint inhibitors. Treatment eligibility requires the tumor biomarker, cancer type, stage, prior treatment and applicable drug indication; a germline result alone is insufficient.","sources":["lynch","mlh1Mallorca"]},{"title":"MLH1 epimutation","text":"Constitutional MLH1 promoter methylation can silence the gene without a sequence variant, usually without family history. Relatives are tested by methylation analysis.","sources":["lynch"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two pathogenic variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, clinical genetics must interpret their combined effect; this alone does not establish biallelic disease. Biallelic pathogenic MLH1 variants cause constitutional mismatch repair deficiency (CMMRD). Across CMMRD genes, about half develop cancer by age 10 years and 80–90% before 18 years; these are not MLH1-specific penetrance estimates. The spectrum includes high-grade brain tumors, hematologic cancers such as T-cell lymphoblastic lymphoma, and Lynch-spectrum cancers. Café-au-lait macules are common. ERN GENTURIS: examination every 6 months, brain MRI from diagnosis or at least age 2 years, every 6 months through age 20 years and at least annually thereafter, and colonoscopy at least yearly from 6 years, under a specialist pediatric and genetics team.","sources":["mlh1Cmmrd","lynch"]},"plans":{}},"MSH2":{"symbol":"MSH2","genotype":"Heterozygous","summary":"MSH2-related Lynch syndrome has a broad cancer spectrum. In the PLSD surveillance cohort, colorectal risk by age 75 years was 42.6% in women and 55.8% in men, and endometrial risk was 44.1%; urinary tract, ovarian, prostate and brain tumors are also important.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"42.6%","relative":"OR 16.17","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"],"relative":["msh2Bbj"]}},"men":{"risk":"55.8%","relative":"OR 16.17","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"],"relative":["msh2Bbj"]}}},{"id":"endometrial","name":"Endometrial cancer","women":{"risk":"44.1%","relative":"OR 53.60","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"],"relative":["msh2Bbj"]}},"men":null},{"id":"ovarian","name":"Ovarian cancer","women":{"risk":"13.4%","relative":"OR 7.11 (nominal)","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"],"relative":["msh2Bbj"]}},"men":null},{"id":"kidney-ureter","name":"Kidney and ureter cancer","women":{"risk":"19.5%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"]}},"men":{"risk":"15.8%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"]}}},{"id":"bladder","name":"Bladder cancer","women":{"risk":"9.4%","relative":"OR 26.56","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"],"relative":["msh2Bbj"]}},"men":{"risk":"13.1%","relative":"OR 26.56","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"],"relative":["msh2Bbj"]}}},{"id":"prostate","name":"Prostate cancer","women":null,"men":{"risk":"24.0%","relative":"OR 5.26 (nominal)","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"],"relative":["msh2Bbj"]}}},{"id":"gastric","name":"Gastric cancer","women":{"risk":"4.0%","relative":"OR 5.80","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"],"relative":["msh2Bbj"]}},"men":{"risk":"8.3%","relative":"OR 5.80","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"],"relative":["msh2Bbj"]}}},{"id":"small-bowel","name":"Small bowel cancer","women":{"risk":"3.7%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"]}},"men":{"risk":"7.0%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"]}}},{"id":"pancreatic","name":"Pancreatic cancer","women":{"risk":"3.5%","relative":"OR 4.00 (uncertain)","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"],"relative":["msh2Bbj"]}},"men":{"risk":"3.3%","relative":"OR 4.00 (uncertain)","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"],"relative":["msh2Bbj"]}}},{"id":"biliary","name":"Biliary tract cancer","women":{"risk":"2.4%","relative":"OR 9.46 (nominal)","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"],"relative":["msh2Bbj"]}},"men":{"risk":"4.6%","relative":"OR 9.46 (nominal)","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"],"relative":["msh2Bbj"]}}},{"id":"brain","name":"Brain tumor","women":{"risk":"2.2%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"]}},"men":{"risk":"6.6%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"]}}},{"id":"sebaceous","name":"Sebaceous skin tumors","women":{"risk":"Not estimated","relative":"Not quantified"},"men":{"risk":"Not estimated","relative":"Not quantified"}},{"id":"breast","name":"Breast cancer","women":{"risk":"15.5%","relative":"OR 1.15 (uncertain)","horizon":"By age 75","citations":{"risk":["msh2Plsd2023"],"relative":["msh2Bbj"]}},"men":{"risk":"Not estimated","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"10-year survival after colon cancer before age 65 years: 89%; after endometrial cancer: 91%. Across Lynch genes, lower after upper urinary tract (73%) and bladder (71%) cancers, poor after pancreatic (17%), brain (34%), and biliary tract (42%). More MSH2 deaths followed non-colorectal than colorectal cancers.","sources":["msh2Plsd2023","msh2FourLynch","cancerPrognosis"]},{"title":"Limits of colonoscopy","text":"Colorectal cancer still occurs under surveillance. Observational comparisons have not established superiority of annual over 2–3-year colonoscopy for all carriers; this does not prove equivalence. Maintain high-quality examinations at the individualized guideline interval.","sources":["msh2Plsd2023","msh2FourLynch","msh2Mallorca"]},{"title":"Association evidence","text":"In UK Biobank (47 unselected MSH2 carriers), colorectal and endometrial risks by age 70 years had lower point estimates than PLSD with overlapping CIs. BioBank Japan confirms colorectal, endometrial, gastric, ureteral, and bladder association at study-wide significance.","sources":["msh2Plsd2023","msh2Ukb","msh2Bbj"]},{"title":"Treatment if cancer develops","text":"Metachronous risk is substantially lower after extended than segmental resection; consider extended colectomy for a first colon cancer. Rectal cancer needs mismatch repair testing and multidisciplinary review. Metastatic or unresectable mismatch repair-deficient tumors are candidates for immune checkpoint inhibitors. Treatment eligibility requires the tumor biomarker, cancer type, stage, prior treatment and applicable drug indication; a germline result alone is insufficient.","sources":["lynch","msh2Mallorca"]},{"title":"MSH2 variant types","text":"MSH2 deletions and duplications account for approximately 20–40% of pathogenic variants. Confirm that the performing laboratory can detect relevant structural variants, including the exon 1–7 inversion when indicated. EPCAM 3′ deletions can silence MSH2 by methylation; see the EPCAM page.","sources":["lynch","msh2Invitae"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two pathogenic variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, clinical genetics must interpret their combined effect; this alone does not establish biallelic disease. Biallelic MSH2 variants cause constitutional mismatch repair deficiency (CMMRD); fewer than 20% of cases involve MLH1 or MSH2. Across CMMRD genotypes, about half develop cancer by age 10 years and 80–90% before 18 years, including high-grade brain tumors, hematologic cancers such as T-cell lymphoblastic lymphoma, and Lynch-spectrum cancers. ERN GENTURIS: examination every 6 months, brain MRI from diagnosis or at least age 2 years, every 6 months through age 20 years and at least annually thereafter, and colonoscopy at least yearly from 6 years, under a specialist pediatric and genetics team.","sources":["msh2Cmmrd","lynch"]},"plans":{}},"MSH3":{"symbol":"MSH3","genotype":"Biallelic","summary":"Biallelic MSH3 variants cause a rare recessive adenomatous polyposis with colorectal and duodenal adenomas. Too few people are described to quantify cancer risk; surveillance borrows from MUTYH.","table":{"caption":"Polyposis and cancer risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"polyposis","name":"Colorectal adenomatous polyposis","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"duodenal","name":"Duodenal adenomas","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"gastric","name":"Gastric cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"brain","name":"Brain tumor (astrocytoma)","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Association evidence","text":"ClinGen classified recessive MSH3-related polyposis as definitive and dominant Lynch syndrome as disputed in August 2024. A September 2026 study subsequently reported increased colorectal cancer risk in single-copy loss-of-function carriers. This does not establish the full Lynch syndrome management pathway for MSH3.","sources":["msh3Clingen","msh3Ehtg","msh3Soriano2026"]}],"otherGenotype":{"title":"If one copy is affected","text":"One affected copy does not establish recessive MSH3 polyposis. A September 2026 study linked single-copy loss-of-function variants to colorectal cancer or multiple-polyp case status in selected cohorts, after ClinGen’s 2024 disputed Lynch classification. This is not a prospective lifetime-risk estimate or a consensus surveillance schedule. Review screening with cancer genetics using the exact variant and personal and family history; discuss reproductive testing when relevant.","sources":["msh3Clingen","msh3Myriad","msh3Adam","msh3Ehtg","msh3Soriano2026"]},"plans":{}},"MSH6":{"symbol":"MSH6","genotype":"Heterozygous","summary":"MSH6-related Lynch syndrome particularly increases endometrial and colorectal cancer risk. In the PLSD surveillance cohort, endometrial risk was 45.7% by age 75 years; colorectal risk was 17.3% in women and 16.4% in men by that age.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"17.3%","relative":"OR 6.28","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"],"relative":["msh6Bbj"]}},"men":{"risk":"16.4%","relative":"OR 6.28","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"],"relative":["msh6Bbj"]}}},{"id":"endometrial","name":"Endometrial cancer","women":{"risk":"45.7%","relative":"OR 148.21","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"],"relative":["msh6Bbj"]}},"men":null},{"id":"ovarian","name":"Ovarian cancer","women":{"risk":"6.3%","relative":"OR 29.49","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"],"relative":["msh6Bbj"]}},"men":null},{"id":"kidney-ureter","name":"Kidney and ureter cancer","women":{"risk":"3.9%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"]}},"men":{"risk":"3.3%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"]}}},{"id":"bladder","name":"Bladder cancer","women":{"risk":"2.6%","relative":"OR 1.07 (uncertain)","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"],"relative":["msh6Bbj"]}},"men":{"risk":"9.0%","relative":"OR 1.07 (uncertain)","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"],"relative":["msh6Bbj"]}}},{"id":"gastric","name":"Gastric cancer","women":{"risk":"0.7%","relative":"OR 2.25 (nominal)","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"],"relative":["msh6Bbj"]}},"men":{"risk":"0.7%","relative":"OR 2.25 (nominal)","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"],"relative":["msh6Bbj"]}}},{"id":"small-bowel","name":"Small bowel cancer","women":{"risk":"0.6%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"]}},"men":{"risk":"2.8%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"]}}},{"id":"pancreatic","name":"Pancreatic cancer","women":{"risk":"2.2%","relative":"OR 1.30 (uncertain)","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"],"relative":["msh6Bbj"]}},"men":{"risk":"1.2%","relative":"OR 1.30 (uncertain)","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"],"relative":["msh6Bbj"]}}},{"id":"biliary","name":"Biliary tract cancer","women":{"risk":"0%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"]}},"men":{"risk":"0%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"]}}},{"id":"prostate","name":"Prostate cancer","women":null,"men":{"risk":"7.0%","relative":"OR 0.73 (uncertain)","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"],"relative":["msh6Bbj"]}}},{"id":"brain","name":"Brain tumor","women":{"risk":"1.2%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"]}},"men":{"risk":"0.8%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"]}}},{"id":"sebaceous","name":"Sebaceous skin tumors","women":{"risk":"Not estimated","relative":"Not quantified"},"men":{"risk":"Not estimated","relative":"Not quantified"}},{"id":"breast","name":"Breast cancer","women":{"risk":"15.1%","relative":"OR 7.86 (nominal)","horizon":"By age 75","citations":{"risk":["msh6Plsd2023"],"relative":["msh6Bbj"]}},"men":{"risk":"Not estimated","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"In PLSD, 10-year survival after colon cancer diagnosed before age 65 years was 85% (95% CI 67–100%); after endometrial cancer it was 89% (95% CI 75–100%). Women had a higher overall cancer incidence than men in this surveillance cohort; this does not make an individual man’s risk negligible.","sources":["msh6Plsd2023","msh6FourLynch","cancerPrognosis"]},{"title":"Why colonoscopy starts later","text":"Colorectal risk by age 50 years is 4.0% in women and 6.9% in men, so US guidance starts at 30–35 years and EHTG/ESCP at 35 years, against 20–25 years for MLH1 and MSH2. A family history of colorectal cancer before age 30 years moves the start earlier.","sources":["msh6Plsd2023","msh6GrSurveillance","msh6Mallorca"]},{"title":"Association evidence","text":"UK Biobank included 290 MSH6 carriers and reported colorectal and endometrial risk estimates broadly consistent with PLSD. The authors did not recommend relaxing care solely because a variant was found incidentally; selection, wide confidence intervals and variant composition still limit generalization. BioBank Japan supports colorectal, endometrial and ovarian associations at study-wide significance.","sources":["msh6Plsd2023","msh6Ukb","msh6Bbj"]},{"title":"Treatment if cancer develops","text":"Metachronous risk is lower than with MLH1 or MSH2; segmental resection is often reasonable for a first colon cancer. MSH6-deficient tumors may show only low-level microsatellite instability, so immunohistochemistry may be more sensitive than MSI testing. Metastatic or unresectable mismatch repair-deficient tumors are candidates for immune checkpoint inhibitors. Treatment eligibility requires the tumor biomarker, cancer type, stage, prior treatment and applicable drug indication; a germline result alone is insufficient.","sources":["lynch","msh6Mallorca"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two pathogenic variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, clinical genetics must interpret their combined effect; this alone does not establish biallelic disease. Biallelic MSH6 variants cause constitutional mismatch repair deficiency (CMMRD); MSH6 accounts for over 20% of cases. Across CMMRD genotypes, about half develop cancer by age 10 years and 80–90% before 18 years, including high-grade brain tumors, hematologic cancers such as T-cell lymphoblastic lymphoma, and Lynch-spectrum cancers. ERN GENTURIS: examination every 6 months, brain MRI from diagnosis or at least age 2 years, every 6 months through age 20 years and at least annually thereafter, and colonoscopy at least yearly from 6 years, under a specialist pediatric and genetics team.","sources":["msh6Cmmrd","lynch"]},"plans":{}},"MUTYH":{"symbol":"MUTYH","genotype":"Biallelic","summary":"Biallelic MUTYH variants cause MUTYH-associated polyposis, with high colorectal cancer risk even when few polyps are present. Regular colonoscopy and upper gastrointestinal surveillance are central; evidence for additional organ-specific screening is limited.","table":{"caption":"Cancer risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"71.7%","relative":"34.1×","horizon":"By age 70","citations":{"risk":["mutyhWin"],"relative":["mutyhWin"]}},"men":{"risk":"75.4%","relative":"26.0×","horizon":"By age 70","citations":{"risk":["mutyhWin"],"relative":["mutyhWin"]}}},{"id":"duodenal-adenoma","name":"Duodenal adenomas","women":{"risk":"Not established","relative":"Not quantified","horizon":"Cumulative risk not established","citations":{"risk":["mutyhEhtg"]}},"men":{"risk":"Not established","relative":"Not quantified","horizon":"Cumulative risk not established","citations":{"risk":["mutyhEhtg"]}}},{"id":"duodenal","name":"Duodenal or periampullary cancer","women":{"risk":"Not established","relative":"SIR 129","horizon":"Cumulative risk uncertain","citations":{"risk":["mutyhEhtg","mutyhVogt"],"relative":["mutyhVogt"]}},"men":{"risk":"Not established","relative":"SIR 129","horizon":"Cumulative risk uncertain","citations":{"risk":["mutyhEhtg","mutyhVogt"],"relative":["mutyhVogt"]}}},{"id":"extraintestinal","name":"Any cancer outside the digestive tract","women":{"risk":"Not established","relative":"SIR 1.9","horizon":"No sex-specific estimate","citations":{"risk":["mutyhVogt"],"relative":["mutyhVogt"]}},"men":{"risk":"Not established","relative":"SIR 1.9","horizon":"No sex-specific estimate","citations":{"risk":["mutyhVogt"],"relative":["mutyhVogt"]}}},{"id":"gastric","name":"Gastric cancer","women":{"risk":"Not established","relative":"SIR 4.2 (uncertain)","citations":{"relative":["mutyhVogt"]}},"men":{"risk":"Not established","relative":"SIR 4.2 (uncertain)","citations":{"relative":["mutyhVogt"]}}},{"id":"ovarian","name":"Ovarian cancer","women":{"risk":"Not established","relative":"SIR 5.7 (uncertain)","citations":{"relative":["mutyhVogt"]}},"men":null},{"id":"bladder","name":"Bladder cancer","women":{"risk":"Not established","relative":"SIR 7.2","citations":{"relative":["mutyhVogt"]}},"men":{"risk":"Not established","relative":"SIR 7.2","citations":{"relative":["mutyhVogt"]}}},{"id":"skin","name":"Skin cancer, including sebaceous tumors","women":{"risk":"Not established","relative":"SIR 2.8","citations":{"relative":["mutyhVogt"]}},"men":{"risk":"Not established","relative":"SIR 2.8","citations":{"relative":["mutyhVogt"]}}},{"id":"endometrial","name":"Endometrial cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":null},{"id":"breast","name":"Breast cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"thyroid","name":"Thyroid cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"About half of patients in historical clinical series presented with colorectal cancer. One matched study reported better survival than in non-MAP colorectal cancer, but individual prognosis still depends on stage and treatment. A surveillance cohort reported an 11% five-year metachronous colorectal cancer risk after an initial cancer.","sources":["mutyhEhtg","cancerPrognosis"]},{"title":"Association evidence","text":"ClinGen: Definitive for familial adenomatous polyposis 2 (recessive, June 20, 2022). Biallelic MUTYH explains about 7% of adenomatous polyposis and 0.7% of colorectal cancers.","sources":["mutyhClingen","mutyhEhtg"]},{"title":"Polyp types","text":"Serrated, hyperplastic, sessile serrated, and mixed polyps also occur; a serrated-predominant colon does not exclude MAP.","sources":["mutyhGeneReviews"]}],"otherGenotype":{"title":"If one copy is affected","text":"One pathogenic MUTYH variant does not establish MAP. Carrier frequency is approximately 1–2% in many European-ancestry populations. A family-based study modeled 2,332 carriers, most not directly genotyped, and estimated colorectal risk by age 70 years at 7.2% in men (95% CI 4.6–11.3%) and 5.6% in women (95% CI 3.6–8.8%). Estimates were 12.5% and 10% when a non-carrier first-degree relative had colorectal cancer at age 50 years. A European-ancestry panel study found no significant association with colorectal (OR 1.2, 95% CI 0.99–1.5), female breast (OR 1.1, 95% CI 0.96–1.3) or endometrial cancer (OR 0.98, 95% CI 0.70–1.3). ClinGen’s 2023 evaluations classify the dominant colorectal association as Disputed and breast association as Refuted. A 2026 analysis of European-ancestry UK colorectal cancer/polyposis cases reported an association with monoallelic variants (OR 1.38, 95% CI 1.18–1.61); this is not a lifetime risk ratio or evidence for a particular screening interval. Follow screening based on age, personal findings, family history and other established risk factors. Discuss reproductive risk and whether partner testing is appropriate; indications vary by guideline.","sources":["mutyhWin","mutyhThompson","mutyhClingen","mutyhForceManagement","mutyhGeneReviews","mutyhPatel","mutyhUkcgg2025","mutyhSherwood2026"]},"plans":{}},"MYBPC3":{"symbol":"MYBPC3","genotype":"Heterozygous · HCM-associated variant","summary":"MYBPC3 is a major cause of inherited hypertrophic cardiomyopathy (HCM). Some carriers never develop hypertrophy; a normal examination requires continued surveillance because expression can appear later in life.","table":{"caption":"Cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"hcm","name":"Hypertrophic cardiomyopathy","women":{"risk":"43%","relative":"Not quantified","horizon":"15 years after baseline without HCM · family carriers, sexes pooled","citations":{"risk":["mybpc3Lorenzini"]}},"men":{"risk":"43%","relative":"Not quantified","horizon":"15 years after baseline without HCM · family carriers, sexes pooled","citations":{"risk":["mybpc3Lorenzini"]}}},{"id":"cm-hf","name":"Cardiomyopathy or heart failure diagnosis","women":{"risk":"Not estimated","relative":"OR 3.03 (pooled)","citations":{"relative":["mybpc3Bourfiss"]}},"men":{"risk":"Not estimated","relative":"OR 3.03 (pooled)","citations":{"relative":["mybpc3Bourfiss"]}}},{"id":"mace","name":"Death or major cardiac event (sarcomere genes pooled)","women":{"risk":"21%","relative":"1.8×","citations":{"relative":["mybpc3DeMarvao"],"risk":["mybpc3DeMarvao"]},"horizon":"By age 70 · eight sarcomere genes and sexes pooled"},"men":{"risk":"21%","relative":"1.8×","citations":{"relative":["mybpc3DeMarvao"],"risk":["mybpc3DeMarvao"]},"horizon":"By age 70 · eight sarcomere genes and sexes pooled"}},{"id":"scd-pre","name":"Sudden cardiac death before hypertrophy","women":{"risk":"Not estimated","relative":"Not quantified"},"men":{"risk":"Not estimated","relative":"Not quantified"}}],"note":"The death/MACE row pools eight HCM sarcomere genes and both sexes. Other rows describe different cohorts. *× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"HCM can cause heart failure, atrial fibrillation, stroke, or sudden death. In the SHaRe specialty registry, patients with established HCM and a sarcomere variant were diagnosed at a median age of 37.5 years, versus 51.1 years without a variant. By age 50 years, 29% versus 14% had the composite of death, cardiac arrest, appropriate ICD therapy, transplant, atrial fibrillation, stroke, or advanced heart failure. These pooled sarcomere-gene results describe patients already diagnosed with HCM, not the risk for an otherwise healthy MYBPC3 carrier.","sources":["mybpc3Share","mybpc3ActionHcm"]},{"title":"Association evidence","text":"ClinGen classifies the autosomal dominant HCM association as Definitive, with Strong clinical actionability. MYBPC3 is among the eight strong-evidence HCM genes named in the 2024 AHA/ACC guideline.","sources":["mybpc3Validity","mybpc3ActionHcm","mybpc3Aha2024"]},{"title":"Genetic result and sudden-death risk","text":"In adults with HCM, the added value of genetic testing for sudden-death risk assessment is uncertain (class 2b); the genotype alone is not an ICD indication. In pediatric HCM, specialist risk models can incorporate genotype together with clinical and imaging findings. A child should not be assessed using an adult risk calculator.","sources":["mybpc3Aha2024"]},{"title":"If HCM develops","text":"Mild to moderate exercise is recommended (class 1); vigorous or competitive exercise is decided annually with an expert, without universal restriction. An ICD is never placed only to allow sport.","sources":["mybpc3Aha2024","mybpc3ActionHcm"]}],"otherGenotype":{"title":"If both copies are affected","text":"Refer a confirmed biallelic result to cardiovascular genetics and a cardiomyopathy specialist. Establish whether two variants are pathogenic and in trans; two variants in cis do not establish biallelic disease and still require variant-specific interpretation. A 2015 report described 21 selected patients with biallelic truncating MYBPC3 variants, all with severe early cardiomyopathy and/or death in the first months; its four new cases died before 13 weeks, and 13/21 (62%) had septal defects or patent ductus arteriosus. This case series is not a universal penetrance estimate for every biallelic genotype. Use an individualized plan rather than routine phenotype-negative surveillance; standard HCM management still applies when relevant. If both parents are heterozygous for a pathogenic MYBPC3 variant, each pregnancy has a 25% chance of inheriting both variants. Offer reproductive genetic counseling.","sources":["mybpc3Wessels","mybpc3Aha2024"]},"plans":{}},"MYH11":{"symbol":"MYH11","genotype":"Heterozygous","summary":"MYH11 causes nonsyndromic heritable thoracic aortic aneurysm and dissection, sometimes with patent ductus arteriosus; type A dissection can occur below 5.0 cm. It is rare (about 1% of familial cases), penetrance is incomplete, and risk data are very limited.","table":{"caption":"Aortic and congenital heart risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"dissection","name":"Aortic dissection","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"repair","name":"Prophylactic aortic aneurysm repair","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pda","name":"Patent ductus arteriosus","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Dissection is the main threat and can occur before usual surgical size. Course, penetrance, and age at onset are poorly characterized; no registry or cohort exists.","sources":["myh11AccHtad","myh11Atash"]},{"title":"Association evidence","text":"Definitive for familial thoracic aortic aneurysm and dissection; limited for congenital heart disease. Incomplete segregation in two families suggests other genetic factors contribute.","sources":["myh11ClinGen","myh11Renard","myh11Harakalova","myh11Actionability"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy aortic plan. Biallelic variants (loss-of-function, or loss-of-function with a hypomorphic allele) cause a recessive visceral myopathy (megacystis microcolon intestinal hypoperistalsis spectrum), usually congenital but reported in adults with bladder dysfunction and intestinal obstruction. The aortic plan does not apply; refer to clinical genetics, and assess the aorta if either variant fits the dominant pattern, including in heterozygous relatives.","sources":["myh11Billon"]},"plans":{}},"MYH7":{"symbol":"MYH7","genotype":"Heterozygous","summary":"MYH7 is an established cause of hypertrophic and dilated cardiomyopathy; some variants also cause skeletal muscle disease. The specific variant, family history, and cardiac findings determine which surveillance pathway applies.","table":{"caption":"Cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"hcm","name":"Hypertrophic cardiomyopathy","women":{"risk":"66%","relative":"Not quantified","horizon":"15 years after baseline without HCM · HCM families, sexes pooled","citations":{"risk":["myh7Lorenzini"],"relative":["myh7Validity","myh7Atlas"]}},"men":{"risk":"66%","relative":"Not quantified","horizon":"15 years after baseline without HCM · HCM families, sexes pooled","citations":{"risk":["myh7Lorenzini"],"relative":["myh7Validity","myh7Atlas"]}}},{"id":"cm-hf","name":"Cardiomyopathy or heart failure diagnosis","women":{"risk":"4.3%","relative":"OR 3.03 (pooled)","horizon":"Recorded diagnoses · UK Biobank · sexes pooled","citations":{"risk":["myh7Bourfiss"],"relative":["myh7Bourfiss"]}},"men":{"risk":"4.3%","relative":"OR 3.03 (pooled)","horizon":"Recorded diagnoses · UK Biobank · sexes pooled","citations":{"risk":["myh7Bourfiss"],"relative":["myh7Bourfiss"]}}},{"id":"mace","name":"Death or major cardiac event (sarcomere genes pooled)","women":{"risk":"21%","relative":"1.8×","citations":{"risk":["myh7DeMarvao"],"relative":["myh7DeMarvao"]},"horizon":"By age 70 · eight sarcomere genes and sexes pooled"},"men":{"risk":"21%","relative":"1.8×","citations":{"risk":["myh7DeMarvao"],"relative":["myh7DeMarvao"]},"horizon":"By age 70 · eight sarcomere genes and sexes pooled"}},{"id":"scd-pre","name":"Sudden cardiac death before hypertrophy","women":{"risk":"Not estimated","relative":"Not quantified","citations":{"risk":["myh7Lorenzini"]}},"men":{"risk":"Not estimated","relative":"Not quantified","citations":{"risk":["myh7Lorenzini"]}}},{"id":"dcm","name":"Dilated cardiomyopathy","women":{"risk":"88%","relative":"Not quantified","horizon":"By age 60 years · selected DCM families, including probands · sexes pooled","citations":{"risk":["myh7DeFrutos2022"],"relative":["myh7Validity","myh7AtlasDcm"]}},"men":{"risk":"88%","relative":"Not quantified","horizon":"By age 60 years · selected DCM families, including probands · sexes pooled","citations":{"risk":["myh7DeFrutos2022"],"relative":["myh7Validity","myh7AtlasDcm"]}}}],"note":"The death/MACE row pools eight HCM sarcomere genes and both sexes. Other rows describe different cohorts. *× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"HCM can cause heart failure, atrial fibrillation, stroke, or sudden death. In the SHaRe specialty registry, patients with established HCM and a sarcomere variant were diagnosed at a median age of 37.5 years, versus 51.1 years without a variant. By age 50 years, 29% versus 14% had the composite of death, cardiac arrest, appropriate ICD therapy, transplant, atrial fibrillation, stroke, or advanced heart failure. Within affected patients, MYH7 was associated with higher hazards than MYBPC3 for the overall composite, atrial fibrillation, and advanced heart failure. These are prognosis findings after HCM is diagnosed, not penetrance in healthy carriers.","sources":["myh7Share","myh7ActionHcm"]},{"title":"Association evidence","text":"ClinGen classifies the autosomal dominant associations with HCM, DCM, and MYH7-related skeletal myopathy as Definitive. Adult clinical actionability is Strong for HCM and DCM. These classifications support clinical evaluation and surveillance; they are not a numerical estimate of an individual carrier’s risk.","sources":["myh7Validity","myh7ActionHcm","myh7ActionDcm"]},{"title":"Genetic result and sudden-death risk","text":"In adults with HCM, the added value of genetic testing for sudden-death risk assessment is uncertain (class 2b); the genotype alone is not an ICD indication. Pediatric HCM specialists may use risk models that incorporate genotype with clinical and imaging findings. A child should not be assessed using an adult risk calculator.","sources":["myh7Aha2024"]},{"title":"If HCM develops","text":"Mild to moderate exercise is recommended (class 1); vigorous or competitive exercise is decided annually with an expert, without universal restriction. An ICD is never placed only to allow sport.","sources":["myh7Aha2024","myh7ActionHcm"]}],"otherGenotype":{"title":"If both copies are affected","text":"Refer a confirmed biallelic result to cardiovascular genetics and a cardiomyopathy specialist, adding neuromuscular assessment when indicated. Establish whether both variants are pathogenic and in trans; variants in cis do not establish biallelic disease but still require variant-specific interpretation. Recessive myosin storage myopathy with DCM has been reported, and multiple sarcomere variants can modify HCM severity; there is no single risk multiplier or uniform schedule for all such genotypes. Use an individualized plan and offer reproductive genetic counseling.","sources":["myh7Validity","myh7Yuceyar2015","myh7Aha2024","myh7Share"]},"plans":{}},"MYL2":{"symbol":"MYL2","genotype":"Heterozygous","summary":"MYL2 can cause hypertrophic cardiomyopathy (HCM); rare variants are found in about 1% of HCM patients, and penetrance varies widely. Some variants cause severe infantile disease only when both copies are affected, so confirm the condition the variant is classified for.","table":{"caption":"Cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"hcm","name":"Hypertrophic cardiomyopathy","women":{"risk":"65%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["myl2Topriceanu"]}},"men":{"risk":"65%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["myl2Topriceanu"]}}},{"id":"dcm","name":"Dilated cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"scd","name":"Sudden cardiac death or cardiac arrest","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Most phenotype-negative carriers appear to have a benign course. Once HCM develops, heart failure and atrial fibrillation dominate; younger age at diagnosis predicts worse outcomes.","sources":["myl2Actionability","myl2Share"]},{"title":"Association evidence","text":"Definitive for HCM, limited for DCM, no known relationship to ARVC (ClinGen). A strong-evidence first-tier HCM gene.","sources":["myl2ClinGen","myl2AhaFamily","myl2Hrs","myl2Actionability"]},{"title":"Filament group","text":"Thick-filament gene. Against thin-filament disease (150 and 80 adults, 10 with MYL2): more hypertrophy (wall thickness 24 mm against 18 mm) and outflow obstruction (34% against 19%), slower progression to LV dysfunction.","sources":["myl2Coppini"]},{"title":"Treatment if HCM develops","text":"Beta-blockers first for obstructive symptoms, then nondihydropyridine calcium channel blockers; then a cardiac myosin inhibitor, disopyramide, or septal reduction at an experienced center. Anticoagulate clinical atrial fibrillation regardless of CHA2DS2-VASc score. Mavacamten is teratogenic.","sources":["myl2AccPoints","myl2AhaCare"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan. A recessive disease distinct from adult HCM. Biallelic last-exon variants caused infantile myopathy with cardiomyopathy and death in infancy; a homozygous frameshift caused infantile HCM with death before age 1 year, and a homozygous missense variant fatal heart failure at 12 months. Heterozygous parents had no cardiomyopathy. An affected infant needs pediatric cardiology and neuromuscular care; test both parental lines.","sources":["myl2Weterman","myl2Manivannan","myl2Uddin"]},"plans":{}},"MYL3":{"symbol":"MYL3","genotype":"Heterozygous","summary":"MYL3 can cause hypertrophic cardiomyopathy (HCM), with lower penetrance in relatives than the commonest HCM genes; rare variants are found in under 1% of HCM patients. HCM variants are missense, while biallelic loss-of-function variants cause recessive cardiomyopathy, so confirm the condition the variant is classified for.","table":{"caption":"Cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"hcm","name":"Hypertrophic cardiomyopathy","women":{"risk":"32%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["myl3Topriceanu"]}},"men":{"risk":"32%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["myl3Topriceanu"]}}},{"id":"arvc","name":"Arrhythmogenic right ventricular cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"scd","name":"Sudden cardiac death or cardiac arrest","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Most phenotype-negative carriers appear to have a benign course. Once HCM develops, heart failure and atrial fibrillation dominate.","sources":["myl3Actionability","myl3Share"]},{"title":"Association evidence","text":"Definitive for HCM, limited for ARVC, disputed for DCM (ClinGen). A strong-evidence first-tier HCM gene.","sources":["myl3ClinGen","myl3AhaFamily","myl3Hrs","myl3Actionability"]},{"title":"Treatment if HCM develops","text":"Beta-blockers first for obstructive symptoms, then nondihydropyridine calcium channel blockers; then a cardiac myosin inhibitor, disopyramide, or septal reduction at an experienced center. Anticoagulate clinical atrial fibrillation regardless of CHA2DS2-VASc score. Mavacamten is teratogenic.","sources":["myl3AccPoints","myl3AhaCare"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan. Homozygous loss-of-function variants (a stop codon, an essential splice variant, and one missense change) caused recessive HCM or DCM from infancy to early adulthood, with sudden cardiac deaths, in three consanguineous families. No established pathway; the plan above does not apply. Refer to clinical genetics and a cardiomyopathy center, and test both parental lines. More than one sarcomere variant may cause more severe disease.","sources":["myl3Osborn","myl3AhaFamily"]},"plans":{}},"MYLK":{"symbol":"MYLK","genotype":"Heterozygous","summary":"MYLK causes heritable thoracic aortic disease, usually type A dissection after age 40 years with little or no prior enlargement, so diameter surveillance can miss the risk. Penetrance is incomplete; missense variants act earlier than null variants.","table":{"caption":"Aortic risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"aortic-event","name":"Aortic dissection or aneurysm repair","women":{"risk":"89%","relative":"Not established","horizon":"By age 84 · family study","citations":{"risk":["mylkWallace"]}},"men":{"risk":"89%","relative":"Not established","horizon":"By age 84 · family study","citations":{"risk":["mylkWallace"]}}},{"id":"type-a","name":"Type A aortic dissection","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"type-b","name":"Type B aortic dissection","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"elective-repair","name":"Elective aneurysm repair as first event","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pregnancy","name":"Pregnancy-associated aortic dissection","women":{"risk":"Not established","relative":"Not established"},"men":null}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"87% of first events are dissections, usually type A in the fifth decade; 3 of 5 type A dissections in one family were fatal. Surveillance alone may not prevent dissection.","sources":["mylkWallace"]},{"title":"Association evidence","text":"Strong for familial thoracic aortic aneurysm and dissection (ClinGen), resting on a handful of families. Not in ClinGen Actionability.","sources":["mylkClinGen","mylkRenard","mylkActionability"]},{"title":"Variant type","text":"Nonsense, frameshift, deletion, or loss-of-function missense variants in the kinase and calmodulin-binding domains. One missense variant segregated over five generations (LOD 4.0) while barely reducing kinase activity.","sources":["mylkRenard","mylkWallace"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy aortic plan. Homozygous loss-of-function variants cause recessive megacystis microcolon intestinal hypoperistalsis syndrome, a congenital bladder and gut smooth muscle failure presenting in infancy. The aortic plan does not apply; refer to clinical genetics.","sources":["mylkHalim"]},"plans":{}},"NF1":{"symbol":"NF1","genotype":"Heterozygous","summary":"NF1 causes neurofibromatosis 1, with near-complete penetrance but very variable severity. Adult threats are MPNST in plexiform neurofibromas, breast cancer in women from age 30 years, and less often pheochromocytoma, GIST, and glioma.","table":{"caption":"Tumor and vascular risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"any-cancer","name":"Any cancer","women":{"risk":"59.6%","relative":"1.9×","horizon":"By age 85","citations":{"risk":["nf1Uusitalo2016"],"relative":["nf1Uusitalo2016","nf1Ern"]}},"men":{"risk":"59.6%","relative":"1.9×","horizon":"By age 85","citations":{"risk":["nf1Uusitalo2016"],"relative":["nf1Uusitalo2016","nf1Ern"]}}},{"id":"mpnst","name":"Malignant peripheral nerve sheath tumor (MPNST)","women":{"risk":"8–16%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf1Ern"]}},"men":{"risk":"8–16%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf1Ern"]}}},{"id":"breast","name":"Breast cancer","women":{"risk":"18.0%","relative":"1.9×","horizon":"By age 85","citations":{"risk":["nf1UusitaloBreast"],"relative":["nf1UusitaloBreast"]}},"men":{"risk":"Not established","relative":"Not established"}},{"id":"plexiform","name":"Plexiform neurofibromas","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cutaneous","name":"Cutaneous neurofibromas","women":{"risk":">95%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf1Ern"]}},"men":{"risk":">95%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf1Ern"]}}},{"id":"pheo","name":"Pheochromocytoma or paraganglioma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"gist","name":"Gastrointestinal stromal tumor (GIST)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"opg","name":"Optic pathway glioma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"glioma","name":"Other brain glioma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ras","name":"Renal artery stenosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Life expectancy is 8–15 years shorter, mainly from malignancy and cardiovascular causes. Learning problems affect 30–60%, epilepsy 6–7%; chronic pain, fatigue, and visible tumors weigh on quality of life.","sources":["nf1Ern","nf1ClinGen","nf1Acmg"]},{"title":"Diagnosis","text":"Two characteristic features, or one plus a pathogenic NF1 variant. An adult panel result without café au lait macules, freckling, or neurofibromas needs careful examination and genetics review; penetrance is near complete after childhood.","sources":["nf1GeneReviews","nf1ClinGen"]},{"title":"Variant type","text":"Missense at codons 844–848 (162 people): more plexiform and symptomatic spinal neurofibromas, optic gliomas, skeletal problems, and malignancy. p.Met992del (41 people): café au lait macules and freckling but almost no neurofibromas or gliomas; learning difficulty 46%.","sources":["nf1Koczkowska","nf1Forde","nf1Ern"]},{"title":"Treatment if cancer develops","text":"MPNST: urgent complete resection when possible; chemotherapy may help some. Decisions, including radiotherapy, belong to an experienced multidisciplinary team.","sources":["nf1Ern","nf1GeneReviews","nf1UusitaloBreast"]}],"otherGenotype":{"title":"If both copies are affected","text":"No separate condition is established. A report of two NF1 variants needs clinical genetics review before management changes.","sources":["nf1GeneReviews"]},"plans":{}},"NF2":{"symbol":"NF2","genotype":"Heterozygous","summary":"NF2 causes NF2-related schwannomatosis (formerly neurofibromatosis type 2): bilateral vestibular schwannomas with progressive hearing loss in nearly all carriers, usually from 18–24 years, plus meningiomas and spinal tumors. The tumors are benign but cause deafness, disability, and early death without specialist care.","table":{"caption":"Tumor and other risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"vs","name":"Bilateral vestibular schwannomas","women":{"risk":"87–95%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}},"men":{"risk":"87–95%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}}},{"id":"cranial","name":"Other cranial nerve schwannomas","women":{"risk":"24–51%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}},"men":{"risk":"24–51%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}}},{"id":"meningioma","name":"Intracranial meningiomas","women":{"risk":"45–58%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}},"men":{"risk":"45–58%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}}},{"id":"spinal","name":"Spinal tumors, any","women":{"risk":"63–90%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}},"men":{"risk":"63–90%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}}},{"id":"intramedullary","name":"Intramedullary spinal tumors, mainly ependymoma","women":{"risk":"18–53%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}},"men":{"risk":"18–53%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}}},{"id":"skin","name":"Skin tumors","women":{"risk":"59–68%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}},"men":{"risk":"59–68%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}}},{"id":"cataract","name":"Cataract","women":{"risk":"60–81%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}},"men":{"risk":"60–81%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}}},{"id":"retinal","name":"Retinal hamartoma","women":{"risk":"6–22%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}},"men":{"risk":"6–22%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}}},{"id":"neuropathy","name":"Peripheral neuropathy","women":{"risk":"≤66%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}},"men":{"risk":"≤66%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["nf2Eviq"]}}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Historically, average age at death was 36 years; survival after diagnosis 85% at 5 years, 67% at 10 years, 38% at 20 years. With specialty care, survival to age 60 years rose from 10% (diagnosed before 1980) to about 82% (2000–2009). Age at diagnosis is the strongest predictor of mortality.","sources":["nf2ClinGen"]},{"title":"Diagnosis and naming","text":"Renamed NF2-related schwannomatosis in 2022 to avoid confusion with NF1; criteria include molecular testing and mosaicism. Diagnosis: bilateral vestibular schwannomas, an identical NF2 variant in two anatomically distinct tumors, or consensus criteria.","sources":["nf2Plotkin","nf2GeneReviews"]},{"title":"Association evidence","text":"Strongly actionable; penetrance close to 100% for a germline variant. Vestibular schwannomas grow faster in younger patients; in one series, 8 of 11 vestibular schwannomas in 7 patients diagnosed after age 70 years showed no significant growth over a mean 8 years.","sources":["nf2ClinGen"]},{"title":"Treatment if tumors develop","text":"Vestibular schwannoma treatment is mainly surgical, with radiosurgery in selected cases; bevacizumab also helps some ependymomas. Treatment balances hearing, tumor size and growth, and preference.","sources":["nf2GeneReviews","nf2ClinGen"]}],"otherGenotype":{"title":"If both copies are affected","text":"No separate condition is established. Two NF2 variants, or a variant only at low allele fraction, need clinical genetics review before management changes.","sources":["nf2GeneReviews","nf2Plotkin"]},"plans":{}},"NTHL1":{"symbol":"NTHL1","genotype":"Biallelic","summary":"NTHL1 tumor syndrome causes colorectal polyposis and increases cancer risk across several organs, especially colorectal and breast cancer. Published risk estimates are based on small cohorts.","table":{"caption":"Cancer risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"adenomas","name":"Colorectal adenomas or polyposis","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"breast","name":"Breast cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified","citations":{"risk":["nthl1GeneReviews"]}}},{"id":"duodenal","name":"Duodenal adenomas","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"extracolonic","name":"Any cancer outside the colon","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"endometrial","name":"Endometrial cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":null},{"id":"bladder","name":"Bladder cancer (urothelial)","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"brain","name":"Meningioma and other brain tumors","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"skin","name":"Basal cell carcinoma","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"head-neck","name":"Head and neck squamous cell carcinoma","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"hematologic","name":"Hematologic cancers","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"Multiple primary cancers occurred in 16 of 29 people in the 2019 family series. Early colorectal and breast cancers are reported. These selected-cohort observations describe susceptibility, not an individual cancer’s stage or prognosis.","sources":["nthl1Grolleman","nthl1Beck","cancerPrognosis"]},{"title":"Association evidence","text":"ClinGen classifies recessive NTHL1-deficiency tumor predisposition as definitive. The spectrum is supported by clinical reports and a characteristic tumor signature, but reliable organ-specific penetrance remains limited.","sources":["nthl1Clingen","nthl1Grolleman","nthl1Beck","nthl1Weren","nthl1GeneReviews"]},{"title":"Treatment if disease develops","text":"Large or dysplastic duodenal polyps are removed endoscopically.","sources":["nthl1GeneReviews"]}],"otherGenotype":{"title":"If one copy is affected","text":"One affected copy does not establish NTHL1 tumor syndrome. Studies have not shown increased colorectal cancer risk sufficient to change screening solely because of a single variant. A small increase in breast cancer risk has been reported, but no NTHL1-specific screening schedule is established for heterozygotes. Use population screening adjusted for personal and family history.","sources":["nthl1Elsayed","nthl1Beck","nthl1Myriad","nthl1GeneReviews"]},"plans":{}},"OTC":{"symbol":"OTC","genotype":"X-linked · Hemizygous men, heterozygous women","summary":"OTC deficiency weakens the urea cycle, so ammonia can rise dangerously with illness, fasting, a large protein load, surgery, childbirth, or drugs such as valproate and corticosteroids. A well adult can still have a fatal hyperammonemic crisis at any age; every patient needs a metabolic specialist and an emergency plan.","table":{"caption":"Hyperammonemia risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"encephalopathy","name":"Hyperammonemic encephalopathy, family cohorts","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"late-ha","name":"Hyperammonemia later in life after an asymptomatic start","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"neuropsych","name":"Mood, sleep, or other neuropsychiatric conditions without crises","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"adult-death","name":"Death after an adult-onset presentation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pregnancy-known","name":"Severe hyperammonemia in pregnancy or postpartum, diagnosis known beforehand","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"pregnancy-unknown","name":"Maternal death, first diagnosed in pregnancy or postpartum","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"neonatal","name":"Neonatal hyperammonemic crisis in an affected child, by the child’s sex","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Crises can cause coma, permanent brain injury, or death at any age, even after years without symptoms. With treatment, symptomatic girls had 90% survival over a mean of 7 years, against 18% historically.","sources":["otcClinGen"]},{"title":"Association evidence","text":"Definitive (ClinGen); adult disease strongly actionable in men and women, with a lower likelihood score for women.","sources":["otcClinGenValidity","otcClinGen"]},{"title":"Why women differ","text":"Liver cells use either the normal or the variant X chromosome. Many mild women self-restrict protein without a diagnosis.","sources":["otcClinGen","otcGeneReviews"]},{"title":"Treatment if a crisis occurs","text":"Tertiary care: stop protein, high-calorie intravenous glucose, intravenous nitrogen scavengers and arginine, and hemodialysis or hemofiltration if ammonia does not fall. Long term: protein prescription with essential amino acids, oral scavengers, and arginine or citrulline.","sources":["otcClinGen","otcGeneReviews"]}],"otherGenotype":{"title":"If a woman has two affected copies","text":"Rare: two variants, one variant with a single X chromosome, or very skewed X inactivation can behave like disease in a man. Follow the men’s plan under metabolic direction.","sources":["otcClinGen","otcGeneReviews"]},"plans":{}},"PALB2":{"symbol":"PALB2","genotype":"Heterozygous · loss-of-function variant","summary":"PALB2 loss-of-function variants increase breast cancer risk in women and men, and ovarian and pancreatic cancer risk. Breast surveillance and preventive decisions should reflect age, family history and individual risk.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"breast","name":"Breast cancer","women":{"risk":"53%","relative":"Incidence RR 7.18","horizon":"By age 80 · family study","citations":{"risk":["palb2Yang"],"relative":["palb2Yang"]}},"men":{"risk":"1%","relative":"Incidence RR 7.34","horizon":"By age 80","citations":{"risk":["palb2Yang"],"relative":["palb2Yang"]}}},{"id":"ovarian","name":"Ovarian cancer","women":{"risk":"5%","relative":"Incidence RR 2.91","horizon":"By age 80","citations":{"risk":["palb2Yang"],"relative":["palb2Yang"]}},"men":null},{"id":"pancreatic","name":"Pancreatic cancer","women":{"risk":"2.2%","relative":"Incidence RR 2.37","horizon":"By age 80","citations":{"risk":["palb2Yang"],"relative":["palb2Yang"]}},"men":{"risk":"2.8%","relative":"Incidence RR 2.37","horizon":"By age 80","citations":{"risk":["palb2Yang"],"relative":["palb2Yang"]}}},{"id":"prostate","name":"Prostate cancer","women":null,"men":{"risk":"Not established","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"PALB2 is particularly associated with ER-negative breast cancer, although many carrier cancers are hormone-receptor positive. Prognosis depends on the cancer and its stage. Routine ovarian screening has no demonstrated benefit; discuss preventive surgery individually.","sources":["palb2Carriers","cancerPrognosis","palb2Force"]},{"title":"Association evidence","text":"Breast, ovarian, and pancreatic associations are established; ACMG calls ovarian risk likely increased. The pancreatic OR did not survive multiple-testing correction, but the family-based RR supports it. No colorectal increase (RR 0.97).","sources":["palb2Pancreas","palb2Yang","palb2Acmg"]},{"title":"Treatment if cancer develops","text":"Oncology should select treatment by cancer type, stage, tumor biomarkers and current approvals. PALB2 may support consideration of platinum regimens, PARP inhibitors or clinical trials. For eligible HRR-mutated metastatic castration-resistant prostate cancer, labeling includes olaparib after progression on enzalutamide or abiraterone, and talazoparib in combination with enzalutamide. For olaparib, the label requires an FDA-approved companion diagnostic; the listed PALB2 indication uses tumor testing. Patients require concurrent GnRH therapy or prior bilateral orchiectomy. These are not blanket approvals for every PALB2-associated cancer. Discuss contralateral surgery using individualized risk.","sources":["palb2Acmg","palb2ForceTreatment","fdaOlaparib","fdaTalazoparib"]}],"otherGenotype":{"title":"If both copies are affected","text":"Two disease-causing PALB2 variants in trans can cause Fanconi anemia subtype N, with substantial early-childhood cancer risk. Confirm variant interpretation and phase with clinical genetics and refer to a Fanconi anemia specialist team. The single-copy risk estimates do not transfer to this condition. Do not use the single-copy care plan alone: the specialist team should integrate Fanconi-specific care with appropriate hereditary cancer surveillance.","sources":["palb2Fancn","fa","palb2Eviq"]},"plans":{}},"PCSK9":{"symbol":"PCSK9","genotype":"Heterozygous gain-of-function variant","summary":"An FH-causing gain-of-function PCSK9 variant increases LDL cholesterol and premature coronary risk. Loss-of-function variants usually lower LDL cholesterol and coronary risk; that finding alone is not an indication for lipid-lowering treatment.","table":{"caption":"Coronary artery disease risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"cad-gof","name":"PCSK9 gain-of-function variant","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"cad-pooled","name":"Any FH variant (pooled genes)","women":{"risk":"Not established","relative":"OR 3.8","citations":{"relative":["pcsk9Khera"]}},"men":{"risk":"Not established","relative":"OR 3.8","citations":{"relative":["pcsk9Khera"]}}},{"id":"cad-pooled-ldl190","name":"FH variant with LDL-C ≥190 mg/dL (pooled genes)","women":{"risk":"Not established","relative":"OR 22.3","citations":{"relative":["pcsk9Khera"]}},"men":{"risk":"Not established","relative":"OR 22.3","citations":{"relative":["pcsk9Khera"]}}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Mechanism","text":"Increased PCSK9 activity promotes LDL-receptor degradation, reducing clearance of LDL cholesterol. Gain-of-function variants can produce different degrees of LDL-C elevation, including variation within a family. Loss-of-function variants generally have the opposite effect.","sources":["pcsk9Hopkins","pcsk9Zhao","fhGr2025"]},{"title":"Association evidence","text":"ClinGen classifies PCSK9-related autosomal dominant hypercholesterolemia as a definitive gene-disease relationship (2018) and heterozygous FH as definitively actionable in adults (2020). These gene-level conclusions do not classify an individual variant; confirm that the reported variant causes gain of function.","sources":["pcsk9Clingen","fhGr2025"]},{"title":"Severity and treatment response","text":"Clinical severity and treatment response vary. The initial 13-person trial showed a 62.5% LDL-C reduction from baseline at 2 weeks in the active-treatment arm; the placebo-adjusted reduction was 53.7%. Longer follow-up in an extension cohort supported sustained LDL lowering for up to 3 years. These small studies support treatment efficacy, not a guaranteed response or proven genotype-specific cardiovascular outcome benefit.","sources":["pcsk9HopkinsOle","pcsk9HopkinsPk","pcsk9HopkinsReprint"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm the functional effect and phase of both variants. Two FH-causing variants affecting separate PCSK9 copies, or an additional FH-causing LDLR or APOB variant, can cause severe disease requiring an FH specialist centre. LDL-C above about 400 mg/dL or childhood xanthomas suggests severity but is not required. Treatment is phenotype- and response-guided and may include combination drugs, apheresis and receptor-independent therapy. Two loss-of-function variants require a different interpretation; reported healthy individuals do not justify an automatic lifelong no-surveillance rule. Mixed gain- and loss-of-function results need specialist assessment.","sources":["pcsk9Zhao","fhGr2025","fhHofh2023"]},"plans":{}},"PDGFRA":{"symbol":"PDGFRA","genotype":"Heterozygous activating variant","summary":"An activating PDGFRA variant causes PDGFRA-mutant (GIST-plus) syndrome: gastric GISTs, inflammatory fibroid polyps of the stomach and small bowel, and other benign gut tumors, with incomplete penetrance. Only a handful of families are published.","table":{"caption":"Tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"gist","name":"Gastrointestinal stromal tumor, usually gastric","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ifp","name":"Inflammatory fibroid polyps","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"fibrous","name":"Gastrointestinal fibrous tumors and lipomas","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"chd","name":"Congenital heart disease","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Polyps are benign but can cause repeated intussusception and surgery. Gastric GISTs are the main malignant concern; no carrier-specific outcome data exist.","sources":["pdgfraHodan","pdgfraRicci"]},{"title":"Association evidence","text":"ClinGen: PDGFRA and GIST Definitive (autosomal dominant, January 2020). Intestinal neurofibromatosis and neurofibromatosis 3b are older names for the same syndrome.","sources":["pdgfraClingen","pdgfraRicci"]},{"title":"Treatment if GIST develops","text":"Choose the tyrosine kinase inhibitor by variant, as in sporadic PDGFRA GIST: imatinib for imatinib-sensitive variants (most exon 12 and 14 variants); avapritinib for p.Asp842Val and other exon 18 variants that resist imatinib. Tumor genotyping guides the choice.","sources":["pdgfraGeneReviews","pdgfraBrodey"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic PDGFRA condition is described in the sources reviewed. Refer two variants to clinical genetics; this plan covers one activating variant.","sources":["pdgfraGeneReviews"]},"plans":{}},"PKP2":{"symbol":"PKP2","genotype":"Heterozygous","summary":"PKP2 is the most common genetic cause of arrhythmogenic right ventricular cardiomyopathy (ARVC), which causes ventricular arrhythmias and sudden death, usually from the teens to middle age. Over half of carrier relatives in affected families develop ARVC; carriers found by population sequencing rarely do.","table":{"caption":"Arrhythmogenic cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"definite-arvc","name":"Definite ARVC (2010 Task Force Criteria)","women":{"risk":"58%","relative":"Not established","horizon":"At last follow-up · carrier relatives","citations":{"risk":["pkp2Muller"]}},"men":{"risk":"58%","relative":"Not established","horizon":"At last follow-up · carrier relatives","citations":{"risk":["pkp2Muller"]}}},{"id":"arvc-records","name":"Features consistent with ARVC in health records (truncating variants; not Task Force Criteria)","women":{"risk":"1.6%","relative":"Not established","horizon":"At assessment · carriers","citations":{"risk":["pkp2Hylind"]}},"men":{"risk":"1.6%","relative":"Not established","horizon":"At assessment · carriers","citations":{"risk":["pkp2Hylind"]}}},{"id":"sustained-va","name":"Sustained ventricular arrhythmia or sudden cardiac death","women":{"risk":"12%","relative":"Not established","horizon":"At assessment · carriers","citations":{"risk":["pkp2Muller"]}},"men":{"risk":"12%","relative":"Not established","horizon":"At assessment · carriers","citations":{"risk":["pkp2Muller"]}}},{"id":"va-pooled","name":"Ventricular arrhythmia diagnosis, any ARVC gene (pooled)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"af","name":"Atrial fibrillation","women":{"risk":"7.9%","relative":"Not established","horizon":"At assessment · carriers","citations":{"risk":["pkp2Hylind"]}},"men":{"risk":"7.9%","relative":"Not established","horizon":"At assessment · carriers","citations":{"risk":["pkp2Hylind"]}}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"ARVC causes up to 20% of sudden deaths in the young in some series. Among 1,001 patients and relatives, cardiac mortality was 6% and transplantation 4%; sudden death occurred in 16% of probands without an ICD against 0.6% with one.","sources":["pkp2Hrs","pkp2Groeneweg"]},{"title":"Association evidence","text":"ClinGen: definitive for autosomal dominant ARVC (2018); moderately actionable for sudden cardiac death in adults. PKP2 accounts for about half of pathogenic ARVC-gene findings in the population.","sources":["pkp2ClinGen","pkp2ClinGenAction","pkp2James2021","pkp2Bourfiss"]},{"title":"What raises penetrance","text":"Endurance exercise, a second desmosomal variant, and age 20–40 years. An additional desmosomal variant: OR 4.7 (95% CI 1.1–20.4) for penetrant disease; more than 1 pathogenic variant: VT or VF earlier (mean age 28 years), with more heart failure and transplantation.","sources":["pkp2Quarta","pkp2Bhonsale","pkp2James2013","pkp2Muller"]},{"title":"Variant type","text":"Most are truncating. Missense and truncating carriers had similar arrhythmia penetrance. Many truncating variants are also carried by people who never develop disease.","sources":["pkp2Bhonsale","pkp2Hylind"]},{"title":"Treatment if ARVC develops","text":"ESC 2023: beta-blockers are recommended with ventricular ectopy, NSVT, or VT (class I, level C); if symptoms persist, amiodarone (IIa C) or flecainide added to a beta-blocker (IIa C). HRS: beta-blockers reasonable in ACM without an ICD (2a).","sources":["pkp2Esc2023","pkp2Hrs"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the heterozygous guidance. Biallelic loss-of-function variants cause perinatal-onset, often lethal biventricular dilated cardiomyopathy with excessive trabeculation and ventricular septal defects, in a few families; one homozygous truncating variant with hypoplastic left heart syndrome. Heterozygous parents had normal ECG and echocardiography. If both partners carry a PKP2 loss-of-function variant, refer to clinical genetics before conception.","sources":["pkp2Gibb","pkp2Katanyuwong","pkp2Verhagen","pkp2Li"]},"plans":{}},"PLN":{"symbol":"PLN","genotype":"Heterozygous (data mainly p.Arg14del)","summary":"The PLN p.Arg14del founder variant causes arrhythmogenic and dilated cardiomyopathy with a low-voltage ECG, malignant ventricular arrhythmias, and heart failure, from adolescence into old age. A variant-specific calculator guides ICD decisions; risks for other PLN variants are not established.","table":{"caption":"Cardiac risk with p.Arg14del","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"major","name":"Major event: malignant ventricular arrhythmia or heart failure","women":{"risk":"43%","relative":"Not established","horizon":"By age 70","citations":{"risk":["plnPenetrance"]}},"men":{"risk":"43%","relative":"Not established","horizon":"By age 70","citations":{"risk":["plnPenetrance"]}}},{"id":"mva","name":"Malignant ventricular arrhythmia, including sudden death","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hf","name":"Heart failure event","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dcm","name":"Dilated cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"arvc","name":"ARVC by 2010 Task Force criteria","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"risk-feature","name":"Any cardiac risk feature","women":{"risk":"84%","relative":"Not established","horizon":"By age 70","citations":{"risk":["plnPenetrance"]}},"men":{"risk":"84%","relative":"Not established","horizon":"By age 70","citations":{"risk":["plnPenetrance"]}}},{"id":"low-voltage","name":"Low-voltage ECG","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"403 carriers: standardized mortality ratio 1.7 (95% CI 1.4–2.0), with excess deaths from age 25 years. Among DCM index patients, carriers had more appropriate ICD shocks (47% vs 10%) and transplants (18% vs 2%) than noncarriers. Disease ranges from none in old age to sudden death or heart failure in early adulthood.","sources":["plnVanRijsingen","plnPenetrance","plnVanDerZwaag"]},{"title":"Association evidence","text":"ClinGen: definitive for intrinsic cardiomyopathy (lumped DCM and HCM, 2021), moderate for ARVC (2020). Adult actionability strong for dilated cardiomyopathy 1P (2025) and hypertrophic cardiomyopathy 18 (2026). Hypertrophic presentations are uncommon.","sources":["plnClinGen","plnJames"]},{"title":"Prevalence","text":"PLN variants account for about 1% of arrhythmogenic cardiomyopathy and DCM (Wilde 2022); p.Arg14del alone was found in 12% of Dutch ARVC and 15% of Dutch DCM index patients (van der Zwaag 2012).","sources":["plnWilde","plnVanDerZwaag"]},{"title":"Treatment if disease develops","text":"Standard guideline-directed heart failure therapy. Beta-blockers once there is ventricular ectopy, NSVT, or VT in ARVC (ESC 2023).","sources":["plnEsc2023"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the heterozygous guidance. Rare. In two families with null p.Leu39Ter, both homozygous individuals developed DCM and heart failure needing transplantation at ages 16 and 27 years; heterozygous relatives had hypertrophy without reduced function. No pathway is established and the calculator does not apply. Refer to a specialist cardiomyopathy and heart failure centre and offer testing along both parental lines.","sources":["plnNull"]},"plans":{}},"PMS2":{"symbol":"PMS2","genotype":"Heterozygous","summary":"PMS2-related Lynch syndrome generally has lower, later colorectal and endometrial risks than other Lynch genes. In the small PLSD surveillance cohort, age-75 estimates were 8.5% for colorectal cancer in women, 32.8% in men and 21.2% for endometrial cancer, with wide uncertainty; cancers can occur earlier.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"8.5%","relative":"OR 3.77 (nominal)","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"],"relative":["pms2Bbj"]}},"men":{"risk":"32.8%","relative":"OR 3.77 (nominal)","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"],"relative":["pms2Bbj"]}}},{"id":"endometrial","name":"Endometrial cancer","women":{"risk":"21.2%","relative":"OR 8.26 (nominal)","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"],"relative":["pms2Bbj"]}},"men":null},{"id":"ovarian","name":"Ovarian cancer","women":{"risk":"2.5%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"]}},"men":null},{"id":"gastric","name":"Gastric cancer","women":{"risk":"0%","relative":"OR 2.13 (uncertain)","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"],"relative":["pms2Bbj"]}},"men":{"risk":"2.7%","relative":"OR 2.13 (uncertain)","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"],"relative":["pms2Bbj"]}}},{"id":"small-bowel","name":"Small bowel cancer","women":{"risk":"2.1%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"]}},"men":{"risk":"3.3%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"]}}},{"id":"kidney-ureter","name":"Kidney and ureter cancer","women":{"risk":"0%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"]}},"men":{"risk":"5.1%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"]}}},{"id":"bladder","name":"Bladder cancer","women":{"risk":"0%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"]}},"men":{"risk":"0%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"]}}},{"id":"pancreatic","name":"Pancreatic cancer","women":{"risk":"0%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"]}},"men":{"risk":"0%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"]}}},{"id":"biliary","name":"Biliary tract cancer","women":{"risk":"0%","relative":"OR 3.56 (uncertain)","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"],"relative":["pms2Bbj"]}},"men":{"risk":"0%","relative":"OR 3.56 (uncertain)","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"],"relative":["pms2Bbj"]}}},{"id":"prostate","name":"Prostate cancer","women":null,"men":{"risk":"3.3%","relative":"OR 0.92 (uncertain)","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"],"relative":["pms2Bbj"]}}},{"id":"brain","name":"Brain tumor","women":{"risk":"7.3%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"]}},"men":{"risk":"0%","relative":"Not quantified","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"]}}},{"id":"breast","name":"Breast cancer","women":{"risk":"12.4%","relative":"OR 2.47 (uncertain)","horizon":"By age 75","citations":{"risk":["pms2Plsd2023"],"relative":["pms2Bbj"]}},"men":{"risk":"Not estimated","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"PMS2-related Lynch syndrome generally has lower and later cancer risks than other Lynch genes. PLSD modeled median colorectal onset at about 66–71 years among carriers who develop cancer by age 75 years. The observational data do not establish why few cancers occurred before age 50 years.","sources":["lynch","pms2FourLynch","pms2Plsd2023"]},{"title":"Association evidence","text":"Estimates depend on ascertainment. PLSD and family studies show raised colorectal and endometrial risk; UK Biobank, with 431 unselected carriers (368 with c.137G>T, p.Ser46Ile), found a smaller colorectal excess and no endometrial excess. c.137G>T may be less penetrant; other variants were too few to tell. That variant makes PMS2 the most common mismatch repair gene in UK Biobank but rare in BioBank Japan.","sources":["pms2Ukb","pms2Bbj","pms2Plsd2023","lynch"]},{"title":"Testing pitfalls","text":"PMS2 pseudogenes can interfere with testing; methods such as long-range PCR or cDNA analysis may be needed. GeneReviews describes large rearrangements as approximately 20–50% of pathogenic variants in its narrative, with a 20–55% range in its testing table. These are literature estimates, not sensitivity figures for this panel. Confirm sequencing, copy-number and difficult-region coverage with the performing laboratory.","sources":["lynch","pms2Invitae"]},{"title":"Treatment if cancer develops","text":"Metastatic or unresectable mismatch repair-deficient tumors are candidates for immune checkpoint inhibitors. Treatment eligibility requires the tumor biomarker, cancer type, stage, prior treatment and applicable drug indication; a germline result alone is insufficient.","sources":["lynch","pms2Mallorca"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two pathogenic PMS2 variants affecting opposite copies, including appropriate pseudogene-aware testing and phase assessment. Biallelic PMS2 variants cause constitutional mismatch repair deficiency (CMMRD); PMS2 accounts for over 60% of cases. Across CMMRD genotypes, about half develop cancer by age 10 years and 80–90% before 18 years: high-grade brain tumors, hematologic cancers such as T-cell lymphoblastic lymphoma, and Lynch-spectrum cancers. Café-au-lait macules are common. ERN GENTURIS: examination every 6 months, brain MRI from diagnosis or at least age 2 years, every 6 months through age 20 years and at least annually thereafter, and colonoscopy at least yearly from age 6 years, under a specialist pediatric team. The adult plan does not apply.","sources":["pms2Cmmrd","lynch"]},"plans":{}},"POLD1":{"symbol":"POLD1","genotype":"Heterozygous variant confirmed to cause POLD1-related PPAP","summary":"PPAP-associated POLD1 variants increase colorectal polyp, colorectal cancer and endometrial cancer risk. Estimates come from small selected families; other variant types can cause different conditions.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"50%","relative":"Not quantified","horizon":"By age 70; sexes pooled","citations":{"risk":["pold1Palles"],"relative":["pold1Buchanan"]}},"men":{"risk":"50%","relative":"Not quantified","horizon":"By age 70; sexes pooled","citations":{"risk":["pold1Palles"],"relative":["pold1Buchanan"]}}},{"id":"adenomas","name":"Colorectal adenomas","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"endometrial","name":"Endometrial cancer","women":{"risk":"75%","relative":"Not quantified","horizon":"By age 70","citations":{"risk":["pold1Palles"]}},"men":null},{"id":"breast","name":"Breast cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"duodenal","name":"Duodenal adenoma or cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"ovarian","name":"Ovarian cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":null},{"id":"brain","name":"Brain tumor","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"Reported POLD1 carriers often have attenuated polyposis, but some develop colorectal cancer with few or no reported polyps. In the Palles series, benign or malignant tumors at more than one site occurred in 2 of 10 men and 10 of 17 women.","sources":["pold1Palles"]},{"title":"Which variants count","text":"PPAP is associated with specific variants that impair exonuclease proofreading. Domain location, rarity and computational predictions are supporting clues, not sufficient proof. Confirm the exact variant’s condition-specific classification with the laboratory or cancer genetics; functional and segregation evidence can be important.","sources":["pold1Palles","pold1Danish","pold1Weedon","pold1Clingen"]},{"title":"Association evidence","text":"ClinGen: Definitive (2023); the MONDO term is now obsolete, which does not change the evidence. Estimates rest on 27 carriers from a handful of families.","sources":["pold1Clingen","pold1Palles"]},{"title":"Treatment if cancer develops","text":"Some PPAP-associated tumors are ultramutated and may respond to immune checkpoint inhibitors even without microsatellite instability. Oncology should use the actual tumor profile, cancer type, stage and current treatment criteria; a germline result alone does not establish eligibility. Colorectal surgery is individualized.","sources":["pold1Pdq","pold1Palles"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm phase and the condition associated with each variant through clinical genetics. Biallelic POLD1 variants have been linked to non-severe combined immunodeficiency; ClinGen rated this association Limited in February 2026. Involve immunology when the genotype and phenotype suggest this disorder. Risks from two PPAP-associated exonuclease variants are not established. Do not automatically discard surveillance warranted by a confirmed PPAP variant or personal history.","sources":["pold1ClingenScid","pold1Danish"]},"plans":{}},"POLE":{"symbol":"POLE","genotype":"Heterozygous variant confirmed to cause POLE-related PPAP","summary":"PPAP-associated POLE variants increase colorectal polyp and cancer risk. Duodenal, endometrial and other tumors have also been reported; their risks are less certain and depend on the exact variant and family history.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"90%","relative":"Not quantified","horizon":"By age 70; sexes pooled","citations":{"risk":["polePalles"],"relative":["poleBuchanan"]}},"men":{"risk":"90%","relative":"Not quantified","horizon":"By age 70; sexes pooled","citations":{"risk":["polePalles"],"relative":["poleBuchanan"]}}},{"id":"adenomas","name":"Colorectal adenomas","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"duodenal","name":"Duodenal cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"endometrial","name":"Endometrial cancer","women":{"risk":"25%","relative":"Not quantified","horizon":"By age 70","citations":{"risk":["polePalles"]}},"men":null},{"id":"ovarian","name":"Ovarian cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":null},{"id":"brain","name":"Brain tumor","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"breast","name":"Breast cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"Most reported carriers have attenuated polyposis, but some develop early colorectal cancer with few polyps. Across both genes, 16 people had multiple colorectal cancers. In the POLE series, benign or malignant tumors at more than one site occurred in 15 of 51 men and 20 of 43 women.","sources":["polePalles"]},{"title":"Which variants count","text":"PPAP is associated with specific variants that impair exonuclease proofreading. Domain location, rarity and computational predictions are supporting clues, not sufficient proof. Confirm the exact variant’s condition-specific classification with the laboratory or cancer genetics; functional and segregation evidence can be important.","sources":["polePalles","poleDanish","poleEhtg","poleClingen"]},{"title":"Association evidence","text":"ClinGen: Definitive (2023). Estimates rest on few families with uneven screening and clinic ascertainment; extracolonic associations are less certain than colorectal.","sources":["poleClingen","polePalles"]},{"title":"Treatment if cancer develops","text":"Some PPAP-associated tumors are ultramutated and may respond to immune checkpoint inhibitors even without microsatellite instability. Oncology should use the actual tumor profile, cancer type, stage and current treatment criteria; a germline result alone does not establish eligibility. Colorectal surgery is individualized.","sources":["polePdq","poleBuchanan","polePalles"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm phase and the condition associated with each variant through clinical genetics. Biallelic variants that reduce POLE function can cause FILS or IMAGe-related developmental and immune disorders, a different mechanism from PPAP; involve immunology and other specialists according to the phenotype. Risks from two PPAP-associated exonuclease variants are not established. Do not automatically discard surveillance warranted by a confirmed PPAP variant or personal history.","sources":["poleFils","poleDanish","poleImage"]},"plans":{}},"POT1":{"symbol":"POT1","genotype":"Heterozygous","summary":"A POT1 variant raises the risk of melanoma, often multiple, and of rarer cancers: cardiac angiosarcoma, chronic lymphocytic leukemia, and glioma. Risks are modest and probably inflated by ascertainment, and US and UK guidance disagree sharply on surveillance.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"melanoma","name":"Cutaneous melanoma","women":{"risk":"3.3–5%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["pot1Uk"]}},"men":{"risk":"3.3–5%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["pot1Uk"]}}},{"id":"angiosarcoma","name":"Angiosarcoma, mainly cardiac","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"sarcoma","name":"Sarcoma, any type","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cll","name":"Chronic lymphocytic leukemia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"glioma","name":"Glioma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"thyroid","name":"Papillary thyroid cancer","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Most cancers occur in adulthood. Carriers more often develop multiple tumors than panel-negative patients (18.9% against 8.7%). Cardiac angiosarcoma is rare but aggressive.","sources":["pot1GeneReviews","pot1HerreraMullar","pot1Uk"]},{"title":"Association evidence","text":"ClinGen: Definitive (2025). Melanoma is best established; other cancers rest on few families, mixed classifications, and biased datasets, which is why the UK limits surveillance.","sources":["pot1Clingen","pot1Andreotti","pot1Uk"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan above. Biallelic POT1 variants are associated with Coats plus syndrome, a telomere biology disorder with retinal and gastrointestinal telangiectasias; the POT1 evidence is a homozygous p.Ser322Leu variant in two siblings. Refer to clinical genetics and a telomere biology disorder service; this plan does not apply.","sources":["pot1Takai","pot1CoatsPlus"]},"plans":{}},"PRKAG2":{"symbol":"PRKAG2","genotype":"Heterozygous","summary":"PRKAG2 cardiac syndrome is a glycogen storage disease of the heart that mimics, but is not, sarcomeric hypertrophic cardiomyopathy. Its dangers are progressive conduction disease needing a pacemaker, pre-excitation, early atrial fibrillation, heart failure, and sudden death, so ECG and rhythm monitoring matter as much as the echocardiogram.","table":{"caption":"Cardiac findings and events","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"any","name":"Any feature of PRKAG2 syndrome","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lvh","name":"Left ventricular hypertrophy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"preexcitation","name":"Ventricular pre-excitation or prior pathway ablation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"af","name":"Atrial fibrillation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pacemaker","name":"Permanent pacemaker","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hf","name":"Heart failure admission","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"scd","name":"Sudden cardiac death or resuscitated arrest","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"transplant","name":"Heart transplant","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"death","name":"Death, any cause","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Not sarcomeric HCM","text":"Variants in this AMP-activated protein kinase subunit cause cardiac glycogen accumulation; US HCM and 2022 HRS/EHRA guidance list PRKAG2 as an HCM phenocopy. Unlike sarcomeric HCM: earlier atrial fibrillation, progressive conduction disease, worse advanced heart failure, and no outflow obstruction above 30 mm Hg among those with LVH in the cohort. Consider it in young people with LVH who develop atrial fibrillation or need a pacemaker.","sources":["prkag2LopezSainz","prkag2Aha2024","prkag2Hrs2022"]},{"title":"Association evidence","text":"ClinGen: definitive for autosomal dominant PRKAG2-related cardiomyopathy (2017, reaffirmed June 2022), lumping hypertrophic cardiomyopathy 6, lethal congenital cardiac glycogen storage disease, and Wolff-Parkinson-White syndrome. Over 190 affected people with at least 13 variants, almost all missense.","sources":["prkag2ClinGen"]},{"title":"Common variants","text":"p.Arg302Gln and p.Asn488Ile were 44% of the cohort, with more pre-excitation and atrial fibrillation but similar event rates.","sources":["prkag2LopezSainz"]},{"title":"Treatment if disease develops","text":"No approved disease-specific therapy; enzyme replacement or gene therapy may come. Care is device-based and supportive: pacing, EP study and selective ablation, defibrillators by individual risk, atrial fibrillation rhythm and anticoagulation management, and heart failure therapy to transplantation.","sources":["prkag2LopezSainz"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan above. No biallelic PRKAG2 condition is established; ClinGen treats the lethal congenital form as part of the dominant disease. With two variants, refer to clinical genetics and a cardiomyopathy center, monitor at least as above, and offer testing along both parental lines.","sources":["prkag2ClinGen"]},"plans":{}},"PRKAR1A":{"symbol":"PRKAR1A","genotype":"Heterozygous","summary":"PRKAR1A causes Carney complex, with penetrance above 95% by age 50 years. Cardiac myxoma, which can embolize, obstruct, and recur, is the main danger; care is lifelong yearly echocardiography and hormone testing.","table":{"caption":"Tumor and feature frequency","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"cardiac-myxoma","name":"Cardiac myxoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ppnad","name":"PPNAD, adrenal Cushing syndrome","women":{"risk":">70%","relative":"Not established","horizon":"By age 40 · family carriers","citations":{"risk":["prkar1aBertherat"]}},"men":{"risk":"Not established","relative":"Not established"}},{"id":"acromegaly","name":"Acromegaly","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"thyroid","name":"Thyroid tumors, mostly follicular adenomas","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"thyroid-cancer","name":"Thyroid carcinoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lccsct","name":"Large-cell calcifying Sertoli cell tumor of the testis","women":null,"men":{"risk":"Not established","relative":"Not established"}},{"id":"ovarian","name":"Ovarian cysts and tumors","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"breast-myxoma","name":"Breast myxoma","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"pms","name":"Psammomatous melanotic schwannoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"skin-myxoma","name":"Skin myxoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lentigines","name":"Lentigines","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"other-cancer","name":"Pancreatic and other cancers","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Estimated life expectancy 50 years, though most live a normal lifespan. Deaths come from myxoma complications (embolism, cardiomyopathy, arrhythmia, surgery), metastatic or intracranial schwannoma, thyroid carcinoma, and metastatic pancreatic or testicular tumors. Long-term survival after myxoma resection is 81–96%.","sources":["prkar1aActionability"]},{"title":"Association evidence","text":"ClinGen: Definitive, autosomal dominant (December 2018). PRKAR1A variants are found in about 70% of people with Carney complex and 80% of those with Cushing syndrome. Median age at diagnosis 20 years.","sources":["prkar1aClingen","prkar1aActionability","prkar1aGeneReviews"]},{"title":"Genotype and phenotype","text":"Most variants (63 of 80) cause nonsense-mediated decay and produce no protein; 82% of carriers had one, with milder disease. Exonic variants associate more with acromegaly, myxomas, lentigines, and schwannomas; c.491_492delTG with lentigines, cardiac myxomas, and thyroid tumors. These do not change the schedule.","sources":["prkar1aBertherat"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan above. No biallelic PRKAR1A condition is described; refer to clinical genetics.","sources":["prkar1aGeneReviews"]},"plans":{}},"PRKG1":{"symbol":"PRKG1","genotype":"Heterozygous p.Arg177Gln","summary":"PRKG1 p.Arg177Gln causes thoracic aortic disease with type A and type B dissections from the late teens, often before the aorta enlarges. It accounts for under 1% of nonsyndromic HTAD; other PRKG1 variants are not established causes.","table":{"caption":"Aortic risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"aortic-event","name":"First aortic dissection or elective aortic surgery","women":{"risk":"86%","relative":"Not established","horizon":"By age 65 · family study","citations":{"risk":["prkg1Askari"]}},"men":{"risk":"86%","relative":"Not established","horizon":"By age 65 · family study","citations":{"risk":["prkg1Askari"]}}},{"id":"dissection","name":"Aortic dissection, type A or B","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"type-a","name":"Type A aortic dissection","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"type-b","name":"Type B aortic dissection","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"root","name":"Aortic root enlargement without dissection","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Dissection is often the first sign of disease.","sources":["prkg1Guo2013","prkg1Shalhub"]},{"title":"Association evidence","text":"ClinGen: strong for familial thoracic aortic aneurysm and dissection (2016), with segregation in four families (combined LOD 7.88) and a gain-of-function mechanism. p.Arg177Gln activates the kinase without cGMP, reducing smooth muscle contraction.","sources":["prkg1ClinGen","prkg1Renard","prkg1Guo2013","prkg1Actionability"]},{"title":"Treatment if the aorta enlarges or dissects","text":"Root, ascending, and proximal arch replacement by an experienced aortic team; the tissue is thin. Distal dissection can occur years after proximal repair.","sources":["prkg1Askari"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan above. No biallelic carrier or recessive PRKG1 condition is described. Refer to clinical genetics and an aortic center.","sources":["prkg1Guo2013","prkg1Renard"]},"plans":{}},"PROC":{"symbol":"PROC","genotype":"Heterozygous","summary":"Heterozygous protein C deficiency is a high-risk thrombophilia, raising the odds of a first venous thromboembolism (VTE) about 7.5-fold.","table":{"caption":"Venous thromboembolism risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"first-vte","name":"First VTE, per year","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"recurrence","name":"Recurrent VTE after a first VTE, per year off anticoagulation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pregnancy-all","name":"Pregnancy-associated VTE, all pregnancies","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"pregnancy-fh","name":"Pregnancy-associated VTE, per pregnancy, family history of VTE","women":{"risk":"7.8%","relative":"Not established","horizon":"Per pregnancy","citations":{"risk":["procCroles2017"]}},"men":null},{"id":"pregnancy-nofh","name":"Pregnancy-associated VTE, per pregnancy, no family history","women":{"risk":"0.7%","relative":"Not established","horizon":"Per pregnancy","citations":{"risk":["procClingen135"]}},"men":null},{"id":"coc","name":"VTE during combined oral contraceptive use, per year","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"hrt","name":"VTE during menopausal hormone therapy","women":{"risk":"Not established","relative":"Not established"},"men":null}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Heterozygotes are usually well until adulthood; most events follow surgery, pregnancy, immobility, or hormones. Usually leg DVT with or without pulmonary embolism; cerebral venous thrombosis occurs. Long-term post-thrombotic syndrome and pulmonary hypertension. Prognosis is good with prevention, though pulmonary embolism can be fatal.","sources":["procClingen135"]},{"title":"Frequency","text":"0.2–0.5% of the general population; about 3% of people with thrombosis (median 2.5% in VTE).","sources":["procClingen135","procAsh2023"]},{"title":"Laboratory pitfalls","text":"Adult reference ranges do not apply to children. Sample handling affects assays differently.","sources":["procIsth"]},{"title":"Association evidence","text":"ClinGen: Definitive, semidominant. Variable expression in families suggests other factors must combine with the deficiency.","sources":["procClingenValidity","procClingen135"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan above. Undetectable protein C usually presents hours to days after birth with purpura fulminans, often in families with no known deficiency; about 1 in 500,000. Low but detectable levels give a course similar to heterozygous deficiency. Protein C concentrate is approved for prevention and treatment of venous thrombosis and purpura fulminans in severe congenital deficiency. Refer an adult with two variants to hematology.","sources":["procClingen135","procIsth","procCeprotin"]},"plans":{}},"PROS1":{"symbol":"PROS1","genotype":"Heterozygous","summary":"Heterozygous protein S deficiency raises the odds of a first venous thromboembolism (VTE) about fivefold and is managed as a high-risk thrombophilia.","table":{"caption":"Venous thromboembolism risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"first-vte","name":"First VTE, per year","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"recurrence","name":"Recurrent VTE after a first VTE, per year off anticoagulation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pregnancy-fh","name":"Pregnancy-associated VTE, per pregnancy, family history of VTE","women":{"risk":"4.8%","relative":"Not established","horizon":"Per pregnancy","citations":{"risk":["pros1Croles2017"]}},"men":null},{"id":"pregnancy-nofh","name":"Pregnancy-associated VTE, per pregnancy, no family history","women":{"risk":"0.5%","relative":"Not established","horizon":"Per pregnancy","citations":{"risk":["pros1Clingen137"]}},"men":null},{"id":"coc","name":"VTE during combined oral contraceptive use, per year","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"hrt","name":"VTE during menopausal hormone therapy","women":{"risk":"Not established","relative":"Not established"},"men":null}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Heterozygotes are usually well until adulthood; most events follow pregnancy, surgery, immobility, or hormones. Usually leg DVT with or without pulmonary embolism; post-thrombotic syndrome and pulmonary hypertension can follow. Prognosis is good with prevention, though pulmonary embolism can be fatal.","sources":["pros1Clingen137"]},{"title":"Frequency","text":"0.03–1% of the general population; about 3.2% of people with thrombosis (median 2.3% in VTE).","sources":["pros1Clingen137","pros1Ash2023"]},{"title":"Laboratory pitfalls","text":"Protein S circulates partly bound to C4b-binding protein; handling and acquired conditions change measured levels.","sources":["pros1Isth"]},{"title":"Association evidence","text":"ClinGen: Definitive, semidominant. Older studies of women with recurrent VTE may overstate risk, and some relatives with low protein S stay well.","sources":["pros1ClingenValidity","pros1Clingen137"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan on this page. Very rare severe deficiency causes thrombosis and secondary bleeding from early infancy: neonatal purpura fulminans, multifocal thrombosis, or intracranial hemorrhage within hours or days of birth. Prevalence is unknown, probably near 1 in 500,000. Hematology leads management.","sources":["pros1Clingen137"]},"plans":{}},"PTCH1":{"symbol":"PTCH1","genotype":"Heterozygous","summary":"PTCH1 causes Gorlin syndrome: multiple basal cell carcinomas in most carriers by age 50 years, jaw keratocysts from the teens, and ovarian fibromas in some women. Life expectancy is near normal; radiation multiplies skin cancers.","table":{"caption":"Tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"bcc","name":"Basal cell carcinoma","women":{"risk":"34.5%","relative":"Not established","horizon":"By age 30 · carriers","citations":{"risk":["ptch1Jones"]}},"men":{"risk":"34.5%","relative":"Not established","horizon":"By age 30 · carriers","citations":{"risk":["ptch1Jones"]}}},{"id":"okc","name":"Odontogenic keratocyst of the jaw","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ovarian-fibroma","name":"Ovarian fibroma","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"cardiac-fibroma","name":"Cardiac fibroma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"medulloblastoma","name":"Medulloblastoma, early childhood","women":{"risk":"<2%","relative":"Not established","horizon":"Childhood estimate","citations":{"risk":["ptch1Siope"]}},"men":{"risk":"<2%","relative":"Not established","horizon":"Childhood estimate","citations":{"risk":["ptch1Siope"]}}},{"id":"meningioma","name":"Meningioma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Life expectancy is near average. The burden is the cosmetic and functional cost of treating many basal cell carcinomas and jaw keratocysts. Irradiated medulloblastoma survivors can develop more than 1,000 basal cell carcinomas in the field.","sources":["ptch1GeneReviews","ptch1Actionability","ptch1Foulkes"]},{"title":"Association evidence","text":"ClinGen: Definitive, autosomal dominant (June 2018). Holoprosencephaly: Limited (July 2025), no adult action. Adult actionability is limited; evidence that surveillance improves outcomes is thin.","sources":["ptch1Clingen","ptch1ClingenHpe","ptch1Actionability"]},{"title":"Genotype and phenotype","text":"Missense variants may mean later diagnosis and fewer tumors, though one cohort found variant type did not predict basal cell carcinoma burden. 9q22.3 deletions including PTCH1 add developmental features and Wilms tumor.","sources":["ptch1Actionability","ptch1Jones","ptch1Siope"]},{"title":"Other features","text":"Falx calcification (90% by age 30 years), palmar and plantar pits, bifid ribs and other skeletal anomalies, macrocephaly, and milia need no treatment.","sources":["ptch1GeneReviews","ptch1Verkouteren"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic PTCH1 condition is described; refer two variants to clinical genetics.","sources":["ptch1GeneReviews"]},"plans":{}},"PTEN":{"symbol":"PTEN","genotype":"Heterozygous","summary":"PTEN hamartoma tumor syndrome increases breast, endometrial, thyroid, kidney, colorectal, and melanoma risk. Estimates vary substantially by study; referral cohorts may overestimate risk for people identified through population testing.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"breast","name":"Breast cancer","women":{"risk":"89%","relative":"SIR 23.0","horizon":"By age 75","citations":{"risk":["ptenYehia"],"relative":["ptenYehia"]}},"men":{"risk":"Not established","relative":"Not quantified","horizon":"Age-specific estimate","citations":{"risk":["ptenYehia"]}}},{"id":"endometrial","name":"Endometrial cancer","women":{"risk":"50%","relative":"SIR 45.5","horizon":"By age 80","citations":{"risk":["ptenYehia"],"relative":["ptenYehia"]}},"men":null},{"id":"thyroid","name":"Thyroid cancer","women":{"risk":"40%","relative":"SIR 44.1","horizon":"By age 80 · Sexes pooled","citations":{"risk":["ptenYehia"],"relative":["ptenYehia"]}},"men":{"risk":"40%","relative":"SIR 44.1","horizon":"By age 80 · Sexes pooled","citations":{"risk":["ptenYehia"],"relative":["ptenYehia"]}}},{"id":"kidney","name":"Kidney cancer","women":{"risk":"31%","relative":"SIR 39.0","horizon":"By age 80 · Sexes pooled","citations":{"risk":["ptenYehia"],"relative":["ptenYehia"]}},"men":{"risk":"31%","relative":"SIR 39.0","horizon":"By age 80 · Sexes pooled","citations":{"risk":["ptenYehia"],"relative":["ptenYehia"]}}},{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"12%","relative":"SIR 11.6","horizon":"By age 80 · Sexes pooled","citations":{"risk":["ptenYehia"],"relative":["ptenYehia"]}},"men":{"risk":"12%","relative":"SIR 11.6","horizon":"By age 80 · Sexes pooled","citations":{"risk":["ptenYehia"],"relative":["ptenYehia"]}}},{"id":"polyposis","name":"Colon polyposis (20 or more polyps)","women":{"risk":"Not established","relative":"OR 31.60","horizon":"Age-specific estimate","citations":{"risk":["ptenCummings"],"relative":["ptenCummings"]}},"men":{"risk":"Not established","relative":"OR 31.60","horizon":"Age-specific estimate","citations":{"risk":["ptenCummings"],"relative":["ptenCummings"]}}},{"id":"melanoma","name":"Melanoma","women":{"risk":"7%","relative":"SIR 10.6","horizon":"By age 80 · Sexes pooled","citations":{"risk":["ptenYehia"],"relative":["ptenYehia"]}},"men":{"risk":"7%","relative":"SIR 10.6","horizon":"By age 80 · Sexes pooled","citations":{"risk":["ptenYehia"],"relative":["ptenYehia"]}}},{"id":"ovarian","name":"Ovarian cancer","women":{"risk":"Not established","relative":"OR 3.77 (disputed)","horizon":"Age-specific estimate","citations":{"risk":["ptenCummings"],"relative":["ptenCummings"]}},"men":null},{"id":"prostate","name":"Prostate cancer","women":null,"men":{"risk":"Not established","relative":"SIR 5.52 (limited)","horizon":"Age-specific estimate","citations":{"risk":["ptenExtended"],"relative":["ptenExtended"]}}},{"id":"sarcoma","name":"Soft tissue sarcoma","women":{"risk":"Not established","relative":"SIR 10.37 (limited)","horizon":"Age-specific estimate","citations":{"risk":["ptenExtended"],"relative":["ptenExtended"]}},"men":{"risk":"Not established","relative":"SIR 10.37 (limited)","horizon":"Age-specific estimate","citations":{"risk":["ptenExtended"],"relative":["ptenExtended"]}}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"In a European clinical cohort, 10-year overall survival after diagnosis was 77% for breast, 87% for thyroid, and 64% for endometrial cancer; outcomes were broadly comparable to sporadic cancers, with limited numbers and possible selection bias. In a separate cohort with a first PHTS-related cancer, estimated 10-year risk of another PHTS-related cancer was 45.7% (95% CI 36.9–55.4%) in women and 19.8% (95% CI 8.6–41.9%) in men.","sources":["ptenPrognosis","ptenSecond","cancerPrognosis"]},{"title":"Non-cancer features","text":"Skin and mucosal lesions (trichilemmomas, papillomatous papules, acral keratoses) are reported in about 99% by the fourth decade; macrocephaly in about 94%; fibrocystic breast disease in up to 67%. Autism, developmental delay, and intellectual disability can occur. Lhermitte-Duclos disease is rare but characteristic. These are frequencies in clinically characterized cohorts, not population-screened penetrance estimates.","sources":["ptenGr"]},{"title":"Association evidence","text":"Most estimates come from expert-center cohorts selected by Cowden criteria. The bias-corrected cohort recommends focusing surveillance on breast, endometrial, and thyroid cancer. Testing-cohort ORs could not assess men.","sources":["ptenHendricks","ptenYehia","ptenCummings","ptenErn2026"]},{"title":"Variant type","text":"Reported associations include promoter variants with breast cancer, nonsense variants with colorectal cancer, frameshift variants with thyroid cancer, and missense variants with autism. A European cohort found higher breast cancer risk with truncating than missense variants and with phosphatase-domain than C2-domain variants. These associations do not currently establish variant-specific surveillance schedules.","sources":["ptenGr","ptenTan","ptenHendricks"]}],"otherGenotype":{"title":"If both copies are affected","text":"These estimates and recommendations describe a heterozygous germline PTEN finding. If two variants are reported, refer to clinical genetics to confirm their classification and whether they affect the same or opposite copies; do not extrapolate a doubled risk. Continue care indicated by an established PHTS diagnosis while the result is clarified.","sources":["ptenGr"]},"plans":{}},"RAD51C":{"symbol":"RAD51C","genotype":"Heterozygous","summary":"RAD51C raises ovarian and fallopian tube cancer risk, mostly after age 50 years, and moderately raises breast cancer risk, mainly ER-negative and triple-negative.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"ovarian","name":"Ovarian / fallopian tube cancer","women":{"risk":"11%","relative":"Incidence RR 7.55","horizon":"By age 80","citations":{"risk":["rad51cYang"],"relative":["rad51cYang"]}},"men":null},{"id":"breast","name":"Breast cancer","women":{"risk":"21%","relative":"Incidence RR 1.99","horizon":"By age 80","citations":{"risk":["rad51cYang"],"relative":["rad51cYang"]}},"men":{"risk":"Not established","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"Breast cancers in carriers are enriched for triple-negative disease. Because triple-negative tumors can be less visible on mammography, this supports discussing MRI; gene-specific screening performance and interval-cancer rates have not been established.","sources":["rad51cAcmg","rad51cEviq"]},{"title":"Association evidence","text":"ClinGen: Definitive for cancer predisposition (autosomal dominant, August 2024). Evidence for prostate and other cancers is insufficient.","sources":["rad51cClinGen","rad51cBcac","rad51cCarriers","rad51cAcmg"]},{"title":"Treatment if cancer develops","text":"Gene-specific treatment evidence remains limited. The FDA olaparib label includes qualifying RAD51C alterations for adults with metastatic castration-resistant prostate cancer progressing after enzalutamide or abiraterone. Eligibility requires the appropriate FDA-approved companion diagnostic; the label lists tumor testing for RAD51C, and treatment requires continued GnRH therapy or prior bilateral orchiectomy. An inherited panel finding alone does not complete treatment eligibility. Oncology should verify the current label and full clinical criteria. In ovarian cancer, treatment depends on the tumor and approved indication; the HRD-negative PAOLA-1 subgroup did not show a progression-free-survival benefit from adding olaparib to bevacizumab.","sources":["rad51cAcmg","rad51cOlaparib"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm that both variants are disease-relevant and whether they are on opposite copies (in trans), using parental testing or laboratory phasing when needed. Biallelic RAD51C is associated with Fanconi anemia group O, which accounts for under 1% of Fanconi anemia cases; ClinGen rates this recessive gene-disease relationship as Limited. Refer to clinical genetics and a Fanconi anemia specialist team. If both variants are on the same copy, genetics should interpret the combined allele before applying the monoallelic cancer-risk plan.","sources":["rad51cClinGen","rad51cAcmg","fa"]},"plans":{}},"RAD51D":{"symbol":"RAD51D","genotype":"Heterozygous","summary":"RAD51D raises ovarian and fallopian tube cancer risk, mostly after age 50 years, and moderately raises breast cancer risk, mainly ER-negative and triple-negative.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"ovarian","name":"Ovarian / fallopian tube cancer","women":{"risk":"13%","relative":"Incidence RR 7.60","horizon":"By age 80","citations":{"risk":["rad51dYang"],"relative":["rad51dYang"]}},"men":null},{"id":"breast","name":"Breast cancer","women":{"risk":"20%","relative":"Incidence RR 1.83","horizon":"By age 80","citations":{"risk":["rad51dYang"],"relative":["rad51dYang"]}},"men":{"risk":"Not established","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"Breast cancers in carriers are enriched for triple-negative disease. Because triple-negative tumors can be less visible on mammography, this supports discussing MRI; gene-specific screening performance and interval-cancer rates have not been established.","sources":["rad51dAcmg","rad51dEviq"]},{"title":"Association evidence","text":"ClinGen: Definitive for cancer predisposition (autosomal dominant, August 2024). Evidence for prostate and other cancers is insufficient.","sources":["rad51dClinGen","rad51dBcac","rad51dCarriers","rad51dAcmg"]},{"title":"Treatment if cancer develops","text":"Gene-specific treatment evidence remains limited. The FDA olaparib label includes qualifying RAD51D alterations for adults with metastatic castration-resistant prostate cancer progressing after enzalutamide or abiraterone. Eligibility requires the appropriate FDA-approved companion diagnostic; the label lists tumor testing for RAD51D, and treatment requires continued GnRH therapy or prior bilateral orchiectomy. An inherited panel finding alone does not complete treatment eligibility. Oncology should verify the current label and full clinical criteria. In ovarian cancer, treatment depends on the tumor and approved indication; the HRD-negative PAOLA-1 subgroup did not show a progression-free-survival benefit from adding olaparib to bevacizumab.","sources":["rad51dAcmg","rad51dOlaparib"]}],"otherGenotype":{"title":"If both copies are affected","text":"No recessive RAD51D condition is currently established. An apparent biallelic result still warrants clinical genetics review to confirm classification, phase and relevance to the patient.","sources":["rad51dAcmg","rad51dClinGen"]},"plans":{}},"RB1":{"symbol":"RB1","genotype":"Heterozygous","summary":"RB1 causes heritable retinoblastoma, usually in infancy. For an adult survivor the issues are second cancers, about one in three within 50 years, highest after radiotherapy, and a 50% chance of passing the variant to each child.","table":{"caption":"Second cancer risk after heritable retinoblastoma","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"any","name":"Any second cancer","women":{"risk":"33.1%","relative":"Not established","horizon":"50 years after retinoblastoma","citations":{"risk":["rb1Schonfeld"]}},"men":{"risk":"33.1%","relative":"Not established","horizon":"50 years after retinoblastoma","citations":{"risk":["rb1Schonfeld"]}}},{"id":"soft-tissue-sarcoma","name":"Soft tissue sarcoma","women":{"risk":"15.1%","relative":"Not established","horizon":"50 years after retinoblastoma","citations":{"risk":["rb1Schonfeld"]}},"men":{"risk":"15.1%","relative":"Not established","horizon":"50 years after retinoblastoma","citations":{"risk":["rb1Schonfeld"]}}},{"id":"bone-sarcoma","name":"Bone sarcoma","women":{"risk":"9.0%","relative":"Not established","horizon":"50 years after retinoblastoma","citations":{"risk":["rb1Schonfeld"]}},"men":{"risk":"9.0%","relative":"Not established","horizon":"50 years after retinoblastoma","citations":{"risk":["rb1Schonfeld"]}}},{"id":"melanoma","name":"Melanoma","women":{"risk":"5.5%","relative":"Not established","horizon":"50 years after retinoblastoma","citations":{"risk":["rb1Schonfeld"]}},"men":{"risk":"5.5%","relative":"Not established","horizon":"50 years after retinoblastoma","citations":{"risk":["rb1Schonfeld"]}}},{"id":"breast","name":"Breast cancer","women":{"risk":"3.8%","relative":"Not established","horizon":"50 years after retinoblastoma","citations":{"risk":["rb1Schonfeld"]}},"men":{"risk":"Not established","relative":"Not established"}},{"id":"nasal","name":"Nasal cavity and sinus cancer","women":{"risk":"1.8%","relative":"Not established","horizon":"50 years after retinoblastoma","citations":{"risk":["rb1Schonfeld"]}},"men":{"risk":"1.8%","relative":"Not established","horizon":"50 years after retinoblastoma","citations":{"risk":["rb1Schonfeld"]}}},{"id":"uterine-lms","name":"Uterine leiomyosarcoma","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"brain","name":"Brain tumor","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pineoblastoma","name":"Pineoblastoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"oral","name":"Oral cavity and pharynx cancer","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lung","name":"Lung cancer","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Melanoma deaths were 23.3–89.0 times expected. After one second cancer, risk of another is more than 7 times higher, and a third cancer worsens survival.","sources":["rb1Tonorezos","rb1Marees","cancerPrognosis"]},{"title":"Treatment effects","text":"External-beam radiotherapy roughly tripled second-cancer risk, concentrated in the field; 34.6% (95% CI 30.2–38.9%) of irradiated survivors had one within 50 years (Schonfeld), with lifetime estimates of 40–50% (AACR). Alkylating chemotherapy added bone tumor and leiomyosarcoma risk. Survivors of modern eye-preserving treatment may have lower risk; nearly 90% of the cohort was irradiated.","sources":["rb1Kleinerman2005","rb1Schonfeld","rb1Wong","rb1Gr","rb1Aacr2017"]},{"title":"Penetrance and variant type","text":"Null variants cause retinoblastoma in more than 99% (GeneReviews) or 90–95% (AACR) of carriers. Under 10% of families show penetrance of 25% or less, usually with in-frame, missense, some splice, or promoter variants; parent-of-origin effects occur. Large 13q14 deletions show reduced expressivity. About 6% of unilateral cases are mosaic and can still transmit.","sources":["rb1Gr","rb1Aacr2017"]}],"otherGenotype":{"title":"If both copies are affected","text":"No inherited biallelic RB1 condition exists; loss of the second copy is the tumor event. Refer an unexpected biallelic report to clinical genetics.","sources":["rb1Gr"]},"plans":{}},"RBM20":{"symbol":"RBM20","genotype":"Heterozygous","summary":"Missense variants in the RBM20 exon 9 and exon 11 hotspots cause an aggressive, arrhythmogenic dilated cardiomyopathy that starts young and is more severe in men. Ventricular arrhythmia can occur before LVEF falls to 35%.","table":{"caption":"Cardiomyopathy and arrhythmia risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"dcm","name":"Dilated cardiomyopathy","women":{"risk":"66%","relative":"Not established","horizon":"At assessment · five familial variants","citations":{"risk":["rbm20Hey"]}},"men":{"risk":"66%","relative":"Not established","horizon":"At assessment · five familial variants","citations":{"risk":["rbm20Hey"]}}},{"id":"mva","name":"Malignant ventricular arrhythmia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"eshf","name":"End-stage heart failure","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Early ventricular arrhythmia with rapid progression to end-stage heart failure, especially in men; the arrhythmic profile resembles LMNA more than TTN cardiomyopathy.","sources":["rbm20Parikh","rbm20Cannie","rbm20Hey"]},{"title":"Association evidence","text":"ClinGen: definitive for dilated cardiomyopathy (2020), strong adult actionability; limited for hypertrophic cardiomyopathy. Haploinsufficiency score 1, consistent with hotspot missense acting other than by loss of one copy. About 2% of DCM.","sources":["rbm20ClinGen","rbm20Jordan","rbm20Ehra"]},{"title":"Treatment if disease develops","text":"Standard heart failure therapy, early arrhythmia risk assessment, and early advanced heart failure referral.","sources":["rbm20Tetaj","rbm20ClinGenAc"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic RBM20 condition is curated. Refer to clinical genetics and a cardiomyopathy center, use at least the surveillance above, and test both parental lines.","sources":["rbm20ClinGen"]},"plans":{}},"RET":{"symbol":"RET","genotype":"Heterozygous activating variant","summary":"An activating RET variant causes MEN2: medullary thyroid carcinoma in nearly every carrier, plus pheochromocytoma and, in MEN2A, hyperparathyroidism by codon. The codon sets the ATA risk category and thyroidectomy timing.","table":{"caption":"Endocrine tumor risk by ATA category","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"mtc-hst","name":"Medullary thyroid carcinoma, highest risk (M918T)","women":{"risk":">95%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["retWells","retWasserman","retGeneReviews"]}},"men":{"risk":">95%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["retWells","retWasserman","retGeneReviews"]}}},{"id":"mtc-h","name":"Medullary thyroid carcinoma, high risk (C634, A883F)","women":{"risk":">95%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["retWasserman","retWells","retActionability"]}},"men":{"risk":">95%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["retWasserman","retWells","retActionability"]}}},{"id":"mtc-mod","name":"Medullary thyroid carcinoma, moderate risk","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pheo-hst","name":"Pheochromocytoma, highest risk","women":{"risk":"50%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["retWells","retWasserman"]}},"men":{"risk":"50%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["retWells","retWasserman"]}}},{"id":"pheo-634","name":"Pheochromocytoma, codon 634","women":{"risk":"88%","relative":"Not established","horizon":"By age 77","citations":{"risk":["retWells","retActionability"]}},"men":{"risk":"88%","relative":"Not established","horizon":"By age 77","citations":{"risk":["retWells","retActionability"]}}},{"id":"pheo-mod","name":"Pheochromocytoma, moderate risk","women":{"risk":"10–50%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["retWells","retWasserman","retActionability"]}},"men":{"risk":"10–50%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["retWells","retWasserman","retActionability"]}}},{"id":"hpth-634","name":"Primary hyperparathyroidism, codon 634","women":{"risk":"20–30%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["retWells","retWasserman","retActionability"]}},"men":{"risk":"20–30%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["retWells","retWasserman","retActionability"]}}},{"id":"hpth-ex10","name":"Primary hyperparathyroidism, codons 609, 611, 618, 620","women":{"risk":"2–12%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["retWells","retWasserman"]}},"men":{"risk":"2–12%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["retWells","retWasserman"]}}},{"id":"hscr","name":"Hirschsprung disease, MEN2A","women":{"risk":"7%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["retWells","retWasserman"]}},"men":{"risk":"7%","relative":"Not established","horizon":"Lifetime estimate","citations":{"risk":["retWells","retWasserman"]}}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Medullary carcinoma is the leading cause of death in MEN2A, curable mainly by thyroidectomy before spread; most MEN2B is diagnosed too late for cure. Unrecognized pheochromocytoma can cause fatal hypertensive crisis in surgery, pregnancy, or delivery.","sources":["retActionability","retWells","retWasserman"]},{"title":"Codon-specific features","text":"Cutaneous lichen amyloidosis or regional itch in 36% of codon 634 carriers (one study). MEN2B adds mucosal neuromas of the lips and tongue, intestinal ganglioneuromatosis with constipation, thick everted eyelids, and a marfanoid build.","sources":["retWells","retGeneReviews"]},{"title":"Treatment if cancer develops","text":"Total thyroidectomy with central neck dissection when ultrasound shows no spread; no radioiodine. Rising markers without visible disease, or stable low-volume disease with marker doubling times over 2 years, do not warrant systemic therapy; kinase inhibitors are for progressive metastatic disease.","sources":["retWells","retWasserman"]},{"title":"Association evidence","text":"ClinGen: definitive for MEN2A and MEN2B, autosomal dominant. About 5–9% of MEN2A arises de novo; about 50–75% of MEN2B arises de novo (GeneReviews and AACR: 50%; ATA 2015: about 75%), so most patients are diagnosed only once cancer is advanced.","sources":["retClingen2a","retClingen2b","retGeneReviews","retWells","retWasserman"]}],"otherGenotype":{"title":"If both copies are affected","text":"Variants on opposite copies: refer to clinical genetics; manage at least by the higher-risk codon. Tandem variants on one copy (V804M with Y806C, S904C, E805K, or Q781R) cause atypical MEN2B with medullary carcinoma at about 20–30 years, some in thyroid-only families. Do not assume the moderate-risk schedule.","sources":["retWells","retWasserman"]},"plans":{}},"RPE65":{"symbol":"RPE65","genotype":"Biallelic","summary":"Biallelic RPE65 variants cause a retinal dystrophy that starts in infancy or childhood with night blindness and reaches legal blindness, usually by early adulthood. Refer early to an inherited retinal disease specialist to assess eligibility for voretigene neparvovec.","table":{"caption":"Vision loss","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"legal-blindness","name":"Legal blindness (US criteria)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"low-vision","name":"Low vision by visual acuity","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"blindness","name":"Blindness by visual acuity","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"night","name":"Reported poor night vision","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"photophobia","name":"Photophobia","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"nystagmus","name":"Nystagmus","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lens","name":"Cataract or other lens opacity","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"erg","name":"Undetectable electroretinogram","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Three overlapping phenotypes: LCA with signs in the first year of life; early-onset severe retinal dystrophy with night blindness in early childhood; juvenile RP from late childhood or adolescence, with central vision into early adulthood. Many reach no light perception by mid-adulthood. Some women with milder disease report unrecovered vision loss in pregnancy, without objective data.","sources":["rpe65GeneReviews","rpe65ClingenAc"]},{"title":"What treatment changes","text":"Voretigene neparvovec supplies working RPE65 to surviving retinal pigment epithelium; it improves dim-light function but cannot restore lost retina. FDA approval 2017, EMA 2018.","sources":["rpe65Luxturna","rpe65Russell","rpe65Aao","rpe65Chung"]},{"title":"Association evidence","text":"ClinGen: recessive retinopathy Definitive (May 2022), dominant Strong (February 2022); adult actionability Strong.","sources":["rpe65Clingen","rpe65ClingenAc"]}],"otherGenotype":{"title":"If one copy is affected","text":"One variant is a carrier state with no expected retinal disease; if a partner also carries one, each child has a 1 in 4 chance of disease. Exception: p.Asp477Gly causes dominant disease with adult-onset night blindness and central vision loss, severe by the fifth to eighth decades, with choroideremia-like atrophy; penetrance is incomplete (one carrier had good vision at 80 years). Arrange a dilated retinal examination; voretigene neparvovec is licensed only for biallelic disease.","sources":["rpe65Hull","rpe65Bowne","rpe65Clingen","rpe65Luxturna"]},"plans":{}},"RYR1":{"symbol":"RYR1","genotype":"Heterozygous MH-causative variant","summary":"An MH-causative RYR1 variant predisposes to a potentially fatal hypermetabolic crisis with volatile anesthetics or succinylcholine. Avoiding both prevents it, and safe alternatives are widely available.","table":{"caption":"Malignant hyperthermia and muscle risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"mh-exposed","name":"MH reaction in carriers given trigger agents","women":{"risk":"29.7%","relative":"Not established","horizon":"After trigger exposure · MH families","citations":{"risk":["ryr1Penetrance"]}},"men":{"risk":"50%","relative":"Not established","horizon":"After trigger exposure · MH families","citations":{"risk":["ryr1Penetrance"]}}},{"id":"mh-per-anesthetic","name":"MH reaction per trigger anesthetic","women":{"risk":"19%","relative":"Not established","horizon":"Per trigger anesthetic · MH families","citations":{"risk":["ryr1Penetrance"]}},"men":{"risk":"31%","relative":"Not established","horizon":"Per trigger anesthetic · MH families","citations":{"risk":["ryr1Penetrance"]}}},{"id":"death-treated","name":"Death in an MH reaction, current care","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"death-untreated","name":"Death in an MH reaction, no dantrolene","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"exertional","name":"Exertional rhabdomyolysis or heat illness","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"muscle","name":"Myalgia, cramps, or raised CK","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Hypercapnia, tachycardia, rigidity, acidosis, hyperkalemia with arrhythmia, rhabdomyolysis, and hyperthermia, usually in the operating room but sometimes early after surgery. Masseter rigidity is often the first sign after succinylcholine.","sources":["mh","ryr1Cpic","ryr1Deaths2008","ryr1Deaths2014","ryr1Complications"]},{"title":"Association evidence","text":"RYR1 variants are found in 60–70% of MHS. EMHG lists 84 pathogenic or likely pathogenic RYR1 variants (October 2026), against 48 reviewed by CPIC in 2019. The trait (about 1 in 2,000 to 1 in 3,000 people) is far more common than reactions because many carriers are never exposed and penetrance is incomplete and variant-dependent. Individual reactions cannot be predicted, so precautions do not depend on these estimates.","sources":["mh","ryr1EmhgVariants","ryr1Cpic","ryr1Penetrance","ryr1UkEpi","ryr1Geisinger"]},{"title":"Treatment if a reaction occurs","text":"Stop triggers, hyperventilate with 100% oxygen, and give dantrolene 2–2.5 mg/kg IV by actual body weight every 10 minutes until PaCO2 is below 6 kPa with normal ventilation and core temperature is falling; an adult may need about 1,200 mg. Stop cooling below 38.5 °C. Monitor at least 24 hours and refer to an MH unit. MHAUS hotline (North America): 800-644-9737.","sources":["ryr1EmhgCrisis","mh","ryr1MhausAgents"]},{"title":"Age","text":"Median age at reaction 12 years in one family study; reactions in older patients were recognized later and graded more severe. Risk may be higher with anesthesia in childhood (unpublished observations).","sources":["ryr1Review","ryr1Complications","ryr1Penetrance","ryr1Cpic"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan above. Two RYR1 variants usually cause a recessive congenital myopathy (multiminicore disease, recessive central core disease, centronuclear myopathy, or congenital fiber-type disproportion), presenting in infancy or childhood with hypotonia, proximal and facial weakness, ptosis, ophthalmoplegia, scapular winging, and sometimes respiratory involvement. These are usually loss-of-function, unlike MHS variants, though a few do both; homozygous p.Arg614Cys produced a stronger contracture response. Refer to neuromuscular medicine, treat as MH susceptible, and plan anesthesia with EMHG guidance for inherited myopathies. Whether a parent carrying one recessive myopathy variant is MH susceptible needs MH unit review.","sources":["ryr1Emqn","ryr1Cpic","ryr1RecessiveFeatures","ryr1Homozygous","ryr1EmhgMyopathy"]},"plans":{}},"RYR2":{"symbol":"RYR2","genotype":"Heterozygous","summary":"Most pathogenic RYR2 variants are gain-of-function and cause CPVT: normal resting ECG and echocardiogram, with polymorphic or bidirectional ventricular tachycardia (VT) on exercise or emotion that can cause syncope or sudden death. Loss-of-function variants cause calcium release deficiency syndrome (CRDS), in which the exercise test is usually normal.","table":{"caption":"Arrhythmic risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"cpvt-phenotype","name":"CPVT phenotype on first evaluation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"syncope","name":"Unexplained syncope","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ltae","name":"Life-threatening arrhythmic event","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"crds","name":"Calcium release deficiency syndrome (loss-of-function variants)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Untreated, about 30% have at least one cardiac arrest and up to 80% syncope; symptoms usually start at 7–12 years, occasionally as late as the fourth decade. Sudden death can be the first event. CPVT causes an estimated 10–15% of sudden cardiac deaths in the young.","sources":["ryr2GeneReviews","ryr2Wilde"]},{"title":"Association evidence","text":"ClinGen: definitive for autosomal dominant CPVT (2021); actionability strong in adults and children. RYR2 explains 60–70% of CPVT (2022 genetic testing consensus) or 50–55% (ClinGen actionability).","sources":["ryr2ClinGen","ryr2Actionability","ryr2Walsh","ryr2Wilde"]},{"title":"Treatment if arrhythmia occurs","text":"In RYR2 CPVT, defibrillator carriers survived all 18 life-threatening events, while 4 of 10 without one died; surgical revision 17% and inappropriate shocks 15% over a median 7.5 years. In a systematic review, 40% of CPVT patients with a defibrillator had an appropriate shock; in two case series, shocks for bidirectional or polymorphic VT almost always failed (71 of 72) while shocks for ventricular fibrillation usually succeeded (66 of 70). In the RYR2 cohort, device therapy ended all 15 VT episodes but only 3 of 6 episodes of unstable fast polymorphic VT.","sources":["ryr2Mazzanti","ryr2Actionability"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan above. No biallelic RYR2 condition is established; ClinGen curates RYR2 only as autosomal dominant, and this plan is not validated for it. Refer to clinical genetics and an inherited arrhythmia center, apply at least the CPVT evaluation, and test both parental lines.","sources":["ryr2ClinGen","ryr2Walsh"]},"plans":{}},"SCN5A":{"symbol":"SCN5A","genotype":"Heterozygous","summary":"Gain-of-function SCN5A variants cause long QT syndrome type 3 (LQT3), with events at rest and in sleep; loss-of-function variants cause Brugada syndrome, conduction disease, sinus node dysfunction, and dilated cardiomyopathy. The two need opposite drug precautions, so the variant type decides the plan.","table":{"caption":"Arrhythmia and heart muscle risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"lqt3-first-event","name":"LQT3: first cardiac event (syncope, cardiac arrest, or sudden death)","women":{"risk":"42%","relative":"Not established","horizon":"By age 40 · before therapy","citations":{"risk":["scn5aPriori"]}},"men":{"risk":"42%","relative":"Not established","horizon":"By age 40 · before therapy","citations":{"risk":["scn5aPriori"]}}},{"id":"lqt3-arrest","name":"LQT3: cardiac arrest or sudden death","women":{"risk":"16%","relative":"Not established","horizon":"By age 40","citations":{"risk":["scn5aPriori"]}},"men":{"risk":"16%","relative":"Not established","horizon":"By age 40","citations":{"risk":["scn5aPriori"]}}},{"id":"lqt3-normal-qtc","name":"LQT3: cardiac arrest or sudden death with QTc 440 ms or less (KCNQ1, KCNH2, and SCN5A pooled) (LQT1–3 pooled)","women":{"risk":"4%","relative":"Not established","horizon":"By age 40","citations":{"risk":["scn5aGoldenberg"]}},"men":{"risk":"4%","relative":"Not established","horizon":"By age 40","citations":{"risk":["scn5aGoldenberg"]}}},{"id":"brugada","name":"Brugada syndrome: major arrhythmic event","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"conduction","name":"Progressive conduction disease or sinus node dysfunction","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dcm","name":"Dilated cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Gain-of-function variants are prominent in LQTS with malignant perinatal presentation; on beta-blockers, 50% of symptomatic LQT3 patients were recurrence-free and 17% died in one registry. In Brugada syndrome, sudden death can be the first sign.","sources":["scn5aWilde","scn5aSchwartz2001","scn5aGeneReviewsBrs"]},{"title":"Association evidence","text":"ClinGen Definitive for SCN5A-related rhythm disorder (2025; LQT3, Brugada syndrome, conduction disorders) and dilated cardiomyopathy 1E (2026). The only definitive Brugada gene of 21 curated, and one of three definitive typical LQTS genes.","sources":["scn5aValidity","scn5aRhythmCuration","scn5aHosseini","scn5aAdler"]},{"title":"Overlap and variant effects","text":"One variant can produce both persistent late current and reduced peak current, giving mixed phenotypes. p.Gly1631Asp is unusually severe; p.Asp1790Gly and p.Glu1784Lys are relatively benign but can combine LQTS, Brugada syndrome, and sinus node dysfunction. In overlap patients, mexiletine does not induce ST elevation, unlike flecainide.","sources":["scn5aRhythmCuration","scn5aWilde","scn5aBalestra"]},{"title":"Polygenic contribution in Brugada syndrome","text":"Common variants explain much of Brugada syndrome and may drive variable expression in carriers. Relatives without the familial variant can still show a drug-induced pattern; routine provocative testing in them is not supported.","sources":["scn5aWilde"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan above. Rare autosomal recessive SCN5A rhythm disease is reported, with no separate risk estimates or pathway; this page may underestimate severity. Refer to an inherited arrhythmia center and offer the parents testing and genetic counseling.","sources":["scn5aRhythmCuration","scn5aWilde"]},"plans":{}},"SDHA":{"symbol":"SDHA","genotype":"Heterozygous","summary":"SDHA raises the risk of paraganglioma, pheochromocytoma, GIST, and renal cancer, with the lowest penetrance of the SDH genes; most carriers never develop a tumor. Guidelines disagree on screening carriers without a family history, so surveillance is a shared decision.","table":{"caption":"Tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"ppgl","name":"Paraganglioma or pheochromocytoma","women":{"risk":"10%","relative":"Not established","horizon":"By age 70","citations":{"risk":["sdhaVanDerTuin"]}},"men":{"risk":"10%","relative":"Not established","horizon":"By age 70","citations":{"risk":["sdhaVanDerTuin"]}}},{"id":"gist","name":"Gastrointestinal stromal tumor","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"renal","name":"Renal cell carcinoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Association evidence","text":"Gene-disease link definitive; ClinGen rates surveillance actionability limited, the lowest of the SDH genes (tied with SDHAF2). Most results are secondary findings: 33 of 37 carriers in one series.","sources":["sdhaClingen","sdhaAc150","sdhaSkefos"]},{"title":"Treatment if a tumor develops","text":"Surgery is the only cure; it is high risk and planned by an experienced multidisciplinary team.","sources":["sdhaAc150"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan above. Two affected copies cause autosomal recessive mitochondrial disease (ClinGen definitive), including Leigh syndrome (moderate), managed by metabolic and neurology specialists. A dominant mitochondrial link for single variants has limited evidence and no clinical action.","sources":["sdhaClingen"]},"plans":{}},"SDHAF2":{"symbol":"SDHAF2","genotype":"Heterozygous","summary":"SDHAF2 predisposes to paragangliomas, mostly multiple and in the head and neck, which rarely secrete catecholamines. Tumors arise almost only after paternal transmission, and data come from very few families.","table":{"caption":"Tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"ppgl-paternal","name":"Paraganglioma or pheochromocytoma, variant inherited from the father","women":{"risk":"87.5%","relative":"Not established","horizon":"At last follow-up · family carriers","citations":{"risk":["sdhaf2Spain"]}},"men":{"risk":"87.5%","relative":"Not established","horizon":"At last follow-up · family carriers","citations":{"risk":["sdhaf2Spain"]}}},{"id":"ppgl-maternal","name":"Paraganglioma or pheochromocytoma, variant inherited from the mother","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hn-pgl","name":"Head and neck paraganglioma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"thoracoabdominal-pgl","name":"Chest or abdominal paraganglioma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pheo","name":"Pheochromocytoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Head and neck tumors are usually benign and slow-growing but harm by local growth into cranial nerves and the skull base; 45.5% of treated patients had complications, mostly vocal cord paralysis (21.2%) and cranial nerve palsy (18.2%). For metastatic paraganglioma in general, about 50% survive 5 years; no SDHAF2-specific survival data.","sources":["sdhaf2Spain","sdhaf2Clingen"]},{"title":"Association evidence","text":"Gene-disease link definitive (ClinGen gene validity, 2021); ClinGen rates surveillance actionability limited, with few reported families; likelihood of disease scored low with poor evidence.","sources":["sdhaf2Validity","sdhaf2Clingen"]},{"title":"Treatment if a tumor develops","text":"After removal of a secreting tumor, blood pressure instability and hypoglycemia can occur; severe hypoglycemia in 13%, usually 2–4.5 hours after resection.","sources":["sdhaf2Clingen"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan above. No biallelic SDHAF2 condition or pathway is described. Refer to clinical genetics; this page covers one affected copy.","sources":["sdhaf2Clingen"]},"plans":{}},"SDHB":{"symbol":"SDHB","genotype":"Heterozygous","summary":"SDHB predisposes to paragangliomas and pheochromocytomas, with the highest metastatic risk of the SDH genes. About a quarter of carriers found through family testing develop a tumor by age 60 years; renal cancer and GIST also occur.","table":{"caption":"Tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"ppgl","name":"Paraganglioma or pheochromocytoma","women":{"risk":"35%","relative":"Not established","horizon":"By age 80","citations":{"risk":["sdhbDavidoff"]}},"men":{"risk":"35%","relative":"Not established","horizon":"By age 80","citations":{"risk":["sdhbDavidoff"]}}},{"id":"metastatic","name":"Metastatic paraganglioma or pheochromocytoma","women":{"risk":"4.2%","relative":"Not established","horizon":"By age 60","citations":{"risk":["sdhbAndrews"]}},"men":{"risk":"4.2%","relative":"Not established","horizon":"By age 60","citations":{"risk":["sdhbAndrews"]}}},{"id":"renal","name":"Renal cell carcinoma","women":{"risk":"4.2%","relative":"Not established","horizon":"By age 60","citations":{"risk":["sdhbAndrews"]}},"men":{"risk":"4.2%","relative":"Not established","horizon":"By age 60","citations":{"risk":["sdhbAndrews"]}}},{"id":"gist","name":"Gastrointestinal stromal tumor","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"thyroid","name":"Thyroid tumor","women":{"risk":"1.5%","relative":"Not established","horizon":"By age 60","citations":{"risk":["sdhbAndrews"]}},"men":{"risk":"1.5%","relative":"Not established","horizon":"By age 60","citations":{"risk":["sdhbAndrews"]}}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Highest disease-specific morbidity and mortality of the hereditary paraganglioma genes. Tumors are often less differentiated and may secrete little or only dopamine, so they can grow unnoticed.","sources":["sdhbTaieb","sdhbAc150"]},{"title":"Why surveillance","text":"In 181 Australian carriers followed a median 6.0 years, surveillance-detected tumors were smaller than in probands (median 27 mm against 45 mm); 10-year overall survival 100% for non-probands with surveillance-detected tumors against 79% for probands. The schedule rests mainly on expert consensus.","sources":["sdhbSurveillance","sdhbAc150","sdhbAmar"]},{"title":"Treatment if a tumor develops","text":"Surgery is the only cure, planned by an experienced multidisciplinary team. Cortical-sparing adrenalectomy is considered because tumors can be bilateral; severe hypoglycemia follows resection in about 13%.","sources":["sdhbAc150","sdhbTaieb"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan above. Two affected copies cause autosomal recessive mitochondrial disease (ClinGen definitive), a childhood metabolic and neurologic disorder managed by specialists. The tumor risks and plan here do not apply.","sources":["sdhbClingen"]},"plans":{}},"SDHC":{"symbol":"SDHC","genotype":"Heterozygous","summary":"SDHC predisposes to paragangliomas, mostly in the head and neck, with low metastatic risk. Penetrance is poorly defined: about a quarter by age 60 years (95% CI 0–57%), from few carriers.","table":{"caption":"Tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"ppgl","name":"Paraganglioma or pheochromocytoma","women":{"risk":"25%","relative":"Not established","horizon":"By age 60","citations":{"risk":["sdhcAndrews"]}},"men":{"risk":"25%","relative":"Not established","horizon":"By age 60","citations":{"risk":["sdhcAndrews"]}}},{"id":"renal","name":"Renal cell carcinoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"gist","name":"Gastrointestinal stromal tumor","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Mainly parasympathetic head and neck paragangliomas, usually slow-growing.","sources":["sdhcAc150"]},{"title":"Association evidence","text":"Gene-disease link definitive; ClinGen rates surveillance actionability moderate, below SDHB.","sources":["sdhcClingen","sdhcAc150","sdhcAndrews"]},{"title":"Treatment if a tumor develops","text":"Surgery is the only cure; it is high risk and planned by an experienced multidisciplinary team.","sources":["sdhcAc150"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan above. No established condition: ClinGen rates SDHC and mitochondrial disease as no known disease relationship. Refer to clinical genetics; this page covers one affected copy.","sources":["sdhcClingen"]},"plans":{}},"SDHD":{"symbol":"SDHD","genotype":"Heterozygous","summary":"Inherited from the father, SDHD predisposes to paragangliomas, mostly in the head and neck and often multiple. Inherited from the mother, it rarely causes tumors, so the parent of origin decides the plan.","table":{"caption":"Tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"ppglPaternal","name":"Paraganglioma or pheochromocytoma, inherited from the father","women":{"risk":"43%","relative":"Not established","horizon":"By age 60","citations":{"risk":["sdhdAndrews"]}},"men":{"risk":"43%","relative":"Not established","horizon":"By age 60","citations":{"risk":["sdhdAndrews"]}}},{"id":"ppglMaternal","name":"Paraganglioma or pheochromocytoma, inherited from the mother","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"renal","name":"Renal cell carcinoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"gist","name":"Gastrointestinal stromal tumor","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Mostly slow-growing head and neck paragangliomas, but multiple and bilateral tumors are common and disease can be locally aggressive, at a young age or late in its course.","sources":["sdhdTaieb","sdhdAc150"]},{"title":"Treatment if a tumor develops","text":"A high-volume center balances surgery, radiotherapy, and observation; surgery is high risk and planned by an experienced multidisciplinary team.","sources":["sdhdTaieb","sdhdAc150"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan above. Recessive mitochondrial disease from two SDHD copies has limited evidence (ClinGen) and no established pathway. Refer to clinical genetics; this page covers one affected copy.","sources":["sdhdClingen"]},"plans":{}},"SERPINA1":{"symbol":"SERPINA1","genotype":"Biallelic severe deficiency alleles","summary":"Two severe-deficiency alleles, most often PI*ZZ, cause emphysema from mid-adulthood, strongly driven by smoking, and liver fibrosis that rises after age 50 years. Never smoking is the most effective protection.","table":{"caption":"Lung and liver risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"copd","name":"COPD","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"emphysema","name":"Emphysema","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"bronchiectasis","name":"Bronchiectasis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"fibrosis","name":"Significant liver fibrosis (F2 or worse)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"advanced-fibrosis","name":"Advanced liver fibrosis (F3–F4)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cirrhosis","name":"Cirrhosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"liver-cancer","name":"Primary liver cancer","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"panniculitis","name":"Necrotizing panniculitis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"vasculitis","name":"Granulomatosis with polyangiitis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Lung disease is the main cause of death, followed by liver complications. Smoking is the dominant modifier.","sources":["serpina1ClinGen","serpina1GeneReviews"]},{"title":"Underdiagnosis","text":"About 1–2% of people with COPD have AATD. In UK Biobank, 0.17% of COPD cases were PI*ZZ and only 6.4% of PI*ZZ participants had an AATD diagnosis. A panel finding is often the first diagnosis.","sources":["serpina1Nakanishi","serpina1ClinGen"]},{"title":"Genotypes covered","text":"PI*ZZ accounts for more than 90% of severe AATD; the table uses PI*ZZ data. Null/null carries emphysema risk close to 100% in older series; PI*SZ carries lower lung risk. Liver disease is generally restricted to ZZ and SZ; PI*SS carries no clear excess.","sources":["serpina1ClinGen","serpina1A1f"]},{"title":"Treatment if disease develops","text":"Augmentation is lifelong weekly intravenous pooled human AAT. Lung volume reduction surgery is not recommended; lung transplantation is an option at end stage. Liver transplantation is the only effective treatment for severe liver disease and restores AAT levels; adult 5-year survival was 80% in one series.","sources":["serpina1A1f","serpina1ClinGen","serpina1GeneReviews"]}],"otherGenotype":{"title":"If one copy is affected","text":"PI*MZ (about 2–4% of European ancestry) does not cause AATD but is not neutral; the biallelic risks and plan on this page do not apply. COPD OR 2.31 (95% CI 1.60–3.35) versus PI*MM in a meta-analysis, 1.61 (95% CI 0.92–2.81) smoking-adjusted. UK Biobank: FEV1/FVC below 0.7 OR 1.1, or 1.2 above 20 pack-years; cirrhosis OR 1.5 (95% CI 1.2–1.8). Case-control: cirrhosis with fatty liver disease or alcohol misuse, adjusted OR 7.3 (95% CI 2.2–24.8) and 5.8 (95% CI 2.9–11.7). Obesity and diabetes were the main factors associated with raised liver stiffness. Support never smoking, manage alcohol, weight, and diabetes, and test relatives; no augmentation, even with COPD. The S allele: no link with fatty-liver cirrhosis, borderline with alcohol-related cirrhosis (adjusted OR 1.47, 95% CI 0.99–2.19).","sources":["serpina1Hersh","serpina1Nakanishi","serpina1Strnad","serpina1Schneider","serpina1A1f"]},"plans":{}},"SERPINC1":{"symbol":"SERPINC1","genotype":"Heterozygous","summary":"One SERPINC1 variant lowers antithrombin and raises the odds of a first VTE about 16-fold, one of the most severe inherited thrombophilias. Heparin-binding-site variants carry lower risk.","table":{"caption":"Venous thromboembolism risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"first-vte","name":"First VTE, per year","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"recurrence","name":"Recurrent VTE after a first VTE, per year off anticoagulation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pregnancy-fh","name":"Pregnancy-associated VTE, per pregnancy, family history of VTE","women":{"risk":"16.6%","relative":"Not established","horizon":"Per pregnancy","citations":{"risk":["serpinc1Croles2017"]}},"men":null},{"id":"pregnancy-nofh","name":"Pregnancy-associated VTE, per pregnancy, no family history","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"coc","name":"VTE during combined oral contraceptive use, per year","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"hrt","name":"VTE during menopausal hormone therapy","women":{"risk":"Not established","relative":"Not established"},"men":null}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Type I deficiency often causes early thrombosis with many affected relatives. Management rests on expert opinion.","sources":["serpinc1Pabinger2019"]},{"title":"Frequency","text":"Median prevalence 2.2% among patients with VTE; probably underdiagnosed because activity assays miss some variants.","sources":["serpinc1Ash2023","serpinc1Budapest3"]},{"title":"Variant type and risk","text":"Type I variants reduce antithrombin; type II impair function. Molecular testing refines risk and finds variants activity assays miss. ClinGen: Definitive, semidominant.","sources":["serpinc1Budapest3","serpinc1Isth","serpinc1ClingenValidity"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the heterozygous plan. Two variants are rare and mostly heparin-binding-site variants, especially Budapest 3 (p.Leu131Phe), common in parts of Europe, particularly the Roma population. Activity is below 20%, with juvenile, recurrent VTE, heparin resistance, vena cava anomalies, and obstetric complications. Refer to a hematology center with antithrombin expertise; the heterozygous plan does not apply.","sources":["serpinc1Budapest3"]},"plans":{}},"SGCD":{"symbol":"SGCD","genotype":"Biallelic","summary":"Delta-sarcoglycanopathy (LGMD R6) is a usually severe recessive muscular dystrophy starting in childhood, often ending independent walking in the early teens. Heart and breathing involvement can be silent.","table":{"caption":"Muscle, heart, and breathing outcomes","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"weakness","name":"Muscle weakness","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"wheelchair","name":"Loss of independent walking","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cardiac","name":"Cardiomyopathy or rhythm abnormality","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dcm","name":"Dilated cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ventilation","name":"Respiratory failure needing ventilation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Beta- and delta-sarcoglycanopathy are the more severe subtypes, with the most frequent and severe heart disease. Milder, later-onset courses occur when some protein is still made. No deaths were recorded in the largest cohort, but follow-up was short.","sources":["sgcdAlonso","sgcdBorland"]},{"title":"Association evidence","text":"ClinGen: Definitive for autosomal recessive limb-girdle muscular dystrophy (2024). Ultra-rare, mostly in consanguineous families. Complete loss of all four sarcoglycans on biopsy is common.","sources":["sgcdClinGenLgmd","sgcdAlonso","sgcdBorland"]},{"title":"Treatment if disease develops","text":"No disease-modifying treatment. Care is supportive and multidisciplinary: rehabilitation, cardiac medicines, non-invasive ventilation, and management of contractures and scoliosis.","sources":["sgcdBorland","sgcdAan","sgcdEnmc"]}],"otherGenotype":{"title":"If one copy is affected","text":"A carrier state: the plan does not apply, and the result alone needs no cardiac or muscle surveillance. ClinGen rates a dominant DCM link (DCM 1L) Limited (2026): no excess of SGCD variants in DCM (p = 0.74), and the first reported variant, p.Ser151Ala, is too common to explain disease. Evaluate any cardiomyopathy on clinical grounds without attributing it to SGCD. Offer partner carrier testing when planning a pregnancy, especially if partners are related, and carrier testing to relatives.","sources":["sgcdClinGenDcm","sgcdAlonso","sgcdClinGenLgmd"]},"plans":{}},"SLC40A1":{"symbol":"SLC40A1","genotype":"Heterozygous loss- or gain-of-function variant","summary":"Loss-of-function variants cause ferroportin disease: high ferritin with normal or low transferrin saturation, macrophage and spleen iron, usually mild organ damage, and anemia with standard phlebotomy. Gain-of-function variants cause SLC40A1-related hemochromatosis, which behaves and is treated like HFE hemochromatosis.","table":{"caption":"Iron overload and organ involvement","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"fd-phenotype","name":"Ferroportin disease phenotype (transferrin saturation 45% or below)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ferritin","name":"Raised ferritin","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"fibrosis","name":"Significant fibrosis or cirrhosis on biopsy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cirrhosis","name":"Cirrhosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"diabetes","name":"Diabetes","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"liver-cancer","name":"Primary liver cancer","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"anemia","name":"Anemia during phlebotomy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Ferroportin disease is usually milder than HFE hemochromatosis. BSH: no significant organ damage; the meta-analysis and registry: fibrosis in a minority, mostly with high saturation, older age, or another liver condition. Gain-of-function disease has more complications.","sources":["slc40a1Pietrangelo","ironReferral","slc40a1Mayr","slc40a1Registry","slc40a1Uguen"]},{"title":"Telling the two disorders apart","text":"Ferroportin disease: iron in spleen, liver, and bone marrow macrophages; on MRI, spleen, spine, and liver. Gain-of-function disease: liver-only parenchymal iron with spared macrophages and low or normal spleen iron, like HFE disease.","sources":["slc40a1Pietrangelo","slc40a1Easl","slc40a1Uguen"]},{"title":"Association evidence","text":"ClinGen: Definitive for hemochromatosis type 4 (autosomal dominant), as a single entity (2026). BIOIRON (2022) keeps gain-of-function disease within hemochromatosis, excludes ferroportin disease, and drops the 4A and 4B labels. p.Val162del is the variant most consistently linked to iron overload.","sources":["slc40a1Clingen","slc40a1Bioiron","slc40a1Uguen"]},{"title":"Frequency","text":"Among the commonest causes of genetic hyperferritinemia in all ancestries; predicted carrier rate about 1 in 1373 across both disorders, an estimate driven by two variants common in African populations (p.Asp270Val and p.Arg371Trp) whose link to iron overload is uncertain.","sources":["slc40a1Pietrangelo"]}],"otherGenotype":{"title":"If both copies are affected","text":"No separate pathway is established; published series describe heterozygous patients. Manage two SLC40A1 variants with an iron-disorders specialist, using this plan as a starting point.","sources":["slc40a1Clingen","slc40a1Uguen"]},"plans":{}},"SMAD3":{"symbol":"SMAD3","genotype":"Heterozygous","summary":"Loeys-Dietz syndrome type 3 (aneurysms-osteoarthritis syndrome): aortic root aneurysm and dissection, often at mildly enlarged diameters, arterial aneurysms and tortuosity, and early-onset osteoarthritis. About half of carriers have an aortic event by age 54 years, later than with TGFBR1 or TGFBR2, usually dissection rather than planned surgery.","table":{"caption":"Aortic, arterial, and joint risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"taad","name":"Thoracic aortic aneurysm or dissection, any diagnosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"aortic-event","name":"Aortic dissection or aortic aneurysm surgery","women":{"risk":"50%","relative":"Not established","horizon":"By age 54","citations":{"risk":["smad3Hostetler"]}},"men":{"risk":"50%","relative":"Not established","horizon":"By age 54","citations":{"risk":["smad3Hostetler"]}}},{"id":"root","name":"Aortic root aneurysm","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"arterial","name":"Aneurysm of other thoracic or abdominal arteries","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cerebrovascular","name":"Cerebrovascular abnormality, of 16 imaged","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"osteoarthritis","name":"Early-onset osteoarthritis or osteochondritis dissecans","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Association evidence","text":"ClinGen: definitive for HTAAD, category A; sufficient evidence for haploinsufficiency. About 2% of familial thoracic aortic aneurysm in one series.","sources":["smad3Renard","smad3ClinGen","smad3Regalado2011"]},{"title":"Treatment if the aorta enlarges","text":"Valve-sparing replacement of the root and whole ascending aorta at an experienced center; open repair over endovascular for thoracoabdominal aneurysm. Interventions are common after dissection.","sources":["smad3AccLds"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic SMAD3 condition is established; IPO8 is the only recessive LDS gene. Refer to clinical genetics and an aortic center, use at least this surveillance under their direction, and test both parental lines.","sources":["smad3GeneReviews"]},"plans":{}},"SMAD4":{"symbol":"SMAD4","genotype":"Heterozygous variant associated with juvenile polyposis/HHT","summary":"SMAD4-associated juvenile polyposis increases colorectal and gastric cancer risk and can overlap with hereditary hemorrhagic telangiectasia (HHT). Arrange both gastrointestinal surveillance and HHT evaluation, including for silent vascular malformations. Specific variants cause Myhre syndrome and require a different pathway.","table":{"caption":"Cancer and vascular risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"any","name":"Any cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"gastric","name":"Gastric cancer","women":{"risk":"Not established","relative":"Not quantified","horizon":"Age-specific estimate","citations":{"risk":["smad4Blatter","smad4Singh"]}},"men":{"risk":"Not established","relative":"Not quantified","horizon":"Age-specific estimate","citations":{"risk":["smad4Blatter","smad4Singh"]}}},{"id":"hht","name":"Any HHT feature","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"pavm","name":"Pulmonary AVM","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"liver-vm","name":"Liver AVM","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"brain-vm","name":"Brain AVM","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}},{"id":"aorta","name":"Thoracic aortopathy","women":{"risk":"Not established","relative":"Not quantified"},"men":{"risk":"Not established","relative":"Not quantified"}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"Anemia was reported in 41 of 71 SMAD4 index patients (58%) versus 14 of 55 BMPR1A index patients (26%) in the European series. Extensive gastric polyposis can require gastrectomy. Vascular and aortic abnormalities may be clinically silent; the 34-person review included one fatal aortic dissection.","sources":["smad4Blatter","smad4Wain"]},{"title":"Myhre syndrome","text":"Myhre syndrome is associated with specific gain-of-function variants, often de novo. Features can include short stature, developmental differences, hearing loss, joint restriction and cardiovascular, airway or gastrointestinal stenosis. Congenital heart defects occurred in 7 of 12 patients (58%) in one series. Neoplasms have been reported in other cases, but these observations do not establish a cancer-risk estimate. Multidisciplinary specialist care is needed.","sources":["smad4Myhre","smad4Clingen"]},{"title":"Association evidence","text":"ClinGen lists definitive associations for JPS/HHT (2023) and Myhre syndrome (2025), and a disputed pulmonary arterial hypertension association (2022). Adult actionability was rated moderate for HHT and juvenile polyposis in 2022. Aortic assessment is supported by small clinical series rather than a validated gene-specific surveillance interval.","sources":["smad4Wain","smad4Heald","smad4Clingen"]}],"otherGenotype":{"title":"If both copies are affected","text":"If two SMAD4 variants are reported, refer to clinical genetics to confirm their classification, phase and constitutional versus tumor-only origin. No established constitutional biallelic risk estimate or separate care pathway was identified in the sources reviewed. Do not double the heterozygous risks. Continue care indicated by an established JPS/HHT or Myhre diagnosis while the result is clarified.","sources":["smad4Wain","smad4Clingen"]},"plans":{}},"SMAD9":{"symbol":"SMAD9","genotype":"Heterozygous","summary":"An uncommon cause of heritable pulmonary arterial hypertension (PAH), reported in roughly 15–25 patients, with unknown but incomplete penetrance. Screening follows guidance for all PAH-causing variants, based on BMPR2 data.","table":{"caption":"Pulmonary arterial hypertension risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"pah","name":"Pulmonary arterial hypertension","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Association evidence","text":"ClinGen: Definitive (2021); one of 12 definitive genes on the 2024 World Symposium list. Genetic evidence is modest (7.3 of 12 points; 9.6 in another scoring) with experimental support. Proposed mechanism: loss of function in the BMP pathway downstream of BMPR2. No ClinGen actionability curation exists.","sources":["smad9ClinGen","smad9Welch","smad9Wsph"]},{"title":"Treatment if PAH develops","text":"Diagnosis needs right heart catheterization at a PH centre, which sets risk-based therapy. No SMAD9-specific treatment evidence exists.","sources":["smad9Esc"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic SMAD9 condition is established, and this plan was not designed for it. Refer to clinical genetics and a PH centre.","sources":["smad9ClinGen","smad9Welch"]},"plans":{}},"SMARCA4":{"symbol":"SMARCA4","genotype":"Heterozygous loss-of-function variant","summary":"A truncating or deleting variant gives women a high risk of small cell carcinoma of the ovary, hypercalcemic type (SCCOHT), an aggressive cancer of young women, and infant carriers a risk of rhabdoid tumors. Men carry no ovarian risk but pass the variant on.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"sccoht","name":"Small cell carcinoma of the ovary, hypercalcemic type","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"rhabdoid","name":"Rhabdoid tumors, infancy and early childhood","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"uterine-sarcoma","name":"SMARCA4-deficient uterine sarcoma","women":{"risk":"Not established","relative":"Not established"},"men":null}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Rhabdoid tumors in infancy have 5-year survival of about 10–30%.","sources":["smarca4Tischkowitz","smarca4Actionability"]},{"title":"Association evidence","text":"More than 95% of SCCOHT tumors carry SMARCA4 inactivation. ClinGen rates actionability limited because the benefit of surveillance and surgery is unproven.","sources":["smarca4Tischkowitz","smarca4Pdq","smarca4Actionability"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic condition is described. SCCOHT and rhabdoid tumors arise when the second copy is lost in the tumor.","sources":["smarca4GeneReviews","smarca4Tischkowitz"]},"plans":{}},"SMARCB1":{"symbol":"SMARCB1","genotype":"Heterozygous","summary":"Depending on the variant, one SMARCB1 copy causes rhabdoid tumor predisposition, a risk to infants, or schwannomatosis: multiple painful benign nerve sheath tumors, usually after age 30 years, with a small risk of meningioma and malignant change.","table":{"caption":"Tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"schwannomas","name":"Schwannomatosis: multiple schwannomas","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"meningioma","name":"Meningioma, in SMARCB1-related schwannomatosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mpnst","name":"Malignant peripheral nerve sheath tumor","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"rhabdoid","name":"Rhabdoid tumors, infancy and early childhood","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Schwannomas are benign, but chronic neuropathic pain can be disabling and is linked to anxiety and depression.","sources":["smarcb1GeneReviewsSwn","smarcb1Ern"]},{"title":"Treatment if disease develops","text":"Bevacizumab may be considered in specialist review for multiple rapidly enlarging inoperable tumors.","sources":["smarcb1Ern","smarcb1GeneReviewsSwn"]},{"title":"Association evidence","text":"Established in GeneReviews, ERN GENTURIS, and the 2022 criteria. ClinGen actionability judged the adult rhabdoid evidence insufficient to score.","sources":["smarcb1GeneReviewsSwn","smarcb1Ern","smarcb1Criteria","smarcb1Actionability"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic condition is described. Tumors arise when the second copy is lost in the tumor; schwannomas also need a separate NF2 change.","sources":["smarcb1Kehrer"]},"plans":{}},"STK11":{"symbol":"STK11","genotype":"Heterozygous","summary":"Peutz-Jeghers syndrome: hamartomatous polyps that can cause small bowel intussusception, and high risks of breast, gastrointestinal, and pancreatic cancer. Published risks vary widely and are probably overestimated by how families were found.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"all","name":"All cancers","women":{"risk":"37–85%","relative":"Not established","horizon":"By age 70","citations":{"risk":["stk11Predidf","stk11Hearle"]}},"men":{"risk":"18–85%","relative":"Not established","horizon":"By age 70","citations":{"risk":["stk11Predidf","stk11Hearle"]}}},{"id":"breast","name":"Breast cancer","women":{"risk":"14.5–45%","relative":"Not established","horizon":"By age 70","citations":{"risk":["stk11Predidf","stk11Hearle"]}},"men":{"risk":"Not established","relative":"Not established"}},{"id":"gi","name":"Any gastrointestinal cancer","women":{"risk":"51–57%","relative":"Not established","horizon":"By age 70","citations":{"risk":["stk11Hearle","stk11VanLier"]}},"men":{"risk":"51–57%","relative":"Not established","horizon":"By age 70","citations":{"risk":["stk11Hearle","stk11VanLier"]}}},{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"4.7%","relative":"Not established","horizon":"By age 70","citations":{"risk":["stk11Predidf"]}},"men":{"risk":"4.7%","relative":"Not established","horizon":"By age 70","citations":{"risk":["stk11Predidf"]}}},{"id":"gastric","name":"Gastric cancer","women":{"risk":"29%","relative":"Not established","horizon":"By age 64","citations":{"risk":["stk11Giardiello"]}},"men":{"risk":"29%","relative":"Not established","horizon":"By age 64","citations":{"risk":["stk11Giardiello"]}}},{"id":"small-bowel","name":"Small bowel cancer","women":{"risk":"1.7%","relative":"Not established","horizon":"By age 70","citations":{"risk":["stk11Predidf"]}},"men":{"risk":"1.7%","relative":"Not established","horizon":"By age 70","citations":{"risk":["stk11Predidf"]}}},{"id":"pancreatic","name":"Pancreatic cancer","women":{"risk":"4.5–26%","relative":"Not established","horizon":"By age 70","citations":{"risk":["stk11Predidf","stk11Korsse"]}},"men":{"risk":"4.5–26%","relative":"Not established","horizon":"By age 70","citations":{"risk":["stk11Predidf","stk11Korsse"]}}},{"id":"lung","name":"Lung cancer","women":{"risk":"7–17%","relative":"Not established","horizon":"By age 70","citations":{"risk":["stk11Lung"]}},"men":{"risk":"7–17%","relative":"Not established","horizon":"By age 70","citations":{"risk":["stk11Lung"]}}},{"id":"ovarian","name":"Ovarian cancer","women":{"risk":"1.4%","relative":"Not established","horizon":"By age 70","citations":{"risk":["stk11Predidf"]}},"men":null},{"id":"cervical","name":"Cervical adenocarcinoma","women":{"risk":"7.7%","relative":"Not established","horizon":"By age 70","citations":{"risk":["stk11Predidf"]}},"men":null},{"id":"uterine","name":"Uterine cancer","women":{"risk":"9%","relative":"Not established","horizon":"By age 64","citations":{"risk":["stk11Giardiello"]}},"men":null},{"id":"testicular","name":"Sertoli cell testicular tumors","women":null,"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"In 133 Dutch patients, mortality HR 3.50 (95% CI 2.57–4.75) versus the general population; 42 died at a median age of 45 years, two thirds from cancer. Excess mortality was also found in 2026, especially among young women.","sources":["stk11VanLier","stk11Predidf"]},{"title":"Polyps and intussusception","text":"Polyps are mainly in the small bowel. Intussusception risk is about 44% by age 10 years and 50% by 20 years, higher with polyps of 15 mm or more. Up to 40% with laparotomy before age 18 years need another within 5 years.","sources":["stk11Ehtg"]},{"title":"Association evidence","text":"ClinGen: Definitive. Surveillance benefit for breast, pancreas, and gynecologic organs is unproven; most schedules are expert consensus.","sources":["stk11Clingen","stk11Ehtg","stk11Predidf"]}],"otherGenotype":{"title":"If both copies are affected","text":"PJS is described only with one affected copy. Refer two reported variants to clinical genetics to confirm the genotype; do not assume the risks change.","sources":["stk11Ehtg","stk11Clingen"]},"plans":{}},"TCAP":{"symbol":"TCAP","genotype":"Biallelic","summary":"Biallelic TCAP variants cause limb-girdle muscular dystrophy R7 (LGMD2G): slowly progressive weakness of the hips, thighs, and lower legs, usually beginning in childhood or adolescence. A single variant, the more common panel result, is a carrier finding; the risks and plan on this page do not apply to it.","table":{"caption":"Muscle, heart, and breathing risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"weakness","name":"Progressive limb-girdle weakness","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"walking-aids","name":"Need for walking aids","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cardiac","name":"Cardiac involvement","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"respiratory","name":"Respiratory involvement","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Usually slowly progressive and usually spares breathing; cardiac involvement reported in a subset. Severity varies within and between families; asymmetry occurred in more than 20% of Bulgarian patients.","sources":["tcapGaviraghi","tcapChamova","tcapMoreira"]},{"title":"Association evidence","text":"ClinGen: Definitive for autosomal recessive limb-girdle muscular dystrophy (August 14, 2024). Not on the ACMG secondary findings list.","sources":["tcapClingenLgmd","tcapMoreira"]},{"title":"Treatment","text":"No disease-modifying treatment. Supportive care: weight control, physical therapy and stretching against contractures, mobility aids, orthopedic care, respiratory support when indicated, and cardiac monitoring as cardiology advises.","sources":["tcapGeneReviews","tcapAan"]}],"otherGenotype":{"title":"If one copy is affected","text":"A carrier of LGMD R7; no muscular dystrophy. ClinGen rates dilated cardiomyopathy Limited (April 18, 2025) and hypertrophic cardiomyopathy Disputed (September 14, 2022), and TCAP is an uncommon cause of cardiomyopathy. Do not start TCAP-specific cardiac surveillance or cascade testing for cardiomyopathy; if relatives have cardiomyopathy, standard family screening applies. Offer the partner carrier testing; 2% of newborns in one Bulgarian region carried p.Trp25*.","sources":["tcapClingenDcm","tcapClingenHcm","tcapAlaei","tcapChamova","tcapHfsa"]},"plans":{}},"TFR2":{"symbol":"TFR2","genotype":"Biallelic","summary":"Biallelic TFR2 variants load iron earlier than HFE hemochromatosis, usually evident in the third decade, with severity between HFE and juvenile disease. Phlebotomy to target prevents complications; assess the heart at a lower threshold than in HFE disease.","table":{"caption":"Iron overload and organ involvement","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"biochemical","name":"Biochemical iron overload","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"liver","name":"Liver fibrosis or cirrhosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"arthropathy","name":"Arthropathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"diabetes","name":"Diabetes","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hypogonadism","name":"Hypogonadism","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cardiomyopathy","name":"Cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"liver-cancer","name":"Primary liver cancer","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Fatigue, abdominal pain, hepatomegaly, joint pain, and skin pigmentation in the third decade; cirrhosis, diabetes, hypogonadism, and cardiomyopathy in older adults.","sources":["tfr2GeneReviews"]},{"title":"Association evidence","text":"ClinGen: Definitive for hemochromatosis type 3, autosomal recessive (August 22, 2025). BIOIRON groups it with HJV, HAMP, and gain-of-function SLC40A1 as non-HFE hemochromatosis.","sources":["tfr2Clingen","tfr2Bioiron","tfr2Easl"]},{"title":"Treatment if liver disease develops","text":"Endoscopic variceal surveillance, non-selective beta-blockers, and ascites management, as for other causes.","sources":["tfr2GeneReviews","tfr2Easl"]}],"otherGenotype":{"title":"If one copy is affected","text":"A carrier state; no guideline recommends monitoring or treatment. Digenic disease (HFE C282Y with one TFR2, HJV, or HAMP variant) is recognized but needs strict proof of pathogenicity. Check iron studies under usual care; refer to an iron-disorders specialist if transferrin saturation and ferritin are raised or the patient also carries HFE C282Y. If a partner also carries a TFR2 variant, each child has a 25% chance of disease.","sources":["tfr2Bioiron","tfr2Easl","tfr2GeneReviews"]},"plans":{}},"TGFB2":{"symbol":"TGFB2","genotype":"Heterozygous loss-of-function variant","summary":"TGFB2 loss-of-function variants cause Loeys-Dietz syndrome type 4: aortic root aneurysm and dissection, with intracranial aneurysm and mitral valve disease in some families. The aortic course appears milder than with TGFBR1, TGFBR2, or SMAD3, with incomplete penetrance, so surgical thresholds are less aggressive.","table":{"caption":"Aortic and arterial risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"taad","name":"Thoracic aortic aneurysm or dissection, any diagnosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"root","name":"Aortic root aneurysm","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dissection","name":"Aortic dissection","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cerebrovascular","name":"Cerebrovascular disease (intracranial aneurysm or hemorrhage)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mitral","name":"Mitral valve prolapse","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Data limited to family series. Dissections in mid-adult life; cerebrovascular events caused deaths in the index families.","sources":["tgfb2Boileau","tgfb2AccLds","tgfb2EscLds"]},{"title":"Association evidence","text":"ClinGen: Definitive for familial thoracic aortic aneurysm and dissection; HTAD category A. Haploinsufficient Tgfb2 mice develop aortic root aneurysm.","sources":["tgfb2ClinGen","tgfb2Renard","tgfb2Lindsay"]},{"title":"Treatment if the aorta enlarges","text":"Valve-sparing replacement of the root and whole ascending aorta at an experienced center; open repair preferred over endovascular for thoracoabdominal aneurysm.","sources":["tgfb2AccLds"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic TGFB2 condition is established; TGFB2-related LDS is autosomal dominant. Refer to clinical genetics and an aortic center, apply at least the surveillance above under their direction, and offer testing along both parental lines.","sources":["tgfb2GeneReviews"]},"plans":{}},"TGFB3":{"symbol":"TGFB3","genotype":"Heterozygous","summary":"TGFB3 variants cause Loeys-Dietz syndrome type 5: Marfan- and LDS-like skeletal features with a later, less penetrant aortic course than other LDS genes. About 3 in 10 carriers have aortic dilation, dissections mostly in mid-adult life (earliest at 30 years in published cohorts), and the surgical threshold is 5.0 cm, as in Marfan syndrome.","table":{"caption":"Aortic, arterial, and heart risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"dilation","name":"Aortic dilation (Z-score above 2)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dissection","name":"Aortic dissection","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"arterial","name":"Aneurysm of other arteries","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"tortuosity","name":"Arterial tortuosity","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mitral","name":"Mitral valve prolapse","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"arvc","name":"Arrhythmogenic right ventricular cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"No deaths in the consortium cohort and none from cardiovascular or pregnancy causes in the Dutch-French cohort. In the index family series, median age at death was 56 years (range 40–80 years), from descending or abdominal dissection and rupture and one cerebral aneurysm dissection.","sources":["tgfb3Lim","tgfb3Marsili","tgfb3BertoliAvella"]},{"title":"Association evidence","text":"ClinGen rated familial thoracic aortic aneurysm Limited in 2016, before most cohorts were published. ClinGen actionability, ACC/AHA, ESC, and GeneReviews treat TGFB3 as an LDS gene with its own threshold.","sources":["tgfb3ClinGen","tgfb3Renard","tgfb3AccLds"]},{"title":"Treatment if the aorta enlarges","text":"Valve-sparing replacement of the root and whole ascending aorta at an experienced center; open repair preferred over endovascular for thoracoabdominal aneurysm.","sources":["tgfb3AccLds"]}],"otherGenotype":{"title":"If both copies are affected","text":"Very rare. One homozygous patient was more severely affected than heterozygous relatives, and a child with a homozygous exon 2–7 deletion had severe LDS with Marfan-like features. No established pathway: refer to clinical genetics and an aortic center, apply at least the surveillance above, and offer testing along both parental lines.","sources":["tgfb3Marsili","tgfb3Megarbane"]},"plans":{}},"TGFBR1":{"symbol":"TGFBR1","genotype":"Heterozygous","summary":"Kinase-domain missense TGFBR1 variants cause Loeys-Dietz syndrome type 1: aortic root aneurysm and dissection at younger ages than in Marfan syndrome, and at smaller diameters (mainly reported with TGFBR2), with aneurysm and tortuosity throughout the arterial tree. Loss-of-function variants instead cause multiple self-healing squamous epithelioma.","table":{"caption":"Aortic and arterial risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"taad","name":"Thoracic aortic aneurysm or dissection, any diagnosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"aortic-event","name":"Aortic dissection or preventive aortic surgery","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dissection","name":"Aortic dissection, type A or B","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"type-a","name":"Type A aortic dissection","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"arterial","name":"Extra-aortic arterial event (repair, dissection, or rupture)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"intracranial","name":"Intracranial aneurysm","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pregnancy","name":"Aortic dissection in pregnancy, per pregnancy","women":{"risk":"Not established","relative":"Not established"},"men":null},{"id":"msse","name":"Multiple self-healing squamous epithelioma (loss-of-function variants)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Mean age at death 26.0 years in the first series, before current care. In the 2016 registry, survival about 80% at 60 years; 19 TGFBR1 deaths, at a median 28.4 years among those who died; across TGFBR1 and TGFBR2, 33 of 46 deaths were aortic.","sources":["tgfbr1Loeys2006","tgfbr1Jondeau"]},{"title":"Association evidence","text":"ClinGen: Definitive for LDS and, separately, for multiple self-healing squamous epithelioma; an HTAD gene that triggers aortic surveillance and family screening.","sources":["tgfbr1ClinGen","tgfbr1Renard"]},{"title":"Sex differences","text":"Men had more aortic events, dissections, and type A dissections. A less aggressive surgical approach may be possible in women without family history or rapid growth. The registry paper’s clinical-perspective summary states the sex effect the other way round; its results and abstract show more events in TGFBR1 men, as given here.","sources":["tgfbr1Jondeau"]},{"title":"Treatment if the aorta enlarges","text":"Valve-sparing replacement of the root and whole ascending aorta at an experienced center; open repair preferred over endovascular for thoracoabdominal aneurysm. Further interventions are common after dissection.","sources":["tgfbr1AccLds","tgfbr1Primer"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic TGFBR1 condition is established; TGFBR1-related LDS is autosomal dominant. Refer to clinical genetics and an aortic center, apply at least the surveillance above under their direction, and offer testing along both parental lines.","sources":["tgfbr1GeneReviews"]},"plans":{}},"TGFBR2":{"symbol":"TGFBR2","genotype":"Heterozygous","summary":"TGFBR2 variants, mostly kinase-domain missense, cause Loeys-Dietz syndrome type 2: aortic root aneurysm and dissection at smaller diameters and younger ages than in Marfan syndrome, more type B dissection than other LDS genes, and arterial aneurysm and tortuosity. Women with small body size and marked extra-aortic features have the lowest surgical thresholds.","table":{"caption":"Aortic and arterial risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"taad","name":"Thoracic aortic aneurysm or dissection, any diagnosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"type-a","name":"Type A aortic dissection","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"type-b","name":"Type B aortic dissection","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"arterial","name":"Extra-aortic arterial event (repair, dissection, or rupture)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"intracranial","name":"Intracranial aneurysm","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"chd","name":"Congenital heart defect (bicuspid valve, septal defect, patent ductus)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Mean age at death 26.0 years in the first series, before current care. In the 2016 registry, survival about 80% at 60 years with either gene; 46 deaths (27 with TGFBR2), 33 of them aortic; TGFBR2 patients who died did so at a median 34.8 years.","sources":["tgfbr2Loeys2006","tgfbr2Jondeau"]},{"title":"Association evidence","text":"ClinGen: Definitive for LDS; an HTAD gene that triggers aortic surveillance and family screening.","sources":["tgfbr2ClinGen","tgfbr2Renard"]},{"title":"Women and small body size","text":"Surgery at 4.5 cm, lowered toward 4.0 cm for women with low body surface area and severe extra-aortic features, as adopted by ACC/AHA and ESC. The registry patients were often untreated and undiagnosed, so risk under current care may be lower.","sources":["tgfbr2Jondeau","tgfbr2AccLds","tgfbr2EscLds"]},{"title":"Treatment if the aorta enlarges","text":"Valve-sparing replacement of the root and whole ascending aorta at an experienced center; open repair preferred over endovascular for thoracoabdominal aneurysm. Further interventions are common after dissection.","sources":["tgfbr2AccLds","tgfbr2Primer"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic TGFBR2 condition is established; TGFBR2-related LDS is autosomal dominant. Refer to clinical genetics and an aortic center, apply at least the surveillance above under their direction, and offer testing along both parental lines.","sources":["tgfbr2GeneReviews"]},"plans":{}},"TMEM127":{"symbol":"TMEM127","genotype":"Heterozygous","summary":"TMEM127 variants predispose to pheochromocytoma, sometimes bilateral, usually diagnosed in mid-adulthood and rarely metastatic. Paraganglioma and kidney cancer are reported but uncommon.","table":{"caption":"Tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"ppgl","name":"Pheochromocytoma or paraganglioma (any)","women":{"risk":"41%","relative":"Not established","horizon":"By age 40 · family study","citations":{"risk":["tmem127Bausch"]}},"men":{"risk":"41%","relative":"Not established","horizon":"By age 40 · family study","citations":{"risk":["tmem127Bausch"]}}},{"id":"bilateral","name":"Pheochromocytoma in both adrenal glands","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pgl","name":"Paraganglioma, including head and neck","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"rcc","name":"Kidney cancer (renal cell carcinoma)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Tumors often resemble sporadic, non-metastatic pheochromocytoma and are curable by surgery. An unrecognized secreting tumor is dangerous in surgery and pregnancy. With metastases, about 50% survive 5 years.","sources":["tmem127ArmaizPena","tmem127Clingen"]},{"title":"Association evidence","text":"ClinGen: Definitive; about 5% of hereditary cases. ClinGen actionability: Limited for adults and children (2026), reflecting low penetrance estimates and weak evidence; surveillance is still recommended by AC150, NCCN, and the Swedish guideline. Actionability scoring rates likelihood of disease low, with poor evidence. Most variants are seen once; a four-group classification helps judge pathogenicity.","sources":["tmem127Clingen","tmem127ClingenGene","tmem127Muth","tmem127Myriad","tmem127ArmaizPena"]},{"title":"Treatment if a tumor develops","text":"Surgery at an experienced center. After removing a secreting tumor, blood pressure instability and hypoglycemia can occur; severe hypoglycemia in 13%, usually 2–4.5 hours after resection.","sources":["tmem127Clingen"]}],"otherGenotype":{"title":"If both copies are affected","text":"No condition from two affected copies, and no separate pathway, is described in the guidelines and cohorts cited here. Refer to clinical genetics for interpretation.","sources":["tmem127Clingen"]},"plans":{}},"TMEM43":{"symbol":"TMEM43","genotype":"Heterozygous p.Ser358Leu","summary":"TMEM43 p.Ser358Leu causes fully penetrant arrhythmogenic right ventricular cardiomyopathy type 5, often with left ventricular involvement; sudden death can be the first event and causes most deaths in men (86 of 99), earlier and more often than in women. Other TMEM43 variants have little supporting evidence.","table":{"caption":"Cardiac risk with p.Ser358Leu","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"clinical","name":"Any clinical cardiac feature","women":{"risk":"67%","relative":"Not established","horizon":"By age 50","citations":{"risk":["tmem43Merner"]}},"men":{"risk":"89%","relative":"Not established","horizon":"By age 50","citations":{"risk":["tmem43Merner"]}}},{"id":"death","name":"Death without an ICD","women":{"risk":"50%","relative":"Not established","horizon":"By age 71 · historical cohort","citations":{"risk":["tmem43Hodgkinson2005"]}},"men":{"risk":"50%","relative":"Not established","horizon":"By age 39 · historical cohort","citations":{"risk":["tmem43Hodgkinson2005"]}}},{"id":"scd","name":"Sudden cardiac death","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lv-enlargement","name":"Left ventricular enlargement","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ectopy","name":"Frequent ventricular ectopy (200 or more PVCs per 24 h)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"heart-failure","name":"Heart failure","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"ICD discharges for VT or VF at 240 beats per minute or faster tracked the death rate of controls, so they can reasonably be read as aborted deaths.","sources":["tmem43Hodgkinson2005","tmem43Hodgkinson2016"]},{"title":"How this subtype differs from desmosomal ARVC","text":"Over about 20 years of ECGs in 68 patients, the commonest finding was an R wave under 3 mm in V3, followed in 62% by intraventricular conduction delay or left bundle branch block, earlier in men. Terminal activation duration of 55 ms or more in 63% of men and 36% of women.","sources":["tmem43Duffett","tmem43Hodgkinson2013","tmem43Merner"]},{"title":"Association evidence","text":"ClinGen: Definitive for arrhythmogenic right ventricular dysplasia 5 (autosomal dominant, 2018); adult actionability moderate (2020).","sources":["tmem43ClinGen","tmem43James","tmem43Actionability"]},{"title":"Exercise","text":"Carriers exercising 9.0 MET-hours per day or more had a first appropriate ICD shock at median 35.8 years, against 58.5 years with moderate activity. Spanish women: vigorous exercise trended to more ventricular arrhythmias (P = .053).","sources":["tmem43Paulin","tmem43Dominguez"]},{"title":"Treatment if disease develops","text":"Beta-blockers for ventricular ectopy, NSVT, or VT; amiodarone or added flecainide if they fail; catheter ablation for incessant VT or repeated ICD therapies (ESC 2023, class I to IIa, level C). Ablation reduces VT burden but does not prevent sudden death.","sources":["tmem43Esc2023"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic pathway is described; the disease is autosomal dominant. Refer to an inherited cardiac disease centre, apply at least the surveillance and ICD assessment above, and offer testing along both parental lines.","sources":["tmem43ClinGen","tmem43James"]},"plans":{}},"TNNC1":{"symbol":"TNNC1","genotype":"Heterozygous","summary":"TNNC1 variants can cause hypertrophic or dilated cardiomyopathy; both links are definitive, but TNNC1 is a rare cause and has no published penetrance. Screen the heart on a schedule; treat only if a phenotype appears.","table":{"caption":"Cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"hcm","name":"Hypertrophic cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dcm","name":"Dilated cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"HCM can cause atrial fibrillation, heart failure, and sudden death. Sudden death without phenotype is rare: no arrhythmic events in 126 genotype-positive, phenotype-negative carriers, including athletes.","sources":["tnnc1Aha2024"]},{"title":"Association evidence","text":"ClinGen: Definitive for autosomal dominant HCM (upgraded from moderate, September 2023) and DCM (Definitive, re-evaluated March 2026); no relationship with ARVC. ClinGen adult actionability: strong for HCM and DCM. The 2024 US HCM guideline and 2022 HRS/EHRA consensus (moderate for HCM) predate the upgrade; carrier recommendations apply by extension.","sources":["tnnc1ClingenHcm","tnnc1ClingenDcm","tnnc1ClingenGene","tnnc1Aha2024","tnnc1Hrs2022"]},{"title":"HCM or DCM in a given family","text":"Some variants raise thin-filament calcium sensitivity, as in HCM; others behave like DCM variants; p.Asp145Glu is reported with both. Relatives’ phenotype is the best guide, but screen for both.","sources":["tnnc1ClingenDcm","tnnc1Landstrom"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan. Rare in DCM: two siblings with p.Asp145Glu and p.Asp132Asn, each from a healthy parent, and one patient with p.Glu59Asp and p.Asp75Tyr; insufficient for a recessive form. Refer to a cardiomyopathy center and clinical genetics, screen at least as above, and offer testing along both parental lines.","sources":["tnnc1ClingenDcm"]},"plans":{}},"TNNI3":{"symbol":"TNNI3","genotype":"Heterozygous","summary":"TNNI3 variants cause hypertrophic cardiomyopathy (HCM), less often restrictive or dilated cardiomyopathy. Among relatives in HCM families, about 60% of TNNI3 carriers have HCM when screened (meta-analysis, 115 carriers); of those with a normal first screen, about 1 in 6 (95% CI 7–39%, 39 carriers) developed it within 15 years. Population-found carriers have low penetrance.","table":{"caption":"Cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"hcm","name":"Hypertrophic cardiomyopathy","women":{"risk":"60%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["tnni3Topriceanu"]}},"men":{"risk":"60%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["tnni3Topriceanu"]}}},{"id":"cm-hf","name":"Cardiomyopathy or heart failure diagnosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mace","name":"Death or major cardiac event","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"scd-pre","name":"Sudden cardiac death before hypertrophy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dcm","name":"Dilated cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"In HCM patients, a sarcomere variant meant diagnosis at median 37.5 years against 51.1 years, and 29% against 14% reached death, arrest, ICD therapy, transplant, atrial fibrillation, stroke, or advanced heart failure by 50 years. Sudden death in HCM: about 0.3–0.4% per year. The two TNNI3 penetrance estimates (about 60% at screening, 17% over 15 years after a normal screen) measure different things and rest on small numbers.","sources":["tnni3Share","tnni3ActionHcm"]},{"title":"Association evidence","text":"ClinGen: Definitive for HCM (September 2017); Strong for dominant DCM (DCM 1FF; March 2026, up from Moderate). Adult actionability for HCM: Strong; TNNI3 is not in the DCM actionability report. HRS/EHRA: moderate-evidence DCM gene.","sources":["tnni3Validity","tnni3ActionHcm","tnni3Hrs2022"]},{"title":"Genetic result and sudden-death risk","text":"Sarcomere-positive HCM starts earlier, with more scar, arrhythmia, and heart failure, but genotype does not decide an adult ICD (class 2b). Under 16 years, one of the pediatric risk tools (PRIMaCY) includes genotype; HCM Risk-Kids does not.","sources":["tnni3Aha2024","tnni3Lopes2024"]},{"title":"If HCM develops","text":"Mild to moderate exercise is recommended (class 1); vigorous or competitive exercise is decided annually with an expert, without universal restriction. An ICD is never placed only to allow sport.","sources":["tnni3Aha2024","tnni3ActionHcm"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan. Biallelic TNNI3 variants cause recessive dilated cardiomyopathy (DCM 2A; ClinGen Strong, March 2026), usually evident before adulthood, so this matters mainly for reproduction. More than one sarcomere variant may mean more severe HCM. If both partners carry a TNNI3 variant, offer preconception genetic counseling.","sources":["tnni3Validity","tnni3Aha2024"]},"plans":{}},"TNNT2":{"symbol":"TNNT2","genotype":"Heterozygous","summary":"A TNNT2 variant can cause hypertrophic (HCM) or dilated cardiomyopathy (DCM). About half of carrier relatives in affected families develop HCM within 15 years of a normal first screen; carriers found by population sequencing have much lower penetrance.","table":{"caption":"Cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"hcm","name":"Hypertrophic cardiomyopathy","women":{"risk":"50%","relative":"Not established","horizon":"15-year follow-up · carriers","citations":{"risk":["tnnt2Lorenzini"]}},"men":{"risk":"50%","relative":"Not established","horizon":"15-year follow-up · carriers","citations":{"risk":["tnnt2Lorenzini"]}}},{"id":"cm-hf","name":"Cardiomyopathy or heart failure diagnosis","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"mace","name":"Death or major cardiac event","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"scd-pre","name":"Sudden cardiac death before hypertrophy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dcm","name":"Dilated cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"HCM ranges from no symptoms to heart failure, atrial fibrillation, stroke, and sudden death. In SHaRe, sarcomere-positive patients were diagnosed at median 37.5 against 51.1 years, and by age 50 years 29% against 14% had death, arrest, ICD therapy, transplant, atrial fibrillation, stroke, or advanced heart failure. Sudden death in HCM runs about 0.3–0.4% per year. Thin-filament HCM (TNNT2, TNNI3, ACTC1, TPM1, TNNC1; 488 patients) against thick-filament: ventricular arrhythmia HR 1.48 (95% CI 1.09–2.01), cardiac arrest HR 2.02 (95% CI 1.33–3.06), transplant or LVAD HR 2.18 (95% CI 1.3–3.65); TNNT2 residues 92–94 against other TNNT2 variants OR 3.02 (95% CI 1.17–7.49). In an earlier thin-filament cohort (53% TNNT2), new LV dysfunction ran 4.3% against 1.9% per year.","sources":["tnnt2Share","tnnt2ActionHcm","tnnt2ThinShare","tnnt2Coppini"]},{"title":"Association evidence","text":"ClinGen: Definitive for DCM 1D (March 2026); HCM Definitive in the 2019 ClinGen HCM gene review but not listed in the current gene-validity file; one of eight strong-evidence HCM genes (AHA/ACC 2024, HRS/EHRA). Strong Actionability for HCM and DCM. About 3% of monogenic DCM.","sources":["tnnt2Validity","tnnt2Ingles","tnnt2ActionHcm","tnnt2ActionDcm","tnnt2Hrs2022"]},{"title":"Genetic result and sudden-death risk","text":"Sarcomere-positive HCM starts earlier, with more scar, arrhythmia, and heart failure, but adult ICD decisions do not use genotype (class 2b). Under 16 years, one of the two pediatric 5-year risk models (PRIMaCY) includes genotype.","sources":["tnnt2Aha2024","tnnt2Lopes2024"]},{"title":"If HCM develops","text":"Mild to moderate exercise is recommended (class 1); vigorous or competitive exercise is decided annually with an expert, without universal restriction. An ICD is never placed only to allow sport.","sources":["tnnt2Aha2024","tnnt2ActionHcm"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy plan. No separate pathway is established for biallelic TNNT2 variants. More than one sarcomere variant may mean more severe HCM, including sudden death, though genotype does not decide ICD use. If both partners carry a sarcomere variant, offer preconception genetic counseling.","sources":["tnnt2Aha2024"]},"plans":{}},"TP53":{"symbol":"TP53","genotype":"Heterozygous constitutional variant","summary":"A constitutional TP53 finding can cause Li-Fraumeni syndrome, with high risk of several cancers beginning in childhood. Coordinate MRI-based surveillance with an LFS specialist; risk depends on the variant and family context, and blood-only findings need clarification.","table":{"caption":"Cancer risk","rowHeader":"Cancer","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"breast","name":"Breast cancer","women":{"risk":"71%","relative":"HR 10.7","horizon":"By age 70 · first cancer","citations":{"risk":["tp53Fortuno"],"relative":["tp53Fortuno"]}},"men":{"risk":"Not established","relative":"Not quantified","citations":{"risk":["tp53Fortuno"]},"horizon":"Age-specific estimate"}},{"id":"soft-tissue-sarcoma","name":"Soft tissue sarcoma","women":{"risk":"15%","relative":"HR 23.7","horizon":"By age 70 · first cancer","citations":{"risk":["tp53Mai"],"relative":["tp53Fortuno"]}},"men":{"risk":"22%","relative":"HR 21.3","horizon":"By age 70 · first cancer","citations":{"risk":["tp53Mai"],"relative":["tp53Fortuno"]}}},{"id":"bone-sarcoma","name":"Bone sarcoma (osteosarcoma)","women":{"risk":"5%","relative":"HR 44.7","horizon":"By age 70 · first cancer","citations":{"risk":["tp53Mai"],"relative":["tp53Fortuno"]}},"men":{"risk":"11%","relative":"HR 42.1","horizon":"By age 70 · first cancer","citations":{"risk":["tp53Mai"],"relative":["tp53Fortuno"]}}},{"id":"brain","name":"Brain tumor","women":{"risk":"6%","relative":"HR 42.8","horizon":"By age 70 · first cancer","citations":{"risk":["tp53Mai"],"relative":["tp53Fortuno"]}},"men":{"risk":"19%","relative":"HR 15.8","horizon":"By age 70 · first cancer","citations":{"risk":["tp53Mai"],"relative":["tp53Fortuno"]}}},{"id":"adrenocortical","name":"Adrenocortical carcinoma","women":{"risk":"2%","relative":"HR 78.3","citations":{"risk":["tp53Fortuno"],"relative":["tp53Fortuno"]},"horizon":"Lifetime estimate · first cancer"},"men":{"risk":"Not established","relative":"Not quantified","citations":{"risk":["tp53Fortuno"]},"horizon":"Age-specific estimate"}},{"id":"leukemia","name":"Leukemia","women":{"risk":"Not established","relative":"HR 4.0 (uncertain)","citations":{"risk":["tp53Fortuno"],"relative":["tp53Fortuno"]},"horizon":"Age-specific estimate"},"men":{"risk":"2%","relative":"HR 4.0","horizon":"By age 60 · first cancer","citations":{"risk":["tp53Fortuno"],"relative":["tp53Fortuno"]}}},{"id":"prostate","name":"Prostate cancer","women":null,"men":{"risk":"22%","relative":"HR 5.6","horizon":"By age 60 · first cancer","citations":{"risk":["tp53Fortuno"],"relative":["tp53Fortuno"]}}},{"id":"colorectal","name":"Colorectal cancer","women":{"risk":"Not established","relative":"HR 1.5 (uncertain)","citations":{"risk":["tp53Fortuno"],"relative":["tp53Fortuno"]},"horizon":"Age-specific estimate"},"men":{"risk":"12%","relative":"HR 6.0","horizon":"By age 60 · first cancer","citations":{"risk":["tp53Fortuno"],"relative":["tp53Fortuno"]}}},{"id":"lung","name":"Lung cancer","women":{"risk":"7%","relative":"HR 9.1","horizon":"By age 60 · first cancer","citations":{"risk":["tp53Fortuno"],"relative":["tp53Fortuno"]}},"men":{"risk":"9%","relative":"HR 4.8","horizon":"By age 60 · first cancer","citations":{"risk":["tp53Fortuno"],"relative":["tp53Fortuno"]}}},{"id":"melanoma","name":"Melanoma","women":{"risk":"8%","relative":"HR 5.4","horizon":"By age 60 · first cancer","citations":{"risk":["tp53Fortuno"],"relative":["tp53Fortuno"]}},"men":{"risk":"Not established","relative":"HR 2.1 (uncertain)","citations":{"risk":["tp53Fortuno"],"relative":["tp53Fortuno"]},"horizon":"Age-specific estimate"}},{"id":"ovarian","name":"Ovarian cancer","women":{"risk":"6%","relative":"HR 11.1","horizon":"By age 60 · first cancer","citations":{"risk":["tp53Fortuno"],"relative":["tp53Fortuno"]}},"men":null},{"id":"gastric","name":"Gastric cancer","women":{"risk":"Not established","relative":"HR 6.7 (uncertain)","citations":{"risk":["tp53Fortuno"],"relative":["tp53Fortuno"]},"horizon":"Age-specific estimate"},"men":{"risk":"4%","relative":"HR 11.0","horizon":"By age 60 · first cancer","citations":{"risk":["tp53Fortuno"],"relative":["tp53Fortuno"]}}},{"id":"pancreatic","name":"Pancreatic cancer","women":{"risk":"Not established","relative":"Not quantified","citations":{"risk":["tp53Fortuno"]},"horizon":"Age-specific estimate"},"men":{"risk":"4%","relative":"HR 12.0","horizon":"By age 60 · first cancer","citations":{"risk":["tp53Fortuno"],"relative":["tp53Fortuno"]}}}],"note":"*× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"In the selected NCI cohort, cumulative first-cancer incidence reached 50% by age 31 years in women and 46 years in men, approaching 100% by age 70 years. Ascertainment-adjusted Fortuno estimates were 92.4% (95% CI 82.2–98.3%) in women and 59.7% (95% CI 39.9–81.3%) in men by age 50 years, excluding p.Arg337His. These estimates are not individualized predictions. About 49% of cancer-affected NCI participants developed another cancer; that study could not establish whether second cancers were treatment-related.","sources":["tp53Mai","tp53Fortuno","tp53Ern"]},{"title":"Does surveillance help","text":"In the observational Toronto study of 89 carriers, surveillance detected 40 asymptomatic tumors in 19 of 59 participants. Five-year overall survival after cancer diagnosis was 88.8% (95% CI 78.7–100%) with surveillance versus 59.6% (95% CI 47.2–75.2%) without; self-selection and crossover limit causal interpretation. A meta-analysis of 703 carriers found suspicious lesions in 31% at baseline and a 6% cancer detection rate; 41 of 46 cancers were early stage. The 2% incidence per patient-round combined baseline and follow-up rounds. False positives and follow-up investigations are important tradeoffs.","sources":["tp53Villani","tp53Wbmri","tp53Ern"]},{"title":"Variant type and penetrance","text":"Risk varies by variant and family context. Variants causing complete loss of function or dominant-negative effects can cause severe disease; null variants should not automatically be considered low risk. p.Arg337His is associated with childhood adrenocortical carcinoma and variable later cancer risks. AACR 2025 advises against reducing surveillance solely on the basis of perceived lower penetrance.","sources":["tp53Ern","tp53Gr","tp53Atypical","tp53Aacr2025"]},{"title":"Association evidence","text":"The five core LFS cancers are breast cancer, soft tissue sarcoma, osteosarcoma, brain tumors, and adrenocortical carcinoma; leukemia is also associated. Fortuno found several additional cancer associations with wide confidence intervals and sparse confirmed carrier cases. Its pancreatic estimate relied on pedigree inference with no genotyped pancreatic cases. Colorectal guidance differs across organizations. The separate pancreatic odds ratio comes from a case-control study using public reference controls.","sources":["tp53Fortuno","tp53Ern","tp53Aacr2025","tp53PancreasOdds"]},{"title":"Treatment if cancer develops","text":"Test TP53 before treatment when LFS is suspected. Favor surgery or ablation and non-genotoxic chemotherapy and avoid radiotherapy where possible, without compromising curative treatment; give radiotherapy when clearly needed, then watch closely. Most LFS breast cancers are hormone receptor-positive; HER2 status may direct therapy.","sources":["tp53Ern","tp53Gr","tp53Aacr2025"]}],"otherGenotype":{"title":"If both copies are affected","text":"Refer two reported variants to clinical genetics to confirm classification, constitutional origin, and whether they are on the same or opposite copies. The cited reference reports one homozygous p.Arg337His individual whose phenotype did not clearly differ from heterozygotes; this does not establish risk for other biallelic combinations. Do not double the table risks or assume that any two variants in cis have standard heterozygous penetrance. Continue surveillance already indicated by the clinical diagnosis while the result is clarified.","sources":["tp53Gr"]},"plans":{}},"TPM1":{"symbol":"TPM1","genotype":"Heterozygous","summary":"TPM1 variants cause hypertrophic cardiomyopathy (HCM) or, for other variants, dilated cardiomyopathy (DCM), sometimes from childhood. They are found in about 1.5% of HCM and 2% of DCM patients; penetrance in relatives resembles the commonest HCM genes but is imprecise.","table":{"caption":"Cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"hcm","name":"Hypertrophic cardiomyopathy","women":{"risk":"49%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["tpm1Topriceanu"]}},"men":{"risk":"49%","relative":"Not established","horizon":"At assessment · carrier relatives","citations":{"risk":["tpm1Topriceanu"]}}},{"id":"dcm","name":"Dilated cardiomyopathy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lvnc","name":"Left ventricular noncompaction","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"scd","name":"Sudden cardiac death or cardiac arrest","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Most phenotype-negative carriers appear to have a benign course. With HCM, thin-filament disease (7 TPM1 patients) had milder hypertrophy (18 mm against 24 mm) but faster LV dysfunction (4.3% against 1.9% per year). p.Arg21Leu shows late onset and a generally favorable prognosis. Pathogenic sarcomere variants carry about twice the risk of adverse outcomes of no variant.","sources":["tpm1Actionability","tpm1Coppini","tpm1Lamounier","tpm1Share"]},{"title":"Association evidence","text":"ClinGen: definitive for HCM (December 2023), moderate for DCM 1Y (March 2026), no known relationship with ARVC (2019). Strong-evidence HCM gene (AHA 2024); moderate-evidence DCM gene (2022 consensus). Adult actionability for HCM: strong.","sources":["tpm1ClinGen","tpm1AhaFamily","tpm1Hrs","tpm1Actionability"]},{"title":"Treatment if HCM develops","text":"Beta-blockers first for obstructive symptoms, then nondihydropyridine calcium channel blockers; then a cardiac myosin inhibitor, disopyramide, or septal reduction at an experienced center. Anticoagulate clinical atrial fibrillation regardless of CHA2DS2-VASc score. Mavacamten is teratogenic.","sources":["tpm1AccPoints","tpm1AhaCare"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance. Recessive TPM1 cardiomyopathy is not established; one report describes homozygous p.Gly3Arg in triplets (two with pediatric HCM, one with patent ductus arteriosus) of unaffected heterozygous parents. Homozygous p.Arg21Leu carriers occur in Iberian founder families (6% of 83 carriers). More than one pathogenic variant may mean more severe disease. Refer to clinical genetics and a cardiomyopathy center, and test both parental lines.","sources":["tpm1Carlus","tpm1Lamounier","tpm1AhaFamily"]},"plans":{}},"TRDN":{"symbol":"TRDN","genotype":"Biallelic loss-of-function variants","summary":"Biallelic loss-of-function TRDN variants cause triadin knockout syndrome: exercise-triggered cardiac arrest or syncope, usually in early childhood, with precordial T-wave inversion, transient QT prolongation in about half, and frequent breakthrough events despite treatment.","table":{"caption":"Arrhythmic and muscle features","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"arrest","name":"Cardiac arrest as first presentation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"syncope","name":"Syncope as first presentation","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"twi","name":"Precordial T-wave inversion","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"qt","name":"Transient QT prolongation above 480 ms","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"ectopy","name":"Ventricular ectopy on exercise testing","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"breakthrough","name":"Recurrent cardiac events despite treatment","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"myopathy","name":"Mild skeletal myopathy or proximal weakness","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Potentially lethal; recessive CPVT forms are more severe than dominant ones.","sources":["trdnClemens","trdnWilde"]},{"title":"Association evidence","text":"ClinGen: definitive for recessive CPVT (2021), strong for recessive LQTS (2020); strong actionability in adults and children. TRDN explains about 1–2% of CPVT. ESC 2022 calls it unclear whether TRDN arrhythmia is a distinct entity.","sources":["trdnClinGen","trdnWalsh","trdnAdler","trdnActionability","trdnEsc"]},{"title":"Overlap phenotype","text":"Modest QT prolongation with adrenergically triggered ventricular arrhythmia, so it may be labeled LQTS or CPVT; management draws on both.","sources":["trdnWilde","trdnEhra2026"]}],"otherGenotype":{"title":"If one copy is affected","text":"A carrier state: carriers normally have no phenotype and need no treatment or cardiac screening, and no dominant TRDN disease is established. Evaluate symptoms such as exertional syncope as usual. Offer the partner testing before a pregnancy; two carrier parents have a 25% chance of an affected child each pregnancy.","sources":["trdnWilde","trdnClinGen","trdnGeneReviews"]},"plans":{}},"TSC1":{"symbol":"TSC1","genotype":"Heterozygous","summary":"A pathogenic TSC1 variant establishes tuberous sclerosis complex even without features, which appear at different ages. Adult threats are renal angiomyolipoma with bleeding and chronic kidney disease, and lung lymphangioleiomyomatosis (LAM) in women; TSC1 disease is on average milder than TSC2.","table":{"caption":"Tuberous sclerosis manifestations","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"aml","name":"Renal angiomyolipoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"renal-cysts","name":"Multiple renal cysts","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"rcc","name":"Renal cell carcinoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lam","name":"Lymphangioleiomyomatosis (LAM)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"epilepsy","name":"Epilepsy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"intellectual","name":"Intellectual disability","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"autism","name":"Autism spectrum disorder","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"sega","name":"Subependymal giant cell astrocytoma (SEGA)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"angiofibroma","name":"Facial angiofibromas","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"retinal","name":"Retinal astrocytic hamartomas","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Central nervous system problems, including TAND, cause most morbidity. Complications of severe intellectual disability (32.5%) and renal disease (27.5%) lead premature deaths; GeneReviews names kidney disease first. Women tend to have milder disease than men, apart from LAM and angiomyolipoma complications.","sources":["tsc1GeneReviews","tsc1ClinGen","tsc1ToscaRenal"]},{"title":"Association evidence","text":"A pathogenic variant is diagnostic regardless of clinical findings (2021 consensus). TSC1 accounts for about 26% of probands with an identified variant (19.7% of everyone tested in TOSCA), is more often inherited, and is milder on average: fewer tubers, less intellectual disability, fewer and later angiomyolipomas, fewer cysts. Expression varies widely within families, and severe TSC1 disease occurs.","sources":["tsc1Northrup","tsc1ClinGen","tsc1Tosca","tsc1Dabora"]},{"title":"Treatment if disease develops","text":"mTOR inhibitors are the cornerstone. Everolimus more often produced a 50% or greater reduction in angiomyolipoma size (responder RR 24.69, 95% CI 3.51–173.41, against control) and SEGA volume (RR 27.85, 95% CI 1.74–444.82, against placebo); sirolimus treats qualifying LAM and, topically, facial angiofibromas. Adverse effects are usually mild to moderate: stomatitis, raised lipids and glucose, usually transient amenorrhea.","sources":["tsc1ClinGen","tsc1Northrup"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance. No separate condition from biallelic germline TSC1 variants is established. TOSCA recorded 5 people with variants in both TSC1 and TSC2, still under investigation. Refer any report of two variants to clinical genetics before changing management.","sources":["tsc1Tosca","tsc1Northrup"]},"plans":{}},"TSC2":{"symbol":"TSC2","genotype":"Heterozygous","summary":"A pathogenic TSC2 variant establishes tuberous sclerosis complex even without features, which appear at different ages. Adult threats are renal angiomyolipoma with bleeding and chronic kidney disease, and lung lymphangioleiomyomatosis (LAM) in women; TSC2 disease is on average more severe than TSC1, and a deletion into PKD1 adds early severe polycystic kidney disease.","table":{"caption":"Tuberous sclerosis manifestations","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"aml","name":"Renal angiomyolipoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"renal-cysts","name":"Multiple renal cysts","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"rcc","name":"Renal cell carcinoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"lam","name":"Lymphangioleiomyomatosis (LAM)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"epilepsy","name":"Epilepsy","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"intellectual","name":"Intellectual disability","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"autism","name":"Autism spectrum disorder","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"sega","name":"Subependymal giant cell astrocytoma (SEGA)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"angiofibroma","name":"Facial angiofibromas","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"retinal","name":"Retinal astrocytic hamartomas","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Central nervous system problems, including TAND, cause most morbidity. Complications of severe intellectual disability (32.5%) and renal disease (27.5%) lead premature deaths; GeneReviews names kidney disease first. Women tend to have milder disease than men, apart from LAM and angiomyolipoma complications.","sources":["tsc2GeneReviews","tsc2ClinGen","tsc2ToscaRenal"]},{"title":"Association evidence","text":"A pathogenic variant is diagnostic regardless of clinical findings (2021 consensus). TSC2 accounts for about 74% of probands with an identified variant (63.3% of everyone tested in TOSCA), is more often de novo, and is more severe on average: more tubers, seizures, and intellectual disability, earlier and larger angiomyolipomas, more cysts. Some missense variants are milder and run in families; expression varies widely.","sources":["tsc2Northrup","tsc2ClinGen","tsc2Tosca","tsc2Dabora"]},{"title":"Treatment if disease develops","text":"mTOR inhibitors are the cornerstone. Everolimus more often produced a 50% or greater reduction in angiomyolipoma size (responder RR 24.69, 95% CI 3.51–173.41, against control) and SEGA volume (RR 27.85, 95% CI 1.74–444.82, against placebo); sirolimus treats qualifying LAM and, topically, facial angiofibromas. Adverse effects are usually mild to moderate: stomatitis, raised lipids and glucose, usually transient amenorrhea.","sources":["tsc2ClinGen","tsc2Northrup"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance. No separate condition from biallelic germline TSC2 variants is established. TOSCA recorded 5 people with variants in both TSC1 and TSC2, still under investigation. Refer any report of two variants to clinical genetics before changing management.","sources":["tsc2Tosca","tsc2Northrup"]},"plans":{}},"TTN":{"symbol":"TTN","genotype":"Heterozygous DCM-associated truncating variant","summary":"A DCM-associated TTN truncating variant increases the risk of dilated cardiomyopathy, heart failure and rhythm problems. Disease may develop later in life; cardiac surveillance is warranted even with a normal baseline, and alcohol excess, pregnancy or cardiotoxic treatment can add risk.","table":{"caption":"Cardiomyopathy and rhythm risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Risk comparison*"}],"rows":[{"id":"dcm","name":"LV dysfunction in DCM families","women":{"risk":"78.9%","relative":"5.6×","horizon":"By age 70 years · selected families, including probands","citations":{"risk":["ttnJohnson"],"relative":["ttnJohnson"]}},"men":{"risk":"92.8%","relative":"7.9×","horizon":"By age 70 years · selected families, including probands","citations":{"risk":["ttnJohnson"],"relative":["ttnJohnson"]}}},{"id":"low-ef","name":"Reduced LVEF without heart failure","women":{"risk":"18.5%","relative":"8.0×","horizon":"Observed at MRI · pooled sexes, 54 carriers","citations":{"risk":["ttnPirruccello"],"relative":["ttnPirruccello"]}},"men":{"risk":"18.5%","relative":"8.0×","horizon":"Observed at MRI · pooled sexes, 54 carriers","citations":{"risk":["ttnPirruccello"],"relative":["ttnPirruccello"]}}},{"id":"heart-failure","name":"Heart failure","women":{"risk":"Not quantified by age","relative":"OR 3.8","citations":{"relative":["ttnHaggerty"]}},"men":{"risk":"Not quantified by age","relative":"OR 3.8","citations":{"relative":["ttnHaggerty"]}}},{"id":"af","name":"Atrial fibrillation","women":{"risk":"Not quantified by age","relative":"OR 2.4","citations":{"relative":["ttnHaggerty"]}},"men":{"risk":"Not quantified by age","relative":"OR 2.4","citations":{"relative":["ttnHaggerty"]}}},{"id":"ppcm","name":"Peripartum cardiomyopathy","women":{"risk":"Not quantified by age","relative":"OR 9.4","citations":{"relative":["ttnGoli"]}},"men":null}],"note":"Family estimates include affected probands and use LVEF below 50%; MRI figures are observed prevalence in 54 carriers, pooling sexes. *× denotes a calculated probability or prevalence comparison. OR = odds ratio; HR = hazard ratio; SIR and incidence RR compare incidence. These measures are not interchangeable probability multipliers. Each estimate has its own source; comparison populations, uncertainty and calculations are under About these estimates."},"details":[{"title":"Severity","text":"Expression ranges from no detectable cardiac disease to severe heart failure or arrhythmias. In the Penn biobank DCM subgroup excluding transplant recipients, carriers had an adjusted LVEF about 12 percentage points lower than non-carriers; that cohort comparison is not an individual prognosis.","sources":["ttnHaggerty","ttnJohnson"]},{"title":"Association evidence","text":"ClinGen classifies the TTN–dilated cardiomyopathy relationship as definitive and adult clinical actionability as strong. These classifications support surveillance for a confirmed DCM-associated variant; they do not classify every TTN sequence change as disease-causing.","sources":["ttnClinGen","ttnClinGenAc"]},{"title":"Variant interpretation","text":"Population carriers of high-PSI truncations have slightly lower LVEF on average, consistent with a risk allele modified by other genes and exposures.","sources":["ttnRoberts","ttnPirruccello","ttnHfsa"]},{"title":"Treatment if disease develops","text":"Treatment is guided by the cardiac phenotype. Early treatment may be considered once ventricular abnormalities emerge; preventive drug treatment solely for an unaffected TTN carrier remains an evidence gap in the reviewed guideline.","sources":["ttnEsc2023"]}],"otherGenotype":{"title":"If both copies are affected","text":"Two TTN variants require specialist interpretation of both variants and whether they are on opposite copies (in trans). Pathogenic biallelic variants can cause recessive TTN-related myopathy, sometimes with cardiac involvement; this is not simply a higher-risk version of dominant DCM. Refer to clinical genetics, neuromuscular medicine and cardiology as appropriate. Variants on the same copy do not establish recessive disease. A parent with a confirmed DCM-associated variant still needs cardiac assessment and surveillance.","sources":["ttnClinGen","ttnJohnson"]},"plans":{}},"TTR":{"symbol":"TTR","genotype":"Heterozygous","summary":"TTR amyloid infiltrates the heart, nerves, eyes, and kidneys, with onset from the third to the ninth decade by variant and ancestry. V122I (p.Val142Ile, 3–4% of Black Americans) mainly causes heart failure after age 60 years and V30M (p.Val50Met) neuropathy; penetrance is incomplete.","table":{"caption":"Amyloidosis risk by variant","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"v122i-hf","name":"V122I, heart failure prevalence, hospital biobank, age 50 years or older","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"v122i-hf75","name":"V122I, heart failure by age 75","women":{"risk":"16.7%","relative":"Not established","horizon":"By age 75","citations":{"risk":["ttrParker"]}},"men":{"risk":"16.7%","relative":"Not established","horizon":"By age 75","citations":{"risk":["ttrParker"]}}},{"id":"v122i-any75","name":"V122I: at least one associated manifestation","women":{"risk":"37.4%","relative":"2.7×","horizon":"By age 75","citations":{"risk":["ttrParker"],"relative":["ttrParker"]}},"men":{"risk":"37.4%","relative":"2.7×","horizon":"By age 75","citations":{"risk":["ttrParker"],"relative":["ttrParker"]}}},{"id":"v122i-pn","name":"V122I, polyneuropathy by age 75","women":{"risk":"7.9%","relative":"Not established","horizon":"By age 75","citations":{"risk":["ttrParker"]}},"men":{"risk":"7.9%","relative":"Not established","horizon":"By age 75","citations":{"risk":["ttrParker"]}}},{"id":"v122i-cts","name":"V122I, carpal tunnel syndrome by age 75","women":{"risk":"13.2%","relative":"Not established","horizon":"By age 75","citations":{"risk":["ttrParker"]}},"men":{"risk":"13.2%","relative":"Not established","horizon":"By age 75","citations":{"risk":["ttrParker"]}}},{"id":"v122i-overt","name":"V122I, overt cardiomyopathy on echocardiography after 65","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"v30m-pt","name":"V30M, disease by age 70, Portuguese families","women":{"risk":"91%","relative":"Not established","horizon":"By age 70 · family study","citations":{"risk":["ttrClinGenAct"]}},"men":{"risk":"91%","relative":"Not established","horizon":"By age 70 · family study","citations":{"risk":["ttrClinGenAct"]}}},{"id":"v30m-fr","name":"V30M, disease by age 70, French families","women":{"risk":"50%","relative":"Not established","horizon":"By age 70 · French families","citations":{"risk":["ttrClinGenAct"]}},"men":{"risk":"50%","relative":"Not established","horizon":"By age 70 · French families","citations":{"risk":["ttrClinGenAct"]}}},{"id":"v30m-se","name":"V30M, disease by age 70, Swedish families","women":{"risk":"36%","relative":"Not established","horizon":"By age 70 · Swedish families","citations":{"risk":["ttrClinGenAct"]}},"men":{"risk":"36%","relative":"Not established","horizon":"By age 70 · Swedish families","citations":{"risk":["ttrClinGenAct"]}}},{"id":"cardiac-symptomatic","name":"Mixed variants, cardiac disease if symptomatic","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Untreated ATTR amyloidosis is progressive and fatal: restrictive heart failure, conduction disease, and arrhythmia; neuropathy progressing to motor weakness, autonomic failure, and cachexia. It is underdiagnosed, especially in Black Americans, and neuropathy is often misdiagnosed as carpal tunnel syndrome or CIDP.","sources":["ttrClinGenAct","ttrGeneReviews"]},{"title":"What treatment changes","text":"In a phase 3 trial of 441 patients with wild-type or hereditary ATTR cardiomyopathy, tafamidis lowered all-cause mortality (29.5% versus 42.9%) and cardiovascular hospitalizations (0.48 versus 0.70 per year) and slowed functional decline. Gene silencers halted or slowed neuropathy in phase 3 trials. Established damage does not usually reverse, so treat early.","sources":["ttrClinGenAct","ttrAccPoints"]},{"title":"Association evidence","text":"ClinGen: definitive, autosomal dominant (December 2017); strongly actionable (score 11CC) for referral and surveillance guiding tafamidis in cardiac amyloidosis.","sources":["ttrClinGen","ttrClinGenAct"]},{"title":"Modifiable risk with V122I","text":"In Black carriers, 0 or 1 cardiovascular risk factor carried a lower heart failure hazard (HR 2.26 versus favorable-profile noncarriers) than 3 or 4 (HR 4.14). Treating hypertension, diabetes, obesity, and high cholesterol is reasonable but does not remove the excess risk.","sources":["ttrRiskFactors"]}],"otherGenotype":{"title":"If both copies are affected","text":"Two TTR variants can occur, such as V122I homozygosity. No separate penetrance or pathway is available; use the same surveillance under an amyloidosis center, which may start earlier.","sources":["ttrGeneReviews","ttrClinGenAct"]},"plans":{}},"VCL":{"symbol":"VCL","genotype":"Heterozygous","summary":"Loss-of-function VCL variants raise dilated cardiomyopathy risk, mostly with childhood onset, but penetrance is low and one variant is often insufficient alone. Evidence for missense variants is weak, and the hypertrophic cardiomyopathy link is disputed.","table":{"caption":"Cardiomyopathy risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"dcm-lof","name":"Dilated cardiomyopathy, loss-of-function variant","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dcm-missense","name":"Dilated cardiomyopathy, missense variant","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"hcm","name":"Hypertrophic cardiomyopathy (ClinGen Disputed)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Mostly a disease of infancy and childhood; infant DCM often recovered on medication. Adult-onset risk with a normal heart is not established.","sources":["vclHawley","vclZahavich"]},{"title":"Association evidence","text":"ClinGen: strong for dominant DCM (upgraded from moderate, August 2024), needing more experimental evidence for definitive; HCM disputed (May 2023). Moderate-evidence gene for first-tier DCM testing (HRS/EHRA 2022).","sources":["vclClingenDcm","vclClingenHcm","vclHrs2022"]},{"title":"Vinculin and metavinculin","text":"Metavinculin, the longer form including exon 19, is expressed in heart and smooth muscle. Early DCM reports involved metavinculin-specific variants; stronger recent evidence is for whole-gene loss of function.","sources":["vclClingenDcm","vclClingenHcm"]},{"title":"If DCM develops","text":"Heart failure guidelines apply; defibrillator decisions follow LVEF and clinical risk.","sources":["vclEscComment","vclDcmFamily"]}],"otherGenotype":{"title":"If both copies are affected","text":"No biallelic VCL condition is established. A second variant in VCL or another cardiomyopathy gene may change risk, unquantified. Refer to clinical genetics and a cardiomyopathy center, and test both parental lines.","sources":["vclHawley","vclClingenDcm"]},"plans":{}},"VHL":{"symbol":"VHL","genotype":"Heterozygous","summary":"A VHL variant causes von Hippel-Lindau disease: lifelong risk of retinal, brain, and spinal hemangioblastomas, clear cell kidney cancer, pheochromocytoma, pancreatic neuroendocrine tumors, and inner ear tumors. Nearly all carriers are affected, often before age 30 years, and organized surveillance reduces harm.","table":{"caption":"Tumor risk","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"any","name":"Any VHL manifestation","women":{"risk":"87%","relative":"Not established","horizon":"By age 60 · clinical cohort","citations":{"risk":["vhlBinderupPenetrance"]}},"men":{"risk":"87%","relative":"Not established","horizon":"By age 60 · clinical cohort","citations":{"risk":["vhlBinderupPenetrance"]}}},{"id":"cerebellar-hb","name":"Cerebellar hemangioblastoma","women":{"risk":"84%","relative":"Not established","horizon":"By age 60 · clinical cohort","citations":{"risk":["vhlMaher1990"]}},"men":{"risk":"84%","relative":"Not established","horizon":"By age 60 · clinical cohort","citations":{"risk":["vhlMaher1990"]}}},{"id":"cns-hb","name":"CNS hemangioblastoma, any site (brain and spinal cord)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"retinal-hb","name":"Retinal hemangioblastoma","women":{"risk":"70%","relative":"Not established","horizon":"By age 60 · clinical cohort","citations":{"risk":["vhlMaher1990"]}},"men":{"risk":"70%","relative":"Not established","horizon":"By age 60 · clinical cohort","citations":{"risk":["vhlMaher1990"]}}},{"id":"rcc","name":"Kidney cancer (clear cell renal cell carcinoma)","women":{"risk":"69%","relative":"Not established","horizon":"By age 60 · clinical cohort","citations":{"risk":["vhlMaher1990"]}},"men":{"risk":"69%","relative":"Not established","horizon":"By age 60 · clinical cohort","citations":{"risk":["vhlMaher1990"]}}},{"id":"ppgl","name":"Pheochromocytoma or paraganglioma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pnet","name":"Pancreatic neuroendocrine tumor","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"pancreatic-cyst","name":"Pancreatic cyst or serous cystadenoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"elst","name":"Endolymphatic sac tumor (inner ear)","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Hemangioblastomas are benign but cause blindness and neurologic disability; kidney and pancreatic tumors can metastasize. CNS hemangioblastoma (51–68% of deaths) and kidney cancer (28–36%) cause most VHL deaths in two cohorts (143 and 340 patients). Danish carriers born in 2000 have an estimated mean life expectancy of 67 years (men) and 60 years (women), against a median 49 years in the 1990 UK series.","sources":["vhlDanish","vhlClingen","vhlBinderupSurvival","vhlMaher1990"]},{"title":"Genotype and phenotype","text":"Type 1 (often truncating or deletions): hemangioblastoma and kidney cancer, infrequent pheochromocytoma. Type 2 (missense) adds pheochromocytoma: 2A lower and 2B high kidney cancer risk; 2C pheochromocytoma only. Truncating variants had more new tumors (HR 1.85, 95% CI 1.06–3.24), and surveillance lowered death rates in truncating (HR 0.22, 95% CI 0.07–0.69) but not missense carriers in one study. Patterns overlap, so surveillance is not stratified by genotype.","sources":["vhlMaher2011","vhlBinderupRisk","vhlClingen","vhlDanish"]},{"title":"Treatment if a tumor develops","text":"Treatment preserves function across many lifetime interventions: nephron-sparing surgery for kidney tumors near 3 cm, surgery for symptomatic or growing CNS hemangioblastomas, laser for most retinal tumors, and adrenalectomy after alpha-blockade. Belzutifan (HIF-2α inhibitor, FDA 2021) produced responses in kidney (49%), pancreatic (77%), and CNS (30%) lesions in a phase II trial.","sources":["vhlClingen","vhlDanish","vhlMaher2011","vhlChahoud"]}],"otherGenotype":{"title":"If both copies are affected","text":"Confirm two variants: homozygous, or two different variants shown on opposite copies (in trans) by parental testing or laboratory phasing. If they are on the same copy, use the single-copy guidance. Biallelic VHL variants cause familial erythrocytosis type 2, a red cell disorder; these variants generally carry no added tumor risk, though a few patients have had both conditions. Refer to hematology and clinical genetics; the tumor plan applies only if one variant is tumor-causing.","sources":["vhlDanish"]},"plans":{}},"WT1":{"symbol":"WT1","genotype":"Heterozygous","summary":"A WT1 variant causes WT1 disorder, a childhood-onset continuum of steroid-resistant kidney disease, Wilms tumor, and disorders of testicular development. DNA-binding missense and intron 9 splice variants cause the kidney disease and testicular development spectrum; truncating or loss-of-function variants mainly confer Wilms tumor risk, with later and less frequent kidney disease. In adults the issues are lifelong kidney monitoring, gonadal tumor risk with 46,XY gonadal dysgenesis, pregnancy, and a 50% chance of passing it to each child.","table":{"caption":"Clinical features","rowHeader":"Condition","inlineReferences":true,"groups":["women","men"],"measures":[{"key":"risk","label":"Absolute risk (%)"},{"key":"relative","label":"Relative risk (×)*"}],"rows":[{"id":"proteinuria","name":"Persistent proteinuria","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"srns","name":"Steroid-resistant nephrotic syndrome","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"kidney-failure","name":"Kidney failure","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"wilms","name":"Wilms tumor","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"dsd","name":"46,XY disorder of sex development","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"gonadal-insufficiency","name":"Early gonadal insufficiency","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"gonadoblastoma","name":"Gonadoblastoma","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}},{"id":"cakut","name":"Kidney and urinary tract malformations","women":{"risk":"Not established","relative":"Not established"},"men":{"risk":"Not established","relative":"Not established"}}],"note":"All risks are estimates. *Relative risks are calculated from published absolute-risk estimates."},"details":[{"title":"Severity","text":"Kidney disease drives long-term health. Survival after Wilms tumor does not differ significantly from Wilms tumor without a known cause.","sources":["wt1Gr"]},{"title":"Kidney disease management","text":"Kidney biopsy is no longer first-tier once the variant is known. Transplant generally requires a weight of about 10 kg and at least a year after Wilms treatment.","sources":["wt1Gr"]},{"title":"Association evidence","text":"ClinGen curates two entities, both definitive: Denys-Drash syndrome (lumping Frasier and Meacham syndromes and nephrotic syndrome type 4; dominant-negative missense and intron 9 splice variants) and Wilms tumor type 1 (loss-of-function variants). GeneReviews treats Denys-Drash, Frasier, and Meacham syndromes as points on one continuum, no longer separate diagnoses.","sources":["wt1ClinGen","wt1Gr"]}],"otherGenotype":{"title":"If both copies are affected","text":"No inherited biallelic WT1 condition is established; loss of the second copy within Wilms tumors is a tumor event. Refer an unexpected biallelic report to clinical genetics; this plan does not apply.","sources":["wt1Gr"]},"plans":{}}};
